RG.HK["33"] = [{"id":"33_okayama_jo","n":"岡山城（宇喜多秀家の «烏城»）","yomi":"おかやまじょう","cat":"城","rank":"S","y":1597,"era":["azuchi","edo","showa"],"sh":"国指定史跡（月見櫓・西丸西手櫓は国の重要文化財）","ad":"岡山市北区丸の内2丁目","st":"JR岡山駅から路面電車で «城下» 下車、歩いて約10分","la":34.6652,"lo":133.936,"hook":"黒い板張りの天守が旭川に映る。その姿から «烏城（うじょう）» と呼ばれた、戦国の若き大名の夢の城。","lead":"岡山城は、戦国大名・宇喜多秀家が大きく造りかえて、1597年ごろに完成したお城です。壁に黒い板をはっているので «烏城» とよばれます。天守は1945年の空襲で焼けてしまい、今の天守は1966年に建て直されたものです。","story":["戦国時代、備前の国をのし上がったのは宇喜多直家でした。«謀略の人» ともいわれた直家は、旭川のほとりの小さな城に目をつけ、ここを本拠にします。«川と海に近いこの場所なら、船で米も兵も運べる»。商人を呼び集め、町づくりを始めたのも直家でした。","その跡を継いだのが、息子の秀家です。父を早くに亡くした秀家は、豊臣秀吉にかわいがられ、秀吉の養女・豪姫を妻にむかえました。若くして豊臣政権の «五大老» のひとりにまでなった秀家は、岡山の城を大きく造りかえます。天守の土台は、なんと «ゆがんだ五角形»。なぜ四角ではないのでしょう? もともとあった岡の地形に合わせて石垣を積んだからだと考えられています。","ところが1600年の関ヶ原の戦いで、秀家は西軍の主力として戦い、敗れてしまいます。秀家は逃げのび、のちに八丈島へ流されました。島での暮らしは約50年におよび、江戸幕府の時代が長く続くのを、遠い島から見ていたことになります。","秀家のあとに岡山城に入ったのは、関ヶ原で東軍に寝返った小早川秀秋でした。秀秋は城の外堀を大急ぎで掘らせ、«二十日で掘った» ので «二十日堀» とよばれたと伝わります。しかし秀秋は2年ほどで亡くなり、そのあとは池田家が明治まで城主をつとめました。","明治になって城の建物は次々と取りこわされましたが、天守と月見櫓などは残りました。ところが1945年6月29日の岡山空襲で、天守は炎に包まれて焼け落ちます。多くの市民も命を落としました。«もう一度、烏城を»。その願いがかない、1966年に天守がよみがえりました。焼けずに残った月見櫓は、今も江戸時代の姿を伝えています。"],"tl":[["1573年ごろ","宇喜多直家が岡山の城に入り、本拠とする"],["1590年ごろ","宇喜多秀家が城の大改修を始める"],["1597年","天守が完成したとされる"],["1600年","関ヶ原の戦いで秀家が敗れる。小早川秀秋が城主に"],["1603年","池田忠継が城主となり、以後池田家の城に"],["1945年6月29日","岡山空襲で天守が焼失"],["1966年","天守が鉄筋コンクリートで再建される"],["2022年","«令和の大改修» を終えてリニューアル公開"]],"who":[["宇喜多直家","秀家の父。岡山城を本拠にし、城下町づくりを始めた"],["宇喜多秀家","城を大改修して天守を築いた。関ヶ原で敗れ八丈島へ流された"],["豪姫","前田利家の娘で秀吉の養女。秀家の妻"],["小早川秀秋","関ヶ原のあと城主となり、外堀を急いで掘らせた"],["池田光政","江戸時代前期の藩主。«名君» として知られる"]],"deep":["天守台は不等辺五角形。全国でもめずらしい形で、元の «岡山» という丘の地形に合わせたためと考えられています。天守の一階も、この形に合わせてゆがんだ平面になっていました。","戦前の天守は国宝（当時の制度）に指定されていました。焼失前の写真や図面が残っていたため、外観はかなり忠実に再建されています。","月見櫓は池田忠雄の時代、1620年代ごろの建築と考えられる現存の櫓。外側からは二階建て、城の内側からは三階建てに見える造りで、国の重要文化財です。","城の石垣には、宇喜多時代・小早川時代・池田時代の積み方の違いが見られます。自然石を積んだ古い石垣と、加工した石を使う新しい石垣を見比べるのが楽しみどころです。","旭川は、城の守りのために流れを変えたといわれます。川が天守の北と東をぐるりと回るのはそのためで、対岸には池田綱政が後楽園を造りました。","宇喜多秀家は八丈島で約50年暮らし、1655年に亡くなったとされます。流罪になった大名の中で、とても長生きした人でした。妻の実家・前田家から島へ米などが送られたと伝わります。"],"look":["不等辺五角形の天守台（天守の中からもゆがみがわかる）","現存する月見櫓（重要文化財）","宇喜多時代の古い石垣が残る本丸の «本段» 周辺","旭川の対岸・後楽園から見る天守の姿","天守の中の展示（宇喜多・小早川・池田の歴代城主）"],"q":["岡山城が «烏城（うじょう）» と呼ばれるのはなぜ？","壁に黒い板（下見板）がはってあり、カラスのように黒く見えるからです。"],"koji":[],"myth":"«二十日堀» を二十日で掘ったという話は伝承。天守完成年は1597年とされるが諸説。","img":["宇喜多秀家","宇喜多直家","岡山空襲","後楽園"],"wp":"岡山城","rel":{"ev":[],"grave":[]},"ph":[["c:a/ae/Okayama_Castle_main_keep_2023-10-18.jpg",1440,1100,"岡山城"],["c:a/ac/Okayama_Castle_detail_-_DSC01786.JPG",4320,3240],["c:4/4f/Okayama_castle17n3200.jpg",3900,2600],["c:1/1c/Okayama_castle13s3872.jpg",3872,2592],["c:0/0b/Okayama_castle10s3872.jpg",3872,2592],["c:f/ff/Okayama_castle02s3872.jpg",3872,2592],["c:2/29/Korakuen_Okayama35s4bs3872.jpg",3872,2592],["c:b/bf/Okayama_castle15s3200.jpg",3200,2142]]},{"id":"33_korakuen","n":"岡山後楽園（池田綱政の大名庭園）","yomi":"おかやまこうらくえん","cat":"大名屋敷","rank":"S","y":1700,"era":["edo","meiji","showa"],"sh":"国の特別名勝","ad":"岡山市北区後楽園","st":"JR岡山駅から路面電車で «城下» 下車、歩いて約10分（岡山城から月見橋を渡ってすぐ）","la":34.668,"lo":133.9357,"hook":"«天下の人より後に楽しむ» ――殿様の庭なのに、名前にこめられたのは «民が先» という考えだった。","lead":"岡山後楽園は、岡山藩主・池田綱政が家臣の津田永忠に命じて造らせた大名庭園です。1687年に工事が始まり、1700年ごろにほぼ今の形になりました。水戸の偕楽園、金沢の兼六園とならぶ «日本三名園» のひとつです。","story":["江戸時代のはじめ、岡山藩は «名君» 池田光政のもとで、学問や新田開発に力を入れていました。そのあとを継いだ息子の綱政は、城の北、旭川の中州のような土地に、大きな庭を造ることを決めます。工事の中心になったのは、閑谷学校や新田の工事でも知られる家臣・津田永忠でした。","当時の呼び名は «御後園（ごこうえん）»。城の «後ろにある園» という意味です。殿様がくつろいだり、客をもてなしたりする場所でした。広い芝生、曲がりくねった水の流れ、小高い山。池のまわりを歩きながら景色の変化を楽しむ «回遊式» の庭です。«なぜ芝生がこんなに広いの?»――江戸時代には、実は田んぼや畑もあり、殿様が農作業を見る場所でもあったのです。","綱政は能が大好きで、庭の中に能舞台を造り、自分でも舞ったといわれます。藩の人々を招いて能を見せる日もあったそうです。庭は «殿様だけのもの» でありながら、ときには領民にも開かれていました。","明治になり、1871年に名前が «後楽園» に変わりました。中国の宋の時代の文章 «岳陽楼記» にある «天下の憂いに先だって憂い、天下の楽しみに後れて楽しむ» ということばから取ったといわれます。1884年には岡山県のものとなり、だれでも入れる公園になりました。","昭和になると試練が続きます。1934年の室戸台風では旭川があふれて庭が水につかり、1945年の空襲では延養亭などの建物が焼けました。それでも江戸時代の絵図をもとに建物や景色がよみがえり、1952年には国の特別名勝に指定されました。今も丹頂鶴が飼われ、正月には園内を歩く姿が見られます。"],"tl":[["1687年","池田綱政の命で津田永忠が工事を始める"],["1700年ごろ","ほぼ現在の形が完成"],["1871年","«後楽園» と名前が改められる"],["1884年","池田家から岡山県に譲られ、一般に公開"],["1934年","室戸台風の洪水で大きな被害"],["1945年","岡山空襲で延養亭などが焼失"],["1952年","国の特別名勝に指定"]],"who":[["池田綱政","岡山藩の2代藩主。庭を造らせ、能を愛した"],["津田永忠","岡山藩の家臣。後楽園・閑谷学校・新田開発などを手がけた"],["池田光政","綱政の父。«名君» として知られる"],["范仲淹","中国・宋の政治家。«先憂後楽» ということばを残した"]],"deep":["«後楽園» の名は范仲淹の «岳陽楼記» にある «先憂後楽» に由来するとされます。東京の小石川後楽園も同じことばから名づけられており、ルーツは同じ思想です。","園の中心にある «唯心山» は高さ約6mの築山。綱政の子・継政の時代に築かれたといわれ、登ると園全体と岡山城の天守を一度に見渡せます。","«流店（りゅうてん）» は建物の中を水路が流れるめずらしい休憩所で、江戸時代の姿を伝える建物のひとつです。床の間の代わりに水の流れと石を眺める造りです。","庭の水は旭川から引いています。園内の曲水は全長約640mほどといわれ、ゆるやかな流れが庭全体をめぐっています。","藩主は園内の «延養亭» から庭を眺めました。延養亭は空襲で焼け、1960年に再建。ふだんは非公開ですが、特別公開されることがあります。","庭の外の山や岡山城を景色に取り入れる «借景» の技法が使われています。城と庭をセットで見ることで、藩主の «ながめ» が体験できます。"],"look":["唯心山の頂上からの全景","延養亭と沢の池","水路が建物の中を流れる流店","丹頂鶴の飼育舎（正月は園内を放鳥）","月見橋から見た岡山城天守の借景"],"q":["後楽園の名前のもとになった «先憂後楽» とはどういう意味？","人々より先に心配し、人々が楽しんだ後で自分が楽しむ、という政治家の心がまえです。"],"koji":[{"w":"先憂後楽","m":"世の中の人より先に心配し、人々が楽しんだ後で楽しむこと。上に立つ者の心がまえ"}],"myth":"«後楽園» の名の由来は «岳陽楼記» とする説が一般的だが、改名の経緯には諸説。","img":["池田綱政","津田永忠","日本三名園","岡山城"],"wp":"後楽園","rel":{"ev":[],"grave":[]},"ph":[["c:4/4b/Okayama_Korakuen_Garden01.jpg",2861,1866,"後楽園"],["c:d/d4/250505_Korakuen_Okayama_Japan40s3.jpg",6000,4000],["c:f/f6/250505_Korakuen_Okayama_Japan36s3.jpg",6000,4000],["c:4/40/250505_Korakuen_Okayama_Japan30s3.jpg",6000,4000],["c:9/9e/250505_Korakuen_Okayama_Japan25s3.jpg",6000,4000],["c:c/c2/250505_Korakuen_Okayama_Japan15s3.jpg",6000,4000],["c:6/67/250505_Korakuen_Okayama_Japan14s3.jpg",6000,4000],["c:a/a6/250505_Korakuen_Okayama_Japan13s3.jpg",6000,4000]]},{"id":"33_kibitsu_jinja","n":"吉備津神社（備中一宮・鳴釜神事）","yomi":"きびつじんじゃ","cat":"寺社","rank":"S","y":1425,"era":["kofun","muromachi"],"sh":"国宝（本殿・拝殿）","ad":"岡山市北区吉備津","st":"JR吉備線（桃太郎線）吉備津駅から歩いて約10分","la":34.6724,"lo":133.8505,"hook":"鬼の首は、釜の下で今もうなっている――桃太郎伝説のふるさとに残る、ふしぎな «鳴る釜»。","lead":"吉備津神社は、備中国でいちばん格の高い «一宮» です。まつられている大吉備津彦命は、鬼の «温羅（うら）» を退治した伝説で知られ、昔話の桃太郎のモデルともいわれます。室町時代に建てられた本殿と拝殿は国宝です。","story":["むかしむかし、吉備の国に «温羅» という者が住みついていました。遠い国から来たとも、百済の王子だともいわれます。山の上に城をかまえ、人々をおそれさせていました。そこで都から派遣されたのが、大吉備津彦命です。命が弓を射ると、温羅も岩を投げて応戦し、矢と岩が空中でぶつかって落ちた――そんな話が今も語られています。","戦いの末に温羅は討たれました。ところが首だけになっても、何年もうなり声をあげ続けたといいます。困った命は、首を神社の «御竈殿（おかまでん）» の下に埋めました。ある夜、夢に温羅があらわれ、«わしの妻に釜を炊かせよ。吉なら釜が豊かに鳴り、凶なら荒々しく鳴るだろう» と告げた――これが «鳴釜神事» のはじまりと伝わります。","«本当に釜が鳴るの?»――今も御竈殿では、釜で湯をわかし、せいろの中で玄米をふるうと、ボーッという低い音が響きます。その音の大小や長さで吉凶をうらなうのです。江戸時代の上田秋成は、この神事を題材に怪談 «吉備津の釜» を書き、«雨月物語» に収めました。","神社の本殿は、室町時代の応永年間に建て直されたものです。屋根は入母屋造の屋根を前後に二つつなげたような独特の形で «吉備津造» とよばれます。巨大な本殿が、亀の甲羅のように山すそに横たわる姿は迫力満点です。","本殿から南へは、ゆるやかな坂にそって長い回廊が一直線にのびています。その長さは約360m。雨の日でもぬれずに歩けるこの回廊は、季節の花で彩られ、参拝者の目を楽しませています。鬼と神の伝説の舞台を、ゆっくり歩いてみてください。"],"tl":[["古代","大吉備津彦命が温羅を退治したと伝わる"],["平安時代","«延喜式» に名神大社として記される"],["1390年ごろ","本殿の再建工事が始まったとされる"],["1425年","本殿・拝殿が完成したとされる"],["1776年","上田秋成の «雨月物語» 刊行。«吉備津の釜» を収める"],["1952年","本殿・拝殿が国宝に指定される"]],"who":[["大吉備津彦命","神社にまつられる神。温羅を退治した伝説の主人公"],["温羅","伝説で吉備を荒らした鬼。鬼ノ城を拠点にしたといわれる"],["阿曽媛","温羅の妻と伝わる女性。鳴釜神事で釜を炊いた"],["上田秋成","江戸時代の作家。«吉備津の釜» を書いた"]],"deep":["本殿と拝殿は «吉備津造（比翼入母屋造）» で、入母屋造の屋根を前後に二つ並べた形。全国でもこの神社だけの様式とされ、1952年に国宝となりました。","再建は室町幕府3代将軍・足利義満のころに始まったと伝わり、完成は1425年とされます。着工から完成まで30年以上かかったことになります。","鳴釜神事を行う御竈殿は江戸時代の建物で、国の重要文化財。釜を炊く女性は «阿曽女（あぞめ）» とよばれ、温羅の妻・阿曽媛にちなむとされます。","回廊は約360m。天正年間（戦国時代の末）に再建されたと伝わり、地形に合わせてまっすぐ下っていくのが特徴です。","温羅伝説は、ヤマト王権が吉備の勢力を従えた歴史を物語にしたものではないか、という見方があります。吉備は古墳時代に巨大古墳を築いた強い地域でした。","桃太郎と吉備を結びつける考えは、昭和初期に広まったといわれます。«きびだんご» も、もとは «吉備団子» と «黍団子» をかけたものと考えられています。"],"look":["国宝の本殿・拝殿（吉備津造の屋根）","約360mの一直線の回廊","鳴釜神事が行われる御竈殿（申し込めば神事を受けられる）","南随神門・北随神門","回廊沿いの季節の花"],"q":["吉備津神社の «鳴釜神事» では、何で吉凶をうらなう？","釜が鳴る音の大小や長さです。音が大きく長いほど吉とされます。"],"koji":[],"myth":"温羅退治・首の埋葬・桃太郎モデル説はいずれも伝承。本殿再建の着工年には諸説。","img":["温羅","雨月物語","大吉備津彦命","吉備津造"],"wp":"吉備津神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Kibitsu_Jinja_10_cropped.jpg",2594,1765,"吉備津神社"],["c:2/22/Nakayama_Chausuyama_Kofun%2C_haisho.jpg",5876,3782],["c:d/d0/Kibitsu_Jinja_Corridor_03.JPG",2848,4288],["c:b/b1/Kibitsu_Jinja_12.JPG",4288,2848],["j:b/be/%E5%AE%87%E8%B3%80%E7%A5%9E%E7%A4%BE_%28%E5%90%89%E5%82%99%E6%B4%A5%E7%A5%9E%E7%A4%BE%E5%A2%83%E5%86%85%E7%A4%BE%29.JPG",3648,2736],["j:d/db/%E4%B8%89%E7%A4%BE%E5%AE%AE_%28%E5%90%89%E5%82%99%E6%B4%A5%E7%A5%9E%E7%A4%BE%E5%A2%83%E5%86%85%E7%A4%BE%29.JPG",3648,2736],["j:f/f8/%E5%90%89%E5%82%99%E3%81%AE%E4%B8%AD%E5%B1%B1_%28%E5%90%89%E5%82%99%E6%B4%A5%E7%A5%9E%E7%A4%BE%E3%81%8B%E3%82%89%29.JPG",3648,2736],["j:e/ed/%E6%9C%AC%E5%AE%AE%E7%A4%BE_%28%E5%90%89%E5%82%99%E6%B4%A5%E7%A5%9E%E7%A4%BE%E5%A2%83%E5%86%85%E7%A4%BE%29.JPG",3648,2736]]},{"id":"33_takamatsu_jo","n":"備中高松城跡（秀吉の水攻め）","yomi":"びっちゅうたかまつじょうあと","cat":"古戦場","rank":"S","y":1582,"era":["azuchi"],"sh":"国指定史跡","ad":"岡山市北区高松","st":"JR吉備線（桃太郎線）備中高松駅から歩いて約10分","la":34.6961,"lo":133.825,"hook":"城のまわりが一夜ごとに湖になっていく――秀吉の «水攻め» と、本能寺の変が交差した場所。","lead":"備中高松城は、低い湿地に囲まれた毛利方の城でした。1582年、羽柴（豊臣）秀吉は城のまわりに長い堤防を築いて川の水を流しこみ、城を湖の中に孤立させました。城主の清水宗治は、城兵の命と引きかえに自ら命を絶ちました。","story":["1582年の春、織田信長の命令で中国地方を攻めていた羽柴秀吉は、備中高松城の前で足止めされていました。城のまわりは沼と田んぼ。攻めこもうとすれば兵の足がぬかるみにとられ、城から弓や鉄砲で狙われます。«力で攻めてはこちらの損が大きい»。","そこで考えられたのが «水攻め» でした。城の南側に堤防を築いて足守川の水をせき止め、梅雨の雨も利用して、城の低地を水びたしにしようというのです。堤防は長さ約3km、わずか十数日で築かれたと伝わります（長さや日数には諸説あります）。やがて城は、湖に浮かぶ小島のようになりました。","城主の清水宗治は、毛利家に忠実な武将でした。城の中では食べ物が減り、助けに来た毛利輝元・吉川元春・小早川隆景の大軍も、水にはばまれて近づけません。そのころ、京都で大事件が起きていました。6月2日、本能寺の変。信長が明智光秀に討たれたのです。","知らせを受けた秀吉は、急いで毛利と和睦をまとめようとします。条件のひとつは、宗治の切腹でした。6月4日、宗治は小舟で湖に漕ぎ出し、舞を舞ったあとで切腹したと伝わります。辞世は «浮世をば 今こそ渡れ 武士の 名を高松の 苔に残して»。城兵の命は救われました。","和睦を結ぶと、秀吉の軍は京都へ向かって大急ぎで引き返します。これが «中国大返し»。そして山崎の戦いで光秀を破り、天下人への道を駆け上がっていきました。静かな城跡の公園には宗治の首塚があり、春には «宗治まつり» が行われています。"],"tl":[["1582年4月ごろ","秀吉軍が備中高松城を囲む"],["1582年5月","堤防を築いて水攻めを始める"],["1582年6月2日","京都で本能寺の変"],["1582年6月4日","清水宗治が湖上で切腹。毛利と和睦"],["1582年6月13日","秀吉が山崎の戦いで明智光秀を破る"],["現在","城跡は公園として整備され、春に «宗治まつり» が行われる"]],"who":[["清水宗治","高松城の城主。城兵を救うため切腹した"],["羽柴秀吉","水攻めで城を包囲し、本能寺の変後に «中国大返し» を行った"],["黒田官兵衛","秀吉の軍師。水攻めを進言したともいわれる"],["毛利輝元","毛利家の当主。救援に来たが水にはばまれた"],["安国寺恵瓊","毛利側の僧。和睦の交渉にあたったとされる"]],"deep":["水攻めの堤防は長さ約3km・高さ約7mとする説が有名ですが、近年は «実際には堤防は短く、自然の地形を生かした» と考える研究者もいます。規模には諸説あります。","城跡の東にある «蛙ヶ鼻（かわずがはな）築堤跡» は、堤防の一部とされる場所で、水攻めの規模を想像できる貴重な遺構です。","城は «沼城» ともいえる平城で、低湿地そのものが守りでした。その «守り» を逆手にとったのが水攻めで、秀吉はのちに紀伊の太田城・武蔵の忍城（石田三成）でも水攻めを行っています。","本能寺の変の知らせは、毛利方への密使が秀吉軍に捕まったことで秀吉が先に知った、という話がよく語られますが、これは後の軍記物に見える話で、確かではありません。","宗治の辞世の句は後世の記録に残るもので、細かな言葉に違いがある写本もあります。城跡には宗治の首塚と、胴塚とされる場所が伝わっています。","城跡の公園には池があり、夏には蓮の花が咲きます。低い湿地の上に建っていた «沼の城» の雰囲気を、今も感じることができます。"],"look":["本丸跡の清水宗治首塚","城跡の資料館（水攻めの模型）","蛙ヶ鼻の築堤跡","城跡公園の沼と蓮","近くの «宗治自刃の地» の石碑"],"q":["秀吉が高松城を落とすために使った作戦は？","城のまわりに堤防を築いて川の水を流しこむ «水攻め» です。"],"koji":[{"w":"中国大返し","m":"本能寺の変のあと、秀吉が備中から京都近くまで大軍を急いで戻したこと"}],"myth":"堤防の長さ・工期、黒田官兵衛の献策、密使捕縛の話などは諸説・軍記物由来。","img":["清水宗治","高松城の戦い","中国大返し","本能寺の変"],"wp":"高松城 (備中国)","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Bitchu_Takamatsu_castle_ruins.jpg",2272,1704,"高松城 (備中国)"],["c:1/17/251101_Takamatsu_Castle_%28Bitchu%29_Okayama_Japan05s3.jpg",5472,3648],["c:6/6f/251101_Takamatsu_Castle_%28Bitchu%29_Okayama_Japan01s3.jpg",5472,3648],["c:d/d4/Kawazugahana_Embankment_site.jpg",2272,1704],["c:3/34/Kawazugahana_Embankment_base.jpg",2272,1704],["c:f/f7/Takamatsumizuseme2.jpg",3013,1213],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/37/Takamatsumizuseme.jpg",646,315]]},{"id":"33_matsuyama_jo","n":"備中松山城（現存天守の山城）","yomi":"びっちゅうまつやまじょう","cat":"城","rank":"S","y":1683,"era":["kamakura","edo"],"sh":"国指定史跡（天守・二重櫓などは国の重要文化財）","ad":"高梁市内山下","st":"JR伯備線 備中高梁駅から車・乗合タクシー等で «ふいご峠» へ、そこから山道を歩いて約20分","la":34.8089,"lo":133.6224,"hook":"雲の海に浮かぶ «天空の山城»。江戸時代から残る天守の中で、いちばん高い場所に建っている。","lead":"備中松山城は、臥牛山（がぎゅうざん）の上に建つ山城です。天守は江戸時代から残る «現存12天守» のひとつで、その中でいちばん高い、標高約430mの場所にあります。秋から冬の朝には、城が雲海に浮かんで見えることがあります。","story":["牛が寝そべったような形の臥牛山。その山に最初に城を築いたのは、鎌倉時代の秋庭三郎重信だと伝わります。やがて城は山全体に広がり、戦国時代には毛利氏や三村氏などが奪いあう、備中の重要な拠点になりました。«ここを押さえれば、備中の道が押さえられる»。","関ヶ原の戦いのあと、備中の国奉行としてこの城に入ったのが小堀正次・政一の父子です。政一はのちの茶人・小堀遠州。城の修理にもかかわったと伝わります。","今に残る天守は、1683年ごろ、藩主の水谷勝宗が大きく修築したときのものと考えられています。二重二階の小さな天守ですが、岩山の上にどっしりと建つ姿は見事です。天守の中には «囲炉裏» があり、籠城のときの暖をとるためとも、城主の住まいとも考えられています。","幕末、この城の藩主は板倉勝静でした。勝静は江戸幕府の老中として幕府の最後の時代を支えます。その下で借金だらけの藩の財政を立て直したのが、農民出身の学者・山田方谷でした。方谷は «義を明らかにして利を計らず» の考えで改革を進め、藩を豊かにしたといわれます。","明治になって城は使われなくなり、天守は長く放置されて傷んでいきました。昭和のはじめ、地元の人々が «城を守ろう» と声をあげ、修理が行われます。平成にも大きな修理がされ、今では雲海の城としても、城で暮らす猫の «城主» としても人気を集めています。"],"tl":[["1240年","秋庭三郎重信が臥牛山に城を築いたと伝わる"],["戦国時代","三村氏・毛利氏などが城をめぐって争う"],["1600年ごろ","小堀正次・政一が国奉行として入る"],["1683年ごろ","水谷勝宗が天守などを修築"],["1873年","廃城令で城が廃止される"],["1940年","地元の人々の努力で天守が修理される"],["1941年","天守などが国宝（旧制度）に指定。のち重要文化財に"]],"who":[["秋庭三郎重信","鎌倉時代に最初に城を築いたと伝わる武士"],["小堀政一（遠州）","関ヶ原後に国奉行として在城。のちの大茶人"],["水谷勝宗","天守を修築した藩主"],["板倉勝静","幕末の藩主で、江戸幕府の老中"],["山田方谷","板倉家に仕え、藩の財政を立て直した学者"]],"deep":["現存12天守の中で最も高い標高約430mにあり、天守の高さそのものは約11mと小さめ。«小さいけれど、いちばん高い» 天守です。","大手門跡の周辺では、自然の岩盤の上に直接石垣を積んだ «岩盤と石垣の一体化» が見られます。山城ならではの迫力ある景観です。","天守の中には囲炉裏があり、天守に囲炉裏があるのは全国でも珍しいとされます。また «装束の間» という部屋があり、城主が籠城のときに身を置く場所だったといわれます。","城の遺構は «小松山» の山頂部が中心ですが、北の «大松山» にも中世の城跡が残ります。山全体が中世から近世にかけての城の歴史をもっています。","山田方谷の改革では、藩札の信用回復のため、古い藩札を人々の前で焼いて見せたと伝わります。藩の借金10万両を返したといわれますが、数字には諸説あります。","城下の高梁市は «備中の小京都» と呼ばれ、武家屋敷や頼久寺（小堀遠州作と伝わる庭園）などが残ります。"],"look":["現存天守と二重櫓（重要文化財）","大手門跡の岩盤の上の石垣","天守内の囲炉裏と装束の間","雲海展望台からの眺め（秋〜冬の早朝）","城下の武家屋敷と頼久寺"],"q":["備中松山城の天守は、現存する天守の中でどんな特徴がある？","いちばん高い場所（標高約430m）にある天守です。"],"koji":[{"w":"義を明らかにして利を計らず","m":"正しい道をはっきりさせれば、利益は後からついてくるという考え。山田方谷の改革の柱"}],"myth":"築城者・築城年は伝承。天守修築年や方谷の返済額には諸説。","img":["臥牛山","山田方谷","板倉勝静","現存天守"],"wp":"備中松山城","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E2.jpg",4032,3024,"備中松山城"],["c:6/63/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E%E7%9F%B3%E5%9E%A32.jpg",5712,4284],["c:0/0b/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E%E7%9F%B3%E5%9E%A3.jpg",5712,4284],["c:c/c2/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E%E5%A4%A9%E5%AE%88.jpg",5712,4284],["c:5/54/%E3%81%95%E3%82%93%E3%81%98%E3%82%85%E3%83%BC%E3%82%8D%E3%83%BC.jpg",4416,2944],["c:6/6d/Matsuyama_Castle90a129.jpg",3167,2446],["c:5/59/Bitchu_Matsuyama_Castle_observatory202201-1.jpg",2048,1536],["c:f/f5/Bitchu_Matsuyama_Casle_observatory202111-1.jpg",2048,1478]]},{"id":"33_tsukuriyama","n":"造山古墳（全国第4位の巨大古墳）","yomi":"つくりやまこふん","cat":"遺跡","rank":"S","y":430,"era":["kofun"],"sh":"国指定史跡","ad":"岡山市北区新庄下","st":"JR吉備線（桃太郎線）備中高松駅から歩いて約30分。車が便利（駐車場あり）","la":34.6865,"lo":133.7757,"hook":"全国4位の大きさなのに、てっぺんまで自由に歩いて登れる。«吉備の大王» の墓の上に立ってみよう。","lead":"造山古墳は、長さ約350mの巨大な前方後円墳です。大きさは全国で4番目。5世紀のはじめごろ、吉備の国の王のために造られたと考えられています。天皇陵として管理されている巨大古墳とちがい、墳丘に自由に登ることができます。","story":["古墳時代、日本でいちばん大きな古墳が集まるのは、大阪や奈良の «畿内» でした。ところが、全国の大きさランキングで4番目に顔を出すのが、この岡山の造山古墳です。上位3つはいずれも大阪府の古墳。«なぜ、吉備にこんなに大きな古墳が?»――それは、吉備の王がヤマトの大王と肩をならべるほどの力をもっていたからだと考えられています。","古墳の長さは約350m。後ろの丸い部分（後円部）の高さは約30mもあります。これだけの土を人の手で運び、形を整え、斜面に石を敷きつめたのです。完成までに何年もかかり、何千人もの人が働いたことでしょう。","墳丘の上に立つと、足守川の流れる平野が一望できます。王は、自分の治めた土地を見下ろす場所に眠ったのかもしれません。まわりには «陪塚（ばいちょう）» とよばれる小さな古墳がいくつも寄りそっており、家来や一族の墓と考えられています。","戦国時代には、この古墳が城として使われたこともありました。1582年の備中高松城の戦いのころ、古墳の上に陣地が置かれたといわれ、墳丘の形が一部変えられています。1600年以上前の王の墓が、戦国武将の砦にもなったのです。","前方部の上には、なぜか石棺がひとつ置かれています。調べてみると、この石は遠く九州・熊本の阿蘇の石だとわかりました。いつ、どこから運ばれてここに置かれたのか、今もはっきりしていません。古墳は、今も多くのなぞを抱えて静かに眠っています。"],"tl":[["5世紀前半","造山古墳が築かれたと考えられる"],["5世紀","周辺に陪塚の千足古墳・榊山古墳などが築かれる"],["1582年ごろ","高松城の戦いに関連して陣地が置かれたといわれる"],["1921年","国の史跡に指定される"],["2010年代","岡山市による発掘調査が進められる"]],"who":[["吉備の大王","古墳の主と考えられる、名前の伝わらない吉備の王"],["大吉備津彦命","吉備を平定したと伝わる神。古墳と結びつける伝承もある"],["羽柴秀吉","高松城攻めのころ、周辺に陣を構えた"],["近藤義郎","吉備の古墳研究を進めた考古学者"]],"deep":["墳丘長約350mは全国第4位。上位3基（大仙陵・誉田御廟山・上石津ミサンザイ）はすべて天皇陵に治定されて立ち入れないため、«自由に登れる古墳としては日本最大級» とよくいわれます。","前方部にある刳抜式の石棺は、阿蘇の溶結凝灰岩製とされます。もとは陪塚などにあったものが運ばれてきたという説があり、造山古墳の埋葬施設そのものかどうかはわかっていません。","陪塚の千足古墳の石室には、«直弧文» という複雑な文様を刻んだ石障がありました。九州の古墳と共通する特徴で、吉備と九州の交流を物語ります。","後円部の上には荒神社が建っています。古墳の上に神社がある例は各地にあり、古墳が地域の信仰の場として守られてきたことがわかります。","古墳の年代は、出土した埴輪から5世紀前半と考えられます。ヤマトの大王墓と同じ頃に、それに近い大きさの古墳が吉備で造られた点が大事なポイントです。","近くには全国第10位の作山古墳もあります。わずかな時間差で巨大古墳が続けて造られたことから、吉備の勢力の大きさがうかがえます。"],"look":["後円部の頂上からの眺め（足守川の平野）","前方部の上に置かれた阿蘇石の石棺","後円部の荒神社","まわりの陪塚（千足古墳など）","戦国時代の陣地の跡とされる平らな部分"],"q":["造山古墳は、全国で何番目に大きい古墳？","4番目です。上位3つはすべて大阪府にあります。"],"koji":[],"myth":"被葬者は不明。戦国期の陣城利用、石棺の由来には諸説。","img":["前方後円墳","作山古墳","千足古墳","吉備国"],"wp":"造山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/Tsukuriyama_Kofun%2C_Okayama_air.jpg",881,824,"造山古墳"],["c:9/92/Tsukuriyamakofun02.jpg",5472,3648],["c:2/2a/Tsukuriyamakofun01.jpg",5472,3648],["c:8/81/Tsukuriyama_Kofun_%28Okayama%29%2C_zenkei.jpg",5976,3938],["c:8/82/Tsukuriyama_Kofun_%28Okayama%29%2C_sekkan-2.jpg",6016,4000],["c:0/0d/Tsukuriyama_Kofun_%28Okayama%29%2C_sekkan-1.jpg",6016,4000],["c:4/42/Tsukuriyama_4th_Monund.JPG",4288,2848],["c:e/e8/Tsukuriyama_3rd_Monund.JPG",4288,2848]]},{"id":"33_kinojo","n":"鬼ノ城（温羅伝説の古代山城）","yomi":"きのじょう","cat":"遺跡","rank":"S","y":670,"era":["asuka"],"sh":"国指定史跡","ad":"総社市奥坂","st":"JR総社駅から車で約25分（鬼城山ビジターセンターに駐車場）。公共交通では行きにくい","la":34.7231,"lo":133.7625,"hook":"鬼が住んだという山の上に、長さ約2.8kmの城壁。だれが、なんのために造ったのか、歴史書は何も語らない。","lead":"鬼ノ城は、総社市の鬼城山（標高約400m）の上にある古代の山城です。7世紀後半ごろ、外国からの攻撃にそなえて造られたと考えられています。吉備津彦命に退治された鬼 «温羅» の城だったという伝説があります。","story":["鬼城山の山頂近くまで登ると、急に視界がひらけ、どっしりとした木造の門があらわれます。これは発掘の成果をもとに復元された «西門»。その横には、土を何層にもつき固めた城壁が、山のへりをぐるりと取り囲んでいます。«ここは、ほんとうに鬼の城?»","伝説では、この山に住んでいたのは «温羅» という鬼でした。温羅は村をおそい、人々を苦しめたため、都から大吉備津彦命がやってきて戦った、と語られます。温羅の血が流れた川が赤く染まった、という «血吸川» の名も近くに残っています。","しかし考古学者たちが調べると、別の姿が見えてきました。城壁の造り方や門の形は、朝鮮半島の山城によく似ていたのです。663年、日本は白村江の戦いで唐と新羅の軍に大敗しました。«次は日本が攻められるかもしれない»――そう恐れた朝廷は、九州から瀬戸内にかけて山城を築きました。鬼ノ城も、そのひとつと考えられています。","ふしぎなのは、«日本書紀» などの歴史書に、鬼ノ城の名前がまったく出てこないことです。大野城や屋嶋城のように記録に残る山城とちがい、鬼ノ城はいつ、だれが造ったのか、書き残されていません。だからこそ、鬼の伝説が生まれ、語りつがれてきたのかもしれません。","城壁の上を歩くと、南には総社や岡山の平野、遠くに瀬戸内海まで見渡せます。敵の船が来れば、すぐに見つけられたでしょう。1300年以上前、この景色を見張っていた兵士たちの気持ちを想像しながら、一周約2.8kmの城壁をたどってみてください。"],"tl":[["663年","白村江の戦いで倭国が大敗"],["7世紀後半","鬼ノ城が築かれたと考えられる"],["1970年代","城壁の存在が注目され、調査が始まる"],["1986年","国の史跡に指定される"],["2000年代","発掘成果をもとに西門や城壁の一部が復元される"]],"who":[["温羅","伝説で鬼ノ城に住んだとされる鬼。百済の王子だったとの話も"],["大吉備津彦命","温羅を退治したと伝わる神"],["天智天皇","白村江の敗戦後、各地に山城を築かせた（中大兄皇子）"],["阿曽媛","温羅の妻と伝わる。地元の阿曽の里に名が残る"]],"deep":["城壁の全長は約2.8km。土をつき固めた «版築» の土塁と、石垣を組み合わせて造られています。","城門は4か所、水門は6か所見つかっています。城内の水を外に流す水門が多いのは、雨の多い山の上で城壁を守るためと考えられます。","城門の近くでは、敷石が並べられた通路が見つかっています。こうした敷石は朝鮮半島の山城に見られる特徴とされます。","«日本書紀» に記録のある古代山城は大野城・基肄城・屋嶋城・高安城などですが、鬼ノ城は記録に出てきません。記録のない山城は «神籠石系山城» ともよばれ、築城の経緯は諸説あります。","城内からは倉庫と考えられる建物の跡や、鍛冶の跡も見つかっています。単なる見張り台ではなく、兵をとどめ、武器を作る拠点でもあったようです。","温羅伝説は、平安時代以降に形づくられたものと考えられ、史実の城とは別の «物語の城» として語られてきました。"],"look":["復元された西門と角楼","版築土塁の断面（ビジターセンターの展示）","敷石の通路と水門跡","城壁上からの岡山平野・瀬戸内海の眺め","鬼城山ビジターセンターの展示"],"q":["鬼ノ城のような古代山城が、7世紀後半に西日本に造られたきっかけは？","663年の白村江の戦いで敗れ、唐や新羅に攻められることを恐れたからです。"],"koji":[],"myth":"温羅の城という話は伝説。築城年・築城者は記録がなく推定。","img":["温羅","白村江の戦い","古代山城","神籠石"],"wp":"鬼ノ城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a5/Kinojo%2C_enkei-2.jpg",4327,2877,"鬼ノ城"],["c:2/20/%E9%AC%BC%E3%83%8E%E5%9F%8E%E8%A7%92%E6%A5%BC.jpg",3888,2592],["c:a/a7/%E9%AC%BC%E3%83%8E%E5%9F%8E%E8%A5%BF%E9%96%80.jpg",3888,2592],["c:0/05/%E9%AC%BC%E3%83%8E%E5%9F%8E%E7%AC%AC%E4%BA%8C%E6%B0%B4%E9%96%80.jpg",2592,3888],["c:6/6a/%E9%AC%BC%E3%83%8E%E5%9F%8E%E7%9F%B3%E5%9E%A3.jpg",3888,2592],["c:f/f8/%E9%AC%BC%E3%83%8E%E5%9F%8E%E3%82%92%E6%9C%9B%E3%82%80%EF%BC%88%E5%8D%97%E9%BA%93%E3%82%88%E3%82%8A%EF%BC%89.jpg",3072,2304],["c:c/cb/%E6%B0%B4%E5%9F%8E%E7%8A%B6%E9%81%BA%E6%A7%8B%E3%82%92%E6%9C%9B%E3%82%80%EF%BC%88%E5%9F%8E%E5%86%85%E3%82%88%E3%82%8A%EF%BC%89%EF%BC%92.jpg",3072,2304],["c:f/f4/%E6%B0%B4%E5%9F%8E%E7%8A%B6%E9%81%BA%E6%A7%8B%E3%82%92%E6%9C%9B%E3%82%80%EF%BC%88%E5%9F%8E%E5%86%85%E3%82%88%E3%82%8A%EF%BC%89%EF%BC%91.jpg",3072,2304]]},{"id":"33_shizutani","n":"旧閑谷学校（最古の庶民の学校）","yomi":"きゅうしずたにがっこう","cat":"学び","rank":"S","y":1670,"era":["edo"],"sh":"国指定特別史跡（講堂は国宝）","ad":"備前市閑谷","st":"JR赤穂線 吉永駅からタクシーで約10分（歩くと約1時間）","la":34.788,"lo":134.2155,"hook":"武士でなくても学べる学校を――350年前の殿様の願いが、赤い瓦の講堂に今も宿る。","lead":"旧閑谷学校は、岡山藩主・池田光政が1670年に始めた、庶民のための学校です。武士だけでなく、村の子どもたちも学ぶことができました。備前焼の瓦をのせた講堂は国宝で、学校全体が国の特別史跡になっています。","story":["江戸時代、学校といえば武士の子が通う «藩校» が中心でした。ところが岡山藩主・池田光政は、«村の人々にも学問が必要だ» と考えました。光政は儒学を重んじ、人として正しく生きる道を教えることが国を豊かにすると信じていたのです。","光政は領内の山あいを見まわり、«ここは静かで、学ぶのによい場所だ» と、閑谷の地を選んだと伝わります。工事をまかされたのは、後楽園や新田開発でも活躍した家臣・津田永忠でした。永忠は光政が亡くなったあとも工事を続け、30年以上かけて学校を完成させます。","学校の中心となる講堂は1701年に完成しました。屋根には備前焼の瓦がふかれ、夕日を浴びると赤くかがやきます。床は拭きこまれて鏡のように光り、窓からの光がうつりこみます。«なぜこんなに丈夫なの?»――永忠は、長く使えるように、雨水が流れやすい屋根や、腐りにくい建材などを工夫しました。","学校をぐるりと囲むのは、かまぼこのような形をした石塀です。長さは約765m。きれいに整えられた石が、すき間なく組まれています。この塀は火事や動物から学校を守るとともに、«学問の場» を区切る意味もあったのでしょう。","閑谷学校では、明治以降も学校として教育が続けられ、今も高校にその流れが受けつがれています。秋には、中国の孔子の墓から持ってきた種を育てた «楷（かい）の木» が赤や黄色に色づき、多くの人がおとずれます。"],"tl":[["1668年","池田光政が領内に手習所を多く置く"],["1670年","閑谷に学校を開くことを決め、工事が始まる"],["1682年","池田光政が亡くなる"],["1701年","講堂が完成（現在の建物）"],["1953年","講堂が国宝に指定される"],["1954年","国の特別史跡に指定される"],["2015年","日本遺産 «近世日本の教育遺産群» に認定"]],"who":[["池田光政","岡山藩主。庶民のための学校をつくった"],["津田永忠","工事を指揮した家臣。講堂や石塀を築いた"],["池田綱政","光政の子。父の遺志を継いで学校を守った"],["孔子","中国の思想家。学校の聖廟にまつられる"]],"deep":["講堂は1701年の完成。内部は «火灯窓» とよばれる曲線の窓が並び、柱や床は漆塗りで、日光が床に反射する美しさで知られます。","屋根の備前焼の瓦は、雨に強く割れにくい。釉薬を使わずに高温で焼きしめた備前焼の特長を、建築に生かした例です。","石塀（かまぼこ形石塀）は長さ約765m。表面をなめらかに加工した石が組まれ、築かれて300年以上たった今もほとんど崩れていないといわれます。","学校の東には、光政をまつる «閑谷神社»（旧芳烈祠）と、孔子をまつる «聖廟» が並びます。儒学の教えと、学校の創設者への敬意が形になっています。","楷の木は、大正時代に中国・曲阜の孔子の墓所から持ち帰った種を育てたものとされ、«学問の木» として知られます。","学校の裏にある «火除山» は、火事が燃え広がらないように人工的に築かれた小山。«椿山» には光政の髪や爪などを納めた供養塚があるとされます。"],"look":["国宝の講堂（床にうつる光）","備前焼瓦の屋根","かまぼこ形の石塀","聖廟と閑谷神社","秋の楷の木の紅葉"],"q":["閑谷学校の講堂の屋根にふかれている瓦は何焼？","備前焼です。雨に強く割れにくい、丈夫な瓦です。"],"koji":[],"myth":"光政が自ら閑谷の地を選んだという話は伝承。","img":["池田光政","津田永忠","備前焼","楷"],"wp":"閑谷学校","rel":{"ev":[],"grave":[]},"ph":[["c:d/d0/Shizutani_school_the_hall_and_shosai.JPG",2240,1488,"閑谷学校"],["c:1/12/SHIZUTANI-_tile02.jpg",4608,3456],["c:b/be/Shizutani_at_night_10.JPG",4288,2848],["c:c/c7/Shizutani_at_night_04.JPG",4288,2848],["c:7/7b/Shizutani_at_night_03.JPG",4288,2848],["c:e/ee/Shizutani_at_night_02.JPG",4288,2848],["c:c/cd/SHIZUTANI-_tile01.jpg",3264,2448],["c:e/e6/SHIZUTANI-Museum-01.jpg",3264,2448]]},{"id":"33_bikan","n":"倉敷美観地区（天領の町並み）","yomi":"くらしきびかんちく","cat":"町","rank":"S","y":1642,"era":["edo","meiji","showa"],"sh":"国の重要伝統的建造物群保存地区","ad":"倉敷市本町・中央","st":"JR倉敷駅から歩いて約10分","la":34.5955,"lo":133.7716,"hook":"白壁の蔵、柳の並木、川を行く小舟。ここはかつて、幕府が直接治めた «天領» の町だった。","lead":"倉敷美観地区は、白い壁と黒い瓦の蔵が倉敷川にそって並ぶ、古い町並みです。江戸時代、倉敷は幕府が直接治める «天領» で、年貢の米や綿を運ぶ港町として栄えました。明治以降は紡績の町となり、今も江戸・明治の建物が多く残っています。","story":["«倉敷» という名前は、«倉屋敷» がたくさんある町、という意味だといわれます。江戸時代、このあたりの海は干拓で陸地になり、とれた米や綿を集めて船で運ぶ拠点として、倉敷川沿いに蔵が建ち並びました。","倉敷は幕府が直接治める «天領» でした。1746年には代官所が置かれ、備中などの天領を治める中心になります。商人たちは力をつけ、なかでも大きな力をもった家は «古禄（ころく）» とよばれました。やがて新しく力をつけた商人 «新禄» と、町の主導権をめぐって争うようになります。","1866年、幕末の動乱のさなか、長州藩の «第二奇兵隊» を脱走した兵たちが倉敷代官所を襲い、焼き払うという事件が起きました。«倉敷浅尾騒動» とよばれるこの事件は、静かな商人の町にも時代の嵐がおしよせたことを物語っています。","明治になると、代官所の跡地に «倉敷紡績» の工場が建てられます。この会社を大きく育てたのが大原孫三郎でした。孫三郎は «会社の利益は地域と社会に返すもの» と考え、病院や研究所、そして大原美術館をつくります。町の景観を守ることにも心をくばりました。","«なぜ倉敷の町並みは残ったの?»――戦後、古い建物が次々と壊される中で、倉敷の人々は «町並みは町の宝» と考え、保存運動を進めました。1979年には国の重要伝統的建造物群保存地区に選ばれます。紡績工場の赤レンガの建物も «倉敷アイビースクエア» としてよみがえり、今も町の顔になっています。"],"tl":[["1642年","倉敷が幕府の直轄地（天領）となる"],["1746年","倉敷代官所が置かれる"],["1866年","第二奇兵隊の脱走兵が代官所を襲撃（倉敷浅尾騒動）"],["1888年","倉敷紡績が設立される"],["1930年","大原美術館が開館"],["1974年","紡績工場を改修した «倉敷アイビースクエア» 開業"],["1979年","国の重要伝統的建造物群保存地区に選定"]],"who":[["大原孫三郎","倉敷紡績の社長。大原美術館などをつくり町の発展を支えた"],["大原總一郎","孫三郎の子。町並み保存に力を注いだ"],["児島虎次郎","画家。大原美術館の名画を集めた"],["大橋家","江戸時代後期の豪商。住宅が国の重要文化財として残る"]],"deep":["«天領» になったのは1642年とされ、それ以前は備中松山藩などの領地でした。代官所の設置は1746年で、その跡地は今のアイビースクエア付近です。","白壁の下半分に見られる格子模様は «なまこ壁»。平たい瓦を壁に貼りつけ、目地を漆喰で盛り上げたもので、雨や火事から蔵を守る工夫です。","倉敷の町家の窓には «倉敷窓» とよばれる格子の窓や、«倉敷格子» と呼ばれる細い格子が見られ、町の個性になっています。","大橋家住宅は1796年の建築とされ、国の重要文化財。長屋門をもつ豪壮な町家で、商人でありながら武家屋敷のような門を構えたことに、豪商の力が表れています。","倉敷川はかつて児島湾へ通じる運河で、川舟が荷物を運びました。今は観光の川舟流しが行われ、江戸時代の «舟運の町» の姿を体感できます。","倉敷浅尾騒動では、代官所に加えて浅尾藩の陣屋も襲われました。幕末の長州藩の内部事情と、倉敷の地域社会が交差した事件です。"],"look":["倉敷川沿いの白壁となまこ壁の蔵","大橋家住宅（重要文化財）","倉敷アイビースクエア（赤レンガの紡績工場跡）","川舟流し","本町通りの町家と倉敷格子"],"q":["江戸時代、倉敷は誰が直接治める土地だった？","江戸幕府です。幕府が直接治める土地を «天領» といいます。"],"koji":[],"myth":"«倉敷» の地名の由来は諸説。","img":["倉敷紡績","大原孫三郎","倉敷アイビースクエア","大原美術館"],"wp":"倉敷美観地区","rel":{"ev":[],"grave":[]},"ph":[["c:c/cb/Kurasiki_morning01.JPG",4608,3072,"倉敷美観地区"],["c:f/fb/%E5%80%89%E6%95%B7%E7%BE%8E%E8%A6%B3%E5%9C%B0%E5%8C%BA5.jpg",4032,3024],["c:a/a4/%E5%80%89%E6%95%B7%E7%BE%8E%E8%A6%B3%E5%9C%B0%E5%8C%BA3.jpg",4032,3024],["c:b/b1/%E5%80%89%E6%95%B7%E7%BE%8E%E8%A6%B3%E5%9C%B0%E5%8C%BA2.jpg",4032,3024],["c:e/e7/%E5%80%89%E6%95%B7%E7%BE%8E%E8%A6%B3%E5%9C%B0%E5%8C%BA.jpg",4032,3024],["c:b/b8/Kurashikikahan01bs4592.jpg",4592,3056],["c:5/5d/Kurashiki_Ivy_Square23s.jpg",4592,3056],["c:8/88/211203_Yurinso_Villa_Kurashiki_Okayama_pref_Japan01s3.jpg",4912,3264]]},{"id":"33_tsuyama_jo","n":"津山城（森忠政の石垣の城）","yomi":"つやまじょう","cat":"城","rank":"S","y":1616,"era":["edo"],"sh":"国指定史跡","ad":"津山市山下","st":"JR津山駅から歩いて約10分","la":35.0658,"lo":134.0036,"hook":"天守も櫓もないのに、見上げると息をのむ。三段に積み上がった石垣そのものが «城» なのだ。","lead":"津山城は、森蘭丸の弟・森忠政が1603年から13年かけて築いた城です。建物は明治時代にほとんど取りこわされましたが、何段にも重なる高い石垣が残り、«石垣の城» として知られています。春には約1000本の桜が咲き、お花見の名所です。","story":["本能寺の変で、織田信長とともに討ち死にした森蘭丸。その弟の森忠政は、兄たちを次々に戦で失い、ただひとり生き残った «森家の末っ子» でした。関ヶ原の戦いのあと、忠政は美作一国をあたえられ、新しい城を築くことになります。","選んだのは、吉井川と宮川が合流する小高い丘 «鶴山»。忠政は丘の名を «津山» と改め、1603年に工事を始めました。城は丘の頂上から三段、四段と石垣を重ねる «一二三段» の造り。下から見上げると、石の壁が空に向かってそびえたつように見えます。","完成したのは1616年。じつに13年がかりでした。天守は四重五階、ほかに60をこえる櫓があったといわれ、建物の数は姫路城にもおとらないほどでした。«なぜこんなに守りを固めたの?»――西国には、関ヶ原で敗れた側の大名がまだ多く、徳川方の大名として、西への備えを担っていたとも考えられています。","しかし森家は、4代目で跡継ぎが絶え、1697年に領地を取り上げられてしまいます。そのあとは越前松平家の一族が入り、明治まで津山を治めました。城下町は美作の中心として栄え、洋学者の宇田川家や箕作家など、多くの学者も生まれています。","明治になり、城は «もう必要ない» とされ、建物はすべて取りこわされました。それでも石垣は残り、今は «鶴山公園» として市民に親しまれています。2005年には、城の築城400年を記念して «備中櫓» が木造で復元されました。石垣の上に立つと、城下町と中国山地の山々が見わたせます。"],"tl":[["1603年","森忠政が鶴山で築城を始める"],["1616年","津山城が完成"],["1697年","森家が断絶し、越前松平家が城主に"],["1873年","廃城が決まり、建物が取りこわされる"],["1963年","国の史跡に指定される"],["2005年","備中櫓が木造で復元される"]],"who":[["森忠政","城を築いた初代津山藩主。森蘭丸の弟"],["森蘭丸（成利）","信長の小姓。本能寺の変で討ち死にした忠政の兄"],["松平長矩（宣富）","森家のあとに津山に入った越前松平家の藩主"],["宇田川榕菴","津山藩の蘭学者。«酸素» «水素» などの言葉を作った"]],"deep":["石垣の高さは、場所によって10mをこえます。本丸・二の丸・三の丸と段を重ねる «一二三段» の構えで、総高さは約45mともいわれます。","天守は四重五階で、破風などの飾りが少ない «質実剛健» な姿だったと、明治の古写真から知られています。","備中櫓の名は、鳥取藩主・池田備中守長幸にちなむといわれます。長幸は忠政の娘婿で、その来訪にちなんで名づけたという説があります。","城跡には «忠政が石垣を積ませた際に、石工が見事な腕をふるった» という話が残りますが、細かな逸話の多くは伝承です。","«さくら名所100選» に選ばれ、春の «津山さくらまつり» には夜のライトアップが行われます。","津山藩からは宇田川玄随・玄真・榕菴や箕作阮甫などの洋学者が出ました。城下の «津山洋学資料館» でその業績を見られます。"],"look":["三段に重なる «一二三段» の石垣","木造で復元された備中櫓（内部公開）","天守台からの城下町の眺め","春の桜とライトアップ","城下の城東町並み保存地区"],"q":["津山城を築いた森忠政は、本能寺の変で亡くなったある有名な人の弟。それはだれ？","織田信長の小姓・森蘭丸です。"],"koji":[],"myth":"備中櫓の名の由来は諸説。","img":["森忠政","森成利","津山藩","鶴山公園"],"wp":"津山城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c1/%E6%B4%A5%E5%B1%B1%E5%9F%8E%E5%82%99%E4%B8%AD%E6%AB%93.jpg",1150,765,"津山城"],["c:e/e6/Tsuyama_castle_mogitenshu.JPG",4608,3456],["c:2/20/Tsuyama_Castle08s5s4272.jpg",4272,2848],["c:0/09/Tsuyama_Castle02n3200.jpg",4200,2800],["c:c/c1/%E6%B4%A5%E5%B1%B1%E5%9F%8E_%E5%82%99%E4%B8%AD%E6%AB%93%E3%81%A8%E6%A1%9C.jpg",3872,2592],["c:c/cc/Tuyama_castle_uratetumon.JPG",3072,2304],["c:1/1e/Tuyama_castle_tensyudai.JPG",3072,2304],["c:0/02/Tsuyama_castle_tensyunaibu.JPG",3072,2304]]},{"id":"33_tatetsuki","n":"楯築遺跡（弥生の巨大墳丘墓）","yomi":"たてつきいせき","cat":"遺跡","rank":"S","y":200,"era":["yayoi"],"sh":"国指定史跡","ad":"倉敷市矢部","st":"JR岡山駅から車で約30分。«王墓の丘史跡公園» の駐車場から歩いてすぐ","la":34.6628,"lo":133.7542,"hook":"丘の上に立つ巨石の輪。その下に眠るのは、古墳が生まれる前の «吉備の王»。","lead":"楯築遺跡は、弥生時代の終わりごろ（2世紀後半〜3世紀前半）につくられた、大きな王の墓です。円い丘の両側に四角い張り出しがついた形で、全長は約80mと推定されます。この墓で使われた土器が、のちの古墳の埴輪のもとになったと考えられています。","story":["倉敷市の住宅地の近く、小高い丘の上に、人の背よりも高い大きな石がいくつも立っています。«まるでストーンヘンジみたい»。この場所こそ、弥生時代の王の墓・楯築遺跡です。","地元には、こんな言い伝えがあります。大吉備津彦命が鬼の温羅と戦ったとき、この丘に石の楯を築いて、飛んでくる岩を防いだ――それで «楯築» というのだ、と。立ち並ぶ巨石は、その楯だというのです。","1976年から岡山大学の近藤義郎さんたちが発掘を始めると、おどろくべきことがわかりました。丘の中心から木の棺が見つかり、その底には真っ赤な «朱» が厚く敷きつめられていたのです。量は30kg以上ともいわれます。棺の中には、玉の首飾りや鉄の剣も納められていました。","さらに、墓の上からは «特殊器台» «特殊壺» という大きな土器が見つかりました。複雑な文様がほどこされたこれらの土器は、やがて古墳の «円筒埴輪» へと変わっていったと考えられています。«古墳のルーツは吉備にある?»――楯築は、日本の歴史の大きななぞにせまる遺跡なのです。","丘の上の小さな祠には、ご神体として «亀石» とよばれる石がまつられています。表面には、帯をねじったような «弧帯文» がびっしりと刻まれ、国の重要文化財です。見学するには、祠の格子ごしにのぞくことができます。王の魂をしずめる力があると信じられていたのかもしれません。"],"tl":[["2世紀後半〜3世紀前半","楯築墳丘墓がつくられる"],["江戸時代","丘の上の祠で «亀石» がまつられる（楯築神社）"],["1976年","岡山大学による発掘調査が始まる"],["1981年","国の史跡に指定される"],["1989年ごろ","主な発掘調査が終わる"]],"who":[["吉備の王","墓に眠る人物。名前は伝わらない"],["大吉備津彦命","伝説で、ここに石の楯を築いたとされる神"],["温羅","伝説で吉備津彦命と戦った鬼"],["近藤義郎","岡山大学の考古学者。発掘調査を率いた"]],"deep":["墳丘は円丘部の径約43m、両側の突出部を含めた全長は約80mと推定されます。北東の突出部は団地造成などで失われ、南西側も一部しか残っていません。","中心の木棺の下の朱は30kg以上とされ、ほかに例がないほどの量です。朱（水銀朱）は魔除けや死者をまもる力があると考えられていました。","«特殊器台» は高さ1m前後に達するものもある大型の土器で、吉備地方の弥生墳丘墓に特徴的です。奈良の箸墓古墳などからも吉備系の特殊器台が見つかり、吉備とヤマトのつながりを示します。","«弧帯文石»（亀石）は、楯築神社のご神体として伝えられてきた石で、全面に弧帯文が刻まれています。発掘では同じ文様の石の破片も墓から見つかりました。","墳丘上の巨石（立石）は5つほど。墓を囲む結界の役割とも考えられますが、意味ははっきりしていません。","楯築の «双方中円» という形は、前方後円墳の成り立ちを考えるうえで大事な手がかりとされますが、直接のつながりについては議論が続いています。"],"look":["丘の上の巨大な立石","楯築神社の祠（格子ごしに亀石の姿）","円丘部の頂上からの眺め","近くの «王墓山» 遺跡群","倉敷考古館・岡山大学の展示（出土品の複製など）"],"q":["楯築遺跡から見つかった特殊器台は、のちに何に変わっていったと考えられている？","古墳に並べられた «円筒埴輪» です。"],"koji":[],"myth":"石の楯を築いたという話は伝承。全長・朱の量は推定値で文献により差がある。","img":["弥生時代","特殊器台","墳丘墓","温羅"],"wp":"楯築遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Tatetsuki_Funkyu-bo%2C_funcho.jpg",5886,3794,"楯築遺跡"],["c:b/b9/Sentaimonseki01.jpg",3648,5472],["j:8/8e/%E6%A5%AF%E7%AF%89%E5%A2%B3%E4%B8%98%E5%A2%93_%E5%87%BA%E5%9C%9F%E5%93%81.JPG",5253,3635],["j:7/77/%E6%A5%AF%E7%AF%89%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E6%97%8B%E5%B8%AF%E6%96%87%E7%9F%B3_%28%E6%A8%A1%E9%80%A0%29.JPG",4487,3224],["j:6/6e/%E6%A5%AF%E7%AF%89%E5%A2%B3%E4%B8%98%E5%A2%93_%E9%81%A0%E6%99%AF.JPG",3648,2736],["j:1/1b/%E6%A5%AF%E7%AF%89%E5%A2%B3%E4%B8%98%E5%A2%93%E5%87%BA%E5%9C%9F_%E7%89%B9%E6%AE%8A%E5%99%A8%E5%8F%B0.JPG",2282,4956],["j:5/5a/%E7%89%B9%E6%AE%8A%E5%99%A8%E5%8F%B0%E3%83%BB%E7%89%B9%E6%AE%8A%E5%A3%BA_%28%E8%A4%87%E8%A3%BD%29.JPG",4471,3199,"特殊器台"],["c:4/45/Gamla_uppsala.jpg",837,368,"墳丘墓"]]},{"id":"33_hofukuji","n":"宝福寺（雪舟 «涙のねずみ»）","yomi":"ほうふくじ","cat":"寺社","rank":"S","y":1232,"era":["kamakura","muromachi"],"sh":"国の重要文化財（三重塔）","ad":"総社市井尻野","st":"JR伯備線 豪渓駅から歩いて約15分","la":34.6917,"lo":133.7303,"hook":"柱にしばられた少年が、足の指と涙で描いたねずみ。それが本物のように動き出した――画聖・雪舟の伝説の寺。","lead":"宝福寺は、鎌倉時代に開かれた臨済宗の禅寺です。室町時代の画僧・雪舟が少年のころに修行した寺として知られ、«涙でねずみを描いた» という有名な話の舞台になっています。室町時代の三重塔は国の重要文化財です。","story":["室町時代、備中の赤浜という村に生まれた少年が、この宝福寺に入りました。のちの雪舟等楊です。少年は、お経を読むよりも絵をかくことが好きで、修行そっちのけで筆を走らせてばかりいました。","ある日、和尚さんはとうとう怒り、少年を本堂の柱にしばりつけてしまいます。«反省するまで、そこにおれ»。夕方、和尚さんが様子を見にくると、少年の足もとに一匹のねずみがいました。«かまれてはいけない» と追いはらおうとしても、ねずみは動きません。よく見ると、それは少年がこぼした涙を足の指につけて、床に描いたねずみだったのです。","おどろいた和尚さんは、それからは少年が絵をかくことを許したといいます。この話は江戸時代の書物 «本朝画史» などに記され、雪舟の天才ぶりを伝える話として広まりました。«本当にあったの?»――実はこれは伝説で、事実かどうかはわかりません。","大人になった雪舟は京都の相国寺で学び、やがて中国（明）へ渡って本場の水墨画を学びます。帰国後は山口などで活躍し、«秋冬山水図» や «天橋立図» などの名作を残しました。そのうち6点が国宝です。日本の水墨画を大きく花開かせた人でした。","宝福寺は、戦国時代の争いで一時さびれましたが、今も静かな禅寺として続いています。秋には境内のもみじが真っ赤に色づき、三重塔や本堂を彩ります。少年雪舟がしばられた本堂で、ねずみを探してみるのもいいかもしれません。"],"tl":[["1232年","鈍庵慧聰によって開かれたと伝わる"],["1376年","三重塔が建てられたとされる"],["1420年","雪舟が備中国に生まれる"],["1467年","雪舟が明へ渡る"],["1693年","狩野永納の «本朝画史» が刊行され、ねずみの話が記される"]],"who":[["雪舟等楊","少年時代に宝福寺で修行した画僧。日本水墨画の大成者"],["鈍庵慧聰","宝福寺を開いたと伝わる僧"],["狩野永納","江戸時代の画家。«本朝画史» でねずみの話を記した"]],"deep":["三重塔は1376年（永和2年）の建立とされ、岡山県内で最も古い木造の塔といわれます。国の重要文化財です。","«涙のねずみ» の話は、狩野永納が1693年に刊行した «本朝画史» に見え、江戸時代に広まりました。雪舟自身の記録には出てきません。","雪舟は1420年、備中国赤浜（今の総社市赤浜）に生まれたとされます。宝福寺にいた年齢は «少年時代» とされるだけで、はっきりしていません。","寺は室町時代には多くの塔頭（小さな寺）をもつ大寺院でしたが、戦国時代の兵火で多くを失ったといわれます。","雪舟の国宝は6点あり、一人の画家の作品が国宝6点というのは日本で最多とされます。","雪舟は明で «天童山景徳寺第一座» の称号を得たと伝わり、自らの作品の落款にも記しています。"],"look":["室町時代の三重塔（重要文化財）","雪舟がしばられたと伝わる本堂","雪舟碑と雪舟の像","秋の紅葉の参道","方丈と庭園"],"q":["宝福寺で、柱にしばられた少年雪舟は何を使ってねずみを描いた？","こぼした涙を足の指につけて描いたと伝わります。"],"koji":[],"myth":"«涙のねずみ» は江戸期の書物に見える伝説。開山年は寺伝。","img":["雪舟","本朝画史","水墨画","臨済宗"],"wp":"宝福寺 (総社市)","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Iyama_Hofukuji_04.JPG",1600,1064,"宝福寺 (総社市)"],["c:7/77/Iyama_Hofukuji_02.JPG",1600,1064],["c:a/ab/Iyama_Hofukuji_07.JPG",1063,1600],["c:a/a4/Iyama_Hofukuji_01.JPG",1063,1600],["c:7/75/Portrait_of_Sesshu.jpg",988,1217,"雪舟"],["c:2/23/Hasegawa_Tohaku_-_Pine_Trees_%28Sh%C5%8Drin-zu_by%C5%8Dbu%29_-_right_hand_screen.jpg",16723,7828,"水墨画"],["c:e/e8/RinzaiGigen.jpg",413,600,"臨済宗"]]},{"id":"33_bitchu_kokubunji","n":"備中国分寺（吉備路の五重塔）","yomi":"びっちゅうこくぶんじ","cat":"寺社","rank":"S","y":741,"era":["nara","edo"],"sh":"国指定史跡（五重塔は国の重要文化財）","ad":"総社市上林","st":"JR総社駅から車で約10分。«吉備路自転車道» 沿い（レンタサイクル利用が便利）","la":34.6767,"lo":133.7644,"hook":"れんげ畑の向こうに立つ五重塔。奈良時代の国の寺は、江戸時代にもう一度よみがえった。","lead":"備中国分寺は、奈良時代に聖武天皇の命令でつくられた国分寺のひとつです。いったん荒れ果てましたが、江戸時代に再興されました。今ある五重塔は江戸時代後期の建物で、岡山県で唯一の五重塔です。","story":["奈良時代、都では伝染病や反乱、地震が相次いでいました。«仏の力で国を守りたい»。741年、聖武天皇は、全国の国ごとに寺を建てるよう命じます。これが国分寺と国分尼寺です。備中の国でも、吉備の平野を見わたすこの場所に、大きな寺が建てられました。","当時の寺は、南大門・中門・金堂・講堂が一直線に並び、七重塔もあったと考えられています。発掘すると、塔の礎石や寺を囲む塀の跡が見つかりました。いまの寺の境内のまわりに、奈良時代の大寺院が広がっていたのです。","けれども、国の力で支えられた国分寺は、時代とともに衰えていきます。南北朝時代の戦乱で焼けたと伝わり、長いあいだ廃寺同然になっていました。«このままでは、国分寺の名が消えてしまう»。","江戸時代の中ごろ、僧の日照が寺を再興しました。そして江戸時代後期、村人たちの寄付と努力で五重塔が建てられます。完成まで20年以上かかったといわれます。高さは約34m。遠くからもよく見えるこの塔は、吉備路のシンボルになりました。","春はれんげ、夏はひまわり、秋はコスモス。まわりの田んぼに花が咲く季節、塔を背景に写真をとる人でにぎわいます。近くには国分尼寺跡や、こうもり塚古墳、作山古墳もあり、自転車で古代吉備の歴史をめぐるのにぴったりの場所です。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["奈良時代","備中国分寺が建てられる"],["南北朝時代","戦乱で焼けたと伝わる"],["江戸時代中期","日照上人らにより再興"],["1844年ごろ","五重塔が完成（江戸時代後期）"],["現在","周辺は «吉備路風土記の丘» として整備されている"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立を支えた"],["日照","江戸時代に寺を再興した僧"]],"deep":["五重塔は総高約34m。江戸時代後期、文政年間ごろに建築が始まり、弘化元年（1844年）ごろ完成したとされます。国の重要文化財です。","塔の初層と二層以上で様式が少しちがうといわれ、長い工期の中で大工が代わったためとする見方があります。","奈良時代の伽藍は、発掘で南門・中門・金堂・講堂・塔などの位置が推定されています。塔の礎石は今の寺の境内の東で見つかっています。","すぐ東には備中国分尼寺跡があり、ともに国の史跡。尼寺跡には礎石が残り、雑木林の中で静かな雰囲気です。","今の寺は真言宗の寺院で、奈良時代の国分寺と同じ場所で法灯を継いでいる、という位置づけです。","吉備路自転車道は総社市から岡山市へ続く約20kmのサイクリングロード。国分寺・作山古墳・造山古墳・吉備津神社をつないでいます。","国分寺は «金光明四天王護国之寺»、国分尼寺は «法華滅罪之寺» が正式な名前とされます。僧の寺と尼の寺をセットで置き、国の平安を祈らせる仕組みでした。"],"look":["江戸時代の五重塔（重要文化財）","奈良時代の塔の礎石","近くの備中国分尼寺跡","春のれんげ・秋のコスモスと塔","吉備路自転車道からの遠景"],"q":["全国に国分寺をつくるよう命じた天皇はだれ？","聖武天皇です。741年に国分寺建立の詔を出しました。"],"koji":[],"myth":"焼失の時期・再興の年代には諸説。塔の完成年は1844年ごろとされる。","img":["国分寺","聖武天皇","五重塔","備中国分尼寺"],"wp":"備中国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"備中国分寺"],["c:e/ec/Bitchu_Kokubunji%2C_tou.jpg",4000,6016],["c:5/50/Bitchu_Kokubunji%2C_tatemono-ato.jpg",5976,3938],["c:9/94/Bitchu_Kokubunji%2C_sanmon.jpg",6016,4000],["c:5/5e/Bitchu_Kokubunji%2C_nanmon-ato.jpg",6002,3978],["c:b/b0/Bitchu_Kokubunji%2C_kyouzou.jpg",6014,3998],["c:a/af/Bitchu_Kokubunji%2C_kyakuden.jpg",5976,3938],["c:a/a7/Bitchu_Kokubunji%2C_kuri.jpg",6016,4000]]},{"id":"33_tanjoji","n":"誕生寺（法然の生まれた地）","yomi":"たんじょうじ","cat":"寺社","rank":"S","y":1193,"era":["heian","kamakura","edo"],"sh":"国の重要文化財（御影堂・山門）","ad":"久米郡久米南町里方","st":"JR津山線 誕生寺駅から歩いて約10分","la":34.9314,"lo":133.9536,"hook":"«かたきを恨むな、仏の道を歩め»――父の最期のことばが、ひとりの少年を浄土宗の開祖・法然にした。","lead":"誕生寺は、浄土宗を開いた法然が生まれた場所に建つ寺です。法然の弟子になった熊谷直実が、1193年に法然の生家を寺にしたと伝わります。江戸時代に建てられた御影堂と山門は、国の重要文化財です。","story":["平安時代の終わり、1133年。美作国の久米の地で、押領使（地方の治安をまもる役人）の漆間時国の家に男の子が生まれました。幼い名は勢至丸。のちの法然です。","勢至丸が9歳のとき、事件が起こります。争っていた明石定明という武士が夜討ちをかけ、父の時国が深い傷を負ったのです。勢至丸は小さな弓で矢を放ち、定明の額に当てたと伝わります。けれども父の命は助かりませんでした。","死の床で、父は勢至丸にこう言い残したといいます。«仇を討とうとしてはならない。恨みは恨みをよび、きりがない。おまえは出家して、わしの菩提をとむらい、みなが救われる道を求めよ»。少年はこのことばを胸に、やがて比叡山にのぼり、仏の道を学びはじめました。","長い修行のすえ、法然は «ただひたすら南無阿弥陀仏と念仏をとなえれば、だれでも救われる» という教えにたどりつきます。身分や学問に関係なく救われる、この教えは多くの人々の心をつかみました。弟子の中には、一ノ谷の戦いで平敦盛を討ったことに苦しんでいた武士・熊谷直実もいました。","出家して «蓮生» と名のった直実は、師の生まれた地をたずね、生家を寺にしたと伝わります。これが誕生寺のはじまりです。境内には、法然の父母をまつる場所や、幼い勢至丸が植えたとされる «逆木のイチョウ» もあります。毎年4月には、菩薩の姿をした人々が行列する «二十五菩薩練供養» が行われます。"],"tl":[["1133年","法然（勢至丸）が美作国久米に生まれる"],["1141年","父・漆間時国が夜討ちで亡くなる"],["1175年","法然が専修念仏の教えを開く（浄土宗の開宗）"],["1193年","熊谷直実（蓮生）が生家を寺にしたと伝わる"],["1212年","法然が京都で亡くなる"],["江戸時代","御影堂・山門などが建てられる"]],"who":[["法然","浄土宗の開祖。この地で生まれた"],["漆間時国","法然の父。美作の押領使"],["明石定明","時国を夜討ちした武士"],["熊谷直実（蓮生）","法然の弟子。生家を寺にしたと伝わる"]],"deep":["父・時国の遺言は «法然上人行状絵図» などの伝記で語られ、法然の出家の動機として有名です。細かな言葉は伝記によって異なります。","御影堂は元禄年間（17世紀末）の建物とされ、法然の像をまつります。山門とともに国の重要文化財です。","«逆木のイチョウ» は、勢至丸が比叡山に向かう際、杖にしていたイチョウの枝を地面に逆さに立てたところ根づいた、と伝わる木です。","«二十五菩薩練供養（お練り）» は、阿弥陀如来と菩薩たちが極楽からむかえにくるようすを再現する行事で、町の無形民俗文化財になっています。","寺の本尊は、法然自作と伝わる像が伝えられますが、制作者や年代については専門的な検討が必要です。","熊谷直実は «平家物語» の «敦盛最期» で知られ、平敦盛を討った後悔から出家した武士として描かれています。"],"look":["御影堂と山門（重要文化財）","逆木のイチョウ","法然の両親をまつる場所","4月の二十五菩薩練供養","JR誕生寺駅（寺の名を駅名にもつ）"],"q":["法然が出家するきっかけになった、父のことばとは？","«仇を討つな。恨みは恨みを生む。出家して、すべての人が救われる道を求めよ» という遺言です。"],"koji":[{"w":"南無阿弥陀仏","m":"阿弥陀仏に身をゆだねるという意味の念仏。法然はこれを唱えればだれでも救われると説いた"}],"myth":"勢至丸の矢の話、父の遺言の言葉、直実による開山、逆木のイチョウは伝承。","img":["法然","熊谷直実","浄土宗","漆間時国"],"wp":"誕生寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Takanobu-no-miei.jpg",420,512,"法然"],["c:b/b5/JRW_yuge_sta.jpg",3456,2304,"近く: 弓削駅"],["c:7/70/Tochikorozan_Tanjoji_02.JPG",2048,1362,"近く: 久米南町"],["c:2/2b/Yuge2.jpg",1280,960,"近く: 岡山県立弓削高等学校"]]},{"id":"33_ohara_museum","n":"大原美術館（日本初の西洋美術館）","yomi":"おおはらびじゅつかん","cat":"近代","rank":"S","y":1930,"era":["showa"],"sh":"","ad":"倉敷市中央1丁目","st":"JR倉敷駅から歩いて約15分（倉敷美観地区内）","la":34.5958,"lo":133.771,"hook":"«日本の若い画家に、本物の西洋絵画を見せたい»――実業家と画家の友情が、地方の町に名画を集めた。","lead":"大原美術館は、倉敷の実業家・大原孫三郎が1930年に開いた、日本で最初の西洋美術を中心とした私立美術館です。画家の児島虎次郎がヨーロッパで買い集めた作品がもとになっています。エル・グレコ «受胎告知» やモネ «睡蓮» などを見ることができます。","story":["明治の終わり、倉敷紡績の若き社長・大原孫三郎のもとに、ひとりの画学生がいました。岡山県出身の児島虎次郎です。孫三郎は虎次郎の才能を認め、学費を援助しました。ふたりは年も近く、やがて深い友情で結ばれます。","虎次郎はヨーロッパに留学し、ベルギーで絵を学びました。現地で本物の西洋絵画にふれた虎次郎は、ある思いをいだきます。«日本の画家たちは、写真や印刷でしか西洋の名画を知らない。本物を見なければ、本当の勉強にはならない»。虎次郎は孫三郎に手紙を書き、絵を買って日本へ持ち帰ることを願い出ました。","孫三郎はこれを許し、虎次郎は何度もヨーロッパに渡って作品を集めます。モネのアトリエをたずねて «睡蓮» をゆずってもらったり、パリの画廊でエル・グレコの «受胎告知» を見つけたりしました。«地方の町に、これほどの名画があるなんて»。集めた絵が倉敷で公開されると、全国から人々が見に来たといいます。","しかし1929年、虎次郎は47歳の若さで亡くなってしまいます。孫三郎は友の業績を記念し、その集めた作品を多くの人に見てもらうため、翌1930年に美術館を開きました。ギリシャ神殿のような柱の本館は、倉敷の白壁の町並みの中で、ひときわ目をひきます。","戦後、孫三郎の子・總一郎が館を受け継ぎ、日本の近代洋画や、民藝運動の作家たちの作品も加わりました。«倉敷は美術館があったから空襲されなかった» という話がありますが、これは確かな根拠のない俗説です。今も大原美術館は、倉敷の町並みとともに、多くの人に «本物» との出会いを届けています。"],"tl":[["1881年","児島虎次郎が岡山県に生まれる"],["1908年","虎次郎がヨーロッパに留学"],["1920年代","虎次郎が再び渡欧し、名画を買い集める"],["1929年","児島虎次郎が亡くなる"],["1930年","大原美術館が開館"],["1961年","分館が開館"],["現在","本館・分館・工芸館などで展示を行う"]],"who":[["大原孫三郎","倉敷紡績の社長。美術館を創設した"],["児島虎次郎","画家。ヨーロッパで作品を集めた"],["大原總一郎","孫三郎の子。戦後の美術館を発展させた"],["クロード・モネ","フランスの画家。虎次郎が «睡蓮» を直接ゆずり受けた"]],"deep":["エル・グレコの «受胎告知» は、日本にある同画家の作品として特に有名です。虎次郎がパリの画廊で見つけ、購入したと伝わります。","モネの «睡蓮» は、虎次郎がジヴェルニーのモネの家を訪ね、画家本人から購入したものとされます。","ゴーギャンの «かぐわしき大地（テ・ナヴェ・ナヴェ・フェヌア）» もコレクションの代表作。タヒチ時代の作品です。","本館の建物はギリシャ神殿風の柱をもつ洋風建築で、開館当時の建物が今も使われています。入口の左右にはロダンの彫刻が置かれています。","工芸館は江戸時代の米蔵を改修した建物で、バーナード・リーチ、濱田庄司、河井寛次郎、棟方志功、芹沢銈介など、民藝運動にかかわった作家の作品を展示しています。","«倉敷が空襲を免れたのは美術館のおかげ» という話は、米国側の資料で確かめられておらず、俗説とされています。"],"look":["エル・グレコ «受胎告知»","モネ «睡蓮»","ギリシャ神殿風の本館の外観","米蔵を改修した工芸館（民藝の作品）","児島虎次郎の作品を展示するコーナー"],"q":["大原美術館の名画を、実際にヨーロッパで買い集めた画家はだれ？","岡山県出身の画家・児島虎次郎です。"],"koji":[],"myth":"«空襲を免れたのは美術館のため» は根拠のない俗説。","img":["児島虎次郎","大原孫三郎","受胎告知 (エル・グレコ)","倉敷美観地区"],"wp":"大原美術館","rel":{"ev":[],"grave":[]},"ph":[["c:3/3a/Kurashiki_Ohara_Art_Museum02nt3200.jpg",2130,3200,"大原美術館"],["c:3/35/Paul_C%C3%A9zanne_-_Landscape_-_Google_Art_Project.jpg",4697,3704],["c:a/a0/Paul_C%C3%A9zanne_-_Bathers_-_Google_Art_Project_%28520022%29.jpg",4001,3603],["c:5/54/OkadaSabur%C5%8Dsuke-1901-Italian_Girl.png",3357,4618],["c:3/36/MatsumotoShunsuke-1940-Cityscape.png",3510,3177],["c:b/b9/Kurashiki_Ohara_Art_Museum06n4592.jpg",3056,4592],["c:c/cd/Kurashiki_Ohara_Art_Museum04n4592.jpg",4592,3056],["c:4/40/KojimaTorajir%C5%8D-1917-Self-Portrait.png",3277,4222]]},{"id":"33_kibitsuhiko","n":"吉備津彦神社（備前一宮）","yomi":"きびつひこじんじゃ","cat":"寺社","rank":"A","y":1697,"era":["kofun","edo"],"sh":"","ad":"岡山市北区一宮","st":"JR吉備線（桃太郎線）備前一宮駅から歩いて約3分","la":34.6776,"lo":133.8563,"hook":"夏至の朝、正面の鳥居から昇った太陽が、まっすぐ社殿の奥へ差しこむ。ここは «朝日の宮»。","lead":"吉備津彦神社は、備前国の «一宮» です。鬼の温羅を退治したと伝わる大吉備津彦命をまつっています。吉備の中山をはさんで、反対側には備中一宮の吉備津神社があり、二つの神社をめぐる人も多くいます。","story":["岡山市の西に、なだらかな «吉備の中山» があります。この山は、昔の備前と備中の国の境にあたり、古くから神の山としてあがめられてきました。山の北東のふもとに建つのが吉備津彦神社、北西のふもとに建つのが吉備津神社です。","まつられている大吉備津彦命は、古代に都から吉備にやってきて、鬼の温羅を退治したと語られる神様です。«桃太郎» のモデルともいわれ、神社には桃やきびだんごにちなむお守りもあります。","この神社が «朝日の宮» とよばれるのには理由があります。夏至の日の朝、正面の鳥居の真ん中から太陽が昇り、その光がまっすぐ祭文殿の鏡に差しこむのです。«なぜ、そんな向きに?»――古代の人々が、太陽の動きを大切にして社殿の向きを決めたからだと考えられています。","江戸時代、岡山藩主の池田綱政は、この神社をとても大切にしました。1697年には本殿を建て直し、藩の守り神として手厚く祭りました。境内の大きな石灯籠は、高さ約11mもあり、日本一の大きさともいわれます。","中山の山頂近くには、大吉備津彦命の墓と伝えられる «中山茶臼山古墳» があり、宮内庁が管理しています。神社の背後の山に登れば、古代の人々が神の山とあがめた中山の空気を感じられます。二つの一宮と古墳を結ぶ道は、歴史好きにはたまらない散歩道です。"],"tl":[["古代","大吉備津彦命が吉備を平定したと伝わる"],["平安時代","備前国の一宮として信仰される"],["1697年","岡山藩主・池田綱政が本殿を再建"],["江戸時代","池田家の保護を受け、藩の守り神となる"],["現在","夏至の «朝日の宮» として知られる"]],"who":[["大吉備津彦命","神社にまつられる神。温羅を退治した伝説の主人公"],["温羅","伝説の鬼。鬼ノ城に住んだとされる"],["池田綱政","岡山藩主。本殿を再建した"],["孝霊天皇","大吉備津彦命の父と伝わる天皇"]],"deep":["本殿は1697年に池田綱政が再建したもので、岡山県の重要文化財とされています。流造の本殿に祭文殿・拝殿が連なる構成です。","夏至の日の出が正面鳥居から社殿へ一直線に入る配置は、冬至や夏至の太陽を意識した古代の信仰と関係づけて語られます。","境内の石灯籠は高さ約11.5mとされ、日本最大級の石灯籠のひとつ。江戸時代に奉納されたものです。","吉備の中山には、中山茶臼山古墳（大吉備津彦命の墓とされる）や、磐座（神が宿る岩）とされる巨石がいくつもあり、神体山としての性格がうかがえます。","吉備津彦神社と吉備津神社は、どちらも大吉備津彦命をまつります。備前・備中の国が分かれたあと、それぞれの国の一宮として祭られてきたと考えられています。","境内には «子安神社» があり、安産の神として信仰されています。"],"look":["正面鳥居と社殿の一直線の配置","高さ約11mの大石灯籠","池田綱政が再建した本殿","吉備の中山への登山道（磐座めぐり）","中山茶臼山古墳（外から見学）"],"q":["吉備津彦神社が «朝日の宮» とよばれるのはなぜ？","夏至の日の朝、正面の鳥居から昇る太陽の光が社殿にまっすぐ差しこむからです。"],"koji":[],"myth":"温羅退治・桃太郎モデル説は伝承。中山茶臼山古墳を大吉備津彦命の墓とするのは宮内庁の治定で学術的には未確定。","img":["大吉備津彦命","吉備の中山","吉備津神社","中山茶臼山古墳"],"wp":"吉備津彦神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/f2/Kibitsuhiko-jinja_tourou_and_haiden.JPG",3648,2736,"吉備津彦神社"],["c:2/22/Nakayama_Chausuyama_Kofun%2C_haisho.jpg",5876,3782],["c:4/45/Kibitsuhiko-jinja_zuishinmon.JPG",3648,2736],["c:c/ce/Kibitsuhiko-jinja_torii.JPG",3648,2736],["c:f/ff/Kibitsuhiko-jinja_massha_%28joudan%29.JPG",3648,2736],["c:c/cc/Kibitsuhiko-jinja_kanjou-resseki.JPG",3648,2736],["c:b/b6/Kibitsuhiko-jinja_honden.JPG",3648,2736],["c:4/47/Kibitsuhiko-jinja_Heian-sugi.JPG",3648,2736]]},{"id":"33_nakayama_jinja","n":"中山神社（美作一宮）","yomi":"なかやまじんじゃ","cat":"寺社","rank":"A","y":1559,"era":["asuka","muromachi"],"sh":"国の重要文化財（本殿）","ad":"津山市一宮","st":"JR津山駅からバスで約20分、«中山神社前» 下車すぐ","la":35.1003,"lo":133.9899,"hook":"«猿の神にいけにえを»――平安の説話集が語るこわい話の舞台は、美作の一宮だった。","lead":"中山神社は、美作国の «一宮» で、地元では «ちゅうさんさま» とよばれ親しまれています。707年に創建されたと伝わり、戦国時代に尼子晴久が再建した本殿は国の重要文化財です。境内には猿の神をまつる «猿神社» があります。","story":["津山の町の北、山すその森の中に、どっしりとした本殿が建っています。美作国でいちばん格の高い «一宮»、中山神社です。まつられているのは、鏡をつくる神とされる鏡作神。古くから牛馬の守り神としても信仰されてきました。","平安時代の説話集 «今昔物語集» には、こんな話が出てきます。むかし美作の国の «中参（ちゅうさん）» という神は猿の姿をしていて、毎年、村の娘をいけにえとして差し出させていた。ある年、いけにえに選ばれた娘を助けようと、東国から来た男が犬を使って猿を退治した――。この «中参» が、中山神社のことだと考えられています。","«本当にいけにえがあったの?»――もちろんこれは説話で、史実ではありません。けれども、境内の奥には今も «猿神社» がまつられ、小さな猿のぬいぐるみなどが奉納されています。こわい話の猿神が、今では安産や子育ての守り神として大切にされているのです。","神社の本殿は、戦国時代の1559年、出雲の戦国大名・尼子晴久によって建て直されました。尼子氏は美作に勢力をのばしており、一宮を再建することで、この地を治める力を示そうとしたのでしょう。屋根の形は «中山造» とよばれる独特のもので、美作地方の神社に多く見られます。","境内には大きな杉の木や、古い鳥居がたたずみ、静かな時間が流れます。一宮らしい広々とした参道を歩きながら、1300年の歴史と、説話の世界を想像してみてください。"],"tl":[["707年","創建と伝わる"],["713年","備前国から美作国が分かれる"],["平安時代","«今昔物語集» に中参の猿神の話が記される"],["1559年","尼子晴久が本殿を再建"],["現在","本殿は国の重要文化財。境内に猿神社がまつられる"]],"who":[["鏡作神","神社の主祭神とされる神"],["尼子晴久","出雲の戦国大名。本殿を再建した"],["猿神","«今昔物語集» に登場する猿の神。境内の猿神社にまつられる"]],"deep":["本殿は «中山造» と呼ばれ、入母屋造の妻入りで正面に向拝をつけた形。美作地方に広まった神社建築の様式です。","本殿は1559年（永禄2年）、尼子晴久の再建とされ、国の重要文化財です。","«今昔物語集» 巻26には、美作の中参・高野という神が猿と蛇であり、いけにえを求めたという話があります。中参が中山神社にあたると考えられています。","«一宮» としての格は平安時代の «延喜式» にも名神大社として見え、美作国を代表する神社でした。","猿神社は本殿の裏手の岩山の上にあり、猿のぬいぐるみやお守りが奉納されています。","神社の名前は古くから «ちゅうさん» と音読みされ、地元では今もそう呼ぶ人が多くいます。","美作国は713年に備前国の北部を分けてつくられた国です。一宮の中山神社は、新しい国の人々の心をまとめる役割も担ったと考えられます。"],"look":["尼子晴久が再建した本殿（中山造）","本殿裏の猿神社","参道と大きな杉の木","神門と拝殿"],"q":["«今昔物語集» で、中山神社の神は何の姿で描かれている？","猿の姿です。境内の奥には «猿神社» がまつられています。"],"koji":[],"myth":"創建年は伝承。今昔物語集の «中参» を中山神社とするのは通説だが説話。","img":["美作国","尼子晴久","今昔物語集","一宮"],"wp":"中山神社","rel":{"ev":[],"grave":[]},"ph":[["c:4/46/Nakayama_Jinja_09.JPG",1600,1064,"中山神社"],["c:1/1d/Nakayama-jinja_otabisho.JPG",3648,2736],["c:b/b6/Nakayama-jinja_keyaki.JPG",3648,2736],["c:d/d2/Nakayama-jinja_kaguraden.JPG",3648,2736],["c:c/ca/Nakayama-jinja_honden-2.JPG",3648,2736],["c:9/98/Nakayama-jinja_hokotateishi.JPG",3648,2736],["c:2/2d/Nakayama-jinja_haiden.JPG",3648,2736],["c:0/01/Nakayama-jinja_%28Tsuyama%29_massha_Saru-jinja.JPG",3648,2736]]},{"id":"33_isonokami","n":"石上布都魂神社（スサノオの剣の伝承）","yomi":"いそのかみふつみたまじんじゃ","cat":"伝承","rank":"A","y":300,"era":["kofun","heian"],"sh":"","ad":"赤磐市石上","st":"JR岡山駅から車で約50分。公共交通では行きにくい","la":34.836,"lo":134.04,"hook":"ヤマタノオロチを斬った剣は、この山にまつられていた――«日本書紀» にも記された、剣の伝説の社。","lead":"石上布都魂神社は、赤磐市の山の中にある古い神社です。スサノオノミコトがヤマタノオロチを斬ったときの剣がまつられていた、という伝説があります。山頂には、神が宿るとされる大きな岩（磐座）があります。","story":["神話の中で、スサノオノミコトは出雲の国で八つの頭をもつ大蛇、ヤマタノオロチを退治します。そのとき使った剣は «十握剣（とつかのつるぎ）» とよばれました。«日本書紀» の一書には、«その蛇を斬った剣は、今、吉備の神部のところにある» と記されています。","«吉備の神部のところ»――それが、この石上布都魂神社だといわれています。剣の神霊は «布都御魂（ふつのみたま）»。のちに崇神天皇の時代に、大和の石上神宮へ移されたと伝わります。奈良の石上神宮と、名前が似ているのはそのためだとされます。","神社は、赤磐市の山あいの細い道を登った先にあります。«本当にこんな山奥に?» と思うほどです。山の中腹に拝殿があり、さらに山頂には «本宮» とよばれる場所があります。そこには大きな岩がそびえ、古くから神の宿る磐座としてあがめられてきました。","平安時代にまとめられた «延喜式» の神名帳にも、この神社の名前が記されています。都の朝廷にも知られた、由緒ある神社だったのです。山の上の小さな社は、長い年月のあいだ、地元の人々の手で守られ、何度も建て直されてきました。","山頂の磐座の周辺は禁足地とされ、むやみに入ることはできません。岩のまわりの静けさの中で、神話の時代から続く信仰の重みを感じてみてください。«備前一宮» を名乗る神社のひとつでもあり、古くから特別な神社とされてきました。"],"tl":[["神話の時代","スサノオがヤマタノオロチを退治したと語られる"],["崇神天皇の代（伝）","剣が大和の石上神宮に移されたと伝わる"],["平安時代","«延喜式» に備前国の神社として名が見える"],["江戸時代以降","地元の人々によって社が守られる"],["現在","山頂の本宮の磐座は禁足地として守られている"]],"who":[["スサノオノミコト","ヤマタノオロチを退治した神"],["布都御魂","剣の神霊。神社の名前の由来"],["崇神天皇","この代に剣が大和へ移されたと伝わる天皇"],["物部氏","大和の石上神宮をまつった古代の豪族。剣の信仰にかかわる"]],"deep":["«日本書紀» 神代上の一書に、スサノオが蛇を斬った剣について «今在吉備神部許（今、吉備の神部のもとにある）» という記述があり、これを当社と結びつける説があります。","祭神は、現在は素盞嗚尊とされますが、古くは剣そのもの（布都御魂・布都斯魂）をまつったとされ、時代によって説明が異なります。","奈良の石上神宮には «布都斯魂大神» がまつられ、これを吉備から移された剣の神霊とする伝承があります。","山頂の本宮の磐座は禁足地で、許可なく立ち入ることはできません。","備前国の一宮については、吉備津彦神社とこの神社の両方が名乗る «論社» の状態があり、諸説があります。","«延喜式神名帳» に «石上布都之魂神社» として記載があり、平安時代には朝廷に知られた神社でした。"],"look":["山中の拝殿と社殿","山頂の本宮と磐座（禁足地、遠くから拝む）","参道の森と山道","周囲の山あいの景観"],"q":["石上布都魂神社にまつられていたと伝わる剣は、どんな怪物を倒した剣？","スサノオノミコトがヤマタノオロチを斬った剣です。"],"koji":[],"myth":"剣がまつられた・移されたという話は神話・伝承。祭神や一宮の扱いにも諸説。","img":["ヤマタノオロチ","石上神宮","十束剣","布都御魂"],"wp":"石上布都魂神社","rel":{"ev":[],"grave":[]},"ph":[["c:7/7f/Isonokamifutsumitama_jinja_01.jpg",2592,1944,"石上布都魂神社"],["c:1/10/Isonokamifutsumitama_jinja_03.jpg",2592,1944],["c:a/a3/Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi.png",2100,1039,"ヤマタノオロチ"],["c:a/a0/Isonokami_Jingu_Haiden1.jpg",4608,2592,"石上神宮"]]},{"id":"33_tsukuriyama2","n":"作山古墳（全国第10位の巨大古墳）","yomi":"つくりやまこふん","cat":"遺跡","rank":"A","y":450,"era":["kofun"],"sh":"国指定史跡","ad":"総社市三須","st":"JR総社駅から車で約10分。吉備路自転車道からも近い","la":34.6826,"lo":133.7574,"hook":"«造山» と «作山»。どちらも «つくりやま»。吉備にならぶ二つの巨大古墳は、王の力の «兄弟» だった。","lead":"作山古墳は、長さ約280mの前方後円墳で、大きさは全国で10番目です。造山古墳のすぐあと、5世紀の中ごろに造られたと考えられています。自然の丘をうまく利用して造られた古墳で、墳丘に登って見学できます。","story":["総社市の平野に、こんもりとした緑の丘があります。一見するとただの小山ですが、じつはこれが全国10位の大きさをほこる作山古墳です。長さは約280m。前方部と後円部が、はっきりとした段になっています。","すぐ東の岡山市には、全国4位の造山古墳があります。どちらも «つくりやま» と読むので、区別するために «ぞうざん» «さくざん» とよぶこともあります。«なぜ、こんなに近くに巨大古墳が二つも?»――吉備の王が代わるたびに、自分の力を示す大きな墓を造ったのだと考えられています。","造山古墳が5世紀前半、作山古墳はその少しあとの5世紀中ごろと考えられています。吉備の王家の力が、何代にもわたって続いたことがわかります。一方で、作山古墳のあと、吉備ではこれほど大きな古墳は造られなくなりました。ヤマト王権の力が強まり、吉備の王の力が弱まったのかもしれません。","作山古墳は、もともとあった丘陵の地形を利用して形を整えたといわれます。すべてを土盛りで造るよりも手間が少ない、古代の技術者の知恵でした。それでも、墳丘の斜面には石が敷かれ、埴輪が並べられていたことがわかっています。","墳丘に登ると、備中国分寺の五重塔や、吉備の平野が見わたせます。1500年以上前、この景色の中に王がいて、たくさんの人々が古墳づくりに汗を流していた――そう想像すると、ただの小山が特別な場所に見えてくるはずです。"],"tl":[["5世紀前半","近くに造山古墳が築かれる"],["5世紀中ごろ","作山古墳が築かれたと考えられる"],["5世紀後半","赤磐市に両宮山古墳が築かれる"],["6世紀後半","近くにこうもり塚古墳が築かれる"],["8世紀","近くに備中国分寺が建てられる"],["現在","国の史跡として墳丘に登って見学できる"]],"who":[["吉備の王","古墳の主と考えられる、名前の伝わらない吉備の王"],["造山古墳の王","少し前の時代の吉備の王。作山古墳の王の先代とも考えられる"],["雄略天皇","5世紀後半の大王。«日本書紀» に吉備の反乱を鎮めた話がある"]],"deep":["墳丘長は約280m前後とされ（測量により286mとする資料もあります）、全国で10位前後の規模です。","丘陵を削り出して形を整えた古墳と考えられ、盛り土だけで造られた古墳とは築き方がちがいます。","墳丘は三段築成で、斜面には葺石、段には円筒埴輪が並べられていたことが確認されています。","«日本書紀» の雄略天皇の時代には、吉備下道臣前津屋や吉備上道臣田狭の反乱の話があり、吉備の勢力がヤマトと緊張関係にあったことを示すとされます。","作山古墳の後、吉備では200mを超える前方後円墳は両宮山古墳（約206m）くらいで、巨大古墳の時代が終わっていきます。","古墳の近くには «こうもり塚古墳» や «備中国分寺» があり、古墳時代から奈良時代への移り変わりを一度に見られます。"],"look":["墳丘の頂上からの吉備路の眺め","前方部と後円部の段の形","備中国分寺の五重塔との遠景","吉備路自転車道からの全景"],"q":["作山古墳は全国で何番目に大きい古墳？","10番目前後です（長さ約280m）。"],"koji":[],"myth":"被葬者は不明。墳丘長は資料により差がある。","img":["造山古墳","前方後円墳","備中国分寺","吉備国"],"wp":"作山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Tsukuriyama_Kofun_%28Soja%29%2C_zenkei.jpg",6016,4000,"作山古墳"],["c:c/c3/Tsukuriyama_Kofun_%28Soja%29%2C_zenpoubu.jpg",6016,4000],["c:8/8a/Tsukuriyama_Kofun_%28Soja%29%2C_zankyu.jpg",5758,3831],["c:e/e8/Tsukuriyama_Kofun_%28Soja%29%2C_tsukuridashi.jpg",6016,4000],["c:6/66/Tsukuriyama_Kofun_%28Soja%29%2C_kouenbu-2.jpg",6016,4000],["c:0/04/Tsukuriyama_Kofun_%28Soja%29%2C_kouenbu-1.jpg",6016,4000],["c:0/0e/Tsukuriyama_Kofun_%28Soja%29%2C_funchou.jpg",6016,4000],["c:5/5d/Tsukuriyama_Kofun%2C_Soja_air.jpg",841,760]]},{"id":"33_ryoguyama","n":"両宮山古墳（備前最大の前方後円墳）","yomi":"りょうぐうさんこふん","cat":"遺跡","rank":"A","y":480,"era":["kofun"],"sh":"国指定史跡","ad":"赤磐市穂崎","st":"JR山陽本線 瀬戸駅から車で約10分。近くに «赤磐市山陽郷土資料館» あり","la":34.741,"lo":134.052,"hook":"長さ約200mの巨大古墳なのに、埴輪も葺石も見つからない。«この墓は、完成しなかったのでは?»","lead":"両宮山古墳は、赤磐市にある長さ約206mの前方後円墳です。備前地方では最大の古墳で、5世紀後半ごろに造られたと考えられています。周りを二重の堀が囲んでいたことがわかっていますが、埴輪や葺石がほとんど見つからない、なぞの多い古墳です。","story":["赤磐市の田んぼの中に、水をたたえた堀に囲まれた大きな古墳があります。両宮山古墳です。長さ約206m。岡山県では造山古墳・作山古墳に次ぐ3番目の大きさで、備前の国では最大です。","吉備の巨大古墳は、はじめは備中（今の岡山県西部）に造られていました。ところが5世紀の後半になると、東の備前にこの大きな古墳が造られます。«吉備の王の中心が、西から東へ移ったの?»――そう考える研究者もいます。","両宮山古墳のふしぎは、ほかにもあります。多くの大型古墳では、墳丘の斜面に石を敷きつめ（葺石）、埴輪をずらりと並べます。ところが、この古墳からは埴輪や葺石がほとんど見つかっていないのです。«造りかけのまま、終わってしまったのでは?» という説があります。","«日本書紀» には、雄略天皇の時代に吉備の豪族が反乱を起こし、鎮められたという話が出てきます。両宮山古墳が未完成なのは、この事件と関係があるのではないか、という考えもあります。ただし、はっきりした証拠はありません。","発掘調査で、古墳のまわりには二重の堀がめぐっていたことがわかりました。今は内側の堀に水がたまり、四季折々の景色を見せています。すぐ近くには奈良時代の備前国分寺跡もあり、古墳時代から奈良時代にかけて、この地が備前の中心だったことがうかがえます。"],"tl":[["5世紀後半","両宮山古墳が築かれたと考えられる"],["奈良時代","近くに備前国分寺が建てられる"],["昭和時代","国の史跡に指定される"],["2000年代","発掘調査で外側の堀（二重の周濠）が確認される"],["現在","堀に水をたたえた姿を見学できる"]],"who":[["吉備の王","古墳の主と考えられる、名前の伝わらない王"],["雄略天皇","«日本書紀» で吉備の反乱を鎮めたとされる大王"],["吉備上道臣田狭","«日本書紀» に登場する吉備の豪族。反乱の話に関係する"]],"deep":["墳丘長約206m。岡山県内では造山古墳（約350m）、作山古墳（約280m）に次ぐ第3位の規模です。","葺石や埴輪がほとんど確認されていないことから、未完成のまま工事が止まったとする説があります。ただし、別の理由で埴輪を並べなかった可能性もあり、諸説あります。","発掘により、内濠の外側にさらに外濠がめぐる二重周濠であったことが確認されました。周濠を含めた全長は300mをこえるとみられます。","«日本書紀» の雄略天皇紀には、吉備上道臣田狭の反乱や、吉備下道臣前津屋の話が見え、吉備とヤマト王権の緊張関係を示すとされます。","周辺には森山古墳や廻り山古墳など、同じ時期の古墳が集まり、«両宮山古墳群» を形づくっています。","古墳の名は、墳丘の上にかつて二つの宮（社）があったことに由来するといわれます。"],"look":["水をたたえた内濠と墳丘","周辺の陪塚的な古墳","近くの備前国分寺跡","赤磐市山陽郷土資料館の展示"],"q":["両宮山古墳が «未完成の古墳» と考えられている理由は？","ふつうの大型古墳にある葺石や埴輪が、ほとんど見つかっていないからです。"],"koji":[],"myth":"未完成説・反乱との関連は推測で諸説。名前の由来も伝承。","img":["前方後円墳","備前国分寺","吉備国","雄略天皇"],"wp":"両宮山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:d/d1/Ryoguzan_Kofun%2C_zenkei-1.jpg",5815,3864,"両宮山古墳"],["c:b/b1/Wada_Chausuyama_Kofun%2C_zenkei.jpg",6016,4000],["c:e/ec/Ryoguzan_Kofun%2C_funkyu.jpg",5958,3912],["c:4/46/Ryoguzan_Kofun%2C_Ryogu-jinja.jpg",5938,3880],["c:2/2f/Ryoguzan_Kofun_air.jpg",744,649],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:a/a0/Bizen_Kokubunji-ato%2C_gaikan.jpg",5974,3936,"備前国分寺"],["c:5/54/Emperor_Y%C5%ABryaku.jpg",630,691,"雄略天皇"]]},{"id":"33_tsukinowa","n":"月の輪古墳（村人総出の発掘）","yomi":"つきのわこふん","cat":"遺跡","rank":"A","y":450,"era":["kofun","showa"],"sh":"県指定史跡","ad":"久米郡美咲町飯岡","st":"JR津山駅から車で約40分。麓の «月の輪郷土館» から山道を歩いて登る","la":35.0005,"lo":134.0865,"hook":"先生も子どもも、農家のおじいさんも。1953年、村じゅうの人がスコップを手に山へ登った。","lead":"月の輪古墳は、美咲町の山の上にある、直径約60mの大きな円墳です。5世紀ごろに造られました。1953年、地元の人々や学生、先生たちが力を合わせて発掘したことで有名で、その様子は映画にもなりました。","story":["岡山県北部、吉井川の流れる美咲町（旧柵原町）。標高300mをこえる山の上に、丸い大きな古墳があります。地元では «月の輪» とよばれていました。なぜその名前なのか、はっきりとはわかりません。","戦争が終わって間もない1953年。«自分たちの村の歴史を、自分たちの手で明らかにしよう»――そんな声が地元で上がりました。指導にあたったのは、若い考古学者・近藤義郎さん。村の人々、小学生から大学生、学校の先生、主婦たちが、次々と山に登ってきました。","発掘に参加した人は、のべ約1万人ともいわれます。重い土を運び、ふるいにかけ、見つかった土器のかけらを洗う。みんなが手分けして作業を進めました。«この村に、こんな昔から人が暮らしていたのか»。発掘は村の人々にとって、歴史を身近に感じる大きな体験になりました。","古墳の頂上からは、棺を納めた場所が見つかり、鉄の剣や鏡、玉などが出土しました。また、墳丘の斜面には石が敷きつめられ、たくさんの埴輪が並べられていたこともわかりました。吉備の中心から離れた山あいにも、力のある首長がいたのです。","この発掘の記録映画 «月の輪古墳» が作られ、全国で上映されました。«国民の歴史学»の運動の象徴としても語られます。今、古墳は葺石が復元され、麓の «月の輪郷土館» では出土品や当時の写真を見ることができます。"],"tl":[["5世紀","月の輪古墳が築かれたと考えられる"],["1953年","地元住民や学生らによる発掘調査"],["1954年","記録映画 «月の輪古墳» が完成"],["その後","岡山県の史跡として保護される"],["現在","葺石が復元され、月の輪郷土館で出土品を展示"]],"who":[["近藤義郎","発掘を指導した考古学者。のち岡山大学教授"],["地元の人々","発掘にのべ約1万人が参加したといわれる"],["月の輪の首長","古墳に葬られた、名前の伝わらない地域の王"]],"deep":["墳丘は直径約60m、高さ約10mの円墳で、造出し（張り出し）をもちます。山の頂上に築かれ、周囲からよく見える位置にあります。","中央の粘土槨からは、鏡・鉄剣・鉄刀・玉類などが出土しました。粘土で棺を包む埋葬方法は、古墳時代中期によく見られます。","発掘参加者はのべ約1万人と伝えられ、専門家だけでなく住民が主体となった発掘として、日本考古学史に残る出来事とされます。","この発掘は、戦後の «国民的歴史学運動» の代表例として語られ、のちの住民参加型の文化財保護にも影響を与えたとされます。","記録映画 «月の輪古墳» は1954年に完成し、全国で上映されました。発掘の風景を記録した貴重な映像資料です。","古墳の名前の由来ははっきりせず、地元での古い呼び名がそのまま使われています。"],"look":["復元された葺石の墳丘","頂上からの吉井川流域の眺め","麓の月の輪郷土館の出土品と発掘写真","山道の途中の案内板"],"q":["1953年の月の輪古墳の発掘に参加した人は、のべ何人くらい？","約1万人といわれます。地元の人や学生、先生などが参加しました。"],"koji":[],"myth":"«月の輪» の名の由来は不明。参加人数は «のべ約1万人» とされる概数。","img":["近藤義郎","円墳","柵原町","美咲町"],"wp":"月の輪古墳","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/Tsukinowa_Kofun_01.JPG",2048,1362,"月の輪古墳"],["c:3/37/Hachimanyama_kofun-Aichi02.jpg",712,440,"円墳"],["c:3/3e/Kichigahara_Station_-03.jpg",2592,1944,"柵原町"],["c:5/51/Ohaga-nishi_-06.jpg",3583,2570,"美咲町"]]},{"id":"33_komorizuka","n":"こうもり塚古墳（巨大な横穴式石室）","yomi":"こうもりづかこふん","cat":"遺跡","rank":"A","y":570,"era":["kofun"],"sh":"国指定史跡","ad":"総社市上林","st":"JR総社駅から車で約10分。備中国分寺から歩いて約5分","la":34.68,"lo":133.768,"hook":"懐中電灯を手に、古墳の中へ。大人が立って歩ける巨大な石の部屋に、家の形をした石棺が眠る。","lead":"こうもり塚古墳は、長さ約100mの前方後円墳です。6世紀後半に造られ、中には全長約19mもある大きな横穴式石室があります。石室の中には家の形をした石棺が残っていて、見学することができます。","story":["備中国分寺の五重塔から少し歩くと、こんもりした森があります。これがこうもり塚古墳。名前の由来は、昔この古墳の石室にたくさんのコウモリが住んでいたから、といわれています。","入口から石室の中へ入ると、ひんやりとした空気に包まれます。通路（羨道）をぬけると、奥に大きな部屋（玄室）があらわれます。高さは3m以上、大人が立ったまま歩ける広さです。«こんな大きな石を、どうやって運んで積んだの?»――巨大な石をすき間なく組み合わせた天井を見上げると、古代の人々の技術におどろかされます。","玄室の中には、家の形をした «家形石棺» が置かれています。この石棺は、井原市のあたりでとれる «浪形石» という貝殻のまじった石灰岩でできているとされます。石棺のふたは屋根のような形をしていて、死者の «家» と考えられていたのかもしれません。","6世紀後半というと、巨大古墳の時代はすでに終わりに近づいていました。それでも、全長約100mの前方後円墳と、これほどの規模の石室を造れた人物は、吉備の中でも特に有力な首長だったのでしょう。","石室の中は照明があり、決められた時間なら自由に見学できます。すぐ近くには備中国分寺や国分尼寺跡があり、古墳時代から奈良時代への歴史の流れを一度にたどることができます。静かに石室に入り、1400年以上前の人々に思いをはせてみてください。"],"tl":[["6世紀後半","こうもり塚古墳が築かれたと考えられる"],["奈良時代","近くに備中国分寺・国分尼寺が建てられる"],["昭和時代","国の史跡に指定される"],["平成・令和","吉備路風土記の丘の一部として整備され、石室内部を見学できる"],["現在","備中国分寺とあわせて訪れる人が多い"]],"who":[["吉備の首長","古墳に葬られた、名前の伝わらない有力者"],["下道氏","備中を拠点とした古代豪族。関係を指摘する説がある"]],"deep":["横穴式石室の全長は約19.4mとされ、岡山県内最大級、全国でも有数の規模です。玄室は長さ約7.7m・幅約3.6m・高さ約3.7mといわれます。","家形石棺は «浪形石» と呼ばれる貝殻石灰岩製とされ、井原市浪形付近が産地と考えられています。","石室内からは、ほかにも陶棺の破片や須恵器、馬具などが出土したことが知られています。何人かが追加で葬られた可能性があります。","墳丘長は約100m。6世紀後半の前方後円墳としては、全国的に見ても大きい部類に入ります。","近くの箭田大塚古墳（倉敷市真備町）と並ぶ巨石墳で、吉備の6世紀の有力首長の墓として比べて語られます。","«こうもり塚» の名は、石室にコウモリが多く住んでいたことからとされます。","6世紀後半は、全国で横穴式石室が広まり、ひとつの石室に家族を追加で葬ることが増えた時代です。大きな石室は、一族の «家の墓» としての性格ももっていました。"],"look":["全長約19mの横穴式石室（内部見学可）","玄室の家形石棺","天井の巨大な石","近くの備中国分寺の五重塔"],"q":["こうもり塚古墳の名前の由来は？","石室にたくさんのコウモリが住んでいたからといわれます。"],"koji":[],"myth":"被葬者は不明。石室の寸法は資料により多少の差がある。","img":["横穴式石室","備中国分寺","家形石棺","前方後円墳"],"wp":"こうもり塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:0/04/Koumoridzuka_kofun_air.jpg",278,209,"こうもり塚古墳"],["c:5/59/Koumorizuka_Kofun%2C_zenkei.jpg",6014,3998],["c:2/27/Koumorizuka_Kofun%2C_sekishitsu-3.jpg",3950,5984],["c:1/10/Koumorizuka_Kofun%2C_sekishitsu-2.jpg",3960,5990],["c:1/19/Koumorizuka_Kofun%2C_sekishitsu-1.jpg",6016,4000],["c:e/e5/Koumoridzuka_Kofun_07.jpg",3872,2592],["c:0/01/Koumoridzuka_Kofun_05.jpg",3872,2592],["c:5/59/Monjuin_Nishi_Kofun%2C_sendou-1.jpg",6002,3978,"横穴式石室"]]},{"id":"33_yata_otsuka","n":"箭田大塚古墳（真備の巨石室）","yomi":"やたおおつかこふん","cat":"遺跡","rank":"A","y":580,"era":["kofun"],"sh":"","ad":"倉敷市真備町箭田","st":"井原鉄道 吉備真備駅から歩いて約15分","la":34.638,"lo":133.6995,"hook":"吉備真備のふるさとに眠る巨石の部屋。豪雨の災害をこえて、今も町の歴史を見守る。","lead":"箭田大塚古墳は、倉敷市真備町にある直径約50mの大きな円墳です。6世紀後半ごろに造られ、中には全長約19mの横穴式石室があります。奈良時代の学者・吉備真備を生んだ豪族 «下道氏»の祖先の墓ではないかと考えられています。","story":["倉敷市の真備町は、奈良時代に遣唐使として唐に渡り、のちに右大臣にまでなった学者・吉備真備のふるさととされます。真備は «下道（しもつみち）» という豪族の出身でした。その下道氏の祖先が眠るのでは、といわれるのが箭田大塚古墳です。","古墳は小高い丘の上にある大きな円墳です。入口から石室に入ると、巨大な石が積み重ねられた部屋が奥へと続いています。全長は約19m。こうもり塚古墳と並ぶ、岡山県でも最大級の石室です。«大きな石の重みを、どうやって支えているの?»――天井の石は、左右の壁に少しずつせり出すように積まれ、重さを分散させています。","石室からは、馬具や須恵器、金の耳飾りなど、多くの品が見つかりました。6世紀の後半、この地の首長が大きな力をもっていたことがわかります。のちに吉備真備のような人物が生まれる土台が、ここにあったのかもしれません。","2018年7月、西日本豪雨（平成30年7月豪雨）で、真備町は小田川などの堤防が決壊し、町の広い範囲が浸水しました。多くの方が亡くなり、今も多くの人がその日を忘れていません。古墳は高台にあり、町の人々とともに、その苦しい時をこえてきました。","復興が進む真備町で、古墳は地域の歴史を伝える大切な場所です。近くには吉備真備公園や、真備の墓と伝わる場所もあります。石室の中の静けさの中で、1400年以上続いてきたこの土地の歩みに思いをはせてみてください。"],"tl":[["6世紀後半","箭田大塚古墳が築かれたと考えられる"],["695年","吉備真備が生まれたとされる"],["717年","吉備真備が遣唐留学生として唐へ渡る"],["766年","吉備真備が右大臣になる"],["2018年7月","西日本豪雨で真備町が大きな被害を受ける"]],"who":[["下道氏","備中の古代豪族。古墳の主の一族と考えられる"],["吉備真備","下道氏出身の学者・政治家。遣唐使として活躍"],["吉備の首長","古墳に葬られた、名前の伝わらない有力者"]],"deep":["墳丘は直径約54mの円墳とされ、横穴式石室の全長は約19.1m。石室は南向きに開口し、内部を見学できます（管理状況により変わるので事前確認が安心）。","石室は羨道と玄室からなり、玄室の奥に一段高い区画がある構造が指摘されています。","出土品には須恵器・馬具・装身具などがあり、6世紀後半の有力首長の墓にふさわしい内容です。","吉備真備は下道国勝の子で、はじめ «下道真備» と名乗り、のちに «吉備朝臣» の姓を与えられました。","真備町にはほかにも古墳が多く、この地域が古代の下道郡の中心だったと考えられています。","2018年の西日本豪雨では、真備町で多数の方が犠牲になりました。訪れる際は、地域の記憶に敬意をもって歩きたい場所です。"],"look":["全長約19mの横穴式石室（内部見学）","巨石を積んだ天井","高台からの真備町の眺め","近くの吉備真備公園"],"q":["箭田大塚古墳の近くで生まれたとされる、奈良時代の遣唐使はだれ？","吉備真備です。のちに右大臣になりました。"],"koji":[],"myth":"下道氏の墓とする説は推定。石室見学の可否は時期により異なる可能性。","img":["吉備真備","下道氏","横穴式石室","平成30年7月豪雨"],"wp":"箭田大塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:e/ec/Yata_Otsuka_Kofun%2C_funkyu.jpg",5568,3712,"箭田大塚古墳"],["c:4/41/Yata_Otsuka_Kofun%2C_sendou-2.jpg",5568,3712],["c:f/fb/Yata_Otsuka_Kofun%2C_sendou-1.jpg",5568,3712],["c:8/8b/Yata_Otsuka_Kofun%2C_sekkan-3.jpg",5305,3533],["c:d/d7/Yata_Otsuka_Kofun%2C_sekkan-2.jpg",5568,3712],["c:4/49/Yata_Otsuka_Kofun%2C_sekkan-1.jpg",5568,3712],["c:f/f7/Yata_Otsuka_Kofun%2C_genshitsu-2.jpg",5568,3712],["c:e/ec/Yata_Otsuka_Kofun%2C_genshitsu-1.jpg",5568,3712]]},{"id":"33_tsushima","n":"津島遺跡（弥生のムラと水田）","yomi":"つしまいせき","cat":"遺跡","rank":"A","y":-300,"era":["yayoi","jomon"],"sh":"国指定史跡","ad":"岡山市北区いずみ町","st":"JR津山線 法界院駅から歩いて約15分（岡山県総合グラウンド内）","la":34.6771,"lo":133.9203,"hook":"運動公園の中に、弥生の村がある。2300年前、ここで米づくりが始まっていた。","lead":"津島遺跡は、岡山市の県総合グラウンドの中にある弥生時代の遺跡です。弥生時代前期の水田の跡と、人々が暮らしたムラの跡が見つかりました。建物が建てられる予定でしたが、市民の保存運動によって守られ、国の史跡になりました。","story":["1968年、岡山県の総合グラウンドに武道館を建てる工事が始まろうとしていました。事前の調査で地面を掘ると、そこから弥生時代の土器や、竪穴住居の跡、そして水田の跡が次々とあらわれたのです。","«弥生時代のはじめのころの水田が、こんなにはっきり残っているなんて»。当時、弥生時代前期の水田跡が見つかることはとてもめずらしく、研究者たちはおどろきました。水田には、あぜのような区画があり、人々が工夫して水を管理していたことがわかりました。","けれども、遺跡の上には建物が建つ計画でした。«このままでは、貴重な遺跡が壊されてしまう»。研究者や市民たちは保存を求める運動を起こしました。話し合いの末、武道館の建設場所は変更され、遺跡は守られることになったのです。1971年、津島遺跡は国の史跡に指定されました。","その後の調査で、ここには縄文時代の終わりから人々が暮らし、弥生時代にかけて村が営まれたことがわかってきました。狩りや漁で暮らしていた人々が、やがて米づくりを始め、定住するようになっていく――日本の歴史の大きな変わり目が、この場所に刻まれています。","今は遺跡の一部が公園として整備され、竪穴住居や高床倉庫が復元されています。すぐ近くでは、スポーツを楽しむ人々の声が聞こえます。2000年以上前の人々の暮らしと、今の私たちの暮らしが、同じ場所で重なっているのです。"],"tl":[["縄文時代後期","この地に人々が暮らし始める"],["弥生時代前期","水田がつくられ、ムラが営まれる"],["1968年","武道館建設前の調査で遺跡が見つかる"],["1969年","保存運動が起こり、建設計画が見直される"],["1971年","国の史跡に指定される"],["2000年代","史跡公園として整備・公開"]],"who":[["津島のムラの人々","弥生時代にここで米づくりをした人々"],["保存運動の人々","遺跡を守るために声を上げた研究者や市民"]],"deep":["津島遺跡は、弥生時代前期の水田と集落が同じ場所で確認された遺跡として重要です。水田は小さな区画に分けられ、水を管理する工夫が見られます。","遺跡の発見は1968年、県営の武道館建設の事前調査がきっかけでした。保存運動の結果、建設地が変更されたことは、文化財保護の歴史でもよく知られています。","縄文時代後期の土器も出土しており、縄文から弥生への移り変わりを考えるうえで大切な遺跡です。","遺跡は «岡山県総合グラウンド» の敷地内にあり、スポーツ施設と史跡が共存する珍しい例です。","園内には竪穴住居・高床倉庫などが復元され、ガイダンス施設で出土品の複製や解説を見ることができます。","岡山平野には、ほかにも百間川遺跡群など、弥生時代の水田跡が見つかった遺跡が多くあります。"],"look":["復元された竪穴住居と高床倉庫","弥生時代前期の水田跡の表示","ガイダンス施設の展示","総合グラウンドの中の史跡公園の景観"],"q":["津島遺跡が守られるきっかけになったのは何？","建物の建設で壊されそうになり、研究者や市民が保存運動を起こしたことです。"],"koji":[],"myth":"","img":["弥生時代","水田","竪穴建物","高床式倉庫"],"wp":"津島遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:f/ff/Tsushima_site%2C_Okayama01.jpg",3264,2448,"津島遺跡"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:7/79/Oryza_sativa_Rice_sprouts_ja01.jpg",1024,768,"水田"],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴建物"],["c:4/41/Yoshinogari-iseki_takayukashiki-souko.JPG",5619,3720,"高床式倉庫"]]},{"id":"33_tsukumo","n":"津雲貝塚（人骨170体の縄文貝塚）","yomi":"つくもかいづか","cat":"遺跡","rank":"A","y":-1000,"era":["jomon"],"sh":"国指定史跡","ad":"笠岡市西大島","st":"JR山陽本線 笠岡駅から車で約15分。車が便利","la":34.506,"lo":133.535,"hook":"貝殻の山の下から、170体をこえる縄文人が見つかった。歯を抜き、腕輪をはめ、ひざを折って眠っていた。","lead":"津雲貝塚は、笠岡市にある縄文時代後期から晩期の貝塚です。大正時代の発掘で、170体をこえる人骨が見つかり、縄文時代の人々の体つきや暮らし、葬り方を知る大切な手がかりになりました。国の史跡に指定されています。","story":["いまの笠岡市のあたりは、縄文時代には海がもっと内陸まで入りこんでいました。人々は海辺の小高い場所にムラをつくり、貝をとり、魚をつって暮らしていました。食べ終わった貝殻を捨てた場所が積み重なってできたのが «貝塚» です。","大正時代のはじめ、この貝塚が研究者たちの注目を集めます。1915年ごろから、京都帝国大学の清野謙次らが次々と発掘を行いました。すると、貝殻の層の下から、たくさんの人骨があらわれたのです。その数は170体をこえました。«貝塚は、ただのごみ捨て場ではなかったの?»","貝殻にふくまれるカルシウムのおかげで、骨は溶けずによく残っていました。多くの人は、ひざを強く折り曲げた «屈葬» の姿勢で葬られていました。死者の魂がさまよい出ないようにするため、あるいは母のおなかの中の姿にもどすため――理由については、いろいろな説があります。","骨を調べると、健康な歯をわざと抜いた «抜歯» のあとが見つかりました。大人になる儀式や、結婚のしるしだったのではないかと考えられています。また、貝で作った腕輪をはめた人や、鹿の角で作った飾りを身につけた人もいました。縄文の人々も、おしゃれや儀式を大切にしていたのです。","津雲貝塚の人骨は、日本人のルーツや縄文人の体つきを研究する上で、とても大切な資料になりました。今、貝塚の場所は静かな畑と住宅地の中にあり、案内板がその歴史を伝えています。3000年以上前、ここに生きた人々に思いをはせ、そっと手を合わせたくなる場所です。"],"tl":[["縄文時代後期〜晩期","貝塚が形成され、人々が葬られる"],["1915年ごろ","研究者による発掘が始まる"],["1919年ごろ","京都帝国大学の清野謙次らが本格的に発掘"],["大正時代","人骨170体以上が見つかる"],["昭和時代","国の史跡に指定される"],["現在","跡地に案内板が立ち、出土品は博物館などに保管"]],"who":[["清野謙次","京都帝国大学の医学者。人骨を多数発掘・研究した"],["津雲のムラの人々","縄文時代にここで暮らし、葬られた人々"],["研究者たち","出土人骨から縄文人の姿を明らかにした"]],"deep":["出土人骨は170体以上とされ、一つの貝塚からの縄文人骨としては国内有数の数です。当時の発掘は現代の基準から見ると記録が十分でない部分もあります。","多くの人骨に抜歯のあとが見られ、どの歯を抜いたかの型によって、出身や婚姻の区別を表したのではないかとする研究があります（諸説）。","貝輪（貝製の腕輪）をはめた人骨が見つかっており、とくに女性に多いとされます。腕輪は子どものころにはめ、外せなくなったと考えられています。","鹿角製の腰飾りを身につけた人骨も出土しており、集団の中で特別な役割をもつ人だった可能性があります。","出土品や人骨の多くは京都大学などで保管・研究され、一部は笠岡市の郷土館などで紹介されています。","笠岡市には «カブトガニ博物館» もあり、縄文時代から続く浅い海の環境を今に伝えています。"],"look":["貝塚跡の案内板と周辺の地形","笠岡市立郷土館の関連展示","かつての海岸線を想像できる丘からの眺め"],"q":["縄文人の骨に見られる、健康な歯をわざと抜く風習を何という？","«抜歯» です。大人になる儀式などのしるしと考えられています。"],"koji":[],"myth":"抜歯・屈葬の意味は諸説。発掘の年や体数は資料により差がある。","img":["貝塚","清野謙次","屈葬","抜歯"],"wp":"津雲貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/Tsukumo_Kaizuka%2C_gaikan.jpg",5990,3960,"津雲貝塚"],["j:e/e5/%E6%B4%A5%E9%9B%B2%E8%B2%9D%E5%A1%9A%E5%87%BA%E5%9C%9F_%E6%8A%9C%E6%AD%AF%E4%BA%BA%E9%AA%A8.JPG",4179,3444],["j:3/3d/%E6%B4%A5%E9%9B%B2%E8%B2%9D%E5%A1%9A%E5%87%BA%E5%9C%9F_%E7%B8%84%E6%96%87%E5%9C%9F%E5%99%A8.JPG",3919,3247],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:2/28/Oguruwa_shell_mounds-Flexed_burial.jpg",2048,1536,"屈葬"],["c:4/4e/M%C3%A9tiers-Dentiste%2C_humour-ann%C3%A9es_20.JPG",252,369,"抜歯"]]},{"id":"33_kumayama","n":"熊山遺跡（謎の石積み三段塔）","yomi":"くまやまいせき","cat":"遺跡","rank":"A","y":770,"era":["nara","heian"],"sh":"国指定史跡","ad":"赤磐市奥吉原（熊山の山頂付近）","st":"JR山陽本線 熊山駅から登山道を歩いて約2時間半。山頂近くまで車道があり、車なら駐車場から歩いて数分","la":34.7953,"lo":134.0955,"hook":"標高500mあまりの山の上に、石を三段に積み上げた «ピラミッド» のような塔がひっそり立っている。だれが、何のために?","lead":"熊山の山頂近くに、四角い石積みを三段に重ねた不思議な遺構があります。奈良時代ごろの仏教にかかわる建物と考えられていますが、何に使われたのかは、今もはっきりわかっていません。山の中には同じような石積みがほかにもたくさん見つかっていて、«謎の遺跡» として知られています。","story":["岡山市の東、吉井川のそばにそびえる熊山。ふもとからは、なだらかな緑の山にしか見えません。ところが山頂の近くまで登ると、木々のあいだに、平たい石をていねいに積み上げた四角い塔があらわれます。一番下の段は一辺が10mをこえ、その上に一回り小さな段、さらに小さな段。まるで小さなピラミッドのようです。","«いったい、だれがこんな山の上に?» 近くの村の人たちも、昔から不思議に思っていました。熊山は古くから山岳信仰の山で、山の上には «霊山寺» というお寺があったと伝わります。お坊さんたちが修行する聖なる山だったのです。石積みもお寺とかかわるものだろう、と考えられてきました。","昭和のはじめ、この石積みが荒らされる事件がありました。そのとき中から焼き物の入れ物が見つかったといわれ、それが奈良時代ごろのものらしいことから、遺跡の年代を考える手がかりになりました。一方で、ていねいな発掘調査が十分にできていないため、くわしいことはまだ霧の中です。","何のための建物だったのか。お坊さんになるための儀式をする «戒壇» だという説、お経をうめた «経塚» だという説、えらい人のお墓だという説、仏さまをまつる «塔» だという説……。研究者の意見は今も分かれています。山を歩くと、ほかにも崩れかけた石積みがあちこちに残っていて、この山全体が一つの大きな祈りの場だったことを感じさせます。","答えが出ていないからこそ、熊山の石積みは人をひきつけます。«日本のピラミッド» とよばれることもありますが、エジプトのピラミッドとは関係ありません。静かな山頂で石の段を見上げながら、1200年以上前にこれを積んだ人たちの祈りに思いをはせてみてください。"],"tl":[["奈良時代ごろ","熊山の山頂近くに三段の石積みが築かれたと考えられる"],["平安時代ごろ","熊山は山岳信仰の霊場としてさかえ、霊山寺があったと伝わる"],["昭和のはじめ","石積みが荒らされ、中から焼き物の容器が見つかったといわれる"],["戦後","国の史跡に指定され、保護されるようになる"],["現在","熊山の山頂一帯はハイキングコースとして親しまれる"]],"who":[["霊山寺の僧たち","熊山で修行した僧。石積みを築いた人たちと考えられることが多い"],["山岳信仰の修験者","熊山を聖なる山としてあがめ、山中で祈りをささげたと伝わる"],["研究者たち","戒壇説・経塚説・墓説・仏塔説など、石積みの正体を議論してきた"]],"deep":["形のひみつ: 石積みは下から上へ三段に小さくなる方形（四角形）の «段台» 状。最上段の中央に穴（石室）があり、ここに何かを納めたと考えられています。","年代の手がかり: 中から見つかったとされる焼き物の容器から、奈良時代ごろにさかのぼると考えられています。ただし正式な発掘による確認が少なく、年代にも幅があります。","正体をめぐる諸説: «戒壇»（僧になる儀式の壇）説、«経塚»（お経を後の世に残すため埋める）説、«墳墓» 説、«仏塔» 説などが出されていて、決め手はありません。","熊山には同じような石積みが数十か所あるといわれ、山全体が信仰の場だったと考えられます。国の史跡になっているのは、もっとも形がよく残る山頂近くの一基です。","よく似た三段の石積み遺構は、奈良県の «頭塔» や大阪府の遺跡など、ほかの地域にも例があり、比べて研究されています。","山頂の近くには熊山神社があり、かつての霊山寺にかかわる伝承とともに、山の信仰が今も続いていることがわかります。"],"look":["三段に重なる石積みの全体の形（まわりを一周して見る）","最上段の中央にあるくぼみ（石室の跡）","山中に点在するほかの石積みの跡","熊山神社と山頂からの吉井川の眺め"],"q":["熊山遺跡の石積みは何段になっている？","三段。下から上へだんだん小さくなる四角い石積みです。"],"koji":[],"myth":"石積みの目的（戒壇・経塚・墓・仏塔）は諸説。霊山寺の由来や、石積みから見つかった遺物の詳細は伝承・記録に幅がある。","img":["熊山","霊山寺 (赤磐市)","頭塔"],"wp":"熊山遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Kumayama_remains.JPG",2240,1488,"熊山遺跡"],["j:e/e2/%E7%86%8A%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E9%99%B6%E8%A3%BD%E7%AD%92%E5%BD%A2%E5%AE%B9%E5%99%A8.JPG",3505,5284],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/e5/Zuto_2022.jpg",4608,2592,"頭塔"]]},{"id":"33_saidaiji","n":"西大寺（はだか祭り «会陽»）","yomi":"さいだいじ","cat":"寺社","rank":"A","y":1510,"era":["nara","muromachi","edo"],"sh":"","ad":"岡山市東区西大寺中","st":"JR赤穂線 西大寺駅から歩いて約10分","la":34.6475,"lo":133.9948,"hook":"真冬の真夜中、まわしだけの男たち数千人が、たった2本の «宝木» をめざしてぶつかり合う。","lead":"西大寺は奈良時代にはじまったと伝わる、岡山を代表するお寺です。毎年2月には «会陽（えよう）» という «はだか祭り» が開かれ、福を授かるとされる «宝木（しんぎ）» を男たちが奪い合います。国の重要無形民俗文化財にもなっている、日本で有名な奇祭の一つです。","story":["吉井川の河口近く、古くから市が立ってにぎわった西大寺の町。そのまん中に、大きな石の門と本堂をもつ «金陵山西大寺» があります。お寺の話によると、奈良時代、安隆（あんりゅう）という僧が観音さまをまつったのがはじまりとされています。","このお寺では昔から、お正月の修行の最後に、お坊さんがお札（牛玉）を配っていました。ありがたいお札を受け取りたい人がどんどん増え、ついには奪い合いに。«それなら、いっそ投げよう» ――こうして、お札が «宝木» という木の棒に変わり、今の会陽の形ができたといわれます。はじまりは室町時代の1510年と伝わります。","祭りの夜、町は熱気に包まれます。まわしと白たびだけの «はだか» の男たちが、冷たい水で身を清めてから本堂の前へ。«わっしょい、わっしょい»。ぎっしりつめかけた人の体から、白い湯気がもうもうと立ちのぼります。","夜10時、本堂の高い窓（御福窓）の明かりがふっと消えます。その瞬間、住職が宝木を投げ入れ、男たちの大きな波がうねります。«どこだ!» «こっちだ!» 暗やみの中で、宝木をつかんだ者がどこにいるかもわかりません。境内から外へ持ち出し、決められた場所に届けて、はじめて «福男» となるのです。","«なぜ真冬のはだかで?» それは、身を清めて仏さまの力をいただくため。今では女性や子どもも参加できる行事もあり、町全体で守り伝える祭りになっています。ふだんの静かな境内で、あの夜の熱気を想像してみるのもおもしろいですよ。"],"tl":[["奈良時代（伝）","安隆上人が観音をまつって寺をひらいたと伝わる"],["1510年","会陽がはじまったと伝わる"],["江戸時代","岡山藩主池田家の保護を受け、会陽は岡山を代表する行事に"],["2016年","«西大寺の会陽» が国の重要無形民俗文化財に指定"],["現在","毎年2月第3土曜日の夜に会陽が行われる"]],"who":[["安隆上人","お寺をひらいたと伝わる僧"],["福男","会陽で宝木をつかみ、境内の外へ持ち出して届けた人"],["岡山藩主池田家","江戸時代にお寺を保護した大名"]],"deep":["宝木（しんぎ）は、長さ約20cmの香木の棒で、2本が投げ込まれるといわれます。これを «枡（ます）» に立てて届けると、その年の福が授かるとされます。","御福窓（ごふくまど）は本堂の高いところにある窓。住職はここから宝木を投げます。窓の明かりが消える一瞬が、祭りのいちばんの見せ場です。","もとは修正会（しゅしょうえ）という新年の法会の «結願»（最後の日）に、お札を配っていたのが起源。お札の奪い合いが祭りに変わっていきました。","はだかで押し合う男たちの体温で、本堂のまわりに湯気が立ちこめるのは会陽の名物。冷え込む2月の夜ならではの光景です。","お寺の正式名は «金陵山西大寺»。高野山真言宗の寺で、石造りの «石門»、三重塔、牛玉所殿など見どころが多くあります。","会陽は戦前から全国に知られ、ほかの地域の «はだか祭り» にも影響を与えたといわれます。"],"look":["本堂の «御福窓»（宝木が投げられる窓）","石造りの石門（山門）","三重塔","牛玉所殿（牛玉＝お札の神をまつる）"],"q":["会陽で男たちが奪い合う木の棒の名前は？","«宝木（しんぎ）»。これを手にして届けた人が «福男» とよばれます。"],"koji":[{"w":"福男","m":"祭りで福をつかんだ男性。会陽では宝木を届けた人をこうよぶ"}],"myth":"寺の開創（奈良時代）や、会陽のはじまり（1510年）は寺の伝承。","img":["西大寺会陽","西大寺駅","金陵山"],"wp":"西大寺 (岡山市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Hadaka_Matsuri_%28-Naked_Festival-%29_festivities_in_Saidaiji%2C_Japan.jpg",1200,799,"西大寺 (岡山市)"],["c:2/25/Kinryouzan_Saidaiji_07.JPG",1600,1064],["c:f/fe/Kinryouzan_Saidaiji_06.JPG",1600,1064],["c:2/2e/Kinryouzan_Saidaiji_05.JPG",1600,1064],["c:6/6b/Kinryouzan_Saidaiji_02.JPG",1600,1064],["c:2/2b/Kinryouzan_Saidaiji_08.JPG",1063,1600],["c:8/8f/Kinryouzan_Saidaiji_04.JPG",1063,1600],["c:8/89/Hadaka_Matsuri_%28-Naked_Festival-%29_in_Saidaiji%2C_Japan.jpg",1200,798]]},{"id":"33_saijo_inari","n":"最上稲荷（高松の日蓮宗霊場）","yomi":"さいじょういなり","cat":"寺社","rank":"A","y":1600,"era":["nara","azuchi","edo"],"sh":"","ad":"岡山市北区高松稲荷","st":"JR吉備線 備中高松駅から歩いて約40分。駅からタクシーやバスも利用できる","la":34.705,"lo":133.811,"hook":"鳥居をくぐった先にあるのは «お寺»。稲荷なのに日蓮宗という、ちょっと不思議な霊場。","lead":"最上稲荷は、正式には «最上稲荷山妙教寺» という日蓮宗のお寺です。大きな鳥居があり、神社のようにも見えますが、仏さまと神さまをいっしょにまつる昔ながらの形を今に残しています。お正月にはたくさんの初もうでの人でにぎわいます。","story":["岡山市の西、備中高松の山すそ。道路をまたぐ朱色の大きな鳥居が、遠くからでも目に入ります。参道には土産物の店が並び、坂の上には大きなお堂。ここが «最上さま» と親しまれる最上稲荷です。","お寺の話によると、奈良時代、孝謙天皇が病気になったとき、報恩大師という僧がこの山で祈ったところ、«最上位経王大菩薩» が白い狐にのって現れた、と伝わります。天皇の病気はよくなり、ここに祈りの場ができたとされます。","戦国時代、このあたりは毛利と羽柴秀吉がぶつかった «備中高松城の戦い» の舞台になりました。お寺も戦火で焼けてしまったといわれます。そのあと、江戸時代のはじめに領主となった花房職之（はなぶさもとゆき）が日蓮宗の僧をまねいて再興し、ここは日蓮宗のお寺として生まれ変わりました。","«でも、どうしてお寺に鳥居が?» 明治時代、政府は神さまと仏さまを分ける命令（神仏分離）を出しました。多くの寺社がどちらかに分かれましたが、最上稲荷は許しを得て、仏教のお寺として «稲荷» の信仰を続けることができたといわれます。だから、今もお寺なのに鳥居があるのです。","本殿で手を合わせたあと、少し山を登ると、古い «奥の院» や、もともとお堂があった «元宮» 跡にも行けます。朱の鳥居、日蓮宗のお題目、狐の像。いろいろな信仰がまじり合う、ふしぎで楽しい霊場です。"],"tl":[["奈良時代（伝）","報恩大師が山で祈り、最上位経王大菩薩が現れたと伝わる"],["1582年","備中高松城の戦い。周辺が戦場となり寺も焼けたといわれる"],["江戸時代はじめ","領主の花房職之が日蓮宗の僧をまねいて再興したと伝わる"],["明治時代","神仏分離のなかで、寺として稲荷信仰を続ける"],["昭和","参道をまたぐ大鳥居が建てられる"],["現在","初もうでに多くの人が訪れる霊場としてにぎわう"]],"who":[["報恩大師","奈良時代の僧。最上稲荷の起こりにかかわると伝わる"],["孝謙天皇","病気平癒の祈りがきっかけになったと伝わる天皇"],["花房職之","江戸時代はじめの領主。日蓮宗の寺として再興したと伝わる"],["羽柴秀吉","近くの備中高松城を水攻めにした武将"]],"deep":["«最上位経王大菩薩»は、稲荷の神さまを仏教の菩薩として拝む名前。日蓮宗の «法華経» の信仰と稲荷信仰がむすびついた、めずらしい形です。","日本では «三大稲荷» の一つといわれることがありますが、どこを三大に数えるかは地域や時代で変わります。","明治の神仏分離では多くの寺社が神社か寺かに分かれました。最上稲荷は寺として残り、鳥居や狐の像など、神社らしい姿も持ち続けました。","本殿（霊光殿）のほか、山の上には旧本殿とされる «元宮»、奥の院などがあり、山全体が信仰の場になっています。","すぐ近くには «備中高松城跡» や、秀吉の水攻めの堤の跡があり、戦国時代の歴史歩きとあわせて訪ねることができます。"],"look":["参道をまたぐ大鳥居","本殿（霊光殿）と、狐の像","山の上の元宮・奥の院","近くの備中高松城跡"],"q":["最上稲荷は、神社？それともお寺？","お寺。正式名は «最上稲荷山妙教寺» という日蓮宗の寺です。"],"koji":[],"myth":"奈良時代の開創や報恩大師・孝謙天皇の話は寺の縁起（伝承）。«三大稲荷»の数え方も諸説。","img":["備中高松城","日蓮宗","稲荷神"],"wp":"最上稲荷","rel":{"ev":[],"grave":[]},"ph":[["c:2/22/Saijo_Inari_02.JPG",2592,1944,"最上稲荷"],["c:c/cc/251101_Saijo-inari_Okayama_Japan29s3.jpg",5472,3648],["c:9/93/251101_Saijo-inari_Okayama_Japan27s3.jpg",3648,5472],["c:4/44/251101_Saijo-inari_Okayama_Japan20s3.jpg",5472,3648],["c:8/8b/251101_Saijo-inari_Okayama_Japan16s3.jpg",5472,3648],["c:9/93/251101_Saijo-inari_Okayama_Japan06s3.jpg",5472,3648],["c:e/e6/251101_Saijo-inari_Okayama_Japan01s3.jpg",5472,3648],["c:3/30/Saijou_inari01.jpg",1280,960]]},{"id":"33_raikyuji","n":"頼久寺（小堀遠州の庭）","yomi":"らいきゅうじ","cat":"寺社","rank":"A","y":1604,"era":["muromachi","edo"],"sh":"国指定名勝（頼久寺庭園）","ad":"高梁市頼久寺町","st":"JR伯備線 備中高梁駅から歩いて約15分","la":34.7935,"lo":133.6205,"hook":"白い砂の海に、まるく刈り込んだサツキの «波»。若き日の小堀遠州がつくったと伝わる庭。","lead":"頼久寺は、備中松山城のふもと、高梁の町にある禅寺です。江戸時代のはじめ、のちに茶人・作庭家として有名になる小堀遠州がここに住み、庭をつくったと伝わります。その庭は国の名勝に指定され、遠州の初期の作品として大切にされています。","story":["城下町・高梁の武家屋敷の通りをぬけると、石段の上に頼久寺の門が見えてきます。門をくぐり、書院に座ると目の前に広がるのが、白砂とサツキの大刈り込みの庭。遠くの山（愛宕山）が、まるで庭の一部のように取りこまれています。","寺の名は、戦国時代にこの地を治めた上野頼久（うえのよりひさ）という武将にちなむといわれます。室町時代から戦国時代にかけて、この寺は備中の武将たちの信仰を集めてきました。","関ヶ原の戦いのあと、備中は徳川の支配になり、小堀正次とその子・政一（のちの遠州）が «備中国奉行» として送りこまれました。松山城は荒れていたため、親子はしばらく頼久寺を仮の住まいにしたといわれます。«この寺で、若き遠州は何を考えていたのだろう?»","遠州はのちに、江戸幕府の作事奉行として城や御所の工事にたずさわり、茶の湯の «遠州流» をひらいた人物です。頼久寺の庭は、そんな遠州がまだ若かったころに手がけたとされる作品。白砂は海、刈り込みは寄せる波、中の石組みは鶴と亀――めでたい «蓬莱» の世界をあらわしているといわれます。","派手さはないけれど、見れば見るほど心が静まる庭です。季節によって、新緑、5〜6月のサツキの花、紅葉と表情が変わります。縁側に座って、400年前の若き作庭家の目になって庭をながめてみましょう。"],"tl":[["室町時代","寺がひらかれたと伝わる（安国寺とする伝えも）"],["戦国時代","上野頼久が寺を再興し、のちの寺名の由来となったと伝わる"],["1600年","関ヶ原の戦い。備中は徳川方の支配に"],["1600年代はじめ","小堀正次・政一（遠州）親子が備中国奉行となり、寺を仮の住まいとする"],["江戸時代はじめ","遠州が庭をつくったと伝わる"],["昭和","頼久寺庭園が国の名勝に指定される"]],"who":[["小堀遠州（政一）","備中国奉行。のちの大名茶人・作庭家。庭をつくったと伝わる"],["小堀正次","遠州の父。備中国奉行として赴任"],["上野頼久","戦国時代の武将。寺名の由来になったと伝わる"]],"deep":["庭は «蓬莱式枯山水»。白砂で海を、サツキの大刈り込みで波をあらわし、鶴島・亀島の石組みを配したといわれます。水を使わずに海を表現する工夫です。","«借景»: 庭の奥の愛宕山を、庭の景色の一部として取りこんでいます。塀や生け垣の高さが、山が一番美しく見えるように考えられているといわれます。","遠州は、のちに伏見奉行、作事奉行などをつとめ、名古屋城天守や二条城の工事にもかかわったとされる多才な人物。茶の湯では «綺麗さび» の美意識で知られます。","頼久寺の庭は、遠州の «初期の作» とされる数少ない例。遠州作と伝わる庭は全国に多いのですが、確かな記録で裏づけられるものは限られます。","すぐ近くの備中松山城は、現存天守をもつ «山城» として有名。遠州親子は、この城の修築にもかかわったといわれます。"],"look":["書院から見る枯山水の庭","サツキの大刈り込み（5〜6月の花どき）","借景の愛宕山","近くの石火矢町の武家屋敷通り"],"q":["頼久寺の庭で、サツキの大刈り込みがあらわしているとされるものは？","海の «波»。白砂を海に見立て、刈り込みで寄せる波をあらわしているといわれます。"],"koji":[{"w":"借景","m":"庭の外の山や景色を、庭の一部として取り入れて見せる技法"}],"myth":"庭が遠州の作とするのは寺の伝えと通説による。寺の創建や寺名の由来も諸説。","img":["小堀政一","備中松山城","枯山水"],"wp":"頼久寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/75/220101_Raikyuji_Takahashi_Okayama_pref_Japan02s3.jpg",6000,4000,"頼久寺"],["c:c/cc/220101_Raikyuji_Takahashi_Okayama_pref_Japan10s3.jpg",6000,4000],["c:c/c4/220101_Raikyuji_Takahashi_Okayama_pref_Japan08s3.jpg",6000,4000],["c:5/59/220101_Raikyuji_Takahashi_Okayama_pref_Japan07s3.jpg",6000,4000],["c:5/5f/Raikyuji_20180502_112529.jpg",4608,2592],["c:2/24/Raikyuji_20180502_111143.jpg",4608,2592],["c:2/22/Raikyuji_20180502_110437.jpg",4608,2592],["c:9/9c/Raikyuji_20180502_105917.jpg",4608,2592]]},{"id":"33_sogenji","n":"曹源寺（岡山藩主池田家の菩提寺）","yomi":"そうげんじ","cat":"墓所","rank":"A","y":1698,"era":["edo"],"sh":"","ad":"岡山市中区円山","st":"JR岡山駅から路線バスで約30分、«円山» 付近下車。車の利用が便利","la":34.6712,"lo":133.9712,"hook":"後楽園をつくった殿さまと名家老が、もう一つ心をこめてつくった «殿さまのための寺»。","lead":"曹源寺は、岡山藩主・池田綱政が江戸時代の中ごろにひらいた禅寺で、池田家の菩提寺（先祖の墓や位牌を守る寺）です。境内には藩主一族の墓所があり、今は海外から修行に来る人も多い «国際禅道場» としても知られています。","story":["岡山の町の東、操山のふもとの静かな森。長い参道を歩いていくと、どっしりした山門と本堂、そして大きな池のある庭があらわれます。ここが池田家の菩提寺・曹源寺です。","寺をひらいたのは、岡山藩の2代藩主・池田綱政。父の光政は «名君» として知られ、儒学を重んじた殿さまでした。綱政は、後楽園をつくらせたことで有名です。その綱政が1698年ごろにこの寺をひらき、池田家の人びとをまつる場所にしました。","工事をまかされたとされるのは、家老の津田永忠。後楽園、閑谷学校、新田開発など、岡山藩の大きな工事を次々と手がけた «スーパー官僚» です。«殿のお寺だ、決して手をぬくな»――そんな声が聞こえてきそうな、ていねいなつくりの伽藍です。","境内の奥には、綱政をはじめとする池田家の人びとの墓所があります。石の門や灯籠が並ぶ静かな空間は、藩の歴史をしずかに見守ってきました。一族の墓所なので、訪ねるときは手を合わせ、静かに歩きましょう。","時代はうつり、昭和の終わりごろから、曹源寺には世界中から坐禅をしに人が集まるようになりました。英語が飛びかう禅寺――«殿さまの寺» は今、国際的な修行の場になっています。江戸と現代が、同じ庭の中でつながっているのです。"],"tl":[["1672年","池田光政が隠居し、綱政が2代藩主となる"],["1687年","綱政の命で後楽園の造営がはじまる"],["1698年ごろ","綱政が曹源寺をひらく"],["江戸時代","池田家の菩提寺として、藩主一族の墓所が整えられる"],["昭和の終わりごろ","海外からの修行者を受け入れる国際禅道場として知られるようになる"]],"who":[["池田綱政","岡山藩2代藩主。曹源寺をひらき、後楽園をつくらせた"],["津田永忠","岡山藩の家老。寺の工事にかかわったといわれる"],["池田光政","綱政の父。岡山藩の名君として知られる"]],"deep":["曹源寺は臨済宗妙心寺派の禅寺。«曹源» は禅の源流を意味する言葉に由来すると考えられています。","岡山藩では、光政が儒教式の葬り方（儒葬）を重んじ、和意谷に墓所を築きました。一方、綱政は仏教（禅宗）の寺として曹源寺をひらき、父とはちがう考え方が見られます。","寺の建物や庭の工事には、後楽園や閑谷学校を手がけた津田永忠がかかわったといわれます。岡山藩の大工事の多くにこの人の名前が出てきます。","池のある庭は、背後の山の緑とあわせて四季の変化を楽しめます。庭と伽藍の配置は、江戸時代の禅寺らしいおちついたつくりです。","境内の墓所は池田家の一族のもので、墓参の場所です。見学のときはマナーを守り、立ち入れない場所には入らないようにしましょう。","綱政は能や和歌を好んだ文化人でもありました。後楽園に能舞台を設けたこととあわせると、曹源寺の落ち着いた庭にも、綱政らしい美意識を感じることができます。"],"look":["参道と山門","本堂前の池のある庭","池田家墓所（静かに見学）","後楽園とあわせて、綱政ゆかりの場所をめぐる"],"q":["曹源寺をひらいた岡山藩主は、何という有名な庭園もつくらせた？","後楽園。池田綱政が津田永忠にまかせてつくらせた大名庭園です。"],"koji":[{"w":"菩提寺","m":"先祖の墓や位牌をまつり、供養を続けてもらうための寺"}],"myth":"寺の工事への津田永忠の関与の程度や、墓所にまつられる人物の範囲は資料で確認を。","img":["池田綱政","津田永忠","岡山後楽園"],"wp":"曹源寺 (岡山市)","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Sogenji_05.JPG",1600,1064,"曹源寺 (岡山市)"],["c:c/c3/%E6%9B%B9%E6%BA%90%E5%AF%BA%EF%BC%88%E5%B2%A1%E5%B1%B1%E5%B8%82%EF%BC%89%E5%B1%B1%E9%96%80.jpg",3024,4032],["c:5/59/Sogenji_the_Ikedas_Graveyard_02.JPG",1600,1064],["c:a/a7/Sogenji_17.JPG",1600,1064],["c:e/e1/Sogenji_09.JPG",1063,1600],["c:0/03/Sogenji_the_Ikedas_Graveyard_04.JPG",1600,1064,"池田綱政"],["c:9/90/Tsuda_Nagatada_003.JPG",2000,3008,"津田永忠"],["c:4/4b/Okayama_Korakuen_Garden01.jpg",2861,1866,"岡山後楽園"]]},{"id":"33_waidani","n":"和意谷池田家墓所（光政が眠る山）","yomi":"わいだにいけだけぼしょ","cat":"墓所","rank":"A","y":1667,"era":["edo"],"sh":"国指定史跡","ad":"備前市吉永町和意谷","st":"JR山陽本線 吉永駅から車で約20分。駐車場から墓所へは山道を歩く","la":34.865,"lo":134.241,"hook":"仏教のお墓ではなく «儒教» の形で。名君・池田光政が、祖父や父を京都から山奥へ移した理由とは。","lead":"和意谷池田家墓所は、岡山藩主・池田光政が江戸時代の前半に築いた、池田家の墓所です。京都のお寺にあった祖父・輝政や父・利隆の墓を、儒教の考え方にもとづく形でこの山に移しました。光政自身もここに葬られ、深い森の中に大きな墓が点々と並んでいます。","story":["備前市の北、吉永の町からさらに山あいへ。車を降りて木々のあいだの石段を登っていくと、ひんやりした空気の中に、石の柵にかこまれた大きな円い墓が姿をあらわします。まわりに人家はなく、聞こえるのは鳥の声と風の音だけです。","池田光政は、江戸時代のはじめに岡山藩をおさめた殿さまです。学問、とくに儒学を大切にし、庶民のための学校 «閑谷学校» をつくったことでも知られます。«先祖を正しくまつることこそ、人の道の基本だ»――光政はそう考えました。","当時、祖父の輝政や父の利隆の墓は、京都の妙心寺の塔頭（護国院）にありました。光政は、仏教式ではなく儒教の礼にもとづいた墓所を領内につくろうと決め、場所をさがします。えらばれたのが、この和意谷の山でした。1660年代、墓は京都から移され、儒教式でまつり直されました。","工事を指揮したのは、光政の信頼があつかった津田永忠。閑谷学校や後楽園もてがけた人物です。山の地形を生かし、尾根ごとに «一のお山»«二のお山» と名づけられた墓域が配置されています。1682年に亡くなった光政も、この山に葬られました。","«なぜ、こんなに人里はなれた場所に?» 静かで清らかな山こそ、先祖の霊を安らかにまつるのにふさわしいと考えたのでしょう。今も墓所は大切に守られています。訪ねるときは、しずかに一礼してから歩きたい場所です。"],"tl":[["1613年","池田輝政が亡くなる。京都の妙心寺に葬られる"],["1632年","光政が鳥取から岡山へ移り、岡山藩主となる"],["1660年代","光政が和意谷に墓所を築き、輝政・利隆らの墓を京都から移す"],["1670年","閑谷学校の整備がはじまる（庶民のための学校）"],["1682年","光政が亡くなり、和意谷の墓所に葬られる"],["昭和","«岡山藩主池田家墓所» として国の史跡に指定される"]],"who":[["池田光政","岡山藩主。儒教を重んじ、この墓所を築いた"],["池田輝政","光政の祖父。姫路城を大改築した大名。京都から改葬された"],["池田利隆","光政の父。京都から改葬された"],["津田永忠","岡山藩の家臣。墓所の工事を指揮したといわれる"]],"deep":["儒葬（じゅそう）: 儒教の礼にしたがった葬り方。仏教式の火葬ではなく土葬とし、墓には «碑» と円い墳丘をもつなど、中国の礼式にならった形がとられました。","墓域は «一のお山» から «七のお山» まで尾根ごとに分かれて配置されているといわれ、山全体が一つの墓所として設計されています。","光政は寛文年間に、領内の寺を大きく減らす «寺院整理» を行い、神職や儒式の葬礼をすすめました。和意谷墓所はその考え方をもっともよくあらわす場所です。","同じ津田永忠がかかわった閑谷学校（国宝の講堂）とは、車で行ける距離にあります。二つを合わせて訪ねると、光政の «儒学の国づくり» がよくわかります。","墓所は今も池田家ゆかりの人びとによって守られています。見学は公開されている範囲にかぎり、墓域の柵の中には入らないようにしましょう。","山道は石段や坂が多く、雨のあとはすべりやすくなります。歩きやすい靴で、時間に余裕をもって訪ねるのがおすすめです。"],"look":["森の中にたたずむ円い墳丘と石の碑","尾根ごとに分かれた «お山» の配置","石の柵や参道の石段のていねいなつくり","近くの閑谷学校とあわせて訪ねる"],"q":["池田光政がこの墓所をつくるときに大切にした考え方は、仏教と儒教のどっち？","儒教。仏教式ではなく、儒教の礼にもとづいて先祖をまつり直しました。"],"koji":[{"w":"孝","m":"親や先祖を大切にし、敬うこと。儒教でもっとも大切な徳の一つ"}],"myth":"改葬の正確な年や、各 «お山» にまつられる人物の割り当ては資料で確認を。","img":["池田光政","池田輝政","閑谷学校"],"wp":"和意谷池田家墓所","rel":{"ev":[],"grave":[]},"ph":[["c:6/69/Gravestone_of_Ikeda_Terumasa.jpg",1600,1064,"和意谷池田家墓所"],["c:3/36/%E6%B1%A0%E7%94%B0%E5%85%89%E6%94%BF2.jpg",1386,2109,"池田光政"],["c:d/de/Terumasa_Ikeda.jpg",601,550,"池田輝政"],["c:d/d0/Shizutani_school_the_hall_and_shosai.JPG",2240,1488,"閑谷学校"]]},{"id":"33_tenjinyama","n":"天神山城跡（浦上宗景の本拠）","yomi":"てんじんやまじょうあと","cat":"城","rank":"A","y":1532,"era":["muromachi"],"sh":"","ad":"和気郡和気町田土","st":"JR山陽本線 和気駅から車で約15分。登山口から山頂の城跡まで歩いて約40分","la":34.8264,"lo":134.177,"hook":"吉井川を見下ろす細長い尾根に、戦国大名・浦上宗景の «天空の本拠» があった。","lead":"天神山城は、戦国時代に備前をおさめた浦上宗景が本拠にした山城です。吉井川ぞいの険しい山の尾根に、曲輪（くるわ）が長く連なっています。宗景は家臣の宇喜多直家にやぶれてこの城を失い、備前の主役は宇喜多氏へとかわっていきました。","story":["和気の町から吉井川をさかのぼると、川のすぐそばに切り立った山がそびえています。その尾根の上、標高400mほどのところに天神山城の跡があります。登山道を息を切らして登ると、石垣の跡や平らにけずられた曲輪が、尾根にそって次々とあらわれます。","城の主は浦上宗景。浦上氏は、もとは播磨・備前をおさめる赤松氏の家臣でしたが、戦国の世に力をのばし、主家をしのぐほどになりました。宗景は兄の政宗と対立し、この天神山に城をかまえて、備前の東部を支配したといわれます。","宗景のもとで力をつけた家臣がいました。宇喜多直家です。直家は知恵と策略で備前の武将たちを次々とたおし、しだいに主君の宗景をもしのぐ実力を持つようになります。«家臣が主君をのみこむ»――それが戦国の «下剋上» でした。","やがて直家は宗景に反旗をひるがえします。1570年代、天神山城は宇喜多方に攻められ、宗景は城を捨てて播磨へのがれたといわれます。落城の年には諸説があります。こうして、備前の主役は浦上氏から宇喜多氏へとかわりました。","«なぜ、こんな不便な山の上に城を?» 敵に攻められにくく、吉井川の水運や街道を見張るのに最適だったからでしょう。今は静かな山ですが、尾根の上に立つと、戦国の武将たちが見た景色がそのまま広がっています。"],"tl":[["1530年代","浦上宗景が天神山城を築いたと伝わる（1532年ごろとも）"],["1550年代","宗景が兄・政宗と対立し、備前東部を支配"],["1560年代","宇喜多直家が宗景の家臣として勢力をのばす"],["1570年代","直家が宗景にそむき、天神山城が落城（1575年説・1577年説などがある）"],["現在","城跡は登山道が整備され、ハイキングで訪ねられる"]],"who":[["浦上宗景","戦国時代の武将。天神山城を本拠に備前を支配"],["浦上政宗","宗景の兄。播磨の室山城を拠点とし、宗景と対立"],["宇喜多直家","宗景の家臣から戦国大名にのし上がった武将"],["明石氏・延原氏など","浦上氏の重臣たち。落城のころ宇喜多方についた者もいたといわれる"]],"deep":["天神山城は、尾根の上に曲輪を一列に並べた «連郭式» の山城。南北に長く、本丸・二の丸・三の丸などの平地が尾根にそって続きます。","城跡には石垣の一部や、堀切（尾根を切って敵の侵入をふせぐ溝）などが残り、戦国時代の山城の姿をよく伝えています。","浦上氏は赤松氏の守護代として力をたくわえ、宗景の兄・浦上村宗の時代には主家の赤松義村を殺すほどの力を持ちました。宗景の代はその «下剋上» の延長にあります。","宗景は一時、織田信長から備前・播磨・美作の支配を認める朱印状を得たといわれます。それが家臣たちの反発をまねいた、とする見方もあります。","落城の年については、1575年（天正3年）説と1577年（天正5年）説などがあり、史料によって異なります。","宗景は落城後、播磨などに逃れて生きのびたとされますが、晩年のことはよくわかっていません。"],"look":["尾根にそって続く曲輪の連なり","石垣の跡と堀切","山頂近くから見下ろす吉井川の流れ","登山口の案内板（城の見取り図）"],"q":["天神山城の城主・浦上宗景をたおした家臣はだれ？","宇喜多直家。家臣が主君をたおす «下剋上» の典型といわれます。"],"koji":[{"w":"下剋上","m":"身分の下の者が上の者をたおして、その地位をうばうこと"}],"myth":"築城年と落城年はいずれも諸説。宗景の晩年も不明な点が多い。","img":["浦上宗景","宇喜多直家","浦上氏"],"wp":"天神山城 (備前国)","rel":{"ev":[],"grave":[]},"ph":[["c:3/32/Tenjinyama_Castle_02.JPG",2048,1362,"天神山城 (備前国)"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/44/Ukita_Naoie.jpg",350,410,"宇喜多直家"]]},{"id":"33_numa_jo","n":"沼城跡（宇喜多直家の本拠・大返しの経由地）","yomi":"ぬまじょうあと","cat":"城","rank":"A","y":1559,"era":["muromachi","azuchi"],"sh":"","ad":"岡山市東区沼","st":"JR山陽本線 上道駅から歩いて約20分","la":34.7036,"lo":134.0342,"hook":"«謀略の名人» 宇喜多直家が出世の足場にした城。のちに秀吉の «中国大返し» の軍勢もここを通った。","lead":"沼城は «亀山城» ともよばれ、戦国時代に宇喜多直家が本拠とした城です。直家はここを拠点に力をのばし、のちに岡山城へうつりました。1582年、本能寺の変を知った羽柴秀吉が備中高松から引き返したとき、軍勢はこの沼城を通って姫路へ向かったといわれます。","story":["岡山市の東、田んぼの中にぽっこりと小さな丘があります。ここが沼城の跡です。名前のとおり、昔はまわりに沼や湿地が広がり、それが天然の堀になっていたと考えられています。","この城の城主は、もとは中山信正という武将でした。浦上氏につかえる宇喜多直家は、信正の娘を妻にむかえ、信正とは «しゅうとと婿» の間がらになります。ところが1559年ごろ、直家は信正を討ち、沼城を手に入れたと伝わります。«謀略の名人» とよばれた直家らしい話です。","沼城に入った直家は、ここを足がかりに、まわりの武将たちを次々と従えていきました。やがて主君の浦上氏をもしのぎ、備前一国を手にします。そして1573年ごろ、もっと広い城下町をつくれる岡山へ本拠をうつしました。これが今の岡山城のはじまりです。","それから約10年後の1582年6月。備中高松城を水攻めにしていた羽柴秀吉のもとに、«信長さま、本能寺にてご自害» という知らせがとどきます。秀吉は毛利と急いで和睦し、全軍を東へ。«一刻も早く京へ!» 軍勢は沼城を通り、ここで休んだともいわれます。その後、姫路、山崎へ。世にいう «中国大返し» です。","今の沼城跡は、小さな丘に碑が立つだけの静かな場所です。けれど、ここは直家が戦国大名へとかけ上がる出発点であり、秀吉が天下へ向かう道のとちゅうでもありました。二つの大きな歴史の流れが交わった、小さな丘なのです。"],"tl":[["戦国時代","中山信正が沼城の城主となる"],["1559年ごろ","宇喜多直家が中山信正を討ち、沼城を本拠とする"],["1560年代","直家が沼城を拠点に備前の武将たちをしたがえる"],["1573年ごろ","直家が岡山城へ本拠をうつす"],["1582年6月","本能寺の変後、羽柴秀吉の軍勢が沼城を経て姫路へ向かう（中国大返し）"],["江戸時代","城は使われなくなり、丘だけが残る"]],"who":[["宇喜多直家","沼城を本拠にのし上がった戦国大名"],["中山信正","直家の妻の父。沼城の城主だったが討たれたと伝わる"],["羽柴秀吉","中国大返しのとき、軍勢が沼城を通過したといわれる"],["宇喜多秀家","直家の子。のちの豊臣五大老の一人"]],"deep":["沼城は «亀山城» ともよばれます。小高い丘（亀山）の上に本丸があり、周囲の沼沢地が守りの役目をはたしたと考えられます。","直家の «謀略»: 舅の中山信正を討った話のほか、宿敵を暗殺した話が多く伝わります。ただし軍記物に書かれた話も多く、どこまで事実かは慎重に見る必要があります。","中国大返しの行程は、6月6日ごろに高松を発ち、沼を経て姫路に入ったとする説が有力ですが、日付や宿泊地にはくわしい議論があります。","直家の子・秀家が沼城で生まれたという伝えもありますが、確かなことはわかっていません。","城跡の丘には «亀山城跡» の碑や案内板があり、まわりの地形からかつての沼地の様子を想像できます。"],"look":["丘の上の本丸跡と城跡の碑","丘のまわりの低い土地（かつての沼地）","岡山城とあわせて、直家の本拠のうつりかわりをたどる"],"q":["秀吉が本能寺の変のあと、備中高松から京へ急いで引き返した出来事を何という？","«中国大返し»。沼城もそのとちゅうの経由地の一つといわれます。"],"koji":[],"myth":"中山信正を討った経緯、大返しで沼城に泊まったかどうか、秀家の生誕地などは諸説・軍記物由来の話を含む。","img":["宇喜多直家","中国大返し","岡山城"],"wp":"亀山城 (備前国)","rel":{"ev":[],"grave":[]},"ph":[["c:c/c2/Numa_Kameyama_Castle_02.JPG",4912,3264,"亀山城 (備前国)"],["c:f/fa/Numa_Kameyama_Castle_10.JPG",4912,3264],["c:c/c4/Numa_Kameyama_Castle_09.JPG",4912,3264],["c:d/db/Numa_Kameyama_Castle_07.JPG",4912,3264],["c:4/40/Numa_Kameyama_Castle_04.JPG",4912,3264],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:7/75/Ruins_of_the_kameyama_castle.jpg",1280,960],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940]]},{"id":"33_tsuneyama","n":"常山城跡（鶴姫と女軍の最期）","yomi":"つねやまじょうあと","cat":"古戦場","rank":"A","y":1575,"era":["azuchi"],"sh":"","ad":"玉野市宇藤木・岡山市南区にまたがる常山","st":"JR宇野線 常山駅から登山口まで歩いて約20分、山頂まで登山約1時間。山頂近くまで車道もある","la":34.5689,"lo":133.9458,"hook":"落城の日、城主の妻・鶴姫は侍女たちとよろいを着け、敵の大軍へ打って出たと伝わる。","lead":"常山は «児島富士» ともよばれる、形の美しい山です。戦国時代、この山の上の城は、毛利軍に攻められて落城しました。そのとき城主の妻・鶴姫が、侍女たちを率いて戦ったという話が伝わり、山頂には «女軍の墓» があります。","story":["岡山市の南、児島湾のほとりにそびえる常山。富士山のような形から «児島富士» とよばれています。山頂からは瀬戸内海と岡山平野が一望でき、戦国時代には海と陸を見張る大切な城がありました。","1575年、備中では «備中兵乱» とよばれる戦いがおきていました。備中の三村元親が毛利氏にそむき、毛利の大軍に攻められたのです。三村の城は次々と落ち、最後に残ったのが、元親の妹・鶴姫の夫、上野隆徳が守る常山城でした。","毛利方の小早川隆景の軍勢に取りかこまれ、城の運命がきまった日。城主の妻・鶴姫は、«女とて、ただ死ぬのを待つわけにはいかぬ»と、よろいを身につけ、なぎなたを手に取りました。侍女たち三十数人もあとに続き、敵の中へ打って出たと伝わります。","鶴姫は、敵の名のある武将・浦宗勝に一騎打ちを申し込みました。しかし宗勝は «女と戦うことはできぬ» と応じなかったといいます。鶴姫は家に伝わる刀を宗勝にわたして «これで、わが家の後をとむらってほしい» と言い、城へもどってみずから命を絶ったと伝わります。","山頂近くには、このとき命を落とした女性たちをしのぶ «女軍の墓» があります。物語は江戸時代の軍記物などで語られてきたもので、細かなところまで事実かはわかりません。それでも、戦いにまきこまれた人びとを思い、静かに手を合わせたくなる場所です。"],"tl":[["戦国時代","常山に城が築かれ、上野氏が城主となる"],["1574〜75年","備中兵乱。三村元親が毛利氏と対立し、三村方の城が次々と落ちる"],["1575年","毛利軍が常山城を攻め、落城。鶴姫と侍女たちが戦ったと伝わる"],["江戸時代","軍記物などで鶴姫の物語が語られる"],["現在","山頂に城跡と «女軍の墓» があり、ハイキングコースになっている"]],"who":[["鶴姫","城主・上野隆徳の妻。三村元親の妹。女軍を率いたと伝わる"],["上野隆徳","常山城の城主。落城のとき自害したと伝わる"],["三村元親","備中の武将。毛利氏と対立した"],["小早川隆景","毛利元就の三男。常山城を攻めた毛利軍の将"],["浦宗勝","毛利方の武将。鶴姫が一騎打ちを申し込んだと伝わる"]],"deep":["«備中兵乱»: 三村元親は、父・家親を暗殺させた宇喜多直家と毛利氏が手を結んだことに反発し、毛利氏からはなれたといわれます。その結果、毛利の大軍に攻められました。","«女軍» の人数は三十数人と伝わりますが、史料によって異なります。物語は江戸時代の軍記物（『備中兵乱記』など）で広まりました。","鶴姫が浦宗勝にわたしたという刀は、家に伝わる名刀だったといわれます。刀の名や、その後の行方についても諸説あります。","浦宗勝は «乃美宗勝» の名でも知られる小早川水軍の将。のちに瀬戸内の海の戦いで活躍しました。","山頂近くには本丸跡や井戸の跡、«女軍の墓» があり、今もお参りの人が花を手向けています。","常山は標高300mほど。山頂からの眺めがよく、児島湾干拓でできた平野や瀬戸内海の島々を見わたせます。"],"look":["山頂の本丸跡と展望","«女軍の墓»（静かに手を合わせる）","城の井戸の跡","児島富士とよばれる山の姿（ふもとから）"],"q":["常山城の落城で、侍女たちを率いて戦ったと伝わる女性はだれ？","鶴姫。城主・上野隆徳の妻で、三村元親の妹です。"],"koji":[],"myth":"鶴姫と女軍の話、浦宗勝との一騎打ちや刀の話は、主に江戸時代の軍記物による伝承。人数や細部は諸説。","img":["備中兵乱","三村元親","小早川隆景"],"wp":"常山城","rel":{"ev":[],"grave":[]},"ph":[["c:2/25/Mt._Tsuneyama.JPG",2048,1362,"常山城"],["c:9/99/Tsuneyamajo_08.JPG",4000,3000],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/9e/Bitchu_Matsuyama_Castle_1.JPG",3008,2000,"備中兵乱"],["c:7/7d/Kobayakawa_Takakage_%28Beisanji_Mihara%29.jpg",299,383,"小早川隆景"]]},{"id":"33_takakoshi","n":"高越城跡（北条早雲生誕の地の伝承）","yomi":"たかこしじょうあと","cat":"城","rank":"A","y":1456,"era":["muromachi"],"sh":"","ad":"井原市西江原町","st":"井原鉄道 早雲の里荏原駅から歩いて約30分（登山を含む）","la":34.6056,"lo":133.4467,"hook":"戦国時代の幕を開けた男・北条早雲。そのふるさとは、備中の山あいの小さな城だったかもしれない。","lead":"高越城は、室町時代に備中の荏原（えばら）をおさめた伊勢氏の城と伝わります。のちに関東で戦国大名となる北条早雲（伊勢宗瑞）は、この伊勢氏の出身で、この城で生まれたという伝承があります。山の上からは、早雲が育ったといわれる荏原の里が見わたせます。","story":["井原市の東、ゆるやかな山の上に高越城の跡があります。登っていくと、木々の間に平らな曲輪が残り、頂上からは、田畑と家並みが広がる荏原の里が見わたせます。«早雲も、この景色を見ていたのだろうか?»","北条早雲は、戦国時代のはじめに伊豆・相模（今の静岡県東部・神奈川県）を手に入れ、関東の戦国大名 «後北条氏» の祖となった人物です。ただし本人は «北条» を名のってはいません。«伊勢新九郎盛時»、出家して «宗瑞» というのが本当の名前です。","昔は «早雲はどこの馬の骨ともわからない浪人だった» という話が有名でした。ところが研究が進み、室町幕府につかえる名門・伊勢氏の一族で、父の伊勢盛定が備中・荏原荘をおさめていたことがわかってきました。そこで、早雲がこの荏原で生まれ育ったという説が有力になったのです。","若いころの早雲は京都にのぼり、将軍に仕えたといわれます。やがて姉（または妹）が嫁いだ駿河の今川家をたすけるために東へ。その後、伊豆の堀越御所を攻め、小田原城を手に入れ、関東に大きな勢力をきずきました。«下剋上の先がけ» とよばれるゆえんです。","高越城のふもとには、伊勢氏ゆかりと伝わる法泉寺があり、早雲の像や供養塔がまつられています。駅の名前も «早雲の里荏原»。小さな山城から、戦国時代という大きな物語がはじまったのかもしれません。"],"tl":[["室町時代","伊勢氏が備中・荏原荘をおさめ、高越城を拠点にしたと伝わる"],["1456年（または1432年）","伊勢盛時（北条早雲）が生まれる（生年は諸説）"],["1480年代","早雲が駿河の今川家をたすけ、東国で活躍をはじめる"],["1493年ごろ","早雲が伊豆の堀越御所を攻め、伊豆を手に入れる"],["1519年","早雲（伊勢宗瑞）が亡くなる"],["現在","城跡は «北条早雲生誕の地» の伝承地として整備されている"]],"who":[["北条早雲（伊勢宗瑞）","後北条氏の祖。ここで生まれたという伝承がある"],["伊勢盛定","早雲の父とされる人物。備中荏原荘をおさめたといわれる"],["北川殿","早雲の姉（または妹）。駿河の今川義忠に嫁いだ"],["今川氏親","北川殿の子。早雲がその家督争いで助けた"]],"deep":["«北条早雲» という名は後世のよび名で、本人は «伊勢新九郎盛時» と名のり、出家して «早雲庵宗瑞» と号しました。«北条» を名のったのは子の氏綱からです。","生年については、1432年説と1456年説があります。1456年説だと、亡くなったときは64歳。近年は1456年説が有力とされますが、決着はしていません。","備中出身説のよりどころは、伊勢盛定が荏原荘の一部を領していたことを示す文書や、法泉寺に残る早雲ゆかりの伝えなどです。一方、京都（山城）で生まれたとする説もあります。","高越城は標高170mほどの山城で、曲輪や堀切の跡が残るといわれます。城跡には «北条早雲生誕之地» の碑が建てられています。","早雲が伊豆を攻めた出来事は、«戦国時代のはじまり» の目印の一つとして、応仁の乱とならんでよく取り上げられます。"],"look":["山頂の城跡と «北条早雲生誕之地» の碑","城跡から見わたす荏原の里","ふもとの法泉寺（早雲ゆかりの伝え）","早雲の里荏原駅の駅名表示"],"q":["北条早雲は、生きているあいだ «北条» を名のっていた？","名のっていません。本人は «伊勢» 氏で、«北条» を名のったのは子の氏綱からです。"],"koji":[],"myth":"早雲の高越城での誕生は伝承。生年（1432年説・1456年説）や出身地（備中説・京都説）も諸説。","img":["北条早雲","後北条氏","伊勢氏"],"wp":"高越城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/Takakoshiyama01.jpg",5472,3648,"高越城"],["c:4/41/Takakoshiyama03.jpg",5472,3648],["c:c/cb/Takakoshiyama02.jpg",5472,3648],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/18/Soun_Hojo_portrait.jpg",673,658,"北条早雲"]]},{"id":"33_myozenji_kassen","n":"明善寺合戦の地（宇喜多直家の出世戦）","yomi":"みょうぜんじかっせんのち","cat":"古戦場","rank":"A","y":1567,"era":["muromachi"],"sh":"","ad":"岡山市中区沢田（明善寺城跡の周辺）","st":"JR岡山駅から路線バスで約20分、沢田付近下車。城跡へは山道を歩く","la":34.6545,"lo":133.965,"hook":"兵力はおよそ4倍の差。それでも勝ったのは、少ない兵をひきいた宇喜多直家だった。","lead":"明善寺合戦は、1567年に備前の宇喜多直家と、備中の三村元親の大軍がぶつかった戦いです。数では大きく負けていた宇喜多軍が、みごとな戦い方で三村軍をやぶりました。この勝利で直家は備前の実力者となり、戦国大名への道を大きく進みました。","story":["岡山市の東、操山のふもと。今は住宅地が広がる沢田のあたりに、かつて «明善寺城» という小さな城がありました。«明禅寺» とも書かれるこの城をめぐって、戦国時代の岡山でもっとも有名な戦いの一つがおこりました。","話は前の年にさかのぼります。備中の大名・三村家親は、備前へ勢力をのばそうとしていました。宇喜多直家は、正面から戦っては勝てないと考え、刺客を送って家親を討ったと伝わります。父を殺された息子の三村元親は、«必ず、宇喜多に仇を»と心に誓いました。","1567年、元親は大軍をひきいて備前へ攻めこみます。その数は2万ともいわれ、対する宇喜多軍は5千ほど。三村軍はまず、明善寺城を取りもどそうと兵を進めます。ところが直家は、先に城を攻めて落とし、三村軍を待ちかまえました。","三村軍はいくつかの隊に分かれて進んできました。直家はその一つ一つを、ばらばらのうちにたたいていきます。«敵が一つにまとまる前に、各個にやぶれ!» 不意をつかれた三村軍は総くずれとなり、多くの兵が命を落としたといわれます。この大敗は «明禅寺崩れ» とよばれました。","この勝利で、直家は備前の武将たちの中で一歩ぬけ出し、やがて主君・浦上氏をもしのぐ力をつけていきます。一方、三村氏との因縁はその後も続き、備中兵乱へとつながっていきました。住宅地の中の小さな山に、戦国の大逆転の記憶がねむっています。"],"tl":[["1566年","三村家親が美作で暗殺される（宇喜多直家が刺客を送ったと伝わる）"],["1567年","三村元親が大軍で備前に攻めこみ、明善寺城周辺で宇喜多軍と戦う（明善寺合戦）"],["1567年","宇喜多軍が勝利。三村軍の敗北は «明禅寺崩れ» とよばれる"],["1570年代","直家が浦上宗景をやぶり、備前の支配者となる"],["1574〜75年","備中兵乱。三村元親が毛利氏に攻められ滅ぶ"]],"who":[["宇喜多直家","備前の武将。少ない兵で三村軍をやぶった"],["三村元親","備中の大名。父の仇をうとうと大軍で攻めこんだ"],["三村家親","元親の父。美作で暗殺されたと伝わる"],["遠藤兄弟","家親を鉄砲で撃ったと伝わる刺客"]],"deep":["兵力は三村軍約2万、宇喜多軍約5千と伝わりますが、数は軍記物によるもので正確とはいえません。«大軍を少数がやぶった» ことが強調されて語られています。","戦い方: 分かれて進んでくる敵を、合流する前に一つずつ攻める «各個撃破»。直家は地形と情報を生かしたといわれます。","三村家親の暗殺は、戦国時代で早い時期の «鉄砲による暗殺» の例として知られます。場所は美作の興善寺と伝わります。","«明善寺» と «明禅寺»、二つの書き方があります。城の名はお寺の名から来たといわれますが、寺そのものは残っていません。","明善寺城跡は小さな山の上にあり、曲輪の跡が残るとされます。山道は整備が十分でないこともあるので、足もとに注意して訪ねましょう。","この戦いのあと、宇喜多と三村の対立は、毛利氏をまきこむ大きな争いへ広がりました。常山城の落城（鶴姫の話）もその流れの中にあります。"],"look":["明善寺城跡の小さな山と、城跡の案内","山の上から見る岡山平野（戦場の広がりを想像）","近くの操山の古墳や史跡とあわせて歩く"],"q":["明善寺合戦で、三村軍の大敗は何とよばれた？","«明禅寺崩れ»。大軍の三村軍が総くずれになったことからこうよばれました。"],"koji":[{"w":"各個撃破","m":"敵がまとまる前に、ばらばらのところを一つずつたおしていく戦い方"}],"myth":"両軍の兵力、家親暗殺の経緯などは軍記物による。戦いの細かな経過は諸説。","img":["宇喜多直家","三村元親","三村家親"],"wp":"明善寺合戦","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Myozenji_Castle_view.JPG",4288,2848,"明善寺合戦"],["c:0/0b/Maru_ni_mitsukashiwa%EF%BC%88%EF%BC%91%EF%BC%89.png",4000,4000],["c:d/de/Myozenji_castle02.jpg",4000,2672],["c:0/03/Okayama_city_view_from_Myozenjijo.JPG",3872,2592],["c:8/80/Myozenji_castle01.jpg",3264,2448],["c:d/dd/%E6%98%8E%E5%96%84%E5%AF%BA%E5%9F%8E%E5%90%88%E6%88%A6.JPG",2048,1536],["c:4/44/Ukita_Naoie.jpg",350,410,"宇喜多直家"]]},{"id":"33_fujito","n":"藤戸の戦いの地（佐々木盛綱の先陣）","yomi":"ふじとのたたかいのち","cat":"古戦場","rank":"A","y":1184,"era":["heian"],"sh":"","ad":"倉敷市藤戸町藤戸","st":"JR倉敷駅から路線バスで約20分、«藤戸» 付近下車","la":34.5535,"lo":133.799,"hook":"馬で海をわたった先陣の手柄。その裏には、命をうばわれた一人の漁師と、泣きさけぶ母の物語があった。","lead":"藤戸の戦いは、1184年、源氏と平氏が児島の海峡をはさんで戦った源平合戦の一つです。源氏の佐々木盛綱は、土地の漁師に浅瀬を教わり、馬で海をわたって平氏を攻めました。この話は『平家物語』や能 «藤戸» で語りつがれ、今も町に伝説の場所が残っています。","story":["今の倉敷市藤戸は、見わたすかぎり陸地です。でも800年以上前、ここは本州と «児島» という島のあいだの海でした。島にいたのは平氏の軍勢、海をはさんで向かいあうのは源氏の軍勢。船を持たない源氏は、海をわたれずに困っていました。","源氏の武将・佐々木盛綱は考えました。«どこかに、馬でわたれる浅瀬はないものか»。盛綱は地元の漁師をたずね、着物などをあたえて浅瀬の場所を聞き出しました。夜、漁師の案内で海に入ってみると、たしかに馬の足がとどく道がある――。","ところが盛綱は、«このことをほかの者に知られてはならぬ» と、その漁師を殺してしまったと『平家物語』は語ります。翌朝、盛綱は家来とともに馬で海へ乗りこみ、みごと平氏の陣に攻めこみました。平氏は児島を捨てて屋島へ逃れ、盛綱は «馬で海をわたった先陣» として大きな手柄をたて、のちに児島をあたえられたといいます。","しかし、物語はここで終わりません。能 «藤戸» では、殺された漁師の年老いた母が盛綱の前にあらわれ、«なぜわが子を殺したのか» とうったえます。盛綱は罪を悔い、漁師のとむらいをします。手柄の影にあった悲しみを、能は静かに描いています。","町には、漁師の母が悲しみのあまり笹をむしりとったため、今も笹が生えないという «笹無山»、盛綱が戦の後に供養をしたと伝わる «藤戸寺» などが残ります。«ほんとうの勝者とはだれだろう?» 陸になった海峡の上で、そんな問いが浮かんできます。"],"tl":[["1183年","平氏が都を落ち、西国へ移る"],["1184年2月","一ノ谷の戦い。平氏は屋島へ"],["1184年12月","藤戸の戦い。佐々木盛綱が馬で海をわたり、平氏を児島から追う"],["1185年","屋島の戦い・壇ノ浦の戦い。平氏がほろぶ"],["室町時代","能 «藤戸» がつくられ、上演される"],["江戸時代","児島湾の干拓が進み、藤戸の海峡は陸地になっていく"]],"who":[["佐々木盛綱","源氏の武将。馬で海峡をわたり、先陣の手柄を立てた"],["浦の男（漁師）","浅瀬を教えたと伝わる土地の漁師。名前は伝わらない"],["平行盛","平氏方の武将。児島に陣をかまえた"],["源範頼","源氏の大将。平氏追討のため西国へ進んだ"]],"deep":["戦いの年は『平家物語』などで元暦元年（1184年）とされます。季節や日付については書物によって違いがあります。","漁師を殺した話は『平家物語』にあるもので、盛綱の非情さと、先陣を争う武士の気質を示す場面として有名です。","能 «藤戸» は、前半で漁師の母が、後半で漁師の霊があらわれて盛綱をうらむ構成。戦の «手柄» の裏側を描いた作品として知られます。","藤戸の «浮洲岩» とよばれた名石は、のちに都へ運ばれ、京都・醍醐寺三宝院の庭の «藤戸石» になったと伝わります。","このあたりの海は、江戸時代からの干拓で陸地になりました。今の地形から当時の海峡を想像するのが、この場所を歩く楽しみです。","盛綱はのちに児島をあたえられ、土地の寺社の保護にかかわったと伝わります。"],"look":["藤戸寺（盛綱の供養の伝え）","笹無山（漁師の母の伝説）","盛綱橋と、かつての海峡のあたり","経ヶ島など、伝説にちなむ場所"],"q":["佐々木盛綱は、どうやって海をわたって平氏を攻めた？","土地の漁師に浅瀬を教わり、馬で海をわたりました。"],"koji":[{"w":"先陣","m":"戦でいちばん先に敵陣に攻め入ること。武士にとって大きな手柄とされた"}],"myth":"漁師の話、笹無山、浮洲岩（藤戸石）の由来は物語・伝承。戦いの日付も書物で違いがある。","img":["佐々木盛綱","藤戸 (能)","平家物語"],"wp":"藤戸の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:4/49/Battle_of_Fujito.jpg",1600,800,"藤戸の戦い"],["c:0/0d/Sasakimoritsuna.jpg",1416,2272],["c:5/58/Sasaki_Moritsuna_kills_a_fisherman.jpg",969,1426],["c:7/73/%E5%B9%B3%E5%AE%B6%E7%89%A9%E8%AA%9E%EF%BD%A5%E7%A5%87%E5%9C%92%E7%B2%BE%E8%88%8E%E3%82%B5%E3%83%B3%E3%83%97%E3%83%AB.png",974,732,"平家物語"]]},{"id":"33_mizushima","n":"水島の戦いの地（日食の源平合戦）","yomi":"みずしまのたたかいのち","cat":"古戦場","rank":"A","y":1183,"era":["heian"],"sh":"","ad":"倉敷市玉島乙島・柏島の周辺","st":"JR山陽新幹線・山陽本線 新倉敷駅から車で約15分","la":34.53,"lo":133.68,"hook":"戦いのさなか、空の太陽が欠けはじめた。あわてたのは源氏、落ち着いていたのは平家だった――?","lead":"水島の戦いは、1183年、木曽義仲の源氏軍と平氏軍が、今の倉敷市玉島の沖で戦った海の戦いです。戦いの日に日食がおきたと記録されていることで有名です。この戦いでは平氏が勝ち、源平合戦のなかで平氏が勢いを取りもどすきっかけになりました。","story":["1183年、木曽義仲は倶利伽羅峠の戦いで平氏をやぶり、京都に入りました。平氏は都を捨てて西へ。四国の屋島に本拠をかまえ、立てなおしをはかります。義仲は平氏を追って、西へ軍を進めました。","義仲の軍は備中までやってきました。家来の足利義清や海野幸広らが、船を集めて四国の平氏を攻めようとします。ところが、平氏はもともと海の戦いが得意な一族。瀬戸内海を知りつくしていました。両軍は、当時は島々だった玉島の乙島・柏島のあたり «水島» の海で向き合います。","戦いの最中、ふしぎなことがおこりました。空の太陽が欠けはじめ、あたりがうす暗くなっていったのです。日食でした。記録によると、源氏の兵たちはおどろき、みだれたといわれます。«これは何かのたたりか?»","一方の平氏は、船どうしをつないで板をわたし、陸のように足場をつくって戦ったといわれます。馬も船にのせ、上陸して攻めかかりました。源氏の大将・足利義清や海野幸広は討ち死にし、源氏軍は大敗しました。","«平氏は日食がおこるのを知っていたのでは?» という話がよく語られます。当時、朝廷は暦で日食を予測しており、都に長くいた平氏がそれを知っていた可能性はありますが、確かなことはわかりません。今は工場や住宅が並ぶ玉島の海辺に、戦いをしのぶ碑が建っています。"],"tl":[["1183年5月","倶利伽羅峠の戦い。木曽義仲が平氏をやぶる"],["1183年7月","平氏が都を落ち、西国へ"],["1183年閏10月","水島の戦い。日食のなか平氏が勝利"],["1184年1月","義仲が源義経らの軍に討たれる"],["1185年","壇ノ浦の戦いで平氏がほろぶ"],["現在","玉島の乙島などに、戦いをしのぶ碑がある"]],"who":[["足利義清","義仲方の大将。この戦いで討ち死にしたといわれる"],["海野幸広","義仲方の武将。この戦いで討ち死にしたといわれる"],["平知盛","平清盛の子。平氏軍を率いた"],["平教経","平氏の猛将。この戦いで活躍したと伝わる"],["木曽義仲","源氏の武将。平氏を追って西へ軍を送った"]],"deep":["この日の日食は、『源平盛衰記』などに記されています。天文学の計算でも、この時期に日本付近で日食がおきたことがたしかめられています。","平氏が日食を事前に知っていたかどうかは、史料からははっきりしません。«平氏は暦を知っていて落ち着いていた» という話は、後世の推測をふくみます。","戦いの場所の «水島» は、当時の玉島付近の海と島々をさすと考えられます。江戸時代以降の干拓で、多くが陸地になりました。","平氏が船をつないで板をわたしたという戦法は、『平家物語』などに描かれています。海上で馬を使うための工夫だったと考えられます。","この敗北で義仲の力は弱まり、京都でも評判を落とします。やがて源頼朝の送った軍に討たれることになりました。","今の «水島» 地区（倉敷市の工業地帯）の名は、この古い地名にちなむといわれます。"],"look":["玉島の乙島付近にある古戦場の碑","かつて島だった乙島・柏島の地形","玉島の港町の古い町並み（あわせて散策）"],"q":["水島の戦いの最中におこった、空の出来事は？","日食。太陽が欠けていくなかで戦いが行われたと記録されています。"],"koji":[],"myth":"平氏が日食を予知していたという話は推測をふくむ。戦いの細かな経過は軍記物による。","img":["木曽義仲","源平合戦","平知盛"],"wp":"水島の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:3/3a/%E8%89%AF%E5%AF%9B%E5%A3%AE%E4%BB%98%E8%BF%91%E3%81%8B%E3%82%89%E8%A6%8B%E3%81%9F%E7%8E%89%E5%B3%B6%E6%B8%AF.jpg",2420,1080],["c:2/27/Minamoto_no_Yoshinaka.jpg",843,767,"木曽義仲"],["c:7/78/Genpei_kassen.jpg",4904,2032,"源平合戦"],["c:0/05/Taira_no_Tomomori.jpg",1403,2180,"平知盛"]]},{"id":"33_kibi_nakayama","n":"吉備の中山（吉備津彦と温羅の神話の山）","yomi":"きびのなかやま","cat":"伝承","rank":"A","y":400,"era":["kofun","muromachi"],"sh":"国宝（吉備津神社本殿・拝殿）","ad":"岡山市北区吉備津・一宮","st":"JR吉備線 吉備津駅から吉備津神社まで歩いて約10分。備前一宮駅から吉備津彦神社まで歩いて約5分","la":34.677,"lo":133.852,"hook":"鬼退治の英雄と、うたれた鬼。二人の物語が «桃太郎» の原形ともいわれる、神話の山。","lead":"吉備の中山は、備前と備中の国ざかいにある小さな山です。ふもとには、備中の一宮・吉備津神社と、備前の一宮・吉備津彦神社があり、どちらも吉備津彦命をまつっています。吉備津彦命が «温羅（うら）» という鬼を退治した伝説は、«桃太郎» の話の原形ともいわれます。","story":["岡山市の西、田んぼの中にこんもりと緑の山があります。標高は170mあまり。昔から «神の山» として大切にされてきた吉備の中山です。西のふもとには吉備津神社、東のふもとには吉備津彦神社。一つの山を、二つの一宮がはさんでいます。","伝説によると、むかし吉備の国に «温羅» という鬼がいました。百済の王子ともいわれる温羅は、山の上に城をかまえ、人びとをおびやかしていたと伝わります。そこへ都から送られてきたのが、吉備津彦命。二人の戦いは、まさに神話の大合戦でした。","吉備津彦命が矢を放つと、温羅も岩を投げ返し、矢と岩は空中でぶつかって落ちたといいます。その場所が «矢喰宮» と伝わります。命が一度に二本の矢を放つと、一本が温羅の目に命中。血が川のように流れ、温羅は鯉に化けて逃げました。命は鵜に化けて追いかけ、ついに温羅をとらえた――と語られます。","とらえられた温羅の首は、ほえつづけて止まりませんでした。そこで吉備津神社の釜の下にうめると、やがて温羅は夢にあらわれ、«これからは釜を鳴らして、吉凶を占ってやろう» と告げたといいます。これが今も続く «鳴釜神事» のはじまりと伝わります。","鬼退治、動物の化身、そして «きび»。«桃太郎の話はここから?» と考える人が多いのも無理はありません。山の上には大きな古墳もあり、ここが古代の «吉備» の人びとにとって特別な場所だったことがわかります。神話と歴史が重なる山を、ぜひ歩いてみてください。"],"tl":[["古墳時代","山の上に中山茶臼山古墳などの古墳がつくられる"],["平安時代","『古今和歌集』に «吉備の中山» をよんだ歌が入る"],["1425年","吉備津神社の本殿が再建される（室町時代）"],["江戸時代","上田秋成の『雨月物語』に «吉備津の釜» の話が書かれる"],["現在","鳴釜神事が今も吉備津神社で行われている"]],"who":[["吉備津彦命","温羅を退治したと伝わる。二つの一宮の祭神"],["温羅","吉備の鬼。百済の王子ともいわれる伝説上の存在"],["上田秋成","『雨月物語』で吉備津神社の鳴釜を題材にした作家"],["足利義満","吉備津神社本殿の再建にかかわったといわれる室町幕府の将軍"]],"deep":["吉備津神社の本殿と拝殿は、室町時代の1425年に完成したといわれ、国宝です。屋根が二つ並ぶ独特の形は «比翼入母屋造（吉備津造）» とよばれます。","吉備津神社の長い回廊は約360mあり、山すそにそって一直線に続きます。","山の上の中山茶臼山古墳は、宮内庁が «大吉備津彦命墓» としている古墳です。考古学的には古墳時代前期の前方後円墳と考えられています。","«まがね吹く 吉備の中山 帯にせる 細谷川の 音のさやけさ» という古い歌があり、«まがね（鉄）» の産地としての吉備を思わせます。","温羅の城とされる «鬼ノ城» は総社市にある古代山城で、実際には7世紀ごろの朝鮮式山城と考えられています。","桃太郎の原形が吉備津彦命の伝説だという説は、昭和のころから広まったもので、各地に «桃太郎のふるさと» をとなえる説があります。"],"look":["吉備津神社の国宝本殿・拝殿と長い回廊","吉備津神社の御釜殿（鳴釜神事の場）","吉備津彦神社と、山への登り口","山上の古墳と «細谷川» の流れ"],"q":["吉備津神社で、釜の鳴る音で吉凶を占う神事を何という？","«鳴釜神事»。温羅の首を釜の下にうめたという伝説と結びついています。"],"koji":[],"myth":"温羅伝説・鳴釜の由来は神話・伝承。桃太郎の原形とする説は後世のもの。古墳の被葬者は不明。","img":["吉備津神社","吉備津彦神社","温羅"],"wp":"吉備の中山","rel":{"ev":[],"grave":[]},"ph":[["j:0/0b/%E5%90%89%E5%82%99%E3%81%AE%E4%B8%AD%E5%B1%B1.JPG",3648,2736,"吉備の中山"],["c:2/22/Nakayama_Chausuyama_Kofun%2C_haisho.jpg",5876,3782],["c:f/fd/Kibitsu_Jinja_10_cropped.jpg",2594,1765,"吉備津神社"],["c:f/f2/Kibitsuhiko-jinja_tourou_and_haiden.JPG",3648,2736,"吉備津彦神社"],["c:c/ce/Ura-kyuusekihi.jpg",5962,3916,"温羅"]]},{"id":"33_ushimado","n":"牛窓（朝鮮通信使の寄港地）","yomi":"うしまど","cat":"町","rank":"A","y":1655,"era":["edo"],"sh":"国指定史跡（本蓮寺境内）","ad":"瀬戸内市牛窓町牛窓","st":"JR赤穂線 邑久駅から路線バスで約20分、«牛窓» 付近下車","la":34.617,"lo":134.157,"hook":"江戸時代、朝鮮からの使節団を乗せた船が、この小さな港に次々と入ってきた。","lead":"牛窓は、瀬戸内海に面した港町です。江戸時代、朝鮮の国王が日本に送った «朝鮮通信使» の船が立ちよった港で、岡山藩が盛大にもてなしました。町には、通信使が宿にしたお寺 «本蓮寺» や、通信使の影響を受けたともいわれる «唐子踊り» が今も残っています。","story":["おだやかな海、オリーブの丘、白い灯台。牛窓は «日本のエーゲ海» ともよばれる明るい港町です。古くから «潮待ち・風待ち» の港として栄え、船乗りたちは、潮の流れや風がよくなるのをここで待ちました。","江戸時代、日本と朝鮮は国交を結び、朝鮮の国王は将軍の代がわりなどに «通信使» を送りました。一行は数百人。釜山を出て対馬をへて、瀬戸内海を船で進み、大坂から陸路で江戸へ向かいました。そのとちゅうの港の一つが、牛窓でした。","通信使がやってくるとなると、岡山藩は大いそがし。港には迎えの船がならび、ごちそうが用意され、町の人びとは見物につめかけました。«どんな人たちだろう?» 色あざやかな衣装、聞きなれない音楽、筆をふるう学者たち。牛窓の人びとにとって、それは外国の文化にふれる大事件でした。","一行が宿にしたのが、港を見下ろす «本蓮寺»。ここで日本の学者や僧と通信使の人びとは、漢詩をやりとりして交流しました。お寺には通信使が書き残した詩の書が伝わっています。言葉は通じなくても、漢字と詩で心を通わせたのです。","町の «唐子踊り» は、子どもたちが異国風の衣装を着て歌い踊る、ふしぎな踊りです。通信使の踊りをまねたのがはじまりともいわれますが、起源ははっきりしません。港町の路地を歩くと、海のむこうの国とつながっていた時代の空気が、今もどこかに残っています。"],"tl":[["古代","潮待ち・風待ちの港として知られ、和歌にもよまれる"],["1607年","江戸時代最初の朝鮮からの使節が来日（以後、計12回）"],["江戸時代","通信使の船が牛窓に立ちより、岡山藩がもてなす"],["1764年","牛窓に立ちよった通信使としては最後の回とされる"],["1994年","本蓮寺の境内が «朝鮮通信使遺跡» として国の史跡に指定"],["現在","唐子踊りが秋祭りで奉納され、町の文化として伝わる"]],"who":[["朝鮮通信使","朝鮮国王が日本へ送った使節団。牛窓に寄港した"],["岡山藩主池田家","通信使の接待を担当した大名"],["本蓮寺の僧","通信使の宿となった寺の僧。詩のやりとりの場を用意した"]],"deep":["通信使は江戸時代に計12回来日しました。最後の1811年は対馬で応接されたため、瀬戸内海を通ったのはそれより前の回です。","本蓮寺は日蓮宗の寺で、室町時代の本堂などが残るといわれます。境内は «朝鮮通信使遺跡 牛窓本蓮寺境内» として国の史跡です。","岡山藩は、牛窓に «御茶屋» という接待用の施設を設けて通信使をもてなしました。料理の品数や献立の記録も残っているといわれます。","唐子踊りは、紺浦の疫神社の秋祭りで、少年二人が踊るもの。岡山県の重要無形民俗文化財に指定されています。起源は通信使説などがありますが、はっきりしません。","牛窓の地名には、神功皇后が牛の姿の怪物をたおしたので «牛転（うしまろび）» とよばれ、それがなまったという伝説があります。","町には «海遊文化館» があり、通信使の行列を再現した資料や、だんじり船などが展示されています。"],"look":["本蓮寺（通信使の宿。港を見下ろす境内）","潮待ち港の古い町並み（しおまち唐琴通り）","海遊文化館の通信使資料","オリーブ園の丘から見る瀬戸内海"],"q":["江戸時代、朝鮮の国王が日本に送った使節団を何という？","«朝鮮通信使»。瀬戸内海を船で進み、牛窓にも立ちよりました。"],"koji":[{"w":"潮待ち・風待ち","m":"潮の流れや風が航海に都合よくなるまで、港で待つこと"}],"myth":"唐子踊りの起源（通信使説）や、地名の由来（牛転伝説）は諸説・伝承。","img":["朝鮮通信使","本蓮寺 (瀬戸内市)","唐子踊り"],"wp":"牛窓町","rel":{"ev":[],"grave":[]},"ph":[["c:f/f7/Setouchi_Ushimado_Port01n4272.jpg",4272,2848,"牛窓町"],["c:9/99/Kuroshima_Venus_Road%2C_gaikan.jpg",6016,4000],["c:c/cc/Honren-ji_%28Setouchi%29%2C_keidai.jpg",6016,4000],["c:4/44/Setouchi_Ushimado_Port04n3200.jpg",3200,2133],["c:1/1c/Ushimado_town-office.jpg",960,720],["c:8/8f/KoreanEmbassy1655KanoTounYasunobu.jpg",2552,1056,"朝鮮通信使"]]},{"id":"33_osafune","n":"備前長船刀剣博物館（刀剣の里）","yomi":"びぜんおさふねとうけんはくぶつかん","cat":"産業","rank":"A","y":1300,"era":["kamakura","muromachi"],"sh":"","ad":"瀬戸内市長船町長船","st":"JR赤穂線 長船駅から歩いて約30分。駅からタクシーの利用が便利","la":34.686,"lo":134.096,"hook":"«日本刀の半分は備前でつくられた» といわれたほどの刀の里。いまも鍛冶場から火花が飛ぶ。","lead":"長船（おさふね）は、鎌倉時代から室町時代にかけて、日本一の刀の産地として栄えた町です。備前長船刀剣博物館では、名刀の展示のほか、刀鍛冶や研ぎ師などの職人の仕事を間近で見ることができます。上杉謙信が愛用した国宝の刀 «山鳥毛» もここに収められています。","story":["吉井川のほとり、長船の里。鎌倉時代、ここには刀鍛冶たちの家が立ちならび、トンテンカン、トンテンカンと鉄を打つ音が一日中ひびいていたといわれます。«長船の刀なら、まちがいない»――全国の武士があこがれた刀が、この里から生まれました。","«なぜ、ここで刀づくりがさかんになったの?» 中国山地では、砂鉄から鉄をつくる «たたら製鉄» が行われていました。その鉄が吉井川の舟で運ばれてきます。炭にする木も豊富。そして、できた刀を運び出す川と街道がありました。刀づくりに必要なものが、そろっていたのです。","長船の刀鍛冶の祖とされるのが «光忠»。その子とされる «長光»、さらに «景光»«兼光» と、名工が次々とあらわれ、«長船派» とよばれるグループになりました。国宝や重要文化財に指定された刀の多くに、長船の名工の名が刻まれています。","しかし戦国時代の終わり、1590年ごろ、吉井川の大洪水が里をおそい、多くの刀鍛冶が命や家を失ったと伝わります。こうして長船の刀づくりは大きくおとろえました。それでも技は細く受けつがれ、現代の刀匠たちがこの地で再び刀を打っています。","博物館では、刀そのものの美しさだけでなく、鍛冶、研ぎ、鞘、白銀（はばき）など、一振りの刀ができるまでの職人の仕事を見学できます。2020年には、瀬戸内市が多くの人の寄付を集めて、国宝の太刀 «山鳥毛» を手に入れました。«刀の里» の物語は、今も続いています。"],"tl":[["鎌倉時代中ごろ","光忠が長船で刀づくりをはじめ、長船派の祖とされる"],["鎌倉時代後期","長光・景光らの名工があらわれ、長船派が全盛に"],["室町時代","大量の注文にこたえ、長船の刀が全国に広まる"],["1590年ごろ","吉井川の大洪水で長船の刀工集団が大きな被害を受けたと伝わる"],["1980年代","備前長船刀剣博物館が開館"],["2020年","瀬戸内市が国宝 «山鳥毛» を取得"]],"who":[["光忠","長船派の祖とされる刀工"],["長光","光忠の子とされる名工。国宝 «大般若長光» で知られる"],["景光","長光の子とされる名工"],["上杉謙信","国宝の太刀 «山鳥毛» を愛用したと伝わる戦国大名"]],"deep":["長船派の刀の特徴として、華やかな «丁子（ちょうじ）乱れ» の刃文などが知られます。時代が下ると «互の目（ぐのめ）» など、刃文の形も変わっていきました。","«大般若長光» は、室町時代に600貫という高値がつけられたことから、600巻ある «大般若経» にかけて名づけられたといわれます（国宝）。","«小竜景光» は、刀身に竜の彫り物がある名刀で、楠木正成が使ったという伝えがありますが、確かではありません。","«山鳥毛» は、長船派ではなく同じ備前の «福岡一文字派» の作とされる国宝の太刀です。刃文が山鳥の羽のように見えることが名の由来といわれます。","室町時代後期には «末備前» とよばれる刀が大量につくられ、戦国時代の需要にこたえました。一方で «数打ち物» とよばれる量産品もふくまれます。","博物館のまわりの «刀剣の里» には、現代の刀匠や研ぎ師などの工房があり、作業の公開日には鍛錬のようすを見られることがあります。"],"look":["展示室の名刀（展示替えがあるので予定を確認）","鍛刀場での刀匠の作業（公開日）","研ぎ・鞘・はばきなどの職人工房","国宝 «山鳥毛» の特別公開（期間限定）"],"q":["長船派の祖とされる刀工はだれ？","光忠。その後、長光・景光などの名工が続きました。"],"koji":[],"myth":"光忠・長光・景光の親子関係は通説。1590年の大洪水の被害規模、小竜景光と楠木正成の関係は伝承をふくむ。","img":["長船派","山鳥毛","大般若長光"],"wp":"備前長船刀剣博物館","rel":{"ev":[],"grave":[]},"ph":[["c:9/90/Bizen_Osafune_Japanese_sword_Museum_1.jpg",4328,3223,"備前長船刀剣博物館"],["c:1/1c/141206_Oishi-jinja_Ako_Hyogo_pref_Japan20bs.jpg",5700,3800,"長船派"],["c:2/29/Tachi_-_Daihannya_Nagamitsu.jpg",2500,1605,"大般若長光"]]},{"id":"33_imbe","n":"伊部の町（備前焼のふるさと）","yomi":"いんべのまち","cat":"産業","rank":"A","y":1580,"era":["kamakura","azuchi","edo"],"sh":"国指定史跡（備前陶器窯跡）","ad":"備前市伊部","st":"JR赤穂線 伊部駅からすぐ","la":34.727,"lo":134.189,"hook":"釉薬をかけず、絵もつけない。炎と灰だけで模様が生まれる、1000年つづく土の焼き物。","lead":"伊部（いんべ）は、備前焼のふるさとです。備前焼は、釉薬（うわぐすり）を使わず、土をそのまま高温で長い時間焼きしめてつくる焼き物で、日本を代表する «六古窯» の一つに数えられます。町には窯元や煙突がならび、中世の大きな窯の跡も残っています。","story":["伊部駅の改札を出ると、そこはもう焼き物の町。通りには窯元やギャラリーが並び、屋根の向こうに四角いレンガの煙突がにょきにょき立っています。塀や道の敷石にも、焼き物のかけらがうめこまれていて、町全体がまるで一つの作品のようです。","備前焼のはじまりは、古墳時代から焼かれていた «須恵器» だといわれます。平安時代の終わりから鎌倉時代にかけて、今のような赤茶色の焼きしめの焼き物になりました。水がめ、すり鉢、つぼ――とてもじょうぶで、«投げても割れぬ備前すり鉢» といわれるほどでした。","«なぜ釉薬をかけないのに、こんなにいろいろな色や模様が出るの?» それが備前焼のいちばんのふしぎです。窯の中で薪の灰がふりかかって溶けると «胡麻»、わらを巻いて焼くと赤い線が走る «緋襷（ひだすき）»、炭にうもれた部分は灰色の «桟切（さんぎり）»。同じものは二つとできません。","桃山時代、茶の湯が広まると、備前焼の素朴な味わいが茶人たちに愛されました。花入れや水指が名品としてもてはやされ、江戸時代には岡山藩が窯元を保護しました。伊部の南や北の山すそには、長さ数十mにもなる大きな共同の窯の跡が残っています。","昭和になると、金重陶陽らが桃山時代の名品にならった作品をつくり、備前焼は再び注目されました。陶陽は備前焼で初めての人間国宝になり、その後も名人が続いています。町を歩き、窯の熱と土のにおいを感じてみましょう。"],"tl":[["古墳時代","このあたりで須恵器が焼かれる（備前焼の源流とされる）"],["鎌倉時代","焼きしめの備前焼が成立し、すり鉢やかめが広く使われる"],["桃山時代","茶の湯の道具として茶人に愛される"],["江戸時代","岡山藩の保護のもと、共同の大窯で焼かれる"],["1956年","金重陶陽が備前焼で初めての人間国宝に認定"],["1982年","国の伝統的工芸品に指定"]],"who":[["金重陶陽","備前焼を再興した陶芸家。備前焼で最初の人間国宝"],["藤原啓","人間国宝の陶芸家"],["山本陶秀","人間国宝の陶芸家"],["千利休ら茶人","桃山時代に備前焼の茶道具を好んだ"]],"deep":["«六古窯» は、中世から今まで続く日本の代表的な焼き物の産地で、備前・瀬戸・常滑・越前・信楽・丹波をさします。","窯変（ようへん）: 窯の中の炎や灰のかかり方で、偶然に生まれる色や模様のこと。«胡麻»«緋襷»«桟切» などの名前がついています。","焼成には、登り窯などで1週間から10日以上も薪をたき続けることが多いといわれます。この長い焼成が、じょうぶで独特の風合いを生みます。","伊部の南大窯・北大窯・西大窯の跡は «備前陶器窯跡» として国の史跡。江戸時代には、いくつかの窯元が共同で巨大な窯を使っていました。","江戸時代、窯元は «六姓»（木村・森・頓宮・寺見・大饗・金重）とよばれる家々が中心だったといわれます。","町の天津神社では、備前焼の狛犬や瓦、陶板などが境内をかざり、焼き物の町らしい姿が見られます。"],"look":["伊部駅の «備前焼伝統産業会館»","町に並ぶ四角いレンガの煙突","南大窯跡など、中世〜江戸の窯跡","天津神社の備前焼の狛犬や陶板"],"q":["わらを巻いて焼くと出る、赤い線の模様を何という？","«緋襷（ひだすき）»。釉薬を使わない備前焼ならではの窯変の一つです。"],"koji":[{"w":"投げても割れぬ備前すり鉢","m":"備前焼のすり鉢がとてもじょうぶだったことを表すことば"}],"myth":"須恵器からの起源や、利休ら特定の茶人との関係は通説・伝承をふくむ。","img":["六古窯","金重陶陽","伊部駅"],"wp":"備前焼","rel":{"ev":[],"grave":[]},"ph":[["c:a/ab/Imbe_Bizen_Okayama_pref_Japan11n.jpg",4410,2940,"備前焼"],["c:1/16/Water_jar_with_lugs%2C_known_as_Tatsutagawa%2C_Bizen_ware%2C_Azuchi-Momoyama_to_Edo_period%2C_1500s-1600s_AD%2C_ceramic_-_Tokyo_National_Museum_-_Ueno_Park%2C_Tokyo%2C_Japan_-_DSC08878.jpg",3315,4166],["c:2/24/Imbe_Bizen_Okayama_pref_Japan01n.jpg",4800,3200],["c:d/de/Flower_Vase_called_%27Tabimakura%27_%28Portable_pillow%29%2C_Bizen_ware%2C_Edo_period%2C_17th_century_-_Tokyo_National_Museum_-_DSC05874.JPG",3402,4828],["c:9/98/Bottle%2C_Bizen_ware%2C_Momoyama_period%2C_1500s_AD%2C_ceramic_-_Hakone_Museum_of_Art_-_Hakone%2C_Kanagawa%2C_Japan_-_DSC08271.jpg",3561,4465],["c:3/3a/Bizen_Pottery_Traditional_and_Contemporary_Art_Museum_Bizen_Okayama_pref_Japan01s3.jpg",3200,4800],["c:9/9f/Bizen-yaki_Traditional_Pottery_Center_Bizen_Okayama_pref_Japan01bs5.jpg",4800,3200],["c:6/6f/Sabukaze_05.JPG",4288,2848]]},{"id":"33_yakage","n":"矢掛宿（山陽道の本陣と脇本陣）","yomi":"やかげしゅく","cat":"街道","rank":"A","y":1800,"era":["edo"],"sh":"国の重要文化財（旧矢掛本陣石井家住宅・旧矢掛脇本陣高草家住宅）","ad":"小田郡矢掛町矢掛","st":"井原鉄道 矢掛駅から歩いて約10分","la":34.6258,"lo":133.588,"hook":"大名が泊まる本陣と、その控えの脇本陣。両方が国の重要文化財として残るのは、全国でここだけ。","lead":"矢掛は、江戸時代に西国の大名たちが参勤交代で通った «山陽道» の宿場町です。大名の宿 «本陣» と、その補助の宿 «脇本陣» の建物がそろって残り、どちらも国の重要文化財に指定されています。白い壁や格子の町並みが続き、江戸の宿場の雰囲気を今に伝えています。","story":["小田川にそって東西にのびる矢掛の町。なまこ壁、うだつ、格子戸。古い町家が道の両側に並び、まるで時代劇の中に入りこんだようです。江戸時代、この道は西国と江戸・大坂を結ぶ大動脈 «山陽道» でした。","参勤交代の季節、大名行列がやってくると宿場は大さわぎ。大名が泊まるのは «本陣»、家来や別の大名は «脇本陣» や旅籠に分かれて泊まりました。矢掛の本陣をつとめたのは石井家、脇本陣は高草家。どちらも地元の有力な商家でした。","本陣石井家は、酒づくりもしていた大きな家です。門をくぐると、大名が通る玄関、殿さまの部屋 «御座敷»、庭園がつづきます。«殿さまはこの部屋でお休みになったのか»――縁側から庭をながめると、行列を迎えた日の緊張感が伝わってくるようです。","本陣には、大名だけでなく身分の高い人も泊まりました。江戸時代の終わり、薩摩から江戸へ向かう篤姫も、ここに泊まったと伝わります。のちに将軍の妻となる篤姫が、どんな思いでこの宿の夜をすごしたのでしょう。","今の矢掛では、秋に «大名行列» を再現する祭りが開かれ、町の人たちが行列を組んで歩きます。古い町家を生かした宿や店も増え、2020年には町並みが国の重要伝統的建造物群保存地区に選ばれました。江戸の旅人の気分で、ゆっくり歩いてみてください。"],"tl":[["江戸時代はじめ","山陽道の宿場として整備される"],["江戸時代","石井家が本陣、高草家が脇本陣をつとめる"],["1853年","篤姫が江戸へ向かう途中、本陣に泊まったと伝わる"],["明治時代","参勤交代がなくなり、宿場の役目を終える"],["昭和","本陣石井家住宅・脇本陣高草家住宅が国の重要文化財に指定"],["2020年","矢掛宿の町並みが重要伝統的建造物群保存地区に選定"]],"who":[["石井家","本陣をつとめた家。酒造業も営んだ"],["高草家","脇本陣をつとめた家"],["篤姫","のちの13代将軍徳川家定の妻。本陣に泊まったと伝わる"],["西国の大名たち","参勤交代で矢掛を通った"]],"deep":["本陣と脇本陣の両方が国の重要文化財に指定されているのは、全国でも矢掛だけといわれます。","本陣石井家住宅は、大名専用の門や玄関、上段の間をもつ «御座敷» など、格式の高いつくりが見どころ。酒蔵などもあわせて残ります。","脇本陣高草家住宅は、なまこ壁や «うだつ» のある外観が特徴。本陣が使えないときなどに大名を泊める役目がありました。","宿場の町並みは、道がところどころで折れ曲がる «鍵の手» などのつくりが見られるといわれます。敵が一気に進めないようにする工夫とされます。","矢掛の大名行列の祭りは、毎年11月ごろに行われ、宿場の歴史を伝える行事として人気です。"],"look":["旧矢掛本陣石井家住宅（御座敷と庭）","旧矢掛脇本陣高草家住宅のなまこ壁とうだつ","宿場の町並みと、道の折れ曲がり","秋の «大名行列» の祭り"],"q":["大名が泊まる宿を何という？","«本陣»。その補助となる宿を «脇本陣» といいます。"],"koji":[{"w":"参勤交代","m":"江戸時代、大名が一年おきなどに江戸と領地を行き来した制度"}],"myth":"篤姫の宿泊は町の伝えによる（年は1853年とされる）。","img":["参勤交代","篤姫","山陽道"],"wp":"旧矢掛本陣石井家","rel":{"ev":[],"grave":[]},"ph":[["c:6/69/160320_Former_Yakage_Honjin_Ishii_Family_Residence_Yakage_Okayama_pref_Japan01s3.jpg",6000,4000,"旧矢掛本陣石井家"],["c:e/e9/%E7%9F%A2%E6%8E%9B%E6%9C%AC%E9%99%A3%E5%BE%A1%E6%88%90%E9%96%80.jpg",5472,3648],["c:1/16/%E7%8A%AC%E9%A4%8A%E6%AF%85%E3%81%AE%E6%9B%B8%EF%BC%88%E7%9F%A2%E6%8E%9B%E6%9C%AC%E9%99%A3%EF%BC%89.jpg",5472,3648],["c:c/c6/2-3_DSC05380%E5%8E%A8%E6%88%BF.jpg",4474,3155],["c:a/ae/160320_Former_Yakage_Honjin_Ishii_Family_Residence_Yakage_Okayama_pref_Japan31s3.jpg",6000,4000],["c:5/56/160320_Former_Yakage_Honjin_Ishii_Family_Residence_Yakage_Okayama_pref_Japan16s3.jpg",6000,4000],["c:f/f0/3-2_DSC07137_%E7%B5%9E%E3%82%8A%E6%A9%9F.jpg",4401,2833],["c:2/2b/3-4_DSC02982.jpg",4240,2832]]},{"id":"33_fukiya","n":"吹屋ふるさと村（ベンガラの町）","yomi":"ふきやふるさとむら","cat":"産業","rank":"A","y":1800,"era":["edo","meiji"],"sh":"","ad":"高梁市成羽町吹屋","st":"JR伯備線 備中高梁駅から路線バスで約1時間、«吹屋» 下車","la":34.8637,"lo":133.495,"hook":"山奥にとつぜんあらわれる、赤い屋根と赤い壁の町。その «赤» は、銅山の町が生んだ宝だった。","lead":"吹屋は、標高500mほどの山の上にある町です。江戸時代から明治時代にかけて、銅山と、赤い顔料 «ベンガラ» の生産で大いに栄えました。ベンガラ色の壁と赤い石州瓦の町並みが残り、国の重要伝統的建造物群保存地区に選ばれています。","story":["高梁の町から、くねくねした山道をバスで1時間。«こんな山の中に町が?» と思ったころ、とつぜん赤い町並みがあらわれます。赤茶色の壁、赤い瓦屋根。まるで絵本の中の町のようです。","吹屋の歴史は、銅山からはじまります。山から銅がとれることは古くから知られ、江戸時代には大坂の商人が経営して多くの人が働きました。明治時代になると三菱が経営し、機械を入れて日本有数の銅山になったといわれます。","そして吹屋を有名にしたもう一つの宝が «ベンガラ»。銅山から出る鉱石をもとにつくった赤い顔料で、焼き物の赤絵、漆器、建物の塗装などに使われました。吹屋のベンガラは色が美しいと評判になり、江戸時代の終わりから明治にかけて、全国一の産地になったといわれます。","ベンガラで大もうけした商人たちは、町の家々を立派につくりました。遠くの石見（島根県）から大工を呼び、赤い石州瓦の屋根、ベンガラ塗りの壁の家を建てたのです。«町並みを一つの色でそろえよう»――町の人びとが協力したから、今の美しい景色ができたといわれます。","町の近くには、豪商が建てた城のような屋敷 «広兼邸» があり、映画のロケ地としても知られています。明治時代の木造校舎 «旧吹屋小学校»、ベンガラづくりを再現した «ベンガラ館»、見学できる坑道 «笹畝坑道» も。山の上の赤い町で、産業が生んだ豊かさの歴史を感じてみてください。"],"tl":[["江戸時代","吹屋の銅山が本格的に開発される"],["江戸時代中ごろ","銅山の鉱石を利用したベンガラづくりがはじまる"],["江戸時代後期〜明治","ベンガラの全国一の産地として栄え、町並みが整う"],["1873年","三菱が銅山の経営にのり出す"],["1977年","町並みが重要伝統的建造物群保存地区に選定"],["2012年","明治時代からの木造校舎・吹屋小学校が閉校"]],"who":[["ベンガラ商人（豪商たち）","ベンガラで財をなし、町並みをつくった"],["広兼家","大庄屋。城のような屋敷を建てた"],["石見の大工","石州瓦の屋根など、町の建物をつくったといわれる"],["三菱（岩崎家）","明治時代に銅山を経営した"]],"deep":["ベンガラのつくり方: 鉱石の硫化鉄から «ローハ（緑礬）» をつくり、それを焼いて水で洗い、干して細かい赤い粉にします。何日もかかる手間のかかる仕事でした。","ベンガラの名は、インドのベンガル地方から伝わったことに由来するといわれます。«弁柄» とも書きます。","九谷焼や伊万里焼の赤絵、輪島塗などの漆器にも吹屋のベンガラが使われたといわれ、日本の «赤» の文化をささえました。","吹屋の町並みは、1977年に全国で最初のころの重要伝統的建造物群保存地区に選ばれました。","広兼邸は江戸時代後期に建てられた屋敷で、高い石垣の上に建つ城のような姿が特徴。映画『八つ墓村』のロケ地としても知られます。","旧吹屋小学校は明治時代に建てられた木造校舎で、2012年まで使われました。修理ののち、見学できるようになっています。"],"look":["ベンガラ色の町並みと石州瓦の屋根","ベンガラ館（ベンガラ工場の再現）","広兼邸（石垣の上の豪商屋敷）","旧吹屋小学校の木造校舎","笹畝坑道（銅山の坑道見学）"],"q":["吹屋の町並みの赤い色のもとになった顔料は何？","«ベンガラ»。銅山の鉱石をもとにつくられた赤い顔料です。"],"koji":[],"myth":"銅山の発見時期（平安時代初めとする伝え）や、町並みを色でそろえた経緯は伝承をふくむ。","img":["ベンガラ","広兼邸","吉岡銅山"],"wp":"吹屋","rel":{"ev":[],"grave":[]},"ph":[["c:8/87/Fukiya01s3200.jpg",3600,2400,"吹屋"],["c:3/3a/Fukiya_katayama_house06s3872.jpg",3872,2592],["c:4/4f/Shimotani_Fukiya_Takahashi06bs3750.jpg",3750,2500],["c:9/99/Sasaune_kodo02s3200.jpg",3200,2142],["c:c/ca/Nishie_House.JPG",2592,1728],["c:4/4c/Fukiya09bs6.jpg",2460,1640],["c:4/4c/Fukiya_historical_museum.jpg",1600,1200],["c:f/fa/Bengala_Akanesawa_red_rock_IMG_5840.jpg",4608,3456,"ベンガラ"]]},{"id":"33_nozaki","n":"旧野崎家住宅（塩田王の屋敷）","yomi":"きゅうのざきけじゅうたく","cat":"産業","rank":"A","y":1833,"era":["edo","meiji"],"sh":"国の重要文化財","ad":"倉敷市児島味野","st":"JR瀬戸大橋線 児島駅から歩いて約15分","la":34.477,"lo":133.81,"hook":"海を塩田に変えた男が建てた、長い長い白壁の屋敷。«塩田王» の暮らしがそのまま残る。","lead":"旧野﨑家住宅は、江戸時代の終わりに塩田の開発で大成功した野﨑武左衛門が建てた屋敷です。広い敷地に主屋、書院、蔵、茶室、庭園がならび、国の重要文化財に指定されています。となりの塩業歴史館では、塩づくりの歴史を学ぶことができます。","story":["児島の町を歩いていくと、長い長い白壁の塀が続く屋敷があらわれます。ここが «塩田王» とよばれた野﨑家の屋敷です。門をくぐると、いくつもの建物と庭が広がり、その大きさにおどろかされます。","野﨑武左衛門は、江戸時代の後期、児島の味野村で生まれました。はじめは足袋の製造・販売で商売をしていたといわれます。しかし武左衛門は、目の前の遠浅の海を見て考えました。«この海を、塩田にできないだろうか»。","武左衛門は、岡山藩の許しを得て、海を堤防でかこみ、広い塩田をつくりました。瀬戸内海は雨が少なく、晴れの日が多い。潮の満ち引きも大きい。塩づくりにぴったりの場所でした。塩田は成功し、武左衛門は大きな富をきずきます。その富で建てたのが、この屋敷でした。","屋敷の中には、客をもてなす書院、いくつもの茶室、石と砂の庭があります。また、塩をたくわえる蔵や、塩田の経営のための部屋もありました。«塩は人の命をささえるもの»――そう考えた武左衛門は、ききんのときに貧しい人びとを助けたとも伝わります。","明治になっても野﨑家は塩業を続け、地域の産業をささえました。その後、塩のつくり方は機械化され、昭和の後半には塩田は姿を消します。けれど屋敷は、塩田王の暮らしと、海とともに生きた町の歴史を、今にしっかりと伝えています。"],"tl":[["1789年","野﨑武左衛門が児島の味野村に生まれる"],["1820年代","武左衛門が塩田の開発をはじめる"],["1830年代","屋敷の建設が進む（その後も増築）"],["1864年","武左衛門が亡くなる"],["昭和の後半","製塩の方法が変わり、塩田がなくなる"],["現在","旧野﨑家住宅として国の重要文化財に指定され、一般公開されている"]],"who":[["野﨑武左衛門","塩田を開発し «塩田王» とよばれた。屋敷を建てた"],["野﨑武吉郎","武左衛門の孫。明治時代に家業を受けつぎ、貴族院議員もつとめた"],["岡山藩","塩田の開発を許可した藩"]],"deep":["入浜式塩田: 潮の満ち引きを利用して海水を塩田の砂にしみこませ、太陽と風で乾かして塩分をこく集めます。それを煮つめて塩をつくりました。","瀬戸内海沿岸は雨が少なく日差しが強いため、江戸時代から «十州塩田» とよばれる一大製塩地帯でした。児島もその一つです。","屋敷の敷地は約3000坪、建物の延べ床面積は約1000坪あるといわれ、主屋の長い外観が特徴です。","屋敷には茶室が複数あり、武左衛門が茶の湯を好んだことがうかがえます。庭の枯山水も見どころです。","昭和の中ごろ以降、塩田は «流下式»、さらに «イオン交換膜法» という工場での製塩に変わり、広い塩田はなくなりました。","児島は、足袋から学生服、ジーンズへと続く繊維の町としても知られます。武左衛門の足袋づくりも、その流れの一つといわれます。"],"look":["長く続く白壁と長屋門","表書院と枯山水の庭","茶室","塩業歴史館（塩づくりの道具や模型）"],"q":["野﨑武左衛門は、何をつくって «塩田王» とよばれた？","塩田。遠浅の海を堤防でかこみ、大規模な塩田を開発しました。"],"koji":[],"myth":"屋敷の建設年や規模の数字、ききんの際の救済の話は資料で確認を。","img":["入浜式塩田","野﨑武左衛門","児島 (倉敷市)"],"wp":"旧野﨑家住宅・野﨑家塩業歴史館","rel":{"ev":[],"grave":[]},"ph":[["c:1/1e/Former_Nozaki_House_2021-08_ac.jpg",5949,3956,"旧野﨑家住宅・野﨑家塩業歴史館"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/93/Marakkanam_Salt_Pans.JPG",4055,2693,"入浜式塩田"]]},{"id":"33_shimotsui","n":"下津井（北前船の港町）","yomi":"しもつい","cat":"町","rank":"A","y":1800,"era":["edo","meiji"],"sh":"","ad":"倉敷市下津井","st":"JR瀬戸大橋線 児島駅から路線バスで約20分、«下津井» 付近下車","la":34.433,"lo":133.805,"hook":"頭の上には瀬戸大橋、足もとには北前船の港。むかし «鰊（にしん）» のにおいがした町。","lead":"下津井は、児島半島の先にある港町です。江戸時代から明治時代にかけて、北海道と大坂を結ぶ «北前船» が立ちよる港として栄えました。四国の金毘羅参りへの渡し船の港でもあり、今も古い町並みと、頭上を走る瀬戸大橋の景色が見られます。","story":["児島半島の南の先。細い路地の両側に、なまこ壁の蔵や格子の町家がならんでいます。見上げると、巨大な瀬戸大橋が海をまたいで四国へのびています。昔と今が一つの風景の中にある、ふしぎな港町、それが下津井です。","江戸時代、日本海をまわって北海道と大坂を行き来する «北前船» が、この港に入ってきました。積んでいたのは、北海道でとれた鰊を煮て干した «鰊粕（にしんかす）»。これは綿や藍などの作物のよい肥料になりました。児島や岡山平野の綿づくりを、北の海の鰊がささえていたのです。","港には、船の荷を売り買いする «問屋» が並び、蔵には荷物がぎっしり。船乗りたちでにぎわう港町には、民謡 «下津井節» も生まれました。«下津井港は 入りよて出よて»――潮待ち・風待ちの港の暮らしが歌われています。","下津井は、四国・丸亀への渡し船の港でもありました。江戸時代、金毘羅参りがさかんになると、多くの参詣者がここから船で四国へ。«金毘羅さんと、ゆがさん（由加山）の両方にお参りするとご利益が大きい» といわれ、下津井はその中継地としてもにぎわいました。","やがて鉄道や汽船の時代がきて、港の役目は小さくなっていきます。1988年、瀬戸大橋が開通し、四国へは橋でわたる時代になりました。けれど路地を歩けば、回船問屋の建物や、海を見張った下津井城の跡に、港町の記憶がしっかり残っています。"],"tl":[["江戸時代はじめ","岡山藩の城（下津井城）が港を見下ろす山に置かれる"],["1639年","下津井城が廃城になる"],["江戸時代中ごろ〜明治","北前船が寄港し、鰊粕などの取引で港町が栄える"],["江戸時代","金毘羅参りの渡し船の港としてもにぎわう"],["1988年","瀬戸大橋が開通"],["平成のはじめ","下津井と児島を結んだ下津井電鉄の鉄道が廃止される"]],"who":[["北前船の船乗りたち","北海道と大坂を行き来し、下津井に寄港した"],["回船問屋","船の荷を売り買いした下津井の商人"],["池田氏","江戸時代はじめ、下津井城を置いた岡山藩の大名家"],["金毘羅参りの人びと","下津井から船で四国へわたった"]],"deep":["北前船は «買積み船» とよばれ、船主が自分で荷を買い、寄港地で売って利益を出しました。一回の航海で大きな利益をあげたといわれます。","鰊粕は、江戸時代の «金肥（お金で買う肥料）» の代表。綿花栽培がさかんだった瀬戸内の農村にとって、なくてはならないものでした。","«むかし下津井回船問屋» は、明治時代の問屋の建物を生かした資料館で、港町の歴史や北前船の資料を見ることができます。","下津井城は、江戸時代のはじめに岡山藩の支城として置かれ、1639年に廃城になりました。山の上には石垣の跡が残っています。","«両参り»: 金毘羅宮（香川県）と由加山（倉敷市）の両方にお参りするとよいといわれ、下津井はそのルートの港として栄えました。","下津井の沖は潮の流れが速く、タコの名産地としても知られます。港には干しダコがつるされる風景も見られます。"],"look":["なまこ壁の蔵や町家が並ぶ路地","むかし下津井回船問屋（資料館）","下津井城跡の石垣と、瀬戸大橋の眺め","港の干しダコのある風景"],"q":["北前船が下津井に運んできた、肥料になる品物は？","«鰊粕»。鰊を煮て干したもので、綿づくりなどの肥料に使われました。"],"koji":[],"myth":"«両参り» の由来や下津井節の起こりは伝承をふくむ。","img":["北前船","下津井城","瀬戸大橋"],"wp":"下津井","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:a/a1/Shimotsui_Castle_1.jpg",3008,2000,"下津井城"],["c:2/28/JP-Kagawa-Great-Seto-Bridge-Minami_Bisan-Seto-Bridge.jpg",3332,2222,"瀬戸大橋"]]},{"id":"33_kurabo","n":"倉敷アイビースクエア（倉敷代官所跡と倉敷紡績）","yomi":"くらしきあいびーすくえあ","cat":"近代","rank":"A","y":1889,"era":["edo","meiji","showa"],"sh":"","ad":"倉敷市本町","st":"JR倉敷駅から歩いて約15分","la":34.5957,"lo":133.7728,"hook":"江戸幕府の代官所 → 明治の紡績工場 → ツタのからまるホテル。同じ場所が、三度生まれ変わった。","lead":"倉敷アイビースクエアは、明治時代の紡績工場の赤レンガの建物を生かした、ホテルや文化施設です。この場所には、もともと江戸幕府の «倉敷代官所» がありました。代官所から工場へ、工場から観光の名所へ。倉敷の歴史が、この一か所に重なっています。","story":["倉敷美観地区の白壁の町並みをぬけると、ツタにおおわれた赤レンガの建物があらわれます。中庭に入ると、レンガの壁とツタの緑がつくる静かな空間。ここが倉敷アイビースクエアです。","江戸時代、倉敷は幕府の直接の領地 «天領» でした。この地には幕府の役所 «代官所» が置かれ、倉敷川の水運で米や綿が集まる、豊かな商人の町として栄えました。しかし幕末の1866年、長州の奇兵隊を脱けだした兵たちが代官所をおそい、焼きはらってしまいます。«倉敷浅尾騒動» とよばれる事件です。","明治になり、代官所はなくなりました。その跡地に目をつけたのが、倉敷の商人たちです。«これからは機械で糸をつくる時代だ»。1888年、大原孝四郎らが中心となって «倉敷紡績所» をつくり、翌年から工場が動きはじめました。これが今の «クラボウ» のはじまりです。","工場の建物にツタをはわせたのには理由があるといわれます。夏の暑さをやわらげ、工場の中を少しでもすずしくするため。社長を受けついだ大原孫三郎は、働く人の暮らしや教育を大切にし、病院や研究所をつくり、やがて «大原美術館» もひらきました。","工場としての役目を終えたあと、1974年に建物はホテルや記念館などに生まれ変わりました。赤レンガの工場を大切に残し、新しく使う――今では各地で見られるこの考え方の、先がけの一つといわれます。«古いものを生かすって、こういうことか»。ツタの壁が、そう語りかけているようです。"],"tl":[["江戸時代","倉敷が幕府の天領となり、のちに代官所が置かれる"],["1866年","倉敷浅尾騒動。長州の脱走兵が倉敷代官所を焼き打ち"],["1888年","大原孝四郎らが倉敷紡績所を設立"],["1889年","倉敷紡績所の工場が操業を開始"],["1930年","大原孫三郎が大原美術館をひらく"],["1974年","工場の建物を生かした倉敷アイビースクエアが開業"]],"who":[["大原孝四郎","倉敷紡績所の初代社長"],["大原孫三郎","孝四郎の子。倉敷紡績を大きくし、大原美術館をつくった"],["児島虎次郎","孫三郎の支援で西洋の名画を集めた画家"],["倉敷代官","江戸幕府から派遣され、天領の倉敷をおさめた役人"]],"deep":["倉敷紡績の工場は、イギリスの紡績工場を参考にしたレンガ造りで、のこぎりの歯のような屋根（のこぎり屋根）など、紡績工場らしいつくりが見られたといわれます。","ツタ（アイビー）は、レンガの壁の温度が上がりすぎるのをふせぐ役目があったといわれ、それが施設名 «アイビースクエア» の由来になりました。","«倉紡記念館» では、倉敷紡績の歴史や、当時の紡績機械、写真などを展示しています。","倉敷浅尾騒動: 長州藩の第二奇兵隊をぬけた兵たちが倉敷代官所をおそい、さらに浅尾藩の陣屋もおそった事件。幕末の混乱をよくあらわす出来事です。","大原孫三郎は、工場で働く女性たちのための寄宿舎の改善や学校づくり、病院（今の倉敷中央病院）の設立など、社会事業にも力を入れました。","アイビースクエアは近代化産業遺産にも選ばれており、美観地区の町並みとあわせて、江戸から近代までの倉敷の歴史をたどれます。"],"look":["ツタにおおわれた赤レンガの壁と中庭","倉紡記念館（紡績の歴史）","代官所跡を示す案内","となりの美観地区と大原美術館"],"q":["倉敷アイビースクエアの建物は、もとは何の工場だった？","紡績工場（倉敷紡績所）。綿から糸をつくる工場でした。"],"koji":[],"myth":"ツタを植えた理由（暑さ対策）は通説。代官所の設置年などは資料で確認を。","img":["倉敷紡績","大原孫三郎","大原美術館"],"wp":"倉敷アイビースクエア","rel":{"ev":[],"grave":[]},"ph":[["c:5/5d/Kurashiki_Ivy_Square23s.jpg",4592,3056,"倉敷アイビースクエア"],["c:2/23/Kurashiki_Ivy_Square21n4592.jpg",4592,3056],["c:a/a2/Kurashiki_Ivy_Square16o4592.jpg",4592,3056],["c:d/d7/Kurashiki_Ivy_Square04nt3200.jpg",4592,3056],["c:2/21/211203_Kurashiki_Ivy_Square_Kurashiki_Okayama_pref_Japan14s3.jpg",4912,3264],["c:8/83/211203_Kurashiki_Ivy_Square_Kurashiki_Okayama_pref_Japan07s3.jpg",4912,3264],["c:d/d8/211203_Kurashiki_Ivy_Square_Kurashiki_Okayama_pref_Japan04s3.jpg",4912,3264],["c:6/67/Ginkgo_in_courtyards_of_Kurashiki_ivy_square.JPG",2048,1536]]},{"id":"33_inujima","n":"犬島精錬所跡（明治の銅精錬所）","yomi":"いぬじませいれんしょあと","cat":"近代","rank":"A","y":1909,"era":["meiji","taisho","heisei"],"sh":"","ad":"岡山市東区犬島","st":"岡山市東区の宝伝港から船で約10分、犬島港下車","la":34.5665,"lo":134.1,"hook":"たった10年ほどで火を消した巨大な精錬所。100年後、その廃墟は美術館として目をさました。","lead":"犬島は、岡山市の沖にうかぶ小さな島です。明治時代の終わりに銅の精錬所がつくられましたが、わずか10年ほどで閉鎖されました。残されたレンガの煙突や壁は、今は «犬島精錬所美術館» の一部として生まれ変わり、たくさんの人が訪れています。","story":["宝伝の港から小さな船にゆられて10分。島に近づくと、木々の間から黒っぽいレンガの煙突が何本も見えてきます。廃墟のような建物と、青い海。どこか外国の遺跡のような景色です。","犬島は、もともと良い花崗岩がとれる «石の島» でした。江戸時代には、大坂城などの石垣に犬島の石が使われたともいわれます。その島に、明治時代の終わり、銅を取り出す大きな工場がつくられました。«島なら、煙の害も町に届きにくい» と考えられたともいわれます。","1909年、精錬所は動きはじめました。鉱石を運ぶ船が港に着き、煙突からはもくもくと煙。島には働く人とその家族が集まり、人口は一気にふえたといいます。けれど、その繁栄は長く続きませんでした。第一次世界大戦のあとに銅の値段が大きく下がり、精錬所は10年ほどで閉鎖されてしまいます。","工場がなくなると、島の人口は少しずつへっていきました。残されたのは、レンガの煙突と壁、そして銅を取り出したあとのかすを固めてつくった黒いレンガ «カラミ煉瓦»。それらは長いあいだ、草木におおわれて静かにねむっていました。","2008年、この精錬所跡に «犬島精錬所美術館» ができました。古い煙突や、太陽と地形を生かした自然のエネルギーで建物の空気をめぐらせる工夫。«近代化が残したものを、どう未来につなぐか?» 島全体が、そんな問いを投げかけてくれます。"],"tl":[["江戸時代","犬島の石が城の石垣などに使われたといわれる"],["1909年","犬島に銅の精錬所が操業を開始"],["1919年ごろ","銅の値段の下落などで精錬所が閉鎖される"],["昭和","島の人口がへり、精錬所跡は廃墟となる"],["2008年","精錬所跡に犬島精錬所美術館が開館"],["現在","瀬戸内国際芸術祭の会場の一つとなっている"]],"who":[["坂本金弥","精錬所をつくった実業家（岡山出身）と伝わる"],["精錬所で働いた人びと","島に移り住み、銅の精錬にたずさわった"],["三分一博志","犬島精錬所美術館を設計した建築家"],["柳幸典","犬島精錬所美術館の作品をつくった美術家"]],"deep":["«カラミ煉瓦»: 銅を精錬したあとに残るかす（スラグ）を型に流して固めたレンガ。黒っぽく重いのが特徴で、精錬所跡の壁や道に使われています。","精錬所の操業期間は約10年と短く、明治の終わりから大正時代にかけての、産業の急な盛衰を物語っています。","美術館は、煙突の «えんとつ効果» などを利用して、機械にたよらず建物の中に空気を流す工夫がされているといわれます。","犬島の名は、島にある «犬の形をした岩» にちなむという伝説があります。","精錬所跡は «近代化産業遺産» にも選ばれています。産業の跡を芸術で生まれ変わらせる取り組みとして注目されました。","島の人口は、精錬所が動いていた時代には数千人ともいわれましたが、今は数十人ほどの小さな島になっています。"],"look":["レンガの煙突群","カラミ煉瓦の壁や道","犬島精錬所美術館（入館は有料）","島の集落に点在するアート作品"],"q":["犬島の精錬所の壁に使われている、銅のかすからつくった黒いレンガを何という？","«カラミ煉瓦»。精錬で出たスラグを固めたレンガです。"],"koji":[],"myth":"犬島の石が大坂城に使われた話、島名の由来は伝承。最盛期の人口の数字は資料で幅がある。","img":["犬島精錬所美術館","瀬戸内国際芸術祭"],"wp":"犬島","rel":{"ev":[],"grave":[]},"ph":[["c:9/91/CCG20072-C4B-29.jpg",2489,1961,"犬島"],["c:2/23/%E7%8A%AC%E5%B3%B6%E7%B2%BE%E9%8C%AC%E6%89%80%E7%BE%8E%E8%A1%93%E9%A4%A8%E6%9C%AC%E9%A4%A8.jpg",6000,4000],["c:6/61/%E7%8A%AC%E5%B3%B6%E4%B8%B8.jpg",4047,3023],["c:6/6c/%E7%8A%AC%E5%B3%B6%E3%80%8C%E5%AE%B6%E3%83%97%E3%83%AD%E3%82%B8%E3%82%A7%E3%82%AF%E3%83%88%E3%80%8DA%E9%82%B8.jpg",4000,6000],["c:9/93/Osaka_Castle_Sakuramon_Kyoseki2.jpg",4128,3096],["c:e/eb/%E7%8A%AC%E5%B3%B6%E5%B9%B3%E9%9D%A2%E5%9B%B3.jpg",5631,2951],["c:c/c9/Korakuen_Okayama30n3872.jpg",3872,2592],["c:5/5e/Korakuen_Okayama10n3872.jpg",3872,2592]]},{"id":"33_yogaku","n":"津山洋学資料館（宇田川家・箕作家）","yomi":"つやまようがくしりょうかん","cat":"学び","rank":"A","y":1830,"era":["edo","meiji"],"sh":"","ad":"津山市西新町","st":"JR津山駅から歩いて約25分。路線バスも利用できる","la":34.9645,"lo":134.0115,"hook":"«酸素»«水素»«細胞»――いま当たり前に使うことばを生んだ学者たちは、みんな津山藩ゆかりの人だった。","lead":"津山洋学資料館は、江戸時代に津山藩から多くの «洋学者»（西洋の学問を学んだ人）が出たことを紹介する資料館です。宇田川玄随・玄真・榕菴の宇田川家三代や、箕作阮甫の一族などが、医学・化学・法律など、さまざまな分野で日本の近代化に大きな役割をはたしました。","story":["津山の城東地区、古い町家が並ぶ出雲街道ぞいに、洋学資料館はあります。中に入ると、オランダ語の本、解剖図、化学の実験道具のスケッチ。«江戸時代の地方の藩から、こんなに多くの学者が?» とおどろかされます。","はじまりは宇田川玄随。津山藩の医者の家に生まれた玄随は、はじめ漢方医学を学んでいましたが、オランダの医学にふれて、その正確さに心をうたれます。«これからは蘭方の医学だ»。玄随は、西洋の内科の本を翻訳し、日本に紹介しました。","その養子・玄真は、西洋の解剖学を分かりやすくまとめた本を出しました。体の中の器官をあらわす «腺» や «膵» の字は、玄真がつくったといわれます。さらにその養子の榕菴は、西洋の化学を日本に紹介し、«酸素»«水素»«窒素»«細胞» などのことばを考え出したとされます。«珈琲» という当て字も榕菴によるといわれます。","もう一人の大物が箕作阮甫です。ペリーが来航したとき、アメリカ大統領の手紙の翻訳にかかわったといわれ、幕府の洋学研究機関 «蕃書調所» でも教えました。その孫の箕作麟祥は、フランスの法律を翻訳し、«権利»«義務» などのことばを広めたといわれ、日本の法律づくりに力をつくしました。","«なぜ津山から、こんなに?» 学問を重んじた藩の気風や、江戸で学ぶ機会、家どうしのつながりがあったからだと考えられています。ことばを生み、新しい知識を日本に根づかせた津山の学者たち。私たちが毎日使うことばの中に、彼らの仕事が生きているのです。"],"tl":[["1790年代","宇田川玄随が西洋内科の本を翻訳して出版"],["1800年代はじめ","宇田川玄真が西洋解剖学の本をまとめる"],["1830年代","宇田川榕菴が西洋化学の本『舎密開宗』を出版しはじめる"],["1853〜54年","ペリー来航。箕作阮甫が外交文書の翻訳にかかわる"],["明治時代","箕作麟祥がフランス法を翻訳し、日本の法律づくりに貢献"],["平成","津山洋学資料館がひらかれ、のちに今の建物へ移る"]],"who":[["宇田川玄随","津山藩医。西洋内科を日本に紹介した"],["宇田川玄真","玄随の養子。西洋解剖学をまとめた"],["宇田川榕菴","玄真の養子。化学用語など多くのことばを考えた"],["箕作阮甫","津山藩医・蘭学者。幕府の翻訳などで活躍"],["箕作麟祥","阮甫の孫。法律家として近代日本の法律づくりに貢献"],["菊池大麓","阮甫の孫。数学者で、東京帝国大学総長などをつとめた"]],"deep":["宇田川榕菴の『舎密開宗（せいみかいそう）』は、日本で最初の本格的な化学の本といわれます。«舎密» はオランダ語で化学をあらわすことばの音をあてたものです。","榕菴は植物学にもくわしく、西洋の植物学を紹介しました。«細胞» のことばも植物学の研究の中で生まれたといわれます。","玄真の『医範提綱』には、くわしい解剖図が付けられ、多くの医学生に読まれたといわれます。","箕作家からは、阮甫の養子・秋坪、孫の麟祥、菊池大麓など、明治の学問を代表する人物が多く出ました。","資料館の近くには、国の史跡 «箕作阮甫旧宅» があり、阮甫が幼いころをすごした町家を見学できます。","«酸素»«水素»«珈琲» など、榕菴がつくったとされることばには、ほかの人の関与を指摘する説もあり、すべてが榕菴一人の発明とは限りません。"],"look":["宇田川家・箕作家の人物と業績の展示","『舎密開宗』などの翻訳書（複製など）","近くの箕作阮甫旧宅（国指定史跡）","城東地区の出雲街道の町並み"],"q":["«酸素»«水素» などのことばを考えたといわれる、津山藩の学者はだれ？","宇田川榕菴。西洋の化学を日本に紹介しました。"],"koji":[],"myth":"榕菴や玄真が作ったとされる用語の一部には諸説がある。阮甫が関わった翻訳の範囲も資料で確認を。","img":["宇田川榕菴","箕作阮甫","宇田川玄随"],"wp":"津山洋学資料館","rel":{"ev":[],"grave":[]},"ph":[["c:1/18/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING02n4140.jpg",4140,2760,"津山洋学資料館"],["c:a/af/Old_bank_at_Tuyama_01.jpg",4608,3072],["c:e/e2/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING01s5s4140.jpg",4140,2760],["c:5/52/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING08bs3840.jpg",2560,3840],["c:b/ba/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING07bs3840.jpg",2560,3840],["c:5/58/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING06bs3840.jpg",2560,3840],["c:e/ea/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING05bs3840.jpg",2560,3840],["c:9/91/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING04bs3840.jpg",2560,3840]]},{"id":"33_shurakuen","n":"衆楽園（津山藩の大名庭園）","yomi":"しゅうらくえん","cat":"大名屋敷","rank":"A","y":1657,"era":["edo","meiji"],"sh":"国指定名勝","ad":"津山市山北","st":"JR津山駅から歩いて約25分。路線バスも利用できる","la":35.07,"lo":134.002,"hook":"殿さまのための庭が、明治に «みんなで楽しむ庭» へ。名前そのものが、その歴史を語っている。","lead":"衆楽園は、江戸時代のはじめに津山藩主・森長継がつくらせた大名庭園です。大きな池のまわりを歩いて楽しむ «池泉回遊式» の庭で、国の名勝に指定されています。明治時代に一般に開かれ、«衆（みんな）が楽しむ庭» という名がつけられました。","story":["津山城から北へ歩くと、広い池と緑につつまれた庭園があります。池には小さな島がいくつもうかび、橋がかかり、水面に木々がうつっています。春は桜、初夏はスイレン、秋は紅葉。季節ごとに表情を変える庭、それが衆楽園です。","この庭をつくらせたのは、津山藩2代藩主の森長継です。森家は、信長につかえた森蘭丸の一族。蘭丸の弟・森忠政が、津山城を築いて藩の基礎をつくりました。長継は江戸時代のはじめ、城の北にこの庭をつくらせたといわれます。","庭は、京都の庭をまねてつくられたと伝わり、京都から作庭の名人をまねいたともいわれます。池を中心に築山や島をおき、歩くたびに景色が変わるようにくふうされています。«殿さまは、ここでどんな客をもてなしたのだろう?» 藩の大事な客を迎える場所として使われたともいわれます。","やがて森家は後つぎの問題で津山をはなれ、松平家が新しい藩主になりました。庭は松平家に受けつがれ、藩の庭として大切にされます。そして明治時代、藩がなくなると、庭は一般の人にも開かれ、«衆楽園» と名づけられました。","«衆楽» とは、«多くの人がともに楽しむ» という意味。殿さまだけの庭が、町の人みんなの庭になったのです。今も入園は無料で、散歩をする人、写真をとる人、ベンチで休む人。この庭の名前は、そのまま今の姿をあらわしています。"],"tl":[["1603年","森忠政が美作に入り、津山藩をひらく"],["1650年代","2代藩主・森長継が庭をつくらせたといわれる"],["1698年","森家が津山をはなれ、松平家が藩主となる"],["明治時代","庭が一般に開かれ、«衆楽園» と名づけられる"],["2002年","国の名勝に指定される"],["現在","無料で開放され、市民の憩いの場となっている"]],"who":[["森長継","津山藩2代藩主。庭をつくらせた"],["森忠政","森蘭丸の弟。津山藩の初代藩主"],["津山松平家","森家の後に津山をおさめた大名家"],["京都の作庭師","庭づくりのためにまねかれたと伝わる"]],"deep":["«池泉回遊式»: 大きな池を中心に、まわりの道を歩きながら景色を楽しむ庭のつくり。江戸時代の大名庭園によく見られます。","庭は京都の仙洞御所の庭をまねたという伝えがありますが、確かな記録は少なく、諸説があります。","衆楽園の池には、いくつもの島がうかび、それぞれが橋でつながれています。北側は «曲水» とよばれる流れのある区域になっています。","衆楽園は、岡山の後楽園、高松の栗林公園などと同じ «大名庭園»。規模は大きくありませんが、江戸時代はじめの様子をよく残す庭と評価されています。","津山藩の森家は、4代で後つぎの問題がおき、津山をはなれました。その後の松平家は明治まで続き、庭を守り伝えました。"],"look":["池と島々、それをつなぐ橋","初夏のスイレン、秋の紅葉","北側の曲水の流れ","津山城跡（鶴山公園）とあわせて歩く"],"q":["«衆楽園» の «衆楽» とはどんな意味？","«多くの人がともに楽しむ» という意味。明治時代に一般に開かれたときに名づけられました。"],"koji":[{"w":"衆楽","m":"多くの人びとがともに楽しむこと"}],"myth":"作庭の年や、京都の作庭師・仙洞御所を手本にしたという話は伝承・諸説。","img":["津山城","森長継","森忠政"],"wp":"衆楽園","rel":{"ev":[],"grave":[]},"ph":[["c:0/03/Shurakuen_Tsuyama05n4272.jpg",4272,2848,"衆楽園"],["c:b/ba/Shurakuen_Tsuyama19n4272.jpg",4272,2848],["c:b/b9/Shurakuen_Tsuyama13n4272.jpg",4272,2848],["c:b/b6/Shurakuen_Tsuyama10n4272.jpg",4272,2848],["c:2/26/Shurakuen_Tsuyama02n4272.jpg",4272,2848],["c:c/c1/%E6%B4%A5%E5%B1%B1%E5%9F%8E%E5%82%99%E4%B8%AD%E6%AB%93.jpg",1150,765,"津山城"],["c:5/52/Mori_tadamasa_2025.jpg",4080,3072,"森忠政"]]},{"id":"33_inukai","n":"犬養木堂記念館（犬養毅の生家）","yomi":"いぬかいぼくどうきねんかん","cat":"近代","y":1855,"era":["meiji","taisho","showa"],"sh":"県指定重要文化財（犬養家旧宅）","rank":"A","ad":"岡山市北区川入","st":"JR山陽本線 庭瀬駅から車で約10分（車・タクシーが便利）","la":34.6536,"lo":133.8386,"hook":"«話せばわかる»――銃口を向けられてもそう言った首相は、この田んぼの中の家で生まれた。","lead":"«木堂» は、明治・大正・昭和の政治家・犬養毅（いぬかいつよし）の号です。ここは犬養が生まれ育った家と、その一生を紹介する記念館。犬養は «憲政の神様» とよばれ、最後は総理大臣のときに «五・一五事件» で命をうばわれました。","story":["江戸時代の終わり、1855年。備中の庭瀬に近い川入村の大庄屋の家に、一人の男の子が生まれました。のちの犬養毅です。今も残る生家は、どっしりした茅葺き風の大屋根と広い土間をもつ、いかにも村のまとめ役の家らしいつくり。少年時代の犬養は、この家から近くの塾に通い、漢学をたっぷり学んだといわれます。","やがて犬養は東京へ出て、慶應義塾で学びながら新聞記者になりました。1877年の西南戦争では、記者として戦場に入り、生々しい記事を書いて名を上げます。«なぜ、書く人だった犬養が政治家に?» ――言葉の力で世の中を動かしたい、という思いが、国会の開設とともに政治の道へ彼を向かわせたのでしょう。1890年の第1回衆議院議員選挙で当選し、以後およそ40年、岡山を地盤に議員をつとめました。","大正のはじめ、藩閥の政府が議会を軽く見ると、犬養は尾崎行雄とともに «憲政を守れ» と先頭に立ちました。これが «第一次護憲運動» です。二人は «憲政の神様» とよばれるようになります。小さな党を率いて苦労しながらも、政党が政治の中心になる時代を目指しつづけました。","1931年、76歳の犬養はついに総理大臣になります。しかし時代は、満州事変のあとで軍の力が強まるばかり。翌1932年5月15日の夕方、海軍の青年将校らが首相官邸に押し入りました。犬養は «まあ待て。話せばわかる» と言ったと伝わり、相手は «問答無用» と撃った、と語られています。犬養はその夜、亡くなりました。","記念館には、犬養が書いた力強い書、愛用の品、孫文ら中国の革命家との交流を物語る資料などが並びます。犬養は書の名手としても知られ、筆あとからも人柄が伝わってきます。«言葉で話し合う政治» を最後まで信じた人の原点が、この静かな村の家にあるのです。"],"tl":[["1855年","備中国賀陽郡川入村（今の岡山市北区）の大庄屋の家に生まれる"],["1877年","新聞記者として西南戦争を取材"],["1890年","第1回衆議院議員選挙で当選"],["1912〜1913年","尾崎行雄らと第一次護憲運動を率いる"],["1929年","立憲政友会の総裁になる"],["1931年12月","内閣総理大臣に就任"],["1932年5月15日","五・一五事件で首相官邸にて襲われ死去"],["1993年","生家のとなりに犬養木堂記念館が開館"]],"who":[["犬養毅（木堂）","ここで生まれた政治家。第29代内閣総理大臣"],["尾崎行雄","護憲運動の盟友。ともに «憲政の神様» とよばれた"],["孫文","中国の革命家。犬養は日本での活動を支えた"],["福沢諭吉","慶應義塾の創設者。犬養が学んだ塾の師"]],"deep":["«木堂» は号（ペンネームのような名）。犬養は漢詩や書にすぐれ、書の作品は今も人気があります。記念館では季節ごとに書の展示替えをすることがあります。","«話せばわかる»«問答無用» のやりとりは広く知られていますが、現場にいた人の証言などをもとに伝わった言葉で、細かな言い回しには異なる伝え方もあります。","五・一五事件の実行犯は、裁判で国民の同情を集め、比較的軽い刑で済みました。このことが、4年後の二・二六事件へつながる空気を生んだ、と見る歴史家は多いです。","犬養内閣は、政党の党首が首相になる «政党内閣» の最後の一つになりました。事件のあと、戦後まで政党内閣は途絶えます。","犬養は長く小さな政党（立憲国民党、革新倶楽部など）を率い、«少数党の雄» といわれました。政友会の総裁になったのは70代半ばになってからです。","孫文だけでなく、インドの独立運動家などアジアの活動家を助けたことでも知られ、亡命者をかくまったと伝わる話もあります。"],"look":["生家（犬養家旧宅）の大きな屋根と土間","犬養の書の展示","五・一五事件に関する資料","孫文ら海外の人びととの交流資料","記念館前の犬養毅の銅像"],"q":["犬養毅と尾崎行雄は、何とよばれた？","«憲政の神様»。藩閥政府に対し、議会中心の政治を守ろうと運動したからです。"],"koji":[{"w":"話せばわかる","m":"暴力ではなく話し合いで解決しよう、という意味。五・一五事件で犬養が言ったと伝わる"}],"myth":"«話せばわかる/問答無用» の正確な言葉は証言によって少しずつ異なる。","img":["犬養毅","五・一五事件","尾崎行雄"],"wp":"犬養木堂記念館","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/Inukai_Tsuyoshi%27s_parents%27_home.JPG",3008,2000,"犬養木堂記念館"],["c:c/c3/Inukai_Tsuyoshi.jpg",1024,1310,"犬養毅"],["c:9/90/Tsuyoshi_Inukai_May_15_Incident_Asahi_Shimbun.png",2495,1653,"五・一五事件"],["c:3/3e/Yukio_Ozaki.jpg",1024,1328,"尾崎行雄"]]},{"id":"33_nagashima","n":"長島愛生園（国立ハンセン病療養所）","yomi":"ながしまあいせいえん","cat":"昭和","y":1930,"era":["showa","heisei"],"sh":"","rank":"A","ad":"瀬戸内市邑久町虫明","st":"JR赤穂線 邑久駅からバスで約40分（本数が少ないので事前に確認）","la":34.6694,"lo":134.1936,"hook":"海をへだてて、わずか30mほど。その短い距離に橋がかかるまで、58年かかった。","lead":"長島愛生園は、1930年にできた日本で最初の国立ハンセン病療養所です。ハンセン病は治る病気なのに、長いあいだ国の法律で患者を島に隔離する政策がとられ、多くの人が家族やふるさとから引き離されました。今は «歴史館» があり、その歴史を学ぶことができます。","story":["瀬戸内海にうかぶ長島。本土とのあいだの海峡は、狭いところでは泳いで渡れそうなほどです。1930年、この島に国立の療養所 «長島愛生園» が開かれました。初代園長は光田健輔。«患者を一か所に集めれば病気はなくなる» という考えのもと、全国から患者が送られてきました。","«なぜ、島だったのか?» ――社会から切り離すためでした。ハンセン病は感染力がとても弱い病気ですが、当時は «こわい病気» と思いこまれ、県ごとに患者を見つけ出して療養所へ送る «無らい県運動» も進められました。島に着いた人は、まず «収容桟橋» から上陸し、消毒を受け、ときには名前を変えて暮らすことになりました。","園の中では、患者自身が畑を耕し、建物を建て、重い病状の仲間の看護までしました。結婚の条件として手術を受けさせられるなど、人としての大切な権利がうばわれたことも、今でははっきり国の誤りとされています。それでも入所者たちは短歌や文学、音楽に心をこめ、歌人・明石海人のように、深い作品を残した人もいました。","戦後、特効薬で病気は治るようになりました。それでも隔離を定めた法律は、1996年まで残りました。1988年、島と本土を結ぶ «邑久長島大橋» ができたとき、入所者たちはこれを «人間回復の橋» とよびました。2001年には熊本地方裁判所が、国の隔離政策は憲法に反すると判断し、国は控訴せずに謝罪しました。","今、旧事務本館は «長島愛生園歴史館» になり、入所者の暮らしや差別の歴史を伝えています。園内には納骨堂もあり、ふるさとへ帰れなかった多くの方が眠っています。ここは今も入所者が暮らす生活の場。見学するときは、静かに、敬意をもって歩きましょう。"],"tl":[["1930年","国立療養所 長島愛生園が開設（初代園長・光田健輔）"],["1931年","らい予防法（旧法）が制定され、隔離が強まる"],["1938年","医師・小川正子の手記『小島の春』が出版され話題に"],["1953年","らい予防法（新法）制定。隔離はつづく"],["1988年","邑久長島大橋が開通。«人間回復の橋» とよばれる"],["1996年","らい予防法が廃止される"],["2001年","熊本地裁が隔離政策を違憲と判断。国が謝罪"],["2003年","旧事務本館が歴史館として公開される"]],"who":[["光田健輔","初代園長。治療に尽くした一方、隔離政策を強く進めた人物として批判もある"],["小川正子","園の医師。各地で患者を訪ねた記録『小島の春』を書いた"],["明石海人","入所者の歌人。歌集『白描』を残した"],["神谷美恵子","精神科医。園で入所者の心のケアにあたった"]],"deep":["愛生園は «国立療養所» の第1号。それまでのハンセン病療養所は府県が共同で運営する «公立» でした。国が直接つくった最初の施設という点で、隔離政策の象徴にもなりました。","«収容桟橋» は入所者が最初に島に上がった場所。ここで家族と別れた人も多く、歴史館の見学コースでも大切な場所として紹介されています。","園内にはかつて «監房» がありました。所長に懲戒の権限が与えられ、逃げ出そうとした人などが閉じこめられました。いまは跡が残されています。","1930年代、定員を大きく超えて患者を受け入れたため、食べ物や住まいが足りなくなり、1936年には入所者が待遇改善を求める «長島事件» が起こりました。","ハンセン病はらい菌による感染症ですが、うつる力はとても弱く、1940年代以降は «プロミン» などの薬で治るようになりました。それでも隔離の法律が1996年までつづいたことが大きな問題です。","長島には «邑久光明園» というもう一つの療養所もあります。1つの島に2つの国立療養所がある例です。"],"look":["長島愛生園歴史館（旧事務本館・1930年の建物）","収容桟橋","監房跡","納骨堂と «恵の鐘»","邑久長島大橋（人間回復の橋）"],"q":["1988年にできた邑久長島大橋は、入所者たちに何とよばれた？","«人間回復の橋»。島と本土が結ばれ、隔離の象徴だった海がつながったからです。"],"koji":[],"myth":"見学は歴史館の開館日・時間に従い、入所者の住まいの近くでは撮影や立ち入りに配慮が必要。","img":["らい予防法","光田健輔","邑久長島大橋"],"wp":"国立療養所長島愛生園","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Mitsuda_Kensuke.jpg",401,576,"光田健輔"],["c:e/e7/Michinoeki_Kuroisan_green_park_-01.jpg",2592,1944,"近く: 道の駅黒井山グリーンパーク"],["c:3/30/Roadside_Station_Ipponmatsu_Tenboen_-01.jpg",2592,1944,"近く: 道の駅一本松展望園"],["c:8/87/Osafune_Miwa_jinja_08.jpg",3841,2547,"近く: 美和神社 (瀬戸内市長船町東須恵)"],["c:3/3c/%E6%9C%9D%E6%97%A5%E5%AF%BA%E5%85%A8%E6%99%AF.jpg",778,584,"近く: 朝日寺 (瀬戸内市)"]]},{"id":"33_okayama_kushu","n":"岡山空襲の跡（1945年6月29日）","yomi":"おかやまくうしゅうのあと","cat":"昭和","y":1945,"era":["showa"],"sh":"","rank":"A","ad":"岡山市北区駅元町（岡山シティミュージアム 岡山空襲展示室）","st":"JR岡山駅から歩いて約5分（展示室）。岡山城へは路面電車で城下電停から歩いて約10分","la":34.6653,"lo":133.9165,"hook":"夜明け前の2時間たらずで、城下町の中心が炎に包まれた。国宝の天守も、そのとき燃えた。","lead":"1945年6月29日の未明、アメリカ軍の爆撃機B-29の大編隊が岡山市を焼夷弾で攻撃しました。市街地の大部分が焼け、1,700人をこえる人が亡くなったとされます。国宝だった岡山城の天守もこの空襲で焼け落ちました。","story":["1945年6月29日、まだ暗い午前2時すぎ。岡山の人びとは空襲警報のサイレンもはっきり聞かないうちに、空から降ってくる火の雨に気づきました。B-29の大編隊が、市の中心へ焼夷弾を落としていったのです。木造の家が多い町は、あっという間に燃え広がりました。","«なぜ、岡山が?» ――この年の春から、アメリカ軍は東京・大阪などの大都市だけでなく、全国の地方都市を次々に空襲していました。岡山もその一つとして狙われたのです。攻撃は2時間たらずで終わりましたが、そのあいだに市街地の大部分が焼け野原になりました。","旭川のほとりに建っていた岡山城の天守は、江戸時代のはじめから残る国宝でした。«真っ黒な城» の意味で «烏城（うじょう）» とよばれ、町のシンボルでした。その天守も炎に包まれ、朝には石垣だけが残りました。後楽園の建物の一部も焼けました。","亡くなった人は1,700人をこえるとされ、けがをした人、家を失った人はさらにたくさんいました。川へ逃げこんで助かった人、家族とはぐれたまま二度と会えなかった人――生き残った人たちの証言は、今も記録として大切に受けつがれています。","岡山駅の近くにある岡山シティミュージアムには «岡山空襲展示室» があり、焼夷弾の実物や焼けた日用品、当時の写真が展示されています。1966年に再建された天守を見上げながら、焼ける前の町と、そこにいた人たちのことを想像してみてください。毎年6月29日の前後には、犠牲者をしのぶ催しが行われています。"],"tl":[["1597年","宇喜多秀家のもとで岡山城の天守が完成したとされる"],["1931年","岡山城の天守が国宝（当時の制度）に指定される"],["1945年6月29日未明","B-29の編隊による岡山空襲。市街地の大部分が焼失"],["1945年8月15日","終戦"],["1966年","岡山城の天守が鉄筋コンクリートで再建される"],["2005年","岡山シティミュージアムが開館、空襲展示室が設けられる"]],"who":[["岡山の市民","空襲で被害を受けた人びと。多くの証言や手記が残されている"],["宇喜多秀家","焼失した岡山城天守を築いた戦国大名"],["池田氏（岡山藩主）","江戸時代の城主。天守は明治以後も残り、国宝となっていた"]],"deep":["死者数は資料により数え方がちがいますが、岡山市は1,700人をこえる犠牲者があったとしています。正確な数がつかめないこと自体が、被害の大きさを物語っています。","焼夷弾は建物を燃やすための爆弾で、木と紙の日本家屋に大きな被害を出しました。子ども用の防空頭巾やバケツリレーでは防ぎようがありませんでした。","焼けた岡山城天守は、1966年に外観を復元して再建されました。石垣のなかには、炎で赤く変色したり割れたりした石があるともいわれます。","同じ夜、岡山と前後して全国の多くの地方都市が空襲を受けました。1945年6月から8月にかけての «中小都市空襲» の一つです。","空襲で焼け残った建物は少なく、戦後の岡山の町並みは大きく作りかえられました。駅前の大通りなど、今の町の形はこの復興から生まれたものが多いです。"],"look":["岡山シティミュージアム «岡山空襲展示室» の焼夷弾や遺品","再建された岡山城天守と、残った石垣","後楽園（戦災で一部が焼け、のちに復旧）","旭川の河原（多くの人が避難した場所）"],"q":["岡山空襲で焼けてしまった、国宝だった建物は？","岡山城の天守。«烏城» とよばれた黒い天守で、1966年に再建されました。"],"koji":[],"myth":"死者数は資料により異なる。石垣の焼け跡とされる石は推定をふくむ。","img":["岡山城","日本本土空襲"],"wp":"岡山大空襲","rel":{"ev":[],"grave":[]},"ph":[["c:3/3f/Okayama_after_the_1945_air_raid.jpg",2560,1920,"岡山大空襲"],["c:d/db/Boeing_B-29_Superfortress_2.jpeg",750,565],["c:8/8c/Okayama_CRED.JPG",528,704],["c:6/64/Old_Okayama_Castle01.jpg",500,324],["c:a/ae/Okayama_Castle_main_keep_2023-10-18.jpg",1440,1100,"岡山城"],["c:c/c6/B-29s_dropping_bombs.jpg",576,896,"日本本土空襲"]]},{"id":"33_niimi_sho","n":"新見荘（たまがき書状の荘園）","yomi":"にいみのしょう","cat":"遺跡","y":1463,"era":["kamakura","muromachi"],"sh":"","rank":"A","ad":"新見市（高梁川上流の新見盆地一帯）","st":"JR伯備線 新見駅周辺。荘園ゆかりの地は車でまわるのが便利","la":34.978,"lo":133.47,"hook":"550年以上前、一人の女性が遠い京都のお寺へ手紙を書いた。«あの人の形見をください»――その手紙が国宝になっている。","lead":"新見荘は、中世に京都の東寺が持っていた荘園（お寺や貴族の私有地）です。東寺に残る膨大な古文書 «東寺百合文書» の中に、新見荘の人びとの声がたくさん残っています。なかでも有名なのが、殺された役人をしのぶ女性 «たまがき» の手紙です。","story":["岡山県の北西、高梁川の上流にひらけた新見盆地。鎌倉時代から室町時代、このあたりは «新見荘» とよばれる荘園で、年貢は京都の東寺へ納められていました。鉄や漆、紙なども送られたといわれ、山あいながら豊かな土地でした。","室町時代の中ごろ、荘園の管理は守護大名の家来が請け負っていました。ところが取り立てがきびしく、百姓たちは «東寺が直接治めてほしい» と訴えます。1461年ごろ、百姓たちは力を合わせて代官を追い出し、東寺から役人を迎えることになりました。","やって来たのは、東寺の僧・祐清（ゆうせい）。しかし年貢の取り立てをめぐって地元の人とのあいだに争いが起こり、1463年、祐清は殺されてしまいます。«なぜ、そんなことに?» ――祐清の強引なふるまいが恨みを買ったとも伝わり、荘園を治めることのむずかしさがうかがえます。","祐清の身の回りの世話をしていた女性が «たまがき» です。彼女は東寺へ手紙を送り、祐清の形見として小袖などの品を分けてほしいと願いました。やさしいかな文字で書かれたこの手紙は、中世の地方に生きた女性が自分の言葉で書いた、たいへんめずらしい記録です。","この手紙をふくむ «東寺百合文書» は国宝で、2015年にはユネスコ «世界の記憶» にも選ばれました。新見では、たまがきと祐清をしのぶ碑が建てられ、中世の市をイメージした祭りも行われています。何百年も前の人の気持ちが、紙一枚でいまに届くのです。"],"tl":[["12世紀後半","新見荘が成立したとされる"],["1271年","領家方と地頭方で土地を分ける «下地中分» が行われたとされる"],["14世紀前半","東寺の荘園となる"],["1461年ごろ","百姓らが守護方の代官を排除し、東寺の直接支配を求める"],["1463年","東寺の代官・祐清が現地で殺される。たまがきが東寺へ手紙を送る"],["1997年","東寺百合文書が国宝に指定される"],["2015年","東寺百合文書がユネスコ «世界の記憶» に登録"]],"who":[["たまがき","祐清の世話をした女性。形見を求める手紙を東寺に送った"],["祐清","東寺から派遣された代官の僧。1463年に殺された"],["新見荘の百姓たち","代官の排除や東寺の直接支配を求めて団結した"],["東寺","京都のお寺。新見荘の領主として多くの文書を残した"]],"deep":["«東寺百合文書» は、江戸時代に加賀藩主の前田綱紀が文書を整理するための桐箱（100の箱）を寄進したことからこの名がついたといわれます。新見荘関係の文書はその中でもとくに豊富です。","新見荘では、鎌倉時代に荘園領主側と地頭側で土地を二つに分ける «下地中分» が行われ、その様子を示す絵図の存在も知られています。中世荘園研究の «教科書» のような場所です。","たまがきの手紙はかな書きで、当時の話しことばに近い表現が見られます。中世の女性の自筆とされる地方の手紙として、とても貴重です。","新見荘からは年貢として鉄が納められたことが文書からわかります。中国山地の «たたら製鉄» とのつながりを考えるうえで重要です。","百姓たちの団結は «一揆» の一つとして注目されます。起請文（神仏に誓う文書）を書いて結束したことなど、村の人びとの自治の力が見えます。"],"look":["たまがきの碑・祐清をしのぶ碑","新見盆地の田園風景（荘園の広がりを想像）","新見市内の郷土資料の展示","高梁川の流れ（年貢を運んだ道）"],"q":["たまがきの手紙がふくまれる古文書のまとまりの名前は？","«東寺百合文書»。国宝で、ユネスコ «世界の記憶» にも登録されています。"],"koji":[],"myth":"祐清殺害の原因は諸説。下地中分の年や成立時期は研究により表現が異なる。","img":["東寺百合文書","東寺"],"wp":"新見荘","rel":{"ev":[],"grave":[]},"ph":[["c:1/1f/Toji_2015.JPG",2500,1667,"東寺"],["c:1/17/%E6%BA%80%E5%A5%87%E6%B4%9E_-_panoramio.jpg",3264,2448,"近く: 新見市"],["c:1/16/Niimi_Police_station.jpg",1600,1200,"近く: 新見警察署"],["c:d/d3/Yamasa%2C_Companies_in_Niimi_City_20260825.jpg",4080,3072,"近く: 山佐"],["c:b/b1/Niimi_high_school.jpg",2048,1536,"近く: 岡山県立新見高等学校"],["c:4/4d/Okayamaken_Kyousei_high_school.jpg",1600,1200,"近く: 岡山県共生高等学校"],["c:5/52/Niimi_Municipal_Shisei_Elementary_School_-01.jpg",2560,1920,"近く: 新見市立思誠小学校"]]},{"id":"33_hyakkengawa","n":"百間川（熊沢蕃山の治水）","yomi":"ひゃっけんがわ","cat":"産業","y":1686,"era":["edo"],"sh":"","rank":"A","ad":"岡山市中区・東区（旭川から分かれ児島湾へ）","st":"JR山陽本線 東岡山駅・高島駅などから歩いて行ける場所が多い。«一の荒手» 付近は車・自転車が便利","la":34.671,"lo":133.967,"hook":"洪水をふせぐため、川を一本 «つくってしまえ»。江戸の学者と役人が考えた、大胆な逃げ道。","lead":"百間川は、岡山の町を流れる旭川が大雨であふれそうになったとき、水を横へ逃がすためにつくられた «人工の川»（放水路）です。熊沢蕃山の考えをもとに、岡山藩の役人・津田永忠が江戸時代前期に完成させました。","story":["岡山城のすぐそばを流れる旭川。城下町にとっては大切な川でしたが、大雨のたびにあふれ、町や田畑を水びたしにしました。1654年には大洪水が起こり、岡山藩は大きな被害を受けます。藩主の池田光政は «どうすれば城下を守れるのか» と頭を悩ませました。","そこで知恵を出したのが、光政に仕えた学者・熊沢蕃山です。陽明学を学んだ蕃山は、«水の勢いを無理におさえるのではなく、逃げ道をつくればよい» と考えたといわれます。旭川の東側に、ふだんは水の少ない «もう一本の川» を用意し、あふれそうなときだけそちらへ流すのです。","この考えを形にしたのが、藩の役人・津田永忠でした。川の分かれ目には «荒手（あらて）» とよばれる、わざと低くした堤防をつくります。水かさが増えると、荒手を越えた水が百間川へ流れこむしくみです。«なぜ、わざと低い所をつくるの?» ――弱い所を決めておけば、ほかの堤防が切れて町が流されるのを防げるからです。","工事は何年もかけて進められ、1686年ごろに河口までが完成したとされます。永忠は同じころ、児島湾を干拓して «沖新田» をひらき、閑谷学校や後楽園の造営にもかかわりました。百間川の河口には、海水が逆流しないよう水門も設けられました。","百間川の名は、川はばが約百間（約180m）あったことに由来するといわれます。昭和から平成にかけての改修工事では、川底から弥生時代の水田跡や集落跡がたくさん見つかり、«百間川遺跡群» として知られるようになりました。江戸の治水の川が、さらに古い暮らしの記憶も守っていたのです。"],"tl":[["1654年","岡山で大洪水。藩主・池田光政が治水にとりくむ"],["1669年ごろ","百間川の開削が始まったとされる"],["1686年ごろ","河口までの工事が完成したとされる"],["1692年ごろ","津田永忠が児島湾の «沖新田» を干拓したとされる"],["昭和後期〜平成","百間川の改修で大規模な発掘調査。弥生時代の水田跡などが見つかる"]],"who":[["熊沢蕃山","陽明学者。放水路の考えを示したとされる"],["津田永忠","岡山藩の役人。百間川や沖新田、閑谷学校の工事を担った"],["池田光政","岡山藩主。洪水対策と教育に力を入れた名君"],["池田綱政","光政の子。後楽園をつくらせた藩主"]],"deep":["«荒手» は越流堤（えつりゅうてい）ともいい、上流から «一の荒手»«二の荒手»«三の荒手» がありました。石を敷きつめた構造で、江戸時代の土木技術を今に伝えます。","百間川は、ふだんは水が少なく、河川敷の多くが田んぼや畑として使われていたといわれます。洪水のときだけ «川» になる、というめずらしい性格の川でした。","蕃山は «大学或問» などの著作で、山の木を切りすぎると洪水がひどくなるという考えを述べたとされ、治山治水の先がけと評価されます。","百間川遺跡群では、弥生時代の水田のあぜ、足あと、洪水の砂におおわれた田などが見つかり、昔の人も水害と戦っていたことがわかりました。","河口の «百間川河口水門» は、江戸時代の石造りの樋門（ひもん）の流れをくむ施設として知られ、干拓地を守る役目を果たしました。"],"look":["«一の荒手»・«二の荒手» の石積み","河川敷の広さ（百間＝約180mを体感）","百間川河口水門","岡山城・後楽園（守られた城下町）"],"q":["百間川の «荒手» は、どんな役目の堤防？","わざと低くした堤防。旭川の水があふれそうなとき、ここを越えて百間川へ水を逃がしました。"],"koji":[],"myth":"工事の開始・完成年は資料で幅がある。«百間» の由来にも異説がある。","img":["熊沢蕃山","津田永忠","旭川 (岡山県)"],"wp":"百間川","rel":{"ev":[],"grave":[]},"ph":[["c:6/61/Hyakken_River_1.JPG",3008,2000,"百間川"],["c:0/07/Kogai_well.JPG",3008,2000],["c:9/9a/Hyakken_River_7.JPG",3008,2000],["c:4/47/Hyakken_River_3.JPG",3008,2000],["c:9/9b/Hyakken_River_16.JPG",3008,2000],["c:7/75/Hyakken_River_13.JPG",3008,2000],["c:3/32/Hyakken_River_11.JPG",3008,2000],["c:f/f9/Hyakken_River_10.JPG",3008,2000]]},{"id":"33_hokoku","n":"方谷駅（山田方谷の旧居の地）","yomi":"ほうこくえき","cat":"幕末","y":1859,"era":["edo","meiji"],"sh":"","rank":"A","ad":"高梁市中井町西方","st":"JR伯備線 方谷駅すぐ（普通列車のみ停車・本数に注意）","la":34.833,"lo":133.609,"hook":"日本の鉄道で «人の名前» が駅名になった、はじまりの駅。その人は、借金まみれの藩を立て直した農民出身の学者だった。","lead":"方谷駅は、幕末の備中松山藩で藩の財政を立て直した山田方谷が、晩年近くに住んだ «長瀬» の地にあります。国鉄の駅で人名が駅名になった最初の例といわれます。方谷は、ここで開墾をしながら、多くの弟子を育てました。","story":["高梁川の谷あいを走る伯備線。小さな駅のホームに «方谷» の文字が見えます。«なぜ、人の名前の駅が?» ――1928年、駅ができるとき、地元の人たちはこの地に住んだ山田方谷の名をつけたいと願いました。人名はだめだという声もありましたが、熱心な願いが通り、この名に決まったと伝わります。","山田方谷は1805年、備中の農家に生まれました。菜種油を売る家業を手伝いながら学問にはげみ、やがて藩校の先生になります。そして1849年、藩主・板倉勝静（かつきよ）から藩の財政を任されました。当時の備中松山藩は、表向き5万石でも実際の収入はずっと少なく、10万両ともいわれる借金をかかえていたのです。","方谷はまず、藩の «本当の収入» をあきらかにし、借金をしている大坂の商人に正直に打ち明けて返済を待ってもらいました。信用を失っていた藩札を集めて焼き捨て、新しいお札に変えたとも伝わります。さらに備中鍬など特産品を藩が直接江戸へ売る仕組みをつくり、数年で借金を返したうえ、たくわえまで生みだしたといわれます。","1859年、方谷は長瀬の地に移り住み、荒れ地を切りひらきました。この年、越後長岡藩の河井継之助がはるばる訪ねてきて、方谷のもとで学んでいます。継之助は別れぎわ、川の向こうから方谷に向かって何度も頭を下げたと伝わります。","幕末、主君の勝静は幕府の老中として徳川方の中心にいました。1868年、新政府軍が迫ると、方谷は城を明けわたして戦を避ける道を選び、城下を戦火から守りました。晩年は閑谷学校の再興にもかかわり、1877年に亡くなりました。駅前には «山田方谷先生旧宅跡» を示す碑が立っています。"],"tl":[["1805年","備中国阿賀郡西方村（今の高梁市）に生まれる"],["1849年","藩主・板倉勝静に元締（財政責任者）を任される"],["1850年代","藩札の刷新や特産品の販売で財政を立て直したとされる"],["1859年","長瀬に移り住む。河井継之助が教えを受けに来る"],["1868年","戊辰戦争で備中松山城を無血で明けわたす"],["1877年","亡くなる"],["1928年","伯備線に方谷駅が開業"]],"who":[["山田方谷","備中松山藩の財政を立て直した陽明学者"],["板倉勝静","備中松山藩主。幕府の老中として幕末の政治を担った"],["河井継之助","越後長岡藩士。1859年に方谷を訪ねて学んだ"],["三島中洲","方谷の弟子。のちに二松学舎を創立"]],"deep":["方谷の財政論 «理財論» には «事の外に立ちて事の内に屈せず» という考えがあり、目先のお金のやりくりより、政治や人の心の立て直しが大事だと説きました。","藩の特産品 «備中鍬» は、農民の使いやすさを追求した鉄の鍬で、江戸で評判になったといわれます。鉄は中国山地のたたら製鉄とつながっています。","方谷は «撫育方» という役所を設けて産業を育て、農民の暮らしを豊かにすることで藩の収入を増やそうとしました。上からしぼり取るやり方とは逆の発想です。","駅名の話は «国鉄で初めての人名駅» として有名ですが、その後に人名に由来する駅はいくつも生まれています。方谷駅はその先がけとして語られます。","方谷の座右の銘とされる «至誠惻怛（しせいそくだつ）» は、まごころと、人をいたわる気持ちを表すことばです。"],"look":["駅の «方谷» の駅名標","山田方谷先生旧宅跡の碑","高梁川の流れと長瀬の風景","高梁市内の備中松山城（方谷が守った城）"],"q":["山田方谷を慕って越後から学びに来た人物はだれ？","河井継之助。のちに長岡藩の家老として戊辰戦争を戦いました。"],"koji":[{"w":"至誠惻怛","m":"まごころをつくし、人を思いやること。方谷が大切にしたことば"}],"myth":"借金の額（10万両など）や改革の成果の数字は伝え方に幅がある。","img":["山田方谷","備中松山藩","河井継之助","備中松山城"],"wp":"方谷駅","rel":{"ev":[],"grave":[]},"ph":[["c:e/e0/JRW_H%C5%8Dkoku_sta_20240605.jpg",5184,3456,"方谷駅"],["c:d/db/JRW_H%C5%8Dkoku_sta_label_of_old_Japanese_National_Railways_type_20240605.jpg",5184,3456],["c:6/66/JRW_H%C5%8Dkoku_sta_enclosure_20240605.jpg",5184,3456],["c:a/a2/JRW_H%C5%8Dkoku_sta_2_20240605.jpg",5184,3456],["c:8/84/Yamada_Hokoku_portrait.jpg",1528,2000,"山田方谷"],["c:8/82/Bitchu_Matsuyama_Castle.JPG",3008,2000,"備中松山藩"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:5/52/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E2.jpg",4032,3024,"備中松山城"]]},{"id":"33_kinko","n":"金光教本部（幕末の民衆宗教）","yomi":"こんこうきょうほんぶ","cat":"幕末","y":1859,"era":["edo","meiji"],"sh":"","rank":"A","ad":"浅口市金光町大谷","st":"JR山陽本線 金光駅から歩いて約10分","la":34.544,"lo":133.625,"hook":"«祟る神» とおそれられた金神（こんじん）を、«人を助ける親神» に変えた農民がいた。","lead":"金光教は、幕末の1859年に、備中の農民・金光大神（こんこうだいじん）が始めた宗教です。人の願いを神に «取次ぐ» ことを大切にし、今も本部には、昼夜を問わず人びとの話を聞く場所があります。","story":["江戸時代の終わり、備中の大谷村に、まじめに田畑を耕す一人の農民がいました。名前は文治（のちの金光大神）。彼の家では、子どもや家畜が次々に亡くなる不幸がつづきました。当時の人びとは、方角の神 «金神» にさわると祟りがあると信じ、家を建てる向きや日取りに気をつけていたのです。","1855年、42歳の文治は大病にかかり、のどがはれて声も出なくなりました。家族が神に祈るなか、文治は «私の不注意で神に失礼をしたのかもしれません» と心からわびたといわれます。すると病はうそのように回復しました。«なぜ、神は許してくれたのか?» ――文治はそこから、金神は人をこらしめる神ではなく、人を助けたい神なのだと考えるようになります。","1859年、文治は «人の願いを神に伝え、神の思いを人に伝える» 役目を引き受け、農業をやめて広前（ひろまえ）にすわりつづけるようになりました。これが金光教の始まりとされます。訪ねてくる人の悩みを一人ひとり聞き、神に祈る――この «取次» が教えの中心です。","幕末から明治にかけては、新しい宗教への取りしまりもあり、苦しい時期がつづきました。それでも信者は各地に広がり、1883年に金光大神が亡くなったあとも教えは受けつがれました。1900年には独立した教団として認められます。","今の本部は、金光駅から歩いてすぐの静かな町なかにあります。大きな «会堂» のほか、教祖が人びとの話を聞いた場所にちなむ «広前» があり、今もそこで取次がつづけられています。町には教団が開いた図書館や学校もあり、宗教が町の形をつくってきたことがわかります。"],"tl":[["1814年","備中国浅口郡占見村（今の浅口市）に生まれる"],["1825年","大谷村の川手家の養子となる"],["1855年","42歳で大病。金神にわびて回復したと伝わる"],["1859年","農業をやめて取次に専念。金光教の立教とされる"],["1868年","«金光大神» の名を名乗るようになる"],["1883年","金光大神が亡くなる"],["1900年","金光教が独立した教団として認められる"]],"who":[["金光大神（赤沢文治）","金光教の教祖。農民から人びとの相談を受ける取次者になった"],["金光萩雄","金光大神の子。教団の独立に尽くした"],["大谷村の人びと","教祖の周りに集まった最初の信者たち"]],"deep":["«金神» は陰陽道に由来する方角の神で、その方角に家を建てたり旅をしたりすると祟ると恐れられました。金光教はこの神を «天地金乃神（てんちかねのかみ）» として、人を育て助ける親神ととらえ直しました。","教祖の名前は、生まれた家の «香取»、養子先の «川手»、のちの «赤沢» などと変わり、最後に «金光大神» となりました。名前の変化自体が信仰の深まりを表すと考えられています。","金光教は黒住教・天理教とともに、幕末に生まれた «民衆宗教» の代表として教科書でも取り上げられます。いずれも農民や町人のあいだから生まれたのが特徴です。","教祖は自分の信仰の歩みを «金光大神御覚書» などに書き残したとされ、宗教学・歴史学の貴重な史料になっています。","JR金光駅の駅名は、この町（旧金光町）の名に由来し、町名は教団の名から来ています。宗教の名が町や駅の名前になった例です。"],"look":["本部の広前（取次の場）","大きな会堂","金光図書館","金光駅から本部へつづく町並み"],"q":["金光教で、人の願いを神に伝え、神の思いを人に伝えることを何という？","«取次（とりつぎ）»。教祖が始め、今も本部でつづけられています。"],"koji":[],"myth":"教祖の大病と回復の話は教団の伝えによる。名の変遷の細部は資料で表記が異なる。","img":["金光大神","金光駅"],"wp":"金光教","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/Konkokyo_Headquarters_Central_Worship_Hall.jpg",2560,1920,"金光教"],["c:a/a3/Konkokyo_Headquarters_Grand_Service_Hall.jpg",2560,1920],["c:8/82/Konkokyo_Headquarters_Faith_Training_Center.jpg",2560,1920],["c:3/3a/Gate_in_the_Konkokyo_Headquarters.jpg",1600,1200],["c:9/9f/Fujin-Seikatsu-1953-December-1.jpg",581,708],["c:1/11/Konkokyo.png",599,554],["c:7/75/Konko_Station_Building_%28South%29_20200927.jpg",6000,4000,"金光駅"]]},{"id":"33_kurozumi","n":"黒住教の地（幕末の民衆宗教）","yomi":"くろずみきょう","cat":"幕末","y":1814,"era":["edo","meiji","showa"],"sh":"","rank":"A","ad":"岡山市北区尾上（神道山）","st":"JR吉備線の駅から車で約10分。車が便利","la":34.677,"lo":133.841,"hook":"冬至の朝、昇る太陽を «飲みこんだ»――そう感じた神主から、一つの宗教が生まれた。","lead":"黒住教は、1814年に岡山の神社の神主・黒住宗忠が始めた宗教です。太陽の神・天照大神と心をひとつにし、明るく感謝して生きることを説きました。幕末に生まれた民衆宗教の中で最も早いものの一つです。本部は岡山市の «神道山» にあります。","story":["江戸時代の後半、備前の今村宮という神社に、黒住宗忠という神主がいました。親孝行でまじめな青年でしたが、30代の半ばに両親を相次いで亡くし、自分も重い病にかかってしまいます。«もう長くはない» と思った宗忠は、最後に太陽を拝もうと決めました。","1814年の冬至の朝。宗忠が東の空から昇る太陽に向かって祈ると、その光が口から体の中に入ってくるように感じたといわれます。«天の神と自分がひとつになった» ――黒住教ではこれを «天命直授（てんめいじきじゅ）» とよび、立教の日としています。宗忠の病は、ここから回復していったと伝わります。","«なぜ、太陽だったのか?» ――宗忠は、太陽はすべての命を育てる親であり、人の心もその分かれだと考えました。だから、くよくよせず、感謝して «陽気» に暮らせば、心も体も元気になる。この教えは、病気や不安に悩む人びとの心をつかみ、岡山から各地へ広がりました。","宗忠は1850年に亡くなりますが、弟子たちが教えを伝え、京都にも彼をまつる神社が建てられました。明治になると、1876年に神道の一派として独立した教団となります。","1974年、本部は岡山市郊外の丘 «神道山（しんとうざん）» へ移りました。ここは岡山平野を見わたし、朝日を拝むのにぴったりの場所。今も信者たちは朝、東の空に向かって手を合わせます。宗忠がつかんだ太陽の光を、みんなで受けとめつづけているのです。"],"tl":[["1780年","備前国御野郡上中野村（今の岡山市北区）の今村宮の神主の家に生まれる"],["1812年ごろ","両親を相次いで亡くし、自らも重い病にかかる"],["1814年","冬至の朝の «天命直授»。黒住教の立教とされる"],["1850年","宗忠が亡くなる"],["1862年","京都・吉田山に宗忠神社が建てられる"],["1876年","黒住教が神道の一派として独立"],["1974年","本部が神道山へ移る"]],"who":[["黒住宗忠","黒住教の教祖。今村宮の神主"],["赤木忠春","宗忠の高弟。京都での布教に力をつくしたとされる"],["黒住家の人びと","代々の教主として教えを受けついだ"]],"deep":["黒住教は、金光教・天理教とともに «幕末三大新宗教» とよばれることがあり、その中で最も早く成立しました。","宗忠が神主をつとめた今村宮は岡山市北区にあり、黒住教の旧本部 «大元（おおもと）» もその近くにありました。いまも宗忠神社が鎮座しています。","京都の宗忠神社は、吉田神社のある吉田山に建てられ、公家や武士の信者もいたことがうかがえます。岡山の宗教が都でも受け入れられた例です。","黒住教の大切な行いの一つが、朝日を拝む «日拝（にっぱい）»。宗忠の体験を毎朝くりかえす意味があります。","宗忠は «まるく、明るく、ほがらかに» 暮らすことを説いたと伝わり、病気なおしの «まじない» だけでなく、心の持ち方を重視しました。"],"look":["神道山の大教殿","朝日を拝む場所からの岡山平野の眺め","旧本部 «大元» 近くの宗忠神社","宗忠が神主をつとめた今村宮"],"q":["黒住宗忠が太陽の光と一体になったと感じたのは、一年のうち何の日？","冬至の日の朝。1814年のこの日が黒住教の立教の日とされています。"],"koji":[],"myth":"天命直授の体験と病の回復は教団の伝えによる。","img":["黒住宗忠","宗忠神社"],"wp":"黒住教","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Kurozumikyo_Honbu_main_worship_building.jpg",5472,3648,"黒住教"],["c:b/ba/Kurozumikyo_-_Shintozan_nippai.jpg",4080,3060],["c:0/06/Kurozumi_Munemichi_%E9%BB%92%E4%BD%8F%E5%AE%97%E9%81%93.jpg",1061,1682],["c:8/89/%E9%BB%92%E4%BD%8F%E5%AE%97%E5%BF%A0%E5%83%8F_%28cropped%29.jpg",2899,3366,"黒住宗忠"]]},{"id":"33_hirokane","n":"広兼邸（銅山とベンガラの豪邸）","yomi":"ひろかねてい","cat":"産業","y":1810,"era":["edo","meiji"],"sh":"","rank":"A","ad":"高梁市成羽町中野","st":"JR伯備線 備中高梁駅からバスで吹屋へ約1時間、そこから車で約5分。車が便利","la":34.882,"lo":133.49,"hook":"山奥に、まるでお城のような石垣。そこは城ではなく、ベンガラの原料でひと財産をきずいた庄屋の家だった。","lead":"広兼邸は、江戸時代の後半に建てられた庄屋・広兼家の屋敷です。広兼家は、近くの吉岡銅山の経営や、赤い顔料ベンガラの原料 «ローハ» の製造で大きな富を得ました。高い石垣の上に建つ姿は映画のロケ地にもなりました。","story":["吹屋の町から少し山を下ったところ。坂道をのぼると、いきなり目の前に高い石垣があらわれます。見上げるほどの石垣の上に白壁の蔵と長屋門――これが広兼邸です。«ここは本当にふつうの家?» と思わず声が出るほどの迫力です。","広兼家は、江戸時代の後半に大野呂村の庄屋をつとめた家です。近くの吉岡銅山から出る鉱石をもとに «ローハ（緑礬・りょくばん）» をつくりました。ローハは、焼くと赤い顔料 «ベンガラ» になる原料です。ベンガラは九谷焼や伊万里焼などの絵付け、建物の塗料として重宝され、広兼家は大きな富を手にしました。","屋敷は1810年ごろに建てられたといわれます。山の斜面を活かした城のような石垣、立派な門、たくさんの蔵。お金持ちだから派手にしたというだけではなく、山の中で財産と家族を守るための、しっかりしたつくりだったのでしょう。","この屋敷を全国に知らせたのは映画でした。横溝正史の小説をもとにした映画『八つ墓村』（1977年、1996年）で、物語の舞台となる屋敷のロケ地に使われたのです。もちろん物語は創作ですが、石垣を見上げると、映画のシーンを思い出す人も多いはず。","近くの吹屋の町は、ベンガラ色の赤い屋根と壁の家が並ぶ町並みで、国の重要伝統的建造物群保存地区に選ばれています。2020年には «ジャパンレッド発祥の地» として日本遺産にもなりました。広兼邸は、その赤い富を生んだ家として、町並みとセットで訪ねたい場所です。"],"tl":[["江戸時代中期","吉岡銅山の開発が進み、ローハ・ベンガラの生産が盛んになる"],["1810年ごろ","広兼家の屋敷が建てられたとされる"],["明治時代","吉岡銅山が近代的な経営で発展する"],["1972年","吉岡銅山が閉山"],["1977年","映画『八つ墓村』のロケ地になる"],["1977年","吹屋が重要伝統的建造物群保存地区に選定される"],["2020年","«ジャパンレッド» 発祥の地として日本遺産に認定"]],"who":[["広兼家","大野呂村の庄屋。銅山とローハ製造で富を築いた"],["横溝正史","『八つ墓村』の作者。岡山に疎開していたことで知られる"],["吹屋の商人たち","ベンガラの生産・販売で町を栄えさせた"]],"deep":["ベンガラ（紅殻）は酸化鉄を主成分とする赤い顔料で、名前はインドのベンガル地方に由来するといわれます。吹屋では、銅山の副産物から原料のローハをつくる独自の方法が発達しました。","吹屋のベンガラは品質が良く、陶磁器の赤絵のほか、神社仏閣や家の柱の塗料にも使われました。全国の «赤» の多くを支えた、と言われるほどです。","広兼邸の石垣は、土地の高低差を利用して積まれています。城郭の石垣と同じような技術がつかわれており、当時の石工の腕の高さがわかります。","映画『八つ墓村』は1977年版と1996年版の両方で広兼邸が使われたとされます。舞台は架空の村で、実在の事件や家とは関係ありません。","吹屋の町並みの家の多くは、明治から大正時代の建物です。石州瓦の赤い屋根とベンガラ格子が統一感をつくっています。"],"look":["城のような石垣と長屋門","母屋や土蔵のたたずまい","吹屋ふるさと村の赤い町並み","ベンガラ館（ベンガラづくりの工程を展示）","吉岡銅山の笹畝坑道"],"q":["広兼家がつくった «ローハ» は、焼くと何になる？","赤い顔料 «ベンガラ»。陶磁器の絵付けや建物の塗料に使われました。"],"koji":[],"myth":"屋敷の建築年は «1810年ごろ» とされる推定。映画の内容は創作。","img":["吹屋","ベンガラ","八つ墓村"],"wp":"広兼邸","rel":{"ev":[],"grave":[]},"ph":[["c:1/14/Hirokane_house14bss.jpg",3420,2280,"広兼邸"],["c:8/87/Fukiya01s3200.jpg",3600,2400,"吹屋"],["c:f/fa/Bengala_Akanesawa_red_rock_IMG_5840.jpg",4608,3456,"ベンガラ"]]},{"id":"33_kibiji","n":"吉備路（古代吉備の王国の道）","yomi":"きびじ","cat":"街道","y":500,"era":["kofun","nara"],"sh":"","rank":"A","ad":"総社市上林（備中国分寺）〜岡山市北区吉備津","st":"JR吉備線（桃太郎線）服部駅・備中高松駅・吉備津駅など。駅で自転車を借りて回るのが人気","la":34.686,"lo":133.764,"hook":"田んぼの中の五重塔、小山のような巨大古墳。ここにはかつて、ヤマトと並ぶほどの «王国» があった。","lead":"吉備路は、岡山市西部から総社市にかけての、古代 «吉備の国» の中心だった地域の呼び名です。全国で4番目に大きい造山古墳、備中国分寺の五重塔、吉備津神社など、古墳時代から奈良・平安時代の名所が田園の中に点々と並びます。","story":["春、れんげ畑の向こうにすっと立つ五重塔――吉備路を代表する風景です。塔は江戸時代の終わりに再建された備中国分寺のもの。そのまわりには、こんもりした森のような古墳がいくつも見えます。«なぜ、こんなに大きな古墳がここに?» それは、ここにかつて強い力をもつ «吉備» の王たちがいたからです。","5世紀ごろ、吉備の王は、ヤマト（今の奈良県）の大王と並ぶほどの力をもっていたと考えられています。その証拠が «造山古墳（つくりやまこふん）»。全長約350m、全国で4番目の大きさで、実際に墳丘に登ることができる古墳としては日本最大級です。すぐ近くの «作山古墳» も全長約280mの巨大古墳です。","吉備の力の秘密は、鉄と塩、そして瀬戸内海の交通だったといわれます。朝鮮半島から伝わった技術で鉄をつくり、船で人や物を運ぶ――まさに交通の要でした。やがてヤマトの力が強まると、吉備は備前・備中・備後に分けられ、のちに美作も分かれました。","奈良時代になると、聖武天皇の命で全国に国分寺・国分尼寺が建てられ、備中にもつくられました。今の五重塔の近くには、国分尼寺の跡や、古代の役所があったと考えられる場所も残ります。吉備の中心は、都の仕組みの中へと組みこまれていったのです。","吉備路の東には、桃太郎のモデルといわれる吉備津彦命をまつる吉備津神社があります。鬼（温羅）退治の伝説の舞台も、このあたりに点々と。古墳・寺・神社・伝説をつなぐ «吉備路自転車道» をのんびり走れば、古代の王国の広さが体で感じられます。"],"tl":[["3世紀ごろ","楯築墳丘墓など、吉備で大型の墓がつくられる"],["5世紀前半","造山古墳が築かれたと考えられる"],["5世紀中ごろ","作山古墳が築かれたと考えられる"],["7世紀後半","吉備が備前・備中・備後に分けられる"],["713年","備前から美作が分けられる"],["741年","聖武天皇が国分寺建立の詔を出す"],["1425年","吉備津神社の本殿・拝殿が再建される（国宝）"],["19世紀中ごろ","備中国分寺の五重塔が再建される"]],"who":[["吉備の王たち","造山古墳などを築いた地方の有力者"],["吉備津彦命","吉備津神社の祭神。桃太郎のモデルといわれる"],["吉備真備","この地域の出身とされる奈良時代の学者・政治家"],["聖武天皇","国分寺の建立を命じた天皇"]],"deep":["造山古墳は、大王の墓とされる古墳（宮内庁が管理）以外で最大の古墳の一つです。そのため墳丘に立ち入ることができ、上から周りを見わたせます。","造山古墳の周りには «陪塚（ばいちょう）» とよばれる小さな古墳がいくつもあります。また前方部の上には、阿蘇（熊本県）の石でつくられたとされる石棺が置かれていて、遠い九州との交流がうかがえます。","備中国分寺の五重塔は江戸時代後期の建築で国の重要文化財。岡山県内で唯一の五重塔です。","吉備津神社の本殿は «比翼入母屋造（吉備津造）» という独特の屋根で、国宝。室町時代の1425年に再建されたものです。","«吉備» の読みは «きび» で、穀物のキビと関係があるという説もありますが、確かなことはわかっていません。"],"look":["備中国分寺の五重塔","造山古墳（墳丘に登れる）","作山古墳","こうもり塚古墳（巨大な横穴式石室）","吉備津神社の本殿と長い回廊"],"q":["吉備路にある造山古墳は、全国で何番目に大きい古墳？","4番目。全長約350mで、墳丘に登れる古墳としては日本最大級です。"],"koji":[],"myth":"吉備津彦命＝桃太郎は伝承。古墳の築造年代は推定。","img":["造山古墳 (岡山市)","備中国分寺","吉備津神社","作山古墳"],"wp":"吉備路","rel":{"ev":[],"grave":[]},"ph":[["c:c/c7/Bitchu_Kokubunji_2.JPG",3008,2000,"吉備路"],["c:6/6e/Kibiji_cycling_road_and_Bitchu_Kokubunji.JPG",4000,3000],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"備中国分寺"],["c:f/fd/Kibitsu_Jinja_10_cropped.jpg",2594,1765,"吉備津神社"],["c:8/88/Tsukuriyama_Kofun_%28Soja%29%2C_zenkei.jpg",6016,4000,"作山古墳"]]},{"id":"33_bizen_kokubunji","n":"備前国分寺跡","yomi":"びぜんこくぶんじあと","cat":"遺跡","y":741,"era":["nara","heian"],"sh":"国指定史跡","rank":"B","ad":"赤磐市馬屋","st":"JR山陽本線 瀬戸駅から車で約10分。車が便利","la":34.747,"lo":134.02,"hook":"広い草はらに、礎石と石の塔だけ。ここに、国を守るための «国の寺» がそびえていた。","lead":"備前国分寺は、奈良時代に聖武天皇の命令で全国につくられた国分寺の一つです。建物はすでになく、今は «跡» として整備され、南門・中門・金堂・講堂などが一直線に並んでいた様子がわかるようになっています。","story":["赤磐市の田園の中に、ぽっかりと広い草地がひろがっています。ところどころに大きな平たい石――建物の柱を支えた «礎石» です。ここがかつての備前国分寺。今は建物は残っていない «跡» ですが、足もとの石を一つずつたどると、大きな寺の姿が浮かんできます。","741年、聖武天皇は «国分寺建立の詔（みことのり）» を出しました。当時は天然痘の流行やききん、反乱がつづき、世の中が不安定でした。«なぜ、寺を全国に?» ――仏教の力で国を守り、人びとの心をまとめようとしたのです。各国に僧の寺（国分寺）と尼の寺（国分尼寺）がつくられました。","発掘調査によって、備前国分寺は南から南門・中門・金堂・講堂が一直線に並び、まわりを築地塀（ついじべい）で囲んだ寺だったことがわかりました。そびえる塔も建っていたと考えられ、その礎石も残ります。遠くから見えるように高い塔を建てることは、国の力を示すことでもありました。","寺のすぐ近くには古代の山陽道が通っていたと考えられ、都から九州へ向かう役人や旅人が、この塔を目じるしにしたかもしれません。周辺には、岡山県で3番目に大きい両宮山古墳もあり、この地域が古くから備前の中心の一つだったことがわかります。","国分寺は、平安時代以降、国の支えが弱まるとともに次第に衰えていきました。跡地には、のちの時代に建てられた石造りの層塔（石の塔）が立ち、長い歴史を見守っています。季節の花が咲くころに訪ねて、礎石に腰かけ、千年以上前の鐘の音を想像してみてください。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀後半","備前国分寺の主な建物が整ったと考えられる"],["平安時代","国の支えが弱まり、次第に衰える"],["鎌倉〜室町時代ごろ","跡地に石造りの層塔が建てられたとされる"],["昭和後期","発掘調査が行われ、伽藍の配置が明らかになる"],["昭和","国の史跡に指定される"]],"who":[["聖武天皇","国分寺・国分尼寺の建立を命じた天皇"],["光明皇后","聖武天皇の皇后。国分寺建立をすすめたといわれる"],["備前の国司たち","都から派遣され、国分寺の建設や運営を担った役人"]],"deep":["国分寺の正式名は «金光明四天王護国之寺»、国分尼寺は «法華滅罪之寺»。お経の名前がそのまま寺の役割を表しています。","備前国分寺の伽藍（建物の配置）は、南門・中門・金堂・講堂が南北一直線に並ぶ形とされます。塔の位置は伽藍のなかで東寄りにあったと考えられ、全国の国分寺と比べる研究が行われています。","出土した瓦には、奈良時代の特徴をもつ文様のものがあり、寺が造られた時期を知る手がかりになっています。","備前の国府（役所）は、今の岡山市中区のあたりにあったと考えられており、国分寺とは少しはなれています。国府と国分寺の位置関係は国ごとにちがい、研究の論点の一つです。","跡地の石の層塔は、国分寺が衰えたあとも、この場所が信仰の地として大切にされてきたことを示しています。"],"look":["南門・中門・金堂・講堂の位置を示す表示と礎石","塔跡の礎石","石造りの層塔","近くの両宮山古墳"],"q":["国分寺をつくるよう命じた天皇はだれ？","聖武天皇。741年に国分寺建立の詔を出しました。"],"koji":[],"myth":"層塔の年代、伽藍配置の細部は調査・研究による推定をふくむ。","img":["国分寺","両宮山古墳"],"wp":"備前国分寺跡","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Bizen_Kokubunji-ato%2C_gaikan.jpg",5974,3936,"備前国分寺跡"],["c:b/b7/Enjuin_%28Akaiwa%29%2C_sanmon.jpg",5974,3936],["c:b/be/Bizen_Kokubunji-ato%2C_tou.jpg",3960,5990],["c:6/64/Bizen_Kokubunji-ato%2C_tou-ato.jpg",5990,3960],["c:9/9c/Bizen_Kokubunji-ato%2C_soubou-ato.jpg",6016,4000],["c:b/b6/Bizen_Kokubunji-ato%2C_nanmon-ato.jpg",6016,4000],["c:f/fa/Bizen_Kokubunji-ato%2C_koudou-ato.jpg",6016,4000],["c:7/74/Bizen_Kokubunji-ato%2C_kondou-ato.jpg",6016,4000]]},{"id":"33_omeguri","n":"大廻小廻山城（古代の朝鮮式山城）","yomi":"おおめぐりこめぐりさんじょう","cat":"遺跡","y":670,"era":["asuka"],"sh":"国指定史跡","rank":"B","ad":"岡山市東区瀬戸町・草ヶ部","st":"JR山陽本線 瀬戸駅から登山口まで車で約15分。山道を歩くので歩きやすい靴で","la":34.74,"lo":134.045,"hook":"日本の歴史書に一行も書かれていない、謎の «古代の城»。山を一周する土塁は約3kmもある。","lead":"大廻小廻山城は、大廻山と小廻山の二つの山にまたがってつくられた、飛鳥時代ごろの山城と考えられる遺跡です。朝鮮半島の城づくりの技術が使われたとみられますが、『日本書紀』などの歴史書には記録がなく、いつ、だれが、何のためにつくったのか、まだ謎が多い城です。","story":["岡山市の東、標高200mほどの大廻山。雑木林の中を歩くと、土を何層にもつき固めた高い土手（土塁）と、その根もとに並ぶ石の列があらわれます。この土塁は、山の尾根をぐるりと一周し、長さは約3kmにもなるといわれます。これが «大廻小廻山城» です。","«なぜ、こんな山の上に城を?» ――ヒントは663年の «白村江の戦い»。日本（倭）は朝鮮半島の百済を助けるために大軍を送りましたが、唐と新羅の連合軍に大敗しました。«今度は敵が日本にせめてくるかもしれない»。そうおそれた朝廷は、九州から瀬戸内海ぞいにかけて、朝鮮式の山城を築いたのです。","香川県の屋嶋城や、福岡県の大野城などは『日本書紀』に名前が出てきます。ところが大廻小廻山城は、どの記録にも出てきません。同じ岡山県の鬼ノ城も同じです。書かれていない城――だからこそ、土塁や石垣の調査が、ただ一つの手がかりになります。","谷の部分には、水を外に流しながら土塁が崩れないようにする «水門（すいもん）» の石組みが残るとされます。敵が入りにくく、しかも雨水で城がこわれないように――古代の技術者たちの工夫がつまっています。完成したのか、途中でやめたのか、それさえ議論が分かれています。","山頂からは、吉井川の流れや瀬戸内海の方向が見わたせます。海からせめてくる敵を見張り、いざというときは人びとが逃げこむ城だったのかもしれません。地元の人たちが道を整え、見学会も行われています。歴史書が語らない城の声を、自分の目で聞きに行ってみましょう。"],"tl":[["663年","白村江の戦いで倭・百済軍が唐・新羅軍に敗れる"],["664〜667年ごろ","朝廷が各地に水城や山城を築く（日本書紀に記録）"],["7世紀後半ごろ","大廻小廻山城が築かれたと考えられる"],["昭和後期","土塁や列石が見つかり、古代山城として知られるようになる"],["2005年","国の史跡に指定される"]],"who":[["天智天皇（中大兄皇子）","白村江の戦いの後、国の守りを固めた"],["百済からの亡命者たち","朝鮮式山城の築城技術を伝えたと考えられる"],["吉備の人びと","工事に動員されたと考えられる地元の人たち"]],"deep":["古代山城は、歴史書に名前が出てくる «朝鮮式山城» と、記録にない «神籠石（こうごいし）系山城» に分けて考えられることがあります。大廻小廻山城は後者のなかまとされます。","土塁は «版築（はんちく）» という方法で、土を薄く入れてはつき固めることをくり返してつくられています。雨でも崩れにくい、とても丈夫な方法です。","岡山県には、総社市の鬼ノ城とこの大廻小廻山城という二つの古代山城があります。どちらも文献に記録がなく、吉備の地が国の防衛で重要だったことをうかがわせます。","城の範囲は大廻山と小廻山の二つの山頂をふくみ、谷をまたいで土塁がめぐります。城の名前は地元の山の名から付けられた現代の呼び名です。","築城の年代や目的については、白村江の戦い後の防衛施設とする説が有力ですが、地方の役所との関係など、ほかの考え方もあります。"],"look":["尾根をめぐる土塁と列石","谷をふさぐ水門の石組み","山頂からの吉井川・瀬戸内方面の眺め","説明板（城の範囲の地図）"],"q":["大廻小廻山城のように、記録のない古代の山城の土塁のつくり方は？","«版築»。土を薄く重ねてはつき固め、丈夫な土手にしました。"],"koji":[],"myth":"築城年代・目的・完成の有無は諸説。水門の数など細部は調査による。","img":["白村江の戦い","鬼ノ城"],"wp":"大廻小廻山城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c2/Mount_Omeguri-Komeguri%2C_zenkei.jpg",6016,4000,"大廻小廻山城"],["c:b/b1/Omeguri_Komeguri_Sanjo-ato%2C_dorui.jpg",6016,4000],["c:3/37/Omeguri_Komeguri_Sanjo-ato%2C_Ni-no-kido-1.jpg",6016,4000],["c:9/9c/Omeguri_Komeguri_Sanjo-ato%2C_Ichi-no-kido-1-2.jpg",6016,4000],["c:8/82/Jorakuji_%28Okayama%29%2C_keidai-2.jpg",6002,3978],["j:9/93/%E5%A4%A7%E5%BB%BB%E5%B0%8F%E5%BB%BB%E5%B1%B1%E5%9F%8E_%E9%A0%88%E6%81%B5%E5%99%A8_%E7%9F%AD%E9%A0%B8%E5%A3%BA.JPG",4667,2975],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/a5/Kinojo%2C_enkei-2.jpg",4327,2877,"鬼ノ城"]]},{"id":"33_urama","n":"浦間茶臼山古墳（最古級の大型古墳）","yomi":"うらまちゃうすやまこふん","cat":"遺跡","y":280,"era":["kofun"],"sh":"国指定史跡","rank":"B","ad":"岡山市東区浦間","st":"JR赤穂線 西大寺駅から車で約10分。車が便利","la":34.717,"lo":134.056,"hook":"奈良の «箸墓古墳» をちょうど半分に縮めた形――最古級の前方後円墳が、吉井川のほとりにある。","lead":"浦間茶臼山古墳は、古墳時代のはじめ、3世紀の終わりごろにつくられたと考えられる前方後円墳です。全長は約138m。邪馬台国の女王・卑弥呼の墓という説もある奈良県の箸墓古墳と形がそっくりで、大きさがほぼ半分であることで注目されています。","story":["吉井川の下流、西の岸に小高い丘のように見える森があります。これが浦間茶臼山古墳。上から見ると、丸い部分（後円部）と、先が三味線のばちのように広がる四角い部分（前方部）をもつ、古いタイプの前方後円墳です。","«なぜ、箸墓古墳と同じ形なの?» ――箸墓古墳は、奈良県桜井市にある最初期の巨大古墳で、ヤマトの王の墓と考えられています。浦間茶臼山古墳は、その設計図を半分に縮めたような «相似形» だと指摘されています。ヤマトの王と吉備の王が深く結びつき、同じ設計の墓を許された――あるいは分け合った――のではないか、と考えられているのです。","後円部の頂上には、長い竪穴式石室がありました。残念ながら昔の盗掘で荒らされていましたが、調査では銅の矢じりや鉄の武器・道具の一部などが見つかったとされます。また吉備で生まれた «特殊器台» の流れをくむ埴輪も出土し、吉備の伝統とヤマトの新しい墓づくりが出会った場所だといえます。","3世紀の終わりごろ、この規模の古墳は全国でもわずかでした。つまり、吉井川の流域を治めた王は、日本列島でもトップクラスの有力者だったのです。川の水運をおさえ、瀬戸内海とつながることで力をたくわえたのでしょう。","今、古墳のまわりは田畑と住宅にかこまれ、ふだんは静かです。すそを一周しながら、«ここが半分なら、箸墓はどれほど大きいのか» と想像してみてください。古墳時代の幕開けに、吉備が大きな役わりを果たしていたことが実感できます。"],"tl":[["3世紀中ごろ","奈良県で箸墓古墳が築かれたと考えられる"],["3世紀末ごろ","浦間茶臼山古墳が築かれたと考えられる"],["昭和後期","岡山大学などによる測量・発掘調査が行われる"],["昭和末ごろ","国の史跡に指定される"]],"who":[["吉井川流域の王","この古墳に葬られたと考えられる有力者"],["ヤマトの王","箸墓古墳の被葬者と考えられる。浦間の王と結びついていたとみられる"],["卑弥呼","箸墓古墳の被葬者とする説がある邪馬台国の女王（諸説）"]],"deep":["全長約138m、後円部の直径は約80mとされます。前方部が低く、先端がばち形に開く形は、古墳時代前期のはじめの特徴です。","箸墓古墳（全長約280m）とのあいだに «1/2の相似形» が指摘されています。同じような相似関係は全国のいくつかの古墳でも研究されており、ヤマト王権との関係を探る手がかりになっています。","出土した埴輪には、吉備の弥生時代の «特殊器台» から発展した «都月形（とつきがた）円筒埴輪» とよばれるタイプがあるとされ、埴輪の起源が吉備にあることを示す例の一つです。","竪穴式石室は長さ7m前後と長大で、木棺をおさめていたと考えられます。石室は盗掘を受けており、副葬品の全体はわかっていません。","築造時期は古墳時代前期のはじめ（3世紀末ごろ）とされますが、年代の決め方には研究者によって幅があります。"],"look":["ばち形に開いた前方部の形","後円部の高さ","古墳の上から見る吉井川の方向","近くの古墳（周辺の古墳群）"],"q":["浦間茶臼山古墳は、奈良県のどの古墳を半分にした形といわれる？","箸墓古墳。最初期の巨大前方後円墳で、形がそっくりの «相似形» と指摘されています。"],"koji":[],"myth":"箸墓古墳の被葬者（卑弥呼説）は諸説。築造年代・相似関係は研究上の推定。","img":["箸墓古墳","前方後円墳"],"wp":"浦間茶臼山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:a/a7/Urama_Chausuyama_Kofun_air.jpg",327,272,"浦間茶臼山古墳"],["c:4/4e/Urama_Chausuyama_Kofun_07.jpg",3872,2592],["c:9/93/Urama_Chausuyama_Kofun_06.jpg",3872,2592],["c:2/2e/Urama_Chausuyama_Kofun_04.jpg",3872,2592],["c:8/8d/Urama_Chausuyama_Kofun_03.jpg",3872,2592],["c:7/77/Hashihaka-kofun_zenkei-2.jpg",5892,3804,"箸墓古墳"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"]]},{"id":"33_kanakurayama","n":"金蔵山古墳","yomi":"かなくらやまこふん","cat":"遺跡","y":380,"era":["kofun"],"sh":"","rank":"B","ad":"岡山市中区沢田","st":"JR岡山駅からバスで操山方面へ、下車後歩いて約20分。車が便利","la":34.652,"lo":133.975,"hook":"石室の «となりの部屋» から、鉄の道具がざくざく。王は、何よりも鉄を大切にしたらしい。","lead":"金蔵山古墳は、岡山市の操山（みさおやま）の尾根にある、4世紀後半ごろの前方後円墳です。全長は約165mで、岡山県内でも屈指の大きさ。1953年の発掘で、たくさんの鉄器や形のめずらしい埴輪が見つかり、古墳研究の重要な手がかりとなりました。","story":["岡山市の東、操山の尾根を歩くと、木々のあいだに大きな盛り土が見えてきます。金蔵山古墳です。今は森におおわれていますが、築かれたころは斜面を石でおおい、埴輪をずらりと並べた、町の平野からよく目立つ «王の墓» でした。","1953年、倉敷考古館の研究者たちがこの古墳の発掘を行いました。後円部の中央には、王の遺体をおさめた竪穴式石室がありました。そして、そのそばに副室（小さなとなりの部屋）が見つかります。«ここには何が?» ――ふたを開けると、刀や剣、斧や鎌、のみなど、おびただしい数の鉄製品が現れたといいます。","«なぜ、そんなに鉄を?» ――古墳時代、鉄はまだ朝鮮半島からの輸入にたよる貴重品でした。武器にも農具にもなる鉄をたくさん持つことは、そのまま力の大きさを示したのです。金蔵山の王は、鉄を手に入れ、人びとに分け与えることで、この地域をまとめていたのかもしれません。","埴輪もたくさん見つかりました。家の形、盾の形などをかたどった «形象埴輪» は、この時期のものとしては早い例とされ、古墳のまわりで行われた儀式を想像させます。発掘の成果はくわしい報告書にまとめられ、今でも古墳研究者が必ず読む資料になっています。","操山には、金蔵山古墳のほかにも多くの古墳が点在し、ハイキングコースも整えられています。山を歩きながら古墳を探すと、この尾根が何世代にもわたる «王たちの丘» だったことがわかります。見晴らしのよい場所から岡山平野を見下ろせば、王が治めた土地が一望できます。"],"tl":[["4世紀後半ごろ","金蔵山古墳が築かれたと考えられる"],["1953年","倉敷考古館による発掘調査。中央石室と副室が調査される"],["1959年","発掘の成果をまとめた報告書が刊行される"],["現在","操山の古墳めぐりのハイキングコースの一つとして親しまれる"]],"who":[["金蔵山の王","この古墳に葬られた有力者。名前はわかっていない"],["鎌木義昌","考古学者。倉敷考古館で発掘にかかわった"],["西谷真治","考古学者。金蔵山古墳の調査・報告にかかわった"]],"deep":["全長約165mは、造山古墳・作山古墳・両宮山古墳に次ぐ規模で、岡山県内で4番目の大きさとされます。","中央石室の副室から出た鉄製品は、刀剣のほか、斧・鎌・鋤先・のみ・やりがんななど工具類が多いのが特徴です。数は数百点におよぶとされ、当時の鉄の集中ぶりがわかります。","出土した形象埴輪（家形・盾形など）は、形象埴輪の出現期を考えるうえでの基準資料の一つになっています。","墳丘の斜面には «葺石（ふきいし）» が敷かれ、段になった墳丘の平らな面に埴輪が並んでいたと考えられます。","名前の «金蔵山» は山の名に由来します。金の蔵のような宝が出たから付いたわけではありませんが、実際に «鉄の宝庫» だったのは偶然の面白さです。"],"look":["森におおわれた墳丘の大きさ（前方部と後円部の段差）","葺石が見える場所","操山の尾根道と周辺の古墳","岡山平野の眺め"],"q":["金蔵山古墳の副室から大量に見つかった副葬品は何？","鉄製品。刀剣や斧・鎌などの工具で、鉄が力の象徴だったことを示します。"],"koji":[],"myth":"発掘関係者・報告書刊行年は要確認。鉄器の点数は資料で表現が異なる。","img":["操山","倉敷考古館"],"wp":"金蔵山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:3/3c/Kanakurayama_Kofun%2C_funkyu.jpg",6016,4000,"金蔵山古墳"],["c:4/4f/Misaoyama%2C_enkei.jpg",6010,3990],["c:1/1f/Kanakurayama_Kofun%2C_tsukuridashi.jpg",6016,4000],["c:1/10/Kanakurayama_Kofun%2C_shima-2.jpg",4000,6016],["c:f/f9/Kanakurayama_Kofun%2C_shima-1.jpg",6016,4000],["c:6/60/Kanakurayama_Kofun%2C_minami-sekishitsu.jpg",6010,3990],["c:8/82/Kanakurayama_Kofun%2C_kouenbu.jpg",6016,4000],["c:9/9a/Kanakurayama_Kofun%2C_funcho.jpg",6016,4000]]},{"id":"33_misaki_kofun","n":"美和山古墳群（津山の前方後円墳）","yomi":"みわやまこふんぐん","cat":"遺跡","y":400,"era":["kofun"],"sh":"国指定史跡","rank":"B","ad":"津山市二宮","st":"JR姫新線 院庄駅から歩いて約25分。車が便利","la":35.067,"lo":133.966,"hook":"美作の平野を見下ろす丘の上に、ひときわ大きな前方後円墳。ここに眠るのは、美作の «はじまりの王» かもしれない。","lead":"美和山古墳群は、津山市二宮の丘の上にある古墳のグループです。中心の1号墳は全長約80mの前方後円墳で、美作地方で最大級の古墳。まわりに円墳がならび、古墳時代の美作の有力者たちの墓と考えられています。","story":["津山の町から西へ。吉井川の流れを見下ろす小高い丘に、こんもりとした森が並んでいます。美和山古墳群です。いちばん大きな1号墳は、前方後円墳で全長約80m。美作の古墳のなかでは、トップクラスの大きさです。","«なぜ、ここに大きな古墳が?» ――津山盆地は、中国山地のまんなかにありながら、川によって瀬戸内海とつながる交通の要所でした。山の幸や鉄を集め、川で運ぶ。この土地をおさめた王は、盆地を一望できる丘を、自分の墓の場所に選んだのでしょう。","古墳群は1号墳のほか、円墳などいくつかの古墳からなります。大きな発掘はされていないため、中にだれが、どんな品といっしょに眠っているのかはわかっていません。わからないからこそ、形そのものが大切な手がかり。前方後円墳の形や、斜面の石の並びから、古墳時代の前期から中期ごろにつくられたと考えられています。","のちの奈良時代、713年に備前から美作国が分けられました。国の役所（国府）は今の津山市総社のあたりに置かれたと考えられています。古墳の近くには、美作国の «二宮» とされる高野神社もあります。«二宮» という地名そのものが、この地が古くから大切にされてきたことを物語ります。","古墳は地元で大切に守られ、説明板も立てられています。まわりの田畑や住宅地から見上げると、丘の上の森がひときわこんもりと盛り上がっているのがわかります。丘の上から津山盆地を見わたして、はるか昔、ここに立った王の目に映った景色を想像してみましょう。"],"tl":[["4〜5世紀ごろ","美和山1号墳などが築かれたと考えられる"],["713年","備前国から美作国が分けられる"],["奈良時代","津山市総社のあたりに美作国府が置かれたと考えられる"],["昭和","古墳群が国の史跡に指定される"],["現在","地元で守られ、外から見学できる"]],"who":[["美作の古代の王","1号墳に葬られたと考えられる有力者。名は不明"],["美作国の国司","奈良時代にこの地を治めた役人"],["高野神社の人びと","美作国二宮とされる神社を守り伝えてきた"]],"deep":["1号墳は全長約80mの前方後円墳で、美作地方では最大級とされます。岡山県南部の巨大古墳にくらべると小さいですが、山あいの盆地としては大きな規模です。","2号墳・3号墳は円墳とされ、主となる前方後円墳と円墳がセットになる形は、ほかの地域の古墳群にも見られます。","本格的な発掘調査は少なく、埋葬施設や副葬品のくわしいことは不明です。年代は墳丘の形などからの推定です。","美作国は備前国から分かれてできた国で、713年のことと『続日本紀』に記されています。古墳時代の有力者の存在が、国の成立の土台になったと考えられます。","近くの高野神社は美作国の二宮とされ、古墳群の名が付いた地名 «二宮» とのつながりを感じさせます。"],"look":["1号墳（前方後円墳）の墳丘","2号墳・3号墳（円墳）","丘の上からの津山盆地の眺め","近くの高野神社"],"q":["美作国が備前国から分かれてできたのは何年？","713年。『続日本紀』に記録があります。"],"koji":[],"myth":"築造年代は推定。国史跡の指定年は未確認。","img":["美作国","津山市"],"wp":"美和山古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:d/dd/Miwayama_Kofun_Group-6%2C_funkyu.jpg",6016,4000],["c:4/4d/Miwayama_Kofun_Group-3%2C_funkyu.jpg",6016,4000],["c:d/df/Miwayama_Kofun_Group-2%2C_funkyu.jpg",6016,4000],["c:0/05/Miwayama_Kofun_Group-1%2C_zenpoubu.jpg",6016,4000],["c:3/34/Miwayama_Kofun_Group-1%2C_kouenbu.jpg",6016,4000],["c:2/20/Miwayama_Kofun_Group-1%2C_funkyu-1.jpg",6016,4000],["c:c/cb/Miwayama_Kofun_Group-1%2C_funcho.jpg",6016,4000],["c:6/61/Miwayama_Kofun_Group-1%2C_dorui-2.jpg",6016,4000]]},{"id":"33_onbara","n":"恩原遺跡（旧石器の狩人のキャンプ）","yomi":"おんばらいせき","cat":"遺跡","y":-25000,"era":["kyuseki"],"sh":"","rank":"B","ad":"苫田郡鏡野町上齋原（恩原高原）","st":"JR津山駅から車で約1時間。公共交通では行きにくい","la":35.272,"lo":133.942,"hook":"標高700mの高原の湖のほとり。2万年以上前、ここで狩人たちがたき火をかこみ、石の刃をけずっていた。","lead":"恩原遺跡群は、岡山県の北のはし、鳥取県との県境に近い恩原高原にある旧石器時代の遺跡です。氷河期の寒い時代、狩りをする人びとがここにキャンプし、石器をつくっていました。何度も調査が行われ、日本の旧石器研究の重要な遺跡の一つとして知られています。","story":["中国山地の山ふところにある恩原高原。今は静かな恩原湖と、夏はキャンプ場、冬はスキーでにぎわう場所です。けれど、およそ2万年以上前、ここには別の «キャンパー» がいました。旧石器時代の狩人たちです。","氷河期のころ、日本列島は今よりずっと寒く、海の水位も低くて、陸地が大きく広がっていました。人びとは土器も田んぼも持たず、シカなどの動物を追って移動しながら暮らしていました。«なぜ、こんな山の上に?» ――高原の水辺には動物が集まり、見晴らしもいい。狩りにはもってこいの場所だったのでしょう。","1980年代から、岡山大学などによる発掘調査が何度も行われました。土の層を1枚ずつていねいにはがしていくと、石器や、石器をつくるときに出た小さなかけらがたくさん見つかりました。かけらの集まり方から、«ここで座って石を割っていた» という作業の場所まで推理できるのです。","とくに注目されたのは、鹿児島の姶良カルデラの大噴火で降り積もった火山灰（AT火山灰）の層です。この層の上と下から石器が見つかり、大噴火の前と後で人びとの道具がどう変わったのかを比べることができました。遠い九州の噴火が、岡山の山奥の遺跡の «時計» になっているのです。","見つかった石器の中には、この近くでは採れない石で作られたものもあるとされ、人びとが広い範囲を移動したり、交換したりしていたことがうかがえます。遺跡は湖畔の自然の中にあり、見学用の施設はほとんどありません。湖を見わたしながら、2万年前の狩人たちのたき火の煙を想像してみましょう。"],"tl":[["約3万年前","姶良カルデラが大噴火し、AT火山灰が日本列島に広く降る"],["約3万〜2万年前ごろ","恩原高原で狩人たちが石器をつくる"],["旧石器時代の終わりごろ","細石刃（小さな刃を組み合わせる道具）の時代の石器も見つかる"],["1980年代〜","岡山大学などによる発掘調査が行われる"]],"who":[["旧石器時代の狩人たち","恩原高原に何度もキャンプした人びと"],["岡山大学の調査団","長年にわたり発掘・研究を行った"],["上齋原の人びと","遺跡のある高原を守り伝えている"]],"deep":["AT火山灰（姶良Tn火山灰）は、鹿児島湾北部の姶良カルデラの噴火によるもので、北は東北地方まで降り積もりました。全国の旧石器遺跡の年代を合わせる «ものさし» として使われます。","恩原遺跡群では、AT火山灰より下の層と上の層の両方から石器が見つかり、石器の形や作り方の移り変わりを一つの遺跡で追える点が評価されています。","石器をつくるときに出たかけら同士をパズルのようにつなぎ合わせる «接合» の研究によって、石をどんな順番で割ったのかまで復元されています。","旧石器時代の終わりには、カミソリの刃のような小さな石の刃（細石刃）を木や骨の柄に並べて使う道具が広まりました。恩原でもこの時期の石器が見つかっています。","旧石器時代の遺跡では、骨や木などは酸性の土の中でほとんど残りません。石器だけが、人びとの暮らしを語る証人です。"],"look":["恩原湖と高原の景色","遺跡のある湖畔周辺の地形（水辺と平らな台地）","県北の資料館などの旧石器の展示"],"q":["鹿児島の噴火でできた、旧石器遺跡の年代の «ものさし» になる火山灰の名前は？","AT火山灰（姶良Tn火山灰）。恩原遺跡ではこの層の上と下から石器が見つかりました。"],"koji":[],"myth":"年代は推定値。石器石材の産地の細部は研究による。","img":["恩原湖","旧石器時代","姶良カルデラ"],"wp":"恩原遺跡群","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:a/ac/Sakura-jima_from_space.jpg",3000,3716,"姶良カルデラ"],["c:a/a1/NagaikeOasisusimoike.jpg",4000,3000,"近く: 上齋原村"],["c:1/14/Ningyouyouge-park.jpg",4834,3053,"近く: 人形峠"],["c:4/4b/Kagamino_town_office_Kamisaibara_development_center.jpg",2048,1536,"近く: 上齋原"],["c:7/7e/Kagamino_town_Kamisaibara_General_Education.JPG",1280,960,"近く: 鏡野町立上齋原小学校"],["c:4/48/%E3%81%8B%E3%81%8C%E3%81%BF%E3%81%AE%E8%BF%91%E4%BB%A3%E7%BE%8E%E8%A1%93%E9%A4%A8%E3%81%AE%E7%A7%8B%E6%99%AF.jpg",640,480,"近く: かがみの近代美術館"]]},{"id":"33_washuzan","n":"鷲羽山遺跡（瀬戸内の旧石器）","yomi":"わしゅうざんいせき","cat":"遺跡","y":-20000,"era":["kyuseki"],"sh":"国指定史跡","rank":"B","ad":"倉敷市下津井（鷲羽山）","st":"JR瀬戸大橋線 児島駅からバスで鷲羽山方面へ約20分","la":34.438,"lo":133.809,"hook":"瀬戸大橋を見下ろす展望の山。2万年前、ここから見えたのは海ではなく、どこまでも続く草原だった。","lead":"鷲羽山遺跡は、瀬戸内海を見わたす鷲羽山にある旧石器時代の遺跡です。氷河期には海面が今より大きく下がり、瀬戸内海は陸地でした。山の上からは、今の海の底にあった平原で動物を追う人びとの姿が見えたかもしれません。","story":["倉敷市の南の先、瀬戸大橋のたもとにそびえる鷲羽山。頂上に立つと、青い海と小さな島々、巨大な橋が一望できます。岡山を代表する絶景ですが、じつはこの山は、旧石器時代の人びとの足あとが残る遺跡でもあります。","«なぜ、山の上に?» ――今からおよそ2万年前の氷河期、世界中の氷が増えて、海面は今より100m以上も低かったと考えられています。瀬戸内海のほとんどは陸地で、四国と本州は歩いて行き来できました。今の海は、草原や川の流れる広い平野だったのです。","その平野を見下ろす鷲羽山は、狩人にとって絶好の見張り台でした。動物の群れを見つけ、どこへ向かうかを見きわめる。山の上で見つかった石器は、そんな狩りの暮らしを物語っています。","見つかった石器の多くは、«サヌカイト» という石でつくられていました。サヌカイトは香川県などで採れる黒くかたい石で、たたくと «カンカン» と金属のような音がします。割るとするどい刃ができるため、ナイフのような石器にぴったりでした。四国の石が岡山の山の上にあるのは、瀬戸内海が陸だったからこそ――とも考えられます。","やがて氷河期が終わると海面が上がり、平原は海の底に沈みました。こうして今の瀬戸内海が生まれたのです。鷲羽山の展望台から海を見下ろすとき、足もとに眠る2万年前の草原を思いうかべてみてください。景色がまったくちがって見えるはずです。"],"tl":[["約2万年前ごろ","氷河期で海面が低く、瀬戸内海の大部分が陸地だった"],["旧石器時代","鷲羽山で狩人たちがサヌカイトの石器を使う"],["約1万年前以降","海面が上がり、瀬戸内海ができていく"],["1934年","瀬戸内海国立公園に指定される（鷲羽山を含む）"],["昭和","鷲羽山遺跡が国の史跡に指定される"],["1988年","瀬戸大橋が開通"]],"who":[["旧石器時代の狩人たち","鷲羽山を見張り台やキャンプ地にした人びと"],["考古学者たち","山の上で石器を見つけ、瀬戸内の旧石器研究を進めた"]],"deep":["瀬戸内海の海底からは、ナウマンゾウなどの化石が漁の網にかかって引き上げられることがあります。ここがかつて陸地で、大きな動物がいた証拠です。","サヌカイトは «讃岐岩» ともいい、香川県の «讃岐» から名前がついています。瀬戸内の旧石器遺跡の多くでこの石が使われ、石材の流通を考える手がかりです。","鷲羽山遺跡の石器には、ナイフ形石器などが含まれるとされ、日本列島の旧石器時代後半の特徴を示しています。","«鷲羽山» の名は、山の形が鷲が羽を広げた姿に見えることからといわれます。","遺跡は国立公園の中にあり、展望台やハイキングコースから周囲の地形をよく観察できます。石器を持ち帰ったり掘ったりすることは法律で禁じられています。"],"look":["鷲羽山の展望台からの瀬戸大橋と島々","遺跡を示す説明板","山の地形（かつての平原を見下ろす位置）","岡山県内の博物館のサヌカイト石器の展示"],"q":["鷲羽山遺跡の石器によく使われた、たたくと金属のような音がする石は？","サヌカイト（讃岐岩）。割るとするどい刃ができます。"],"koji":[],"myth":"氷河期の海面の低さは推定値。指定年は未確認。","img":["鷲羽山","サヌカイト","瀬戸大橋"],"wp":"鷲羽山遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:d/db/%E5%9B%BD%E7%AB%8B%E5%85%AC%E5%9C%92_%E9%B7%B2%E7%BE%BD%E5%B1%B1_%E7%AC%AC%E4%B8%80%E5%8F%A4%E5%A2%B3_-_panoramio.jpg",3648,2048,"鷲羽山遺跡"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c2/Mount_Washu_-_Looking_at_the_Seto_Inland_Sea.jpg",4496,3000,"鷲羽山"],["c:f/f8/Sanukite.JPG",1280,960,"サヌカイト"],["c:2/28/JP-Kagawa-Great-Seto-Bridge-Minami_Bisan-Seto-Bridge.jpg",3332,2222,"瀬戸大橋"]]},{"id":"33_koikui","n":"鯉喰神社（温羅と吉備津彦の伝説）","yomi":"こいくいじんじゃ","cat":"伝承","y":250,"era":["yayoi","kofun"],"sh":"","rank":"B","ad":"倉敷市矢部","st":"JR吉備線（桃太郎線）吉備津駅から歩いて約30分。自転車が便利","la":34.664,"lo":133.778,"hook":"鯉に化けて逃げる鬼、鵜に化けて追う皇子。桃太郎の «原作» の決着の場所がここ。","lead":"鯉喰神社は、吉備に伝わる «温羅（うら）伝説» の舞台の一つです。吉備津彦命に追いつめられた鬼の温羅が鯉に化けて逃げ、吉備津彦命が鵜に化けて食べてとらえた、と伝わります。じつはこの神社は、弥生時代の墓の上に建っていることでも知られています。","story":["むかしむかし、吉備の国に «温羅» という鬼がいたと伝わります。温羅は山の上に «鬼ノ城» を築き、人びとをおそれさせていました。そこで都から、吉備津彦命（きびつひこのみこと）が退治にやってきます。――これが、桃太郎のもとになった話の一つといわれる «温羅伝説» です。","二人は矢を射あいました。吉備津彦命の矢と温羅の投げた岩が空中でぶつかって落ちた場所が «矢喰宮（やぐいのみや）» だと伝わります。やがて吉備津彦命が一度に二本の矢を放つと、一本が温羅の目に命中。流れ出た血で川が赤く染まり、その川は «血吸川（ちすいがわ）» とよばれるようになったといいます。","«このままではやられる!» 温羅は鯉に化けて血吸川へ逃げこみました。すると吉備津彦命はすぐさま鵜に化け、水にもぐって鯉をくわえ上げた――。その場所に建つのが «鯉喰神社» だと伝わります。境内には今も、血吸川の流れが近くを通っています。","物語のつづきでは、温羅の首ははねられても声を上げつづけ、ついに吉備津神社の御釜殿の下に埋められたとされます。その釜が鳴る音で吉凶を占う «鳴釜神事» は、今も吉備津神社で行われています。伝説と神事が、今もつながっているのです。","«なぜ、鬼の話がここに?» ――じつは鯉喰神社は、弥生時代の終わりごろにつくられた墳丘墓の上に建っていて、吉備で生まれた «特殊器台» のかけらなども見つかっています。すぐ近くには有名な楯築墳丘墓もあります。古くからの «王の墓» の土地に、のちの人びとが英雄と鬼の物語を重ねたのかもしれません。"],"tl":[["弥生時代後期","神社の建つ場所に墳丘墓がつくられる"],["弥生時代後期","近くに楯築墳丘墓が築かれる"],["古代〜中世","吉備津彦命と温羅の伝説が語られるようになったと考えられる"],["室町時代","吉備津神社の本殿が再建され、鳴釜神事なども伝えられる"],["現在","温羅伝説の «ゆかりの地» の一つとして親しまれる"]],"who":[["吉備津彦命","温羅を退治したと伝わる皇子。吉備津神社の祭神"],["温羅","鬼ノ城にいたと伝わる鬼。渡来の人を表すという説もある"],["弥生時代の吉備の王","神社の下の墳丘墓に葬られたと考えられる人物"]],"deep":["温羅伝説は、吉備津神社の縁起（由来の話）などに伝わる物語で、江戸時代以前から語られていたとされます。桃太郎の «ルーツ» の一つとする説がありますが、桃太郎の話の成り立ちには諸説あります。","温羅は百済の王子だったという話もあり、朝鮮半島から来た技術者集団を表しているのでは、と考える人もいます。鬼ノ城が朝鮮式の山城であることとも結びつけられますが、学問的に確かめられたものではありません。","神社の下の墳丘墓は «鯉喰神社墳丘墓» などとよばれ、弥生時代後期の吉備の墓の一つとして考古学上も注目されています。","伝説の場所は吉備路一帯にちらばっています。矢喰宮（岡山市北区）、血吸川、鬼ノ城（総社市）、吉備津神社の御釜殿など、つなげて巡るとまるで物語のすごろくです。","«鳴釜神事» では、釜の鳴る音の大小で吉凶を占います。上田秋成の『雨月物語』の «吉備津の釜» にも登場します。"],"look":["小さな社殿と境内（墳丘墓の高まりの上）","近くを流れる血吸川","楯築遺跡（楯築墳丘墓）","矢喰宮・吉備津神社の御釜殿"],"q":["温羅が鯉に化けて逃げたとき、吉備津彦命は何に化けた？","鵜（う）。水にもぐって鯉をとらえた、と伝わります。"],"koji":[],"myth":"温羅伝説は伝承。温羅＝百済王子説・桃太郎のルーツ説は諸説で確証なし。","img":["温羅","吉備津神社","楯築墳丘墓","鬼ノ城"],"wp":"鯉喰神社","rel":{"ev":[],"grave":[]},"ph":[["c:c/c4/Koikui_shrine.jpg",1440,1080,"鯉喰神社"],["c:7/7d/Koikui_shrine_honden.jpg",1440,1080],["c:c/ce/Ura-kyuusekihi.jpg",5962,3916,"温羅"],["c:f/fd/Kibitsu_Jinja_10_cropped.jpg",2594,1765,"吉備津神社"],["c:7/71/Tatetsuki_Funkyu-bo%2C_funcho.jpg",5886,3794,"楯築墳丘墓"],["c:a/a5/Kinojo%2C_enkei-2.jpg",4327,2877,"鬼ノ城"]]},{"id":"33_kibidera","n":"吉備寺（吉備真備ゆかりの寺）","yomi":"きびでら","cat":"寺社","y":717,"era":["asuka","nara"],"sh":"","rank":"B","ad":"倉敷市真備町箭田","st":"井原鉄道 吉備真備駅から歩いて約15分","la":34.642,"lo":133.696,"hook":"唐で囲碁の勝負にも勝ったと伝わる天才・吉備真備。そのふるさとの古い寺の跡に、今も瓦のかけらが眠る。","lead":"吉備寺は、奈良時代の学者・政治家、吉備真備（きびのまきび）の一族がたてた寺のあとに建つといわれるお寺です。境内には古代の寺の礎石が残り、近くには真備の墓と伝わる場所もあります。地名の «真備» も、この人物にちなんでいます。","story":["倉敷市の西、小田川が流れる真備町。ここは奈良時代の大学者、吉備真備のふるさととされる土地です。真備は695年ごろ、吉備の地方豪族・下道氏（しもつみちうじ）の家に生まれたとされます。今の吉備寺の場所には、その一族の氏寺があったと考えられ、古い瓦や礎石が見つかっています。","717年、20代前半の真備は遣唐使の留学生として唐へ渡りました。同じ船団には、のちに唐で役人になる阿倍仲麻呂や、僧の玄昉もいました。真備は唐で約17年も学び、儒学、天文、暦、兵法、音楽まで、ありとあらゆる知識を身につけて帰国します。","«なぜ、そんなに有名なのか?» ――真備の帰国は、日本に最新の学問をもたらす大事件でした。のちに再び遣唐使として唐へ渡り、帰りの船団には唐の高僧・鑑真も乗っていました。帰国後は、764年の藤原仲麻呂の乱で作戦を立てて鎮めるなど活躍し、ついには地方豪族の出身ながら右大臣にまで上りつめます。","真備には不思議な伝説もたくさんあります。平安時代の絵巻『吉備大臣入唐絵巻』では、唐の人びとから次々に難問を出された真備が、鬼（阿倍仲麻呂の霊）の助けで、囲碁の勝負や難しい文書の読み解きに勝つ物語が描かれています。もちろん作り話ですが、それほど «すごい人» と思われていたのです。","吉備寺の境内には古代の礎石が残り、近くには «吉備公墓» とよばれる、真備の墓と伝わる場所もあります。真備町は2018年の西日本豪雨で大きな被害を受けましたが、地域の人びとは復興を進めながら、ふるさとの偉人を大切にしています。静かな境内で、千三百年前の天才の足あとをたどってみましょう。"],"tl":[["695年ごろ","吉備真備が生まれる（下道氏の出身）"],["717年","遣唐使の留学生として唐へ渡る"],["735年","唐から帰国し、多くの書物や道具をもたらす"],["752年","遣唐副使として再び唐へ（翌々年に帰国）"],["764年","藤原仲麻呂の乱の鎮圧に活躍"],["766年","右大臣になる"],["775年","亡くなる"]],"who":[["吉備真備","奈良時代の学者・政治家。このあたりの出身とされる"],["阿倍仲麻呂","同じ遣唐使で唐へ渡った。唐で一生を終えた"],["玄昉","同じく唐へ渡った僧。帰国後、真備とともに政治に関わった"],["鑑真","真備が帰国したときの船団で日本へ来た唐の高僧"]],"deep":["吉備寺の地は «箭田廃寺» とよばれる古代寺院の跡と考えられ、飛鳥時代から奈良時代ごろの瓦が見つかっています。一族が地方で寺をたてる力をもっていたことがわかります。","真備は、唐から «唐礼»（儀式の本）や暦の本、楽器、武器などを持ち帰ったと『続日本紀』に記録されています。","『吉備大臣入唐絵巻』は平安時代末ごろの作とされ、現在はアメリカのボストン美術館が所蔵しています。","真備が右大臣になったのは、学問の力で出世した例としてとても珍しく、後世の菅原道真と並んで語られることがあります。","«吉備公墓» は真備の墓と伝えられる場所ですが、確かな証拠があるわけではありません。周辺は «まきび公園» として整えられています。"],"look":["吉備寺の境内に残る古代の礎石","吉備公墓（真備の墓と伝わる場所）","まきび公園","小田川の流れと真備町の町並み"],"q":["吉備真備が唐から帰国するときの船団で日本へやって来た唐の高僧はだれ？","鑑真。何度も航海に失敗したすえ、日本にたどり着きました。"],"koji":[],"myth":"吉備公墓・氏寺との関係は伝承をふくむ。絵巻の話は創作。","img":["吉備真備","吉備大臣入唐絵巻","遣唐使"],"wp":"吉備寺","rel":{"ev":[],"grave":[]},"ph":[["c:f/f1/Kibiji_Temple_%28Mabi-cho%2C_Kurashiki_City%29.jpg",4896,3672,"吉備寺"],["j:8/85/%E7%AE%AD%E7%94%B0%E5%BB%83%E5%AF%BA%E5%87%BA%E5%9C%9F_%E8%93%AE%E8%8F%AF%E6%96%87%E9%AC%BC%E7%93%A6.JPG",3206,3306],["c:f/f1/Kyorinan_Kibiji_02.JPG",2048,1362],["c:4/44/Kyorinan_Kibiji_01.JPG",2048,1362],["c:4/49/Kibi_Daijin_Seated_at_a_Chinese_Table_LACMA_M.84.31.239.jpg",1397,2100,"吉備真備"],["c:3/37/Kibi_Daijin_nitt%C5%8D_e_-_S2_sc228985.jpg",960,719,"吉備大臣入唐絵巻"],["c:c/c7/Japanese_embassy_to_the_Tang_court.jpg",2099,1740,"遣唐使"]]},{"id":"33_yuga","n":"由加山蓮台寺（金毘羅との両参り）","yomi":"ゆがさんれんだいじ","cat":"寺社","y":1700,"era":["nara","edo"],"sh":"","rank":"B","ad":"倉敷市児島由加","st":"JR瀬戸大橋線 児島駅から車で約20分。車が便利","la":34.508,"lo":133.825,"hook":"«金毘羅さんだけ参るのは片参り»――江戸の旅人たちは、海をはさんで二つのお参りをセットにした。","lead":"由加山蓮台寺は、倉敷市児島の山の上にあるお寺で、古くから «由加山（ゆがさん）» の名で知られています。江戸時代には、海の向こうの香川県・金刀比羅宮（こんぴらさん）と両方にお参りする «両参り» が大流行し、たくさんの参拝者でにぎわいました。","story":["児島半島の山あいを車でのぼると、門前町の雰囲気が残る参道にたどり着きます。ここが由加山。お寺の由来は、奈良時代に行基がひらいたと伝わるほど古く、本尊の «瑜伽大権現（ゆがだいごんげん）» は、厄よけの神仏として信仰されてきました。","江戸時代、庶民のあいだで旅行がブームになると、四国の金刀比羅宮へのお参りが大人気になりました。«なぜ、由加山も?» ――金毘羅さんと由加山は、どちらか一方だけでは «片参り» になってご利益が少ない、といわれるようになったのです。本州から船で丸亀へ渡り、金毘羅さんを参ったら、帰りは由加山へ。こうして «両参り» が定着しました。","児島の港には、四国へ渡る船が行き来しました。由加山の門前には宿屋や茶店が並び、参拝者たちがおみやげを買い求めました。岡山藩主の池田家も由加山を大切にし、祈願の寺としたと伝わります。立派な客殿などには、そうした時代の繁栄が感じられます。","明治時代のはじめ、神と仏を分ける «神仏分離» の政策によって、由加山は «蓮台寺（お寺）» と «由加神社本宮（神社）» に分かれることになりました。それでも今も二つはすぐとなりにあり、どちらも «ゆがさん» として親しまれています。一つの山に、寺と神社の二つの歴史が重なっているのです。","1988年に瀬戸大橋ができると、本州と四国は鉄道と車で結ばれました。江戸の人びとが船で渡った «両参り» の道は、今では橋の上をあっという間に通れます。由加山の境内から瀬戸内の方向を見て、かつての旅人たちの長い道のりを思いうかべてみましょう。"],"tl":[["733年ごろ","行基がひらいたと伝わる"],["江戸時代","岡山藩主池田家の祈願寺として大切にされたと伝わる"],["江戸時代後期","金刀比羅宮との «両参り» が流行する"],["明治初め","神仏分離により蓮台寺と由加神社本宮に分かれる"],["1988年","瀬戸大橋が開通し、四国との行き来が大きく変わる"]],"who":[["行基","奈良時代の僧。由加山をひらいたと伝わる"],["池田家（岡山藩主）","由加山を祈願の場として大切にしたと伝わる"],["江戸時代の参拝者","金毘羅参りと合わせて由加山を訪れた庶民たち"]],"deep":["«両参り» は、由加山と金刀比羅宮の両方に参ることで、ご利益が大きくなるという考え方です。由加山側の宣伝もあって広まったとみられ、江戸時代の «観光の工夫» としても面白い例です。","本尊の瑜伽大権現は、神と仏が一体となった «権現» の信仰です。«瑜伽» はもともとサンスクリット語の «ヨーガ» を漢字で表したことばです。","神仏分離のあと、同じ山に寺と神社が並び立つことになりました。どちらも «由加山» を名のり、歴史的な経緯をめぐって語られることもあります。","由加神社本宮には、江戸時代の備前焼の大きな鳥居があることで知られ、岡山の焼き物文化と信仰のつながりを感じられます。","児島は江戸時代、下津井や田之口などの港から四国へ渡る拠点でした。金毘羅参りの船が行き来し、港町として栄えました。"],"look":["蓮台寺の本堂と客殿","由加神社本宮と備前焼の鳥居","門前の参道の町並み","山の上からの瀬戸内方面の眺め"],"q":["由加山と金刀比羅宮の片方だけに参ることを何という？","«片参り»。両方に参る «両参り» がよいとされ、江戸時代に流行しました。"],"koji":[],"myth":"行基開山・池田家祈願寺は寺伝。«両参り» の起こりは諸説。","img":["由加神社本宮","金刀比羅宮"],"wp":"蓮台寺 (倉敷市)","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Rendaiji_01.jpg",4288,2848,"蓮台寺 (倉敷市)"],["c:0/0b/Yuga_Jinja_04.jpg",4288,2848,"由加神社本宮"],["c:3/3d/Kotohira-gu01s.jpg",3648,2432,"金刀比羅宮"]]},{"id":"33_fukuyama_jo","n":"福山城跡（南北朝の福山合戦）","yomi":"ふくやまじょうあと","cat":"古戦場","y":1336,"era":["kamakura","muromachi"],"sh":"国指定史跡","rank":"B","ad":"総社市清音・倉敷市の境（福山）","st":"JR伯備線 清音駅から登山口まで歩いて約30分、山頂まではさらに山道を約1時間","la":34.662,"lo":133.745,"hook":"«湊川の戦い» の直前、足利軍の前に立ちはだかった山の城。南北朝の大きな分かれ道が、ここにあった。","lead":"福山城跡は、総社市と倉敷市の境にそびえる福山（標高約300m）の山頂にある城あとです。1336年、九州から京都へ攻め上る足利尊氏・直義の軍と、後醍醐天皇方の新田義貞の軍勢がここで戦いました。これを «福山合戦» といい、『太平記』にもくわしく描かれています。","story":["鎌倉幕府がほろんだあと、後醍醐天皇の «建武の新政» が始まりました。しかし武士たちの不満は高まり、足利尊氏は天皇にそむきます。一度は京都を追われて九州へ落ちのびた尊氏でしたが、1336年、大軍をひきいて再び都を目指しました。","尊氏は船で瀬戸内海を東へ、弟の直義は陸の山陽道を進みました。これをむかえうつため、新田義貞の一族・大井田氏経（おおいだうじつね）らが陣を張ったのが、備中の «福山» です。山の上に城をかまえ、東へ向かう足利軍の行く手をふさごうとしたのです。","«なぜ、この山だったのか?» ――福山のふもとには高梁川が流れ、山陽道が通っていました。山の上からは平野を行く軍勢がよく見わたせます。ここをおさえれば、陸の道を止められる。まさに «関所» のような場所でした。","しかし、足利方は大軍でした。『太平記』によれば、足利方は山を取りかこみ、激しい戦いのすえに城は落ち、大井田らは東へ退いたといいます。勢いにのった足利軍は、そのまま東へ進み、同じ月の終わりには摂津の «湊川の戦い» で楠木正成を破りました。","福山の山頂には、城のくるわ（平らな場所）や土塁などのあとが残り、戦いをしのぶ碑も立っています。ハイキングの山として整えられた道を登り、頂上から平野を見下ろすと、足利の大軍が山陽道を押し寄せてくる光景が目にうかぶようです。戦いで命を落とした人びとへの思いも忘れずに歩きましょう。"],"tl":[["1333年","鎌倉幕府がほろびる"],["1334年","後醍醐天皇による建武の新政が始まる"],["1336年春","足利尊氏が九州へ落ちのびる"],["1336年5月","福山合戦。足利直義の軍が福山城を攻め落とす"],["1336年5月25日","湊川の戦い。楠木正成が戦死"],["1336年","足利尊氏が京都に入り、のちに室町幕府をひらく"]],"who":[["足利直義","尊氏の弟。陸路を進み福山を攻めた"],["足利尊氏","室町幕府の初代将軍。九州から東上した"],["大井田氏経","新田一族の武将。福山城にこもって戦ったとされる"],["新田義貞","後醍醐天皇方の総大将。足利軍をむかえうった"],["楠木正成","福山合戦のあと湊川で足利軍と戦い戦死"]],"deep":["福山合戦のようすは『太平記』に描かれていますが、軍記物語なので、兵の数や戦いの様子には大げさな表現もふくまれていると考えられます。","福山は標高約300mで、山頂からは高梁川の流れと総社・倉敷方面の平野が見えます。古代の山陽道がふもとを通っていたことが、城の場所えらびの理由と考えられます。","山頂付近にはくるわや土塁、井戸のあとなどの遺構が残るとされ、南北朝時代の山城のようすを知る手がかりになっています。","福山合戦は、湊川の戦いへとつながる «東上作戦» の一こまです。ここで足利方が勝ったことで、後醍醐天皇方の防衛線は東へ下がりました。","福山城は、広島県の福山城（江戸時代の城）とは別の城です。こちらは «備中の福山城» とよび分けます。"],"look":["山頂のくるわ跡と土塁","福山合戦をしのぶ碑","山頂からの高梁川と平野の眺め","登山道の途中の説明板"],"q":["福山合戦のあと、足利軍が楠木正成を破った戦いは？","湊川の戦い（1336年）。福山合戦と同じ月のできごとです。"],"koji":[],"myth":"合戦の細部は『太平記』の記述で誇張をふくむ可能性。遺構の範囲は調査による。","img":["湊川の戦い","足利直義","太平記"],"wp":"福山城 (備中国)","rel":{"ev":[],"grave":[]},"ph":[["c:0/01/Bitchu_Hukuyama_Castle.JPG",2841,1881,"福山城 (備中国)"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:0/07/%E8%B6%B3%E5%88%A9%E7%9B%B4%E7%BE%A9.jpg",1608,1583,"足利直義"],["c:7/7c/Taiheiki_-_1698_-_1-5.jpg",2592,1728,"太平記"]]},{"id":"33_mitsuishi","n":"三石城跡（浦上氏の山城）","yomi":"みついしじょうあと","cat":"城","y":1521,"era":["kamakura","muromachi"],"sh":"","rank":"B","ad":"備前市三石","st":"JR山陽本線 三石駅から登山口まで歩いて約10分、山頂まで山道を約40分","la":34.81,"lo":134.265,"hook":"主君を追いつめ、ついには命をうばった戦国の «下剋上»。その舞台裏にあったのが、播磨との国境の山城だった。","lead":"三石城は、備前市三石の天王山（標高約290m）にある山城のあとです。播磨（兵庫県）との国境、山陽道のすぐそばにあり、室町時代から戦国時代にかけて、備前の守護代・浦上氏の本拠となりました。浦上村宗は、ここを拠点に主君の赤松氏と争いました。","story":["岡山県の東のはし、兵庫県との県境の町・三石。JRの駅のすぐ北に、けわしい山がそびえています。この山の上にあったのが三石城です。ふもとには昔から山陽道が通り、都と西国をむすぶ «のど元» ともいえる場所でした。","城は鎌倉時代の終わりごろに築かれたと伝わり、南北朝の戦乱でも争いの場となったといわれます。室町時代になると、播磨・備前・美作を治める守護大名・赤松氏の家来である «浦上氏» がこの城を拠点にしました。浦上氏は «守護代»――守護の代わりに国を治める役目です。","戦国時代、浦上家の当主・浦上村宗は、力を強めていきました。主君の赤松義村は村宗をおさえようと、三石城を攻めます。しかし、けわしい山城はなかなか落ちません。«なぜ、この城はこんなに強かったのか?» ――尾根の上に細長くくるわを連ね、どこから攻めても坂を登らなければならない。攻める側には、たいへんな城だったのです。","逆に力を失った義村は、やがて村宗に捕らえられ、1521年に播磨の室津で命をうばわれたと伝わります。家来が主君をたおす――まさに «下剋上» の時代の始まりでした。村宗はその後、畿内の争いに加わり、1531年に摂津で戦死します。","浦上氏の力はその後、村宗の子の宗景に引きつがれ、拠点は西の天神山城へ移っていきました。三石城の山頂には、くるわのあとや石垣、井戸のあとなどが残り、登山道も整えられています。汗をかいて登りきり、国境の山なみを見わたすと、ここを守った武士たちの気持ちが少しわかるかもしれません。"],"tl":[["1330年代ごろ","三石城が築かれたと伝わる"],["南北朝時代","足利方・南朝方の争いの舞台になったといわれる"],["室町時代中ごろ","赤松氏の守護代・浦上氏の本拠となる"],["1519〜1520年ごろ","赤松義村が三石城を攻めるが落とせなかったとされる"],["1521年","浦上村宗が赤松義村を死に追いやる"],["1531年","浦上村宗が摂津で戦死（大物崩れ）"],["16世紀中ごろ","浦上宗景が天神山城を本拠とし、三石城の役わりは小さくなる"]],"who":[["浦上村宗","浦上氏の当主。三石城を拠点に主君の赤松義村と争った"],["赤松義村","播磨などの守護大名。三石城を攻めたが失敗し、のちに命をうばわれた"],["浦上宗景","村宗の子。天神山城を拠点に備前で勢力を広げた"],["浦上則宗","村宗より前の浦上氏の当主。赤松氏を支えて力をたくわえた"]],"deep":["三石城は尾根にそってくるわを並べた «連郭式» の山城とされ、大手（正面）の門のあとや石垣の一部が残ります。","浦上氏は、赤松氏の家来でありながら、備前の実際の支配者として力をのばしました。守護代が守護をしのぐ «下剋上» の典型例とされます。","赤松義村の最期については、室津で幽閉されたのちに殺されたと伝わりますが、細かな経緯には諸説があります。","1531年の «大物崩れ» は、摂津の大物（今の兵庫県尼崎市）で細川高国と浦上村宗の軍が敗れた戦いです。村宗はここで戦死しました。","三石はのちに耐火れんがの原料 «ろう石» の産地として知られ、近代には町の産業をささえました。城山のふもとの町並みにも、その面影があります。"],"look":["山頂のくるわ跡と石垣","大手門跡","井戸のあと","山頂からの県境の山なみと山陽道（国道・JR）の眺め"],"q":["家来が主君をたおして力を持つことを何という？","«下剋上»。浦上村宗が主君の赤松義村をたおしたのはその代表例です。"],"koji":[{"w":"下剋上","m":"下の者が上の者に打ち勝って地位をうばうこと。戦国時代を表すことば"}],"myth":"築城年・南北朝期の戦い・義村の最期の細部は諸説。","img":["浦上村宗","赤松義村","浦上宗景"],"wp":"三石城","rel":{"ev":[],"grave":[]},"ph":[["c:5/59/Mitsuishi_Castle_05.JPG",4912,3264,"三石城"],["c:2/22/Mitsuishi_Castle_15.JPG",4912,3264],["c:9/9e/Mitsuishi_Castle_14.JPG",4912,3264],["c:9/9b/Mitsuishi_Castle_11.JPG",4912,3264],["c:9/9e/Mitsuishi_Castle_10.JPG",4912,3264],["c:3/3a/Mitsuishi_Castle_09.JPG",4912,3264],["c:f/f0/Mitsuishi_Castle_04.JPG",4912,3264],["c:5/56/Mitsuishi_Castle_02.JPG",4912,3264]]},{"id":"33_iwaya","n":"岩屋城跡（美作の山城）","yomi":"いわやじょうあと","cat":"城","y":1582,"era":["muromachi","azuchi"],"sh":"","rank":"B","ad":"津山市中北上","st":"JR津山駅から車で約40分。登山口から山頂まで山道を約40分","la":35.116,"lo":133.905,"hook":"尼子、毛利、宇喜多――美作の山の上の城は、戦国の大名たちに次々と奪い合われた。","lead":"岩屋城は、津山市の北西、標高約480mの岩屋山にある山城のあとです。室町時代に築かれたと伝わり、戦国時代には美作をねらう尼子氏・毛利氏・宇喜多氏らのあいだで何度も争奪戦が起こりました。山の上には、くるわや堀切などの遺構がよく残っています。","story":["津山盆地の北西、深い山の中に岩屋山がそびえます。名前のとおり、岩がごつごつした山で、頂上近くには岩の洞窟もあると伝わります。この山の上にあったのが岩屋城。美作の山城のなかでも、とくに遺構がよく残る城として知られています。","城は、室町時代の中ごろ、美作の守護となった山名氏が築いたと伝わります。«なぜ、この山に?» ――岩屋山は、美作の西部と北の出雲方面をむすぶ道を見下ろす場所にありました。山陰から美作へ攻めこむ敵を見張り、止めるには、うってつけだったのです。","戦国時代になると、美作はまわりの大名たちにとって «取り合いの国» になりました。出雲の尼子氏が攻めこみ、つづいて安芸の毛利氏、そして備前の宇喜多氏が勢力をのばしてきます。岩屋城も、そのたびに城主が入れかわりました。","とくに激しかったのは、毛利氏と宇喜多氏が美作をめぐって争った天正年間です。宇喜多方は岩屋城を攻め、まわりに «付城（つけじろ）»――攻めるための陣地の城――を築いて包囲したと伝わります。やがて羽柴秀吉と毛利氏の和睦により、美作は宇喜多氏の領地と決まり、岩屋城も戦の役目を終えていきました。","今、山頂付近には、くるわ、堀切、たくさんの竪堀（たてぼり）などが残り、戦国の山城の «設計図» をそのまま見るようです。登山道は地元の人たちによって整えられています。山道はけわしいので、しっかりした準備をして、遠い戦国の攻防に思いをはせてみましょう。"],"tl":[["1441年ごろ","嘉吉の乱の後、美作守護の山名氏が築いたと伝わる"],["16世紀前半〜中ごろ","出雲の尼子氏が美作に進出する"],["1560年代","毛利氏が美作へ勢力をのばす"],["天正年間（1570〜80年代）","毛利氏と宇喜多氏が美作をめぐって争い、岩屋城も攻防の舞台となる"],["1582〜1583年ごろ","羽柴秀吉の仲立ちで美作が宇喜多領となる方向が決まる"],["江戸時代初め","城は使われなくなり、山城のあとが残る"]],"who":[["山名教清","美作の守護。岩屋城を築いたと伝わる"],["尼子氏","出雲の戦国大名。美作へ攻めこんだ"],["毛利氏","安芸の戦国大名。美作の城をめぐって宇喜多氏と争った"],["宇喜多直家・秀家","備前の戦国大名。美作へ勢力を広げた"]],"deep":["岩屋城は、尾根の上に連なるくるわと、それを区切る深い堀切、斜面にならぶ多数の竪堀が特徴です。竪堀を並べる «畝状竪堀（うねじょうたてぼり）» は、斜面を横に移動させないための工夫です。","城のまわりには、攻める側が築いた陣城（付城）のあとと考えられる遺構があるとされ、城攻めのようすを立体的に考えられる貴重な場所です。","«嘉吉の乱»（1441年）は、播磨の守護・赤松満祐が将軍・足利義教を殺した事件です。赤松氏がほろぼされ、美作の守護は山名氏にかわりました。","美作は、備前・備中・播磨・因幡・伯耆・出雲などにかこまれ、どの大名にとっても «通り道» でした。そのため中小の山城がとても多い地域です。","羽柴秀吉と毛利氏の «国分け» では、美作・備中の境をどう引くかが大きな問題になりました。美作の城のいくつかは、決まったあとも毛利方の武士がこもって抵抗したといわれます。"],"look":["山頂の本丸跡とくるわ","深い堀切","斜面に並ぶ竪堀","岩屋山の岩場と眺め","登山口の説明板"],"q":["山の斜面にたてにいくつも並べて掘った堀を何という？","«竪堀»。たくさん並べたものは «畝状竪堀» とよばれ、敵が斜面を横に動けないようにしました。"],"koji":[],"myth":"築城者・築城年は伝承。城主の交代や攻防の年は資料で異同がある。","img":["嘉吉の乱","美作国","宇喜多直家"],"wp":"岩屋城 (美作国)","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/44/Ukita_Naoie.jpg",350,410,"宇喜多直家"],["c:9/94/Okutsu_Onsen_04.jpg",2048,1536,"近く: 鏡野町"],["c:6/61/Kagamino_town_Oono_elementary_school.jpg",1280,964,"近く: 鏡野町立大野小学校"],["c:6/6c/Kagamino_town_Kagamino_junior_high_school.jpg",1280,964,"近く: 鏡野町立鏡野中学校"],["c:1/18/Homyoji_Kofun_%28Kagamino%29%2C_funkyu.jpg",5568,3712,"近く: 法明寺古墳 (鏡野町)"],["c:b/ba/Doi_Tennozan_Kofun%2C_funkyu.jpg",5568,3712,"近く: 土居天王山古墳"],["c:7/7e/Inoue_Otsuka_Kofun%2C_entrance-1.jpg",5568,3712,"近く: 井上大塚古墳"]]},{"id":"33_tomiyama","n":"富山城跡（松田氏の城）","yomi":"とみやまじょうあと","cat":"城","y":1568,"era":["muromachi","azuchi"],"sh":"","rank":"B","ad":"岡山市北区矢坂東町（矢坂山）","st":"JR吉備線（桃太郎線）備前三門駅から登山口まで歩いて約15分","la":34.676,"lo":133.884,"hook":"岡山駅から見える小さな山の上に、宇喜多直家の前に立ちふさがった一族の城があった。","lead":"富山城は、岡山市北区の矢坂山にあった山城のあとです。戦国時代、備前の西部に勢力をもった松田氏の城として知られ、のちに宇喜多直家との争いの中で松田氏がほろびると、宇喜多氏の城となりました。岡山の市街地をすぐ近くに見下ろす場所にあります。","story":["岡山駅の西、住宅地の向こうにこんもりと見える矢坂山。今は散歩やハイキングで人が訪れる山ですが、戦国時代、ここには «富山城（とみやまじょう）» がありました。城のはじまりは古く、平安時代に «富山氏» という一族が築いたと伝わります。","室町時代から戦国時代にかけて、備前の西部で力をもったのが «松田氏» です。松田氏は旭川の上流の金川城を本拠とし、富山城もその大切な拠点の一つでした。富山城から東を見れば、旭川の平野と、のちに岡山城が築かれる場所が目の前です。","そのころ、備前の東では宇喜多直家がどんどん力をのばしていました。«なぜ、松田氏と宇喜多氏はぶつかったのか?» ――どちらも備前を自分の手でおさめたかったからです。直家は、松田氏の家来を味方に引き入れる «調略» を重ね、じわじわと追いつめていきました。","1568年、宇喜多直家はついに金川城を攻め、松田氏はほろびたとされます。富山城も宇喜多氏の手に渡り、岡山の西の守りとなりました。直家はその後、石山城（のちの岡山城）に入り、城下町づくりを始めます。富山城は、宇喜多氏の «岡山時代» の幕開けを見届けた城でもあったのです。","今、矢坂山の山頂付近には、くるわのあとや石垣の一部と考えられる石が残るとされます。山頂からは岡山の市街地が一望でき、戦国の武将たちが見た «岡山平野の取り合い» の舞台がよくわかります。気軽に登れる山なので、城あと歩きの入門にもぴったりです。"],"tl":[["平安時代","富山氏が城を築いたと伝わる"],["室町時代","備前西部の松田氏の拠点となる"],["16世紀中ごろ","宇喜多直家が備前東部で勢力をのばす"],["1568年","宇喜多直家が金川城の松田氏をほろぼしたとされる"],["1573年ごろ","宇喜多直家が石山城（のちの岡山城）へ移る"],["江戸時代初め","城は使われなくなる"]],"who":[["松田氏","備前西部の戦国武将の一族。金川城を本拠とし富山城も拠点とした"],["宇喜多直家","備前の戦国大名。松田氏をほろぼし、岡山城下を築いた"],["富山氏","城を最初に築いたと伝わる一族"]],"deep":["松田氏は法華宗（日蓮宗）をあつく信仰し、領内の寺を法華宗に改めさせたといわれ、ほかの宗派との対立も生んだと伝わります。","松田氏の本拠・金川城は旭川の上流、今の岡山市北区御津にあり、富山城とともに備前西部の守りを固めていました。","宇喜多直家は、合戦だけでなく、相手の家来を寝返らせたり、暗殺したりする «謀略» で勢力を広げたことで知られます。松田氏との争いでも家臣の内通があったと伝わります。","矢坂山は標高約140mほどの低い山ですが、平野の中にぽつんとあるため見晴らしがよく、城を置くのに向いていました。","富山城の «富山» は «とみやま» と読みます。富山県の «とやま» とは別です。"],"look":["山頂付近のくるわ跡","石垣の一部と考えられる石","山頂からの岡山市街の眺め","登山道の途中の説明板"],"q":["松田氏の本拠地だった城の名前は？","金川城。旭川の上流にあり、1568年に宇喜多直家に攻められたとされます。"],"koji":[],"myth":"富山氏築城は伝承。松田氏と富山城の関係・滅亡年の細部は諸説。","img":["宇喜多直家","金川城"],"wp":"富山城 (備前国)","rel":{"ev":[],"grave":[]},"ph":[["c:7/73/%E5%82%99%E5%89%8D%E5%AF%8C%E5%B1%B1%E5%9F%8E_03.JPG",2048,1536,"富山城 (備前国)"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/44/Ukita_Naoie.jpg",350,410,"宇喜多直家"],["c:7/7c/Kanagawa_Castle.JPG",3008,2000,"金川城"]]},{"id":"33_otoko","n":"乙子城跡（宇喜多直家の最初の城）","yomi":"おとごじょうあと","cat":"城","y":1544,"era":["muromachi"],"sh":"","rank":"B","ad":"岡山市東区乙子","st":"JR赤穂線 大富駅から歩いて約20分","la":34.642,"lo":134.058,"hook":"兵はたった30人ほど、城は小さな丘の上。のちの «梟雄» 宇喜多直家は、ここからはい上がった。","lead":"乙子城は、岡山市東区の吉井川河口近くにあった小さな城のあとです。1544年、宇喜多直家が主君の浦上宗景からこの城をまかされたといわれ、直家が初めて持った城として知られます。直家はここから力をたくわえ、やがて備前の大名へとのし上がっていきました。","story":["吉井川が瀬戸内海に注ぐ近く、田んぼの中にぽこんと小さな丘があります。高さは50mにも満たない、城と呼ぶには小さな山。ここが乙子城のあとです。今は静かな丘ですが、戦国時代には海と川をにらむ «最前線» の城でした。","宇喜多直家の子ども時代はきびしいものでした。祖父の宇喜多能家は、同じ浦上家の家来に攻められて命を落とし、一族は散りぢりになったと伝わります。少年の直家は、父とともに放浪の暮らしを送ったといわれます。","1544年、成長した直家は浦上宗景に仕え、手柄を立てて乙子城をまかされました。与えられた兵は足軽30人ほどだったと伝わります。«なぜ、こんな小さな城を?» ――乙子は、児島の方から船でやってくる敵や海賊を見張る場所。小さくても大切な守りの城だったのです。","乙子城時代の直家には、こんな話が伝わります。食べ物が少なく、直家は家来に食事を回すために、自分は月に何日か食事をぬいた――。本当かどうかはわかりませんが、家来の心をつかむのがうまかった直家らしいエピソードとして語られています。","その後、直家は新庄山城、沼城と城を移しながら力をのばし、ついには主君の浦上宗景をも追い落として、備前の大名になります。そして石山城を大きくし、岡山の町づくりを始めました。«梟雄（きょうゆう）»――ずるがしこく強い武将――とよばれた直家の出発点が、この小さな丘なのです。丘の上には、城あとを示す碑が立っています。"],"tl":[["1529年","宇喜多直家が生まれる"],["1534年ごろ","祖父・宇喜多能家が攻められて死去したと伝わる"],["1544年","直家が浦上宗景から乙子城をまかされたとされる"],["1559年ごろ","直家が沼城（亀山城）に移る"],["1568年","直家が松田氏をほろぼしたとされる"],["1573年ごろ","直家が石山城（のちの岡山城）へ移る"],["1581年ごろ","直家が亡くなる"]],"who":[["宇喜多直家","乙子城を最初の城とし、備前の大名にのし上がった武将"],["浦上宗景","直家の主君。のちに直家に追われた"],["宇喜多能家","直家の祖父。攻められて命を落としたと伝わる"],["宇喜多秀家","直家の子。豊臣政権の五大老の一人になった"]],"deep":["«足軽30人» という数は、のちの軍記物などに伝わる話で、正確な数字かどうかは確かめられていません。直家の «小さな出発» を強調する話として語られてきました。","乙子城は吉井川の河口に近く、当時は今よりも海がずっと近くまで来ていたと考えられています。児島湾の干拓が進む前の地形を想像すると、城の役わりがよくわかります。","直家は、敵の武将を暗殺したり、親族をも利用したりした «謀略家» として知られますが、それは後世の軍記物が強調した面もあり、評価は見直されつつあります。","直家の死の年は1581年とも1582年ともいわれ、諸説があります。死を一時かくしたという話も伝わります。","直家の子・秀家は、豊臣秀吉にかわいがられ、関ヶ原の戦いで西軍の主力として戦いましたが、敗れて八丈島へ流されました。"],"look":["乙子城あとの丘と城あとを示す碑","丘の上からの吉井川河口方面の眺め","周辺の田園（かつての海辺の地形を想像）","岡山城（直家の «ゴール»）"],"q":["宇喜多直家が乙子城をまかされたとき、与えられた兵はどれくらいと伝わる？","足軽30人ほど。小さな出発から備前の大名へとのし上がりました（数は伝承）。"],"koji":[{"w":"梟雄","m":"残忍で強く、たくましい武将。宇喜多直家を表すことばとしてよく使われる"}],"myth":"足軽30人・断食の話は伝承。直家の没年は1581年・1582年の諸説。","img":["宇喜多直家","浦上宗景","宇喜多秀家"],"wp":"乙子城","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Otogo_Castle.JPG",1600,1064,"乙子城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/44/Ukita_Naoie.jpg",350,410,"宇喜多直家"],["c:3/33/Ukita_Hideie.jpg",350,420,"宇喜多秀家"]]},{"id":"33_mitsuboshi","n":"三星城跡（後藤勝基の最後）","yomi":"みつぼしじょうあと","cat":"城","rank":"B","y":1579,"era":["muromachi","azuchi"],"sh":"","ad":"美作市明見","st":"JR姫新線・林野駅から歩いて約30分で登山口、そこから山道を登る。車が便利","la":35.0205,"lo":134.1486,"hook":"美作の山城で、戦国の城主・後藤勝基は宇喜多直家の大軍を前に最後まで城を守ろうとした。","lead":"三星城は、美作（岡山県北東部）の東の入り口をおさえた山の上の城の跡です。戦国時代、この地の武将・後藤氏が城主でした。1579年ごろ、備前の宇喜多直家に攻められて落城し、城主の後藤勝基は命を落としたと伝わります。","story":["美作の林野（はやしの）の町の北に、こんもりとした山がそびえています。これが三星城のあった山です。ふもとには吉野川と梶並川が流れ、東の播磨（兵庫県）へ向かう道も通っていました。«ここをおさえれば美作の東がおさえられる»。そんな場所だからこそ、戦国の武将たちはこの山を大事にしたのです。","城主の後藤氏は、この地で長く力をもった一族でした。戦国時代の後半、城を守っていたのが後藤勝基です。美作は、西の毛利、東の織田、南の宇喜多、さらに尼子の残党などが入り乱れる «草刈り場» のような国でした。小さな領主は、どの大きな勢力につくかで生き残りが決まります。勝基も、ときに味方を変えながら家を守ろうとしました。","やがて備前の宇喜多直家が、美作へ手をのばしてきます。直家は、はかりごとと戦の両方を使って勢力を広げた武将です。勝基は宇喜多と縁を結んだ時期もあったといわれますが、最後には敵対することになりました。«なぜ味方どうしだったのに戦うことになったのか?» ここには、毛利と織田のどちらにつくかという大きな流れが関わっていたと考えられています。","1579年（天正7年）ごろ、宇喜多の軍勢が三星城を取り囲みました。山の上の城は守りやすいとはいえ、長く囲まれれば食べ物も水も少なくなります。城はついに落ち、勝基は城を出たのち自害したと伝わります。«最後まで美作の武士として生きた»。地元では今も、勝基をしのぶ声が残っています。","いま山の上には、平らにならした曲輪（くるわ）や堀切などの跡が残り、登ると林野の町や川の流れを見わたせます。建物は何も残っていない «跡» ですが、地形そのものが城のしくみを教えてくれる場所です。"],"tl":[["室町時代","後藤氏がこの地で力をもち、三星城を本拠にしたといわれる"],["戦国時代後半","美作が毛利・宇喜多・尼子などの争いの場になる"],["1579年ごろ","宇喜多直家の軍勢に攻められ落城。後藤勝基が亡くなる（年は諸説）"],["その後","城は使われなくなり、山城の遺構が残る"],["現在","城跡として整備され、登山道から曲輪などを見学できる"]],"who":[["後藤勝基","三星城の城主。宇喜多氏との戦いで城を失い、最期を迎えたと伝わる"],["宇喜多直家","備前の戦国大名。美作へ勢力を広げ、三星城を攻め落とした"],["毛利輝元","中国地方の大名。美作の領主たちが味方につくかどうかを左右した"]],"deep":["三星城は典型的な «山城»。山頂から尾根にかけて曲輪を段々に並べ、尾根を堀切で断ち切って敵が一気に登れないようにしています。石垣よりも土を削って造る «土の城» です。","城の名前の «三星» は、山の峰の形や家紋に由来するなど諸説があり、はっきりしません。","落城の年は1579年（天正7年）とされることが多いものの、史料によって前後の年が書かれることもあり、細かな経過には諸説があります。","後藤氏の出自については、古くからこの地の領主だったとする説などがありますが、系図には後世に整えられた部分があるとみられます。","美作は戦国時代の終わりまで、毛利・宇喜多・織田方の境目になり、小さな城が数多く造られました。三星城はその中でも規模の大きい城の一つです。","勝基が亡くなったあと、美作東部は宇喜多氏の支配が強まり、のちに宇喜多秀家の領国の一部になっていきます。"],"look":["山頂の本丸跡からの林野の町のながめ","尾根を断ち切る堀切","段々に並ぶ曲輪の平らな面","登山口の案内板（縄張り図があると歩きやすい）"],"q":["三星城を攻め落としたのは、どこの戦国大名？","備前の宇喜多直家です。美作へ勢力を広げる中で、後藤勝基の三星城を攻めました。"],"myth":"落城の年や勝基の最期のようす、城の名前の由来には諸説・伝承がある。","img":["宇喜多直家","美作国"],"wp":"三星城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/44/Ukita_Naoie.jpg",350,410,"宇喜多直家"],["c:e/e3/Hayashino-sta.jpg",3837,2738,"近く: 林野駅"],["c:c/c4/Mimasaka_IC.jpg",2592,1944,"近く: 美作インターチェンジ"],["c:a/a9/%E6%B9%AF%E9%83%B7%E6%B8%A9%E6%B3%89_-_panoramio.jpg",1600,900,"近く: 美作町"],["c:b/b7/Mimasaka_police_station.jpg",2048,1536,"近く: 美作警察署"],["c:7/7f/R179-134.jpg",1600,900,"近く: 道の駅彩菜茶屋"],["c:3/3a/Mimasaka_City_Office.jpg",3965,2688,"近く: 美来 (美作市)"]]},{"id":"33_shimotsui_jo","n":"下津井城跡（瀬戸内の見張りの城）","yomi":"しもついじょうあと","cat":"城","rank":"B","y":1600,"era":["azuchi","edo"],"sh":"","ad":"倉敷市下津井","st":"JR瀬戸大橋線・児島駅から下電バスで下津井方面へ約20分、下車して坂道を歩いて約15分","la":34.439,"lo":133.808,"hook":"瀬戸大橋のすぐ横、海を見下ろす丘の上に、瀬戸内の船の行き来を見張った城があった。","lead":"下津井城は、瀬戸内海に突き出た児島半島の先、下津井の港を見下ろす丘に造られた城の跡です。安土桃山から江戸時代のはじめにかけて、岡山の大名の城として使われました。一国一城令のあと廃城になり、今は石垣などの跡が残る公園になっています。","story":["下津井の港は、昔から «風待ち・潮待ち» の港として知られていました。瀬戸内海は潮の流れが速く、船は潮の向きが変わるのを港で待ったのです。その港を見下ろす丘の上に建てられたのが下津井城でした。«海を行く船を見張り、いざというときは守りを固める»。そんな役目をもった、海の城です。","城が本格的に整えられたのは、豊臣秀吉の時代から江戸時代のはじめにかけてといわれます。関ヶ原の戦いのあと、備前は小早川秀秋、つづいて池田氏が治めました。池田氏は、岡山城を守るための大事な支城として下津井に重臣を置きました。石垣を積んだ本丸や二の丸があり、海からもよく目立ったことでしょう。","ところが、1615年に幕府が «一国一城令» を出すと、大名は原則として一つの国に一つしか城を持てなくなりました。«なぜ下津井城はすぐに取りこわされなかったの?» 実は、しばらくは例外的に残され、廃城になったのは寛永年間（1630年代の終わりごろ）といわれます。瀬戸内の守りとして、それだけ大切にされたのかもしれません。","城がなくなったあとも、下津井は北前船が立ち寄る港町として栄えました。ニシンのかすなどの肥料が運びこまれ、児島の綿づくりを支えました。丘の上の城跡は、港の人々にとって、昔の殿さまの時代を思い出させる場所になりました。","今、城跡に立つと、目の前に瀬戸大橋の巨大な橋脚が見えます。400年前に船を見張った丘から、鉄道と自動車が海をわたる橋を見上げる。時代の大きな変化を、一度に感じられる場所です。"],"tl":[["16世紀後半","宇喜多氏の時代に城が築かれたといわれる"],["1600年","関ヶ原の戦い。のち備前は小早川秀秋の領地に"],["1603年","池田氏が備前を治めるようになり、下津井城は支城として重臣が守る"],["1615年","一国一城令が出されるが、下津井城はしばらく残される"],["1639年ごろ","廃城になる（寛永年間）"],["江戸時代","下津井が北前船の寄港地として栄える"],["1988年","すぐそばを通る瀬戸大橋が開通"]],"who":[["宇喜多秀家","備前の大名。この時代に下津井の城が整えられたとされる"],["小早川秀秋","関ヶ原の戦いのあと備前を治めた大名"],["池田忠継・池田忠雄","江戸時代はじめの岡山藩主。下津井城を支城として使った"],["池田由成","池田家の重臣で、下津井城を預かったと伝わる"]],"deep":["一国一城令のあとも残された支城は全国的に少数で、下津井城は瀬戸内海の要所という理由で例外扱いになったと考えられます。","城跡には本丸・二の丸・西の丸などの曲輪と、石垣の一部が残ります。廃城のとき石垣は崩されたといわれ、角の部分などに往時のようすが見られます。","築城の時期は、宇喜多氏の時代とする見方が多いものの、はっきりした年は分かっていません。","下津井は江戸時代、対岸の讃岐の丸亀への渡し船の港でもあり、金毘羅参りの人々が多く行き来しました。","城の近くの «むかし下津井回船問屋» では、北前船でにぎわった港町の暮らしを知ることができ、城跡とあわせて歩くと港の歴史がよくわかります。","瀬戸大橋の建設で、城跡の近くは景色が大きく変わりました。城跡の公園は、橋を横から見られる展望地としても人気です。"],"look":["本丸跡から見る瀬戸大橋と瀬戸内の島々","残っている石垣の角","港に向かって下る坂道と下津井の古い町並み","むかし下津井回船問屋（港町の資料館）"],"q":["下津井の港が昔にぎわったのは、船が何を待つためだった？","«風待ち・潮待ち» です。潮の流れが速い瀬戸内海で、船は潮の向きが変わるのを待ちました。"],"myth":"築城者・築城年や、廃城の正確な年には諸説がある。","img":["瀬戸大橋","一国一城令"],"wp":"下津井城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a1/Shimotsui_Castle_1.jpg",3008,2000,"下津井城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:2/28/JP-Kagawa-Great-Seto-Bridge-Minami_Bisan-Seto-Bridge.jpg",3332,2222,"瀬戸大橋"],["c:5/5e/MEIN%26SMALL_CASTLE_TOWER_%2CMATSUYAMA_CASTLE%28IYO%29.JPG",2816,2112,"一国一城令"]]},{"id":"33_niwase","n":"庭瀬城跡・撫川城跡（水に囲まれた陣屋）","yomi":"にわせじょうあと・なつかわじょうあと","cat":"城","rank":"B","y":1600,"era":["muromachi","azuchi","edo"],"sh":"","ad":"岡山市北区庭瀬・撫川","st":"JR山陽本線・庭瀬駅から歩いて約15分","la":34.644,"lo":133.85,"hook":"お堀の水に四方を囲まれた小さな島。そこが、戦国の城と江戸の陣屋の跡だ。","lead":"岡山市の西、庭瀬には、となり合う二つの城の跡があります。戦国時代の撫川城と、江戸時代に庭瀬藩の陣屋が置かれた庭瀬城です。どちらもまわりを水の堀に囲まれ、今もその水辺の景色が残っています。","story":["庭瀬のあたりは、昔は海に近い低い湿地でした。川や水路がたくさん流れ、土地は水びたし。«そんな場所に、なぜ城を造ったの?» じつは、水そのものが守りになったのです。まわりが沼や堀なら、敵は簡単には近づけません。庭瀬と撫川の城は、そうした «水の城» でした。","撫川城は、戦国時代に備中で力をもった三村家親が築いたと伝わります。のちに備中と備前の境目になると、宇喜多氏や毛利氏がこのあたりの城をめぐって争いました。豊臣秀吉の備中高松城攻めのころ、宇喜多方が守った «境目七城» の一つに数えられる城もこの一帯にあったといわれます。","関ヶ原の戦いのあと、この地に来たのが戸川達安です。もとは宇喜多家の重臣でしたが、家中の争いで宇喜多家を離れ、徳川方について戦いました。その功で庭瀬に領地をもらい、陣屋を構えます。戸川家のあとは何家かが入れかわり、江戸時代の中ごろからは板倉氏が明治まで庭瀬藩を治めました。","一方の撫川城跡には、戸川家の一族が陣屋を置いた時期もありました。こうして «城» といっても、江戸時代には天守のある城ではなく、藩の役所と屋敷をかねた «陣屋» として使われたのです。","今、撫川城跡には石垣とお堀が残り、庭瀬城跡には神社がまつられています。水面に木々が映る静かな景色の中で、戦国の争いと江戸の暮らしの両方を思い浮かべてみてください。"],"tl":[["1559年ごろ","三村家親が撫川城を築いたと伝わる"],["1582年","羽柴秀吉が備中高松城を水攻め。周辺の城が境目の守りとなる"],["1600年","関ヶ原の戦い。戸川達安が徳川方で戦う"],["1600年以降","戸川達安が庭瀬に領地を得て陣屋を置く"],["1699年","板倉氏が庭瀬藩主となり、明治まで続く"],["1871年","廃藩置県で庭瀬藩がなくなる"]],"who":[["三村家親","戦国時代の備中の武将。撫川城を築いたと伝わる"],["戸川達安","元宇喜多家の重臣。関ヶ原後に庭瀬の領主となった"],["板倉氏","江戸時代中ごろから明治まで庭瀬藩を治めた大名家"],["宇喜多秀家","戸川達安のかつての主君。家中の対立で戸川らが離れた"]],"deep":["戸川達安らが宇喜多家を離れたのは «宇喜多騒動» と呼ばれる家中の対立がきっかけです。原因については宗教や政治の対立など諸説あります。","庭瀬藩の石高はおよそ2万石で、陣屋を中心に小さな城下町がつくられました。","撫川城跡には、野面積みの石垣と四方を囲む堀が比較的よく残り、戦国の «平城» の姿を想像しやすい場所です。","庭瀬城跡と撫川城跡は、堀をへだてて隣り合っています。二つを一つの城の別の曲輪とみる考え方もあります。","このあたりの水路は、城の守りだけでなく、米や荷物を運ぶ舟の道にもなっていました。庭瀬には港の役目をした «庭瀬港» の跡も伝わります。","備中高松城の水攻めがあった場所は、ここから北西へ数kmほど。低い湿地の地形が、この地域の戦いの形を決めたともいえます。"],"look":["撫川城跡の石垣とお堀","庭瀬城跡にまつられた神社と水辺","城跡のまわりの水路と古い町並み","近くの «庭瀬往来» の旧道"],"q":["庭瀬城・撫川城のまわりの守りに使われたものは何？","水です。湿地や堀の水が、敵を近づけない守りになりました。"],"myth":"撫川城の築城者・築城年、境目七城との関係には諸説がある。","img":["撫川城","庭瀬藩","戸川達安"],"wp":"庭瀬城","rel":{"ev":[],"grave":[]},"ph":[["c:3/3b/Niwasejo_01.JPG",4000,3000,"庭瀬城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/9d/%E5%BA%AD%E7%80%AC%E5%9F%8E_02.JPG",1536,2048],["c:7/7b/Natsukawajo_04.JPG",4000,3000,"撫川城"],["c:8/8e/Niwasejo_03.JPG",4000,3000,"庭瀬藩"],["c:b/b3/Togawa_Michiyasu.jpg",768,768,"戸川達安"]]},{"id":"33_katsuyama","n":"勝山の町並み（勝山藩の城下）","yomi":"かつやまのまちなみ","cat":"町","rank":"B","y":1764,"era":["edo"],"sh":"","ad":"真庭市勝山","st":"JR姫新線・中国勝山駅から歩いて約10分","la":35.088,"lo":133.693,"hook":"白壁と格子の町に、一軒ずつちがう «のれん» がゆれる。ここは江戸時代の小さな城下町だった。","lead":"真庭市の勝山は、江戸時代に勝山藩の城下町として栄えた町です。旭川の水運で荷物が集まり、商家が軒をつらねました。今は古い町並みが残され、家々の軒先にかかる草木染めの «のれん» で知られています。","story":["旭川に沿って細長くのびる町を歩くと、白いしっくいの壁、黒い瓦、こまかな格子窓の家が次々にあらわれます。勝山は、美作の西のはし。山あいの小さな町ですが、江戸時代には «高瀬舟» が行き来する川の港として、とてもにぎわいました。","この地には、もともと «高田城» という山城がありました。戦国時代には尼子・毛利・宇喜多などがこの城をめぐって争ったといわれます。江戸時代になり、美作は津山藩の森家が治めましたが、森家が断絶したあと、領地は細かく分けられていきました。","1764年、三河（愛知県）の西尾から三浦明次がこの地に移ってきます。三浦家は城を整え、地名を «勝山» とあらためました。«なぜ勝山という名前にしたの?» 縁起のよい «勝» の字を使い、新しい藩の出発を祝ったのだと考えられています。こうして勝山藩はおよそ2万3千石の小さな藩として、明治まで続きました。","城下には武家屋敷と町人の町がつくられ、川の港には米や鉄、木材などが集まりました。高瀬舟は旭川を下って岡山まで荷物を運び、帰りには塩や海産物を積んで戻ってきたといいます。酒蔵や問屋の立派な建物は、そのころの豊かさを今に伝えています。","昭和の終わりごろ、町の人たちは «町並みを守ろう» と動き出しました。1985年に岡山県の町並み保存地区に選ばれ、やがて家ごとに意匠のちがうのれんをかける取り組みが始まりました。昔の城下町の景色に、新しい工夫を重ねた町。それが今の勝山です。"],"tl":[["戦国時代","高田城をめぐり諸勢力が争ったといわれる"],["1603年","美作が森家の津山藩領となる"],["1697年","森家が改易され、美作の領地が分けられる"],["1764年","三浦明次が西尾から移り、勝山藩が成立"],["1871年","廃藩置県で勝山藩がなくなる"],["1985年","岡山県の町並み保存地区に指定される"],["平成時代","家々にのれんをかける町づくりが広がる"]],"who":[["三浦明次","三河西尾から移ってきた勝山藩の初代藩主"],["三浦家歴代藩主","明治まで勝山藩を治めた"],["高瀬舟の船頭たち","旭川で荷物を運び、町の繁栄を支えた人々"]],"deep":["勝山藩の三浦家は、鎌倉時代の有力御家人・三浦氏の流れをくむと称した家です。中世にこの地を治めた «美作三浦氏» とは別の家とされます。","旭川の高瀬舟は、勝山から岡山までを下り、帰りは綱で舟を引いて上ったといわれます。川港には舟をつなぐ «舟着き場» の雁木（がんぎ）が残ります。","高田城は標高300mほどの如意山にあった山城です。江戸時代の三浦氏の城は、その山麓の城郭を中心に整えられました。","勝山の町並み保存地区には、白壁・なまこ壁・格子窓の商家や酒蔵が並び、江戸から昭和にかけての建物が混ざっています。","のれんの多くは地元の染色作家が手がけた草木染めで、家業や家族にちなむ絵柄が描かれています。","勝山は出雲街道の宿場でもあり、参勤交代の大名行列や旅人も通りました。"],"look":["旭川沿いの白壁の町並みとのれん","高瀬舟の舟着き場の跡","酒蔵などの古い商家の建物","城跡の石垣（勝山の町の北側）"],"q":["勝山藩の三浦家は、どこから移ってきた？","三河（愛知県）の西尾からです。1764年に移ってきて、地名を勝山とあらためました。"],"myth":"勝山という地名の由来の解釈には諸説がある。","img":["真庭市","高瀬舟"],"wp":"勝山藩","rel":{"ev":[],"grave":[]},"ph":[["c:1/17/Hiruzen_02.jpg",4288,2837,"真庭市"],["c:0/07/Takase_River_%28Kyoto%29_-_DSC05937.JPG",4320,3240,"高瀬舟"],["c:2/24/%E4%B8%AD%E5%9B%BD%E5%8B%9D%E5%B1%B1%E9%A7%85_%E9%A7%85%E8%88%8E_2022.jpg",4032,3024,"近く: 中国勝山駅"],["c:a/ae/Kanba_Falls.JPG",680,1024,"近く: 勝山町 (岡山県)"],["c:6/63/Maniwa_police_station.jpg",1600,1200,"近く: 真庭警察署"],["c:f/f4/Gozensyu_shop01.jpg",4608,3072,"近く: 辻本店"],["c:8/8d/Maniwa_City_Katsuyama_Library_exterior_ac.jpg",6016,4000,"近く: 真庭市立勝山図書館"],["c:1/15/%E5%8B%9D%E5%B1%B1%E6%96%87%E5%8C%96%E5%BE%80%E6%9D%A5%E9%A4%A8%E3%81%B2%E3%81%97%E3%81%8A011.jpg",2048,1536,"近く: 勝山文化往来館ひしお"]]},{"id":"33_ashimori","n":"足守（木下家の陣屋町と近水園）","yomi":"あしもり","cat":"町","rank":"B","y":1615,"era":["edo"],"sh":"県指定名勝（近水園）","ad":"岡山市北区足守","st":"JR岡山駅から中鉄バスで足守方面へ約50分、「足守」下車すぐ","la":34.747,"lo":133.778,"hook":"豊臣秀吉の妻・ねねの実家、木下家が明治まで守り続けた小さな陣屋町。","lead":"岡山市北部の足守は、江戸時代に足守藩が置かれた町です。藩主の木下家は、豊臣秀吉の正室・ねね（北政所・高台院）の兄の家系でした。武家屋敷や商家の町並み、そして藩主の庭園 «近水園（おみずえん）» が残っています。","story":["足守川の流れに沿って、静かな町並みが続きます。ここが、戦国の天下人・豊臣秀吉とつながる町だと聞くと、驚く人も多いでしょう。足守藩の藩主・木下家は、秀吉の妻ねねの兄、木下家定を祖とする家なのです。","関ヶ原の戦いのあと、家定は備中の足守に領地を与えられました。ところが家定が亡くなったあと、跡継ぎをめぐって幕府の判断があり、領地はいったん取り上げられます。«豊臣の親せきだから、きびしくされたのかな?» と思うかもしれません。その後、家定の子・利房が大坂の陣で徳川方として働いたことで、1615年に足守の領主にもどることができました。","それからおよそ250年、木下家は2万5千石の小さな藩として足守を治め続けました。陣屋のまわりには家臣の屋敷が並び、町には商人や職人が暮らしました。武家屋敷の一つ «旧足守藩侍屋敷» は、今も中を見学することができます。","藩主の屋敷の庭として造られたのが近水園です。池の中に島を浮かべ、周りの山を景色に取り入れた «池泉回遊式» の庭で、池のほとりには «吟風閣» という建物が立っています。季節ごとに色を変える木々が水に映り、藩主はここで客をもてなしたといわれます。","この町からは、日本の近代医学の礎を築いた緒方洪庵も生まれました。小さな藩の小さな町が、大きな歴史とつながっている。足守を歩くと、そんな «意外なつながり» をいくつも見つけることができます。"],"tl":[["1600年","関ヶ原の戦い後、木下家定が足守に領地を得る"],["1608年","木下家定が亡くなる"],["1609年ごろ","相続をめぐり足守の領地がいったん没収される"],["1615年","木下利房が足守藩主となり、以後明治まで木下家が治める"],["江戸時代","藩主の庭園・近水園が整えられる"],["1810年","足守藩士の家に緒方洪庵が生まれる"],["1871年","廃藩置県で足守藩がなくなる"]],"who":[["木下家定","ねねの兄。足守木下家の祖"],["木下利房","家定の子。大坂の陣の功で足守藩主となった"],["木下勝俊（長嘯子）","家定の長男。のちに歌人として名を残した"],["ねね（高台院）","豊臣秀吉の正室。木下家定の妹"],["緒方洪庵","足守藩士の家に生まれた蘭方医"]],"deep":["木下家定は、ねねの実家・杉原家の出身で、のちに «木下» を名のりました。秀吉の一族として豊臣政権で大名になりました。","家定の長男・勝俊は関ヶ原の戦いで伏見城を守る役を離れたことから所領を失い、のちに «長嘯子» の名で和歌に打ちこみました。その歌は近世の和歌に大きな影響を与えたとされます。","近水園は岡山県の名勝に指定されています。池に浮かぶ «鶴島» と «亀島» の二つの島など、めでたい意匠が取り入れられています。","吟風閣は江戸時代に建てられた数寄屋風の建物で、池にせり出すように建っています。","足守は岡山県の町並み保存地区に指定され、醤油屋として栄えた商家 «藤田千年治邸» なども見学できます。","ねね（高台院）ゆかりの品は、足守の木下家を通じて伝わったものもあり、地元の資料館などで紹介されることがあります。"],"look":["近水園の池と吟風閣","旧足守藩侍屋敷","藤田千年治邸などの商家の町並み","緒方洪庵誕生地の碑"],"q":["足守藩の木下家は、豊臣秀吉の妻ねねとどんな関係？","ねねの兄・木下家定の子孫です。"],"koji":[],"myth":"領地没収の経緯や木下家と豊臣家の関係の細部には諸説がある。","img":["足守藩","木下家定","木下勝俊"],"wp":"近水園","rel":{"ev":[],"grave":[]},"ph":[["c:b/b7/Omizuen_01.jpg",2048,1536,"近水園"],["c:b/b1/211231_Ashimori_Jinya_Okayama_Okayama_pref_Japan03s3.jpg",6000,4000,"足守藩"],["c:9/97/Kinoshita_Iesada.jpg",2200,4200,"木下家定"],["c:d/dc/Kinosita_Choushushi.jpg",1400,1600,"木下勝俊"]]},{"id":"33_ogata","n":"緒方洪庵誕生地（足守）","yomi":"おがたこうあんたんじょうち","cat":"幕末","rank":"B","y":1810,"era":["edo"],"sh":"県指定史跡","ad":"岡山市北区足守","st":"JR岡山駅から中鉄バスで足守方面へ約50分、「足守」下車、歩いて約10分","la":34.75,"lo":133.776,"hook":"天然痘から子どもたちを守り、福沢諭吉ら多くの若者を育てた医師は、この小さな藩の武士の家に生まれた。","lead":"江戸時代の終わりに活やくした医師・緒方洪庵は、1810年、足守藩の武士の家に生まれました。大坂に «適塾» を開いて多くの人材を育て、天然痘の予防（種痘）を広めました。足守には、その誕生の地を示す碑と、生家の跡が残っています。","story":["1810年（文化7年）、足守藩士・佐伯惟因の家に一人の男の子が生まれました。のちの緒方洪庵です。体があまり丈夫でなかったといわれる少年は、«武士として剣をふるうより、人の命を救う道に進みたい» と考えるようになります。","やがて父について大坂に出た洪庵は、蘭学（オランダ語で学ぶ西洋の学問）と出会います。江戸や長崎でも学び、オランダ語の医学書を読みこみました。辞書も少ない時代、一つの単語の意味を知るのにも何日もかかったといいます。それでも洪庵は «西洋の医学で、多くの人を救える» と信じていました。","1838年、洪庵は大坂に «適塾» を開きます。全国から若者が集まり、夜おそくまでオランダ語の本を写し、読み合いました。その中には福沢諭吉や、のちに日本の陸軍をつくる大村益次郎などがいました。«なぜ洪庵のもとにこれほどの人材が集まったのか?» 身分にかかわらず、学ぶ意欲のある人を受け入れたことが大きかったと考えられています。","当時、天然痘はおそろしい病気で、多くの子どもが命を落としていました。洪庵は牛痘を使った種痘を広めるため、1849年に大坂に «除痘館» を開きます。«牛の病気をうつすなんて» と怖がる人も多い中、洪庵は無料で種をうえるなどして理解を広げていきました。","晩年、洪庵は幕府に呼ばれて江戸に移り、奥医師と西洋医学所の頭取をつとめましたが、1863年に急死しました。足守の誕生地に立つと、この小さな町から日本の医学の夜明けが始まったことに思いをはせることができます。"],"tl":[["1810年","足守藩士・佐伯惟因の三男として生まれる"],["1826年ごろ","大坂に出て、中天游のもとで蘭学を学ぶ"],["1838年","大坂に適塾（適々斎塾）を開く"],["1849年","大坂に除痘館を開き、種痘を広める"],["1862年","幕府に招かれ江戸へ。奥医師・西洋医学所頭取となる"],["1863年","江戸で亡くなる"]],"who":[["緒方洪庵","足守出身の蘭方医・教育者。適塾を開いた"],["佐伯惟因","洪庵の父。足守藩士"],["福沢諭吉","適塾で学んだ。のちに慶應義塾を開く"],["大村益次郎","適塾で学び、のちに塾頭もつとめた。近代陸軍の創始者"],["中天游","大坂で洪庵に蘭学を教えた師"]],"deep":["洪庵が訳した病理学書などは当時の医学に大きな影響を与えました。晩年のコレラ流行の際には、治療の手引書をいち早くまとめたことでも知られます。","洪庵の «扶氏医戒之略»（ドイツの医師フーフェランドの教えをまとめたもの）には、医師は自分のためでなく人のために生きるべきだ、という考えが記されています。","適塾の建物は大阪市中央区に現存し、国の史跡・重要文化財に指定されています。足守の誕生地とあわせて訪ねると、洪庵の一生をたどれます。","«緒方» の姓は、洪庵が大坂で学ぶ中で名のるようになったもので、生家は佐伯家です。","除痘館の活動は、のちに «大阪大学医学部» の源流の一つとされています。","足守の誕生地には碑が建てられ、近くには洪庵の像もあります。足守の町並み散策とあわせて訪れる人が多い場所です。"],"look":["緒方洪庵誕生地の碑","近くに建つ洪庵の像","足守の町並みと近水園","旧足守藩侍屋敷（当時の藩士の家の雰囲気がわかる）"],"q":["緒方洪庵が大坂に開いた塾の名前は？","«適塾» です。福沢諭吉や大村益次郎などが学びました。"],"koji":[{"w":"人のために生活して、おのれのために生活せざるを医業の本体とす","m":"«扶氏医戒之略» の中の考え。医師は自分のためでなく人のために生きることが本分だ、という意味"}],"myth":"幼いころ体が弱かったため医師を志したという話は、伝記などで語られる逸話。","img":["適塾","除痘館","足守藩"],"wp":"緒方洪庵","rel":{"ev":[],"grave":[]},"ph":[["c:8/86/Koan_Ogata_1901.jpg",700,971,"緒方洪庵"],["c:3/33/Tekijuku_01.JPG",2592,1944],["c:c/c7/Traces_of_the_smallpox_building.jpg",1200,900],["c:c/c8/Sagalibdb_06000028_shut%C5%8D-no-zu.jpg",9484,7913,"除痘館"],["c:b/b1/211231_Ashimori_Jinya_Okayama_Okayama_pref_Japan03s3.jpg",6000,4000,"足守藩"]]},{"id":"33_mitsukuri","n":"箕作阮甫旧宅","yomi":"みつくりげんぽきゅうたく","cat":"幕末","rank":"B","y":1799,"era":["edo"],"sh":"国指定史跡","ad":"津山市西新町","st":"JR津山駅から歩いて約20分","la":35.066,"lo":133.996,"hook":"ペリーが持ってきたアメリカ大統領の手紙。それを翻訳した学者は、津山の町医者の家で育った。","lead":"箕作阮甫（みつくりげんぽ）は、江戸時代の終わりに活やくした津山藩の医師・洋学者です。ペリー来航のときにアメリカの国書を翻訳し、幕府の洋学の学校で教えました。津山の城下町には、少年時代をすごした家が残り、国の史跡として公開されています。","story":["津山城の西、出雲街道沿いの町並みの一角に、古い町家が建っています。ここが箕作阮甫の旧宅です。阮甫は1799年（寛政11年）、津山藩の医師の家に生まれました。この家は、阮甫が少年時代をすごした場所と伝えられています。","阮甫は若くして家をつぎ、京都で医学を学びました。やがて江戸に出て、蘭学者のもとでオランダ語を学びます。«なぜ医者がオランダ語を?» 当時、西洋の新しい医学や科学を知るには、オランダ語の本を読むしかなかったのです。阮甫は医学だけでなく、地理・歴史・兵学など、はば広い本を翻訳しました。","1853年、ペリーの黒船が浦賀にあらわれます。アメリカ大統領の国書が幕府に渡されましたが、それを日本語に訳す仕事を担当した一人が阮甫でした。翌年にはロシアのプチャーチンとの交渉のため、長崎へも向かっています。日本の運命を左右する外交の場で、阮甫の語学の力が必要とされたのです。","1856年、幕府は洋学の研究と教育のための «蕃書調所» をつくり、阮甫はその首席教授に選ばれました。この学校はのちに東京大学のもとの一つになります。阮甫の家からは、孫の箕作麟祥（民法づくりに関わった法学者）など、多くの学者が生まれました。","旧宅は、江戸時代の津山の町家のつくりをよく伝えています。表の店の間から奥へと続く部屋、中庭、土蔵。少年阮甫がここで本を読みふけっていた姿を想像しながら歩いてみてください。"],"tl":[["1799年","津山藩医の家に生まれる"],["1820年代","京都や江戸で医学・蘭学を学ぶ"],["1839年","幕府の天文方で翻訳の仕事につく"],["1853年","ペリー来航。アメリカ国書の翻訳にあたる"],["1854年","ロシア使節プチャーチンとの交渉に関わる"],["1856年","蕃書調所の首席教授となる"],["1863年","江戸で亡くなる"],["1975年","旧宅が国の史跡に指定される"]],"who":[["箕作阮甫","津山藩医・洋学者。旧宅の主"],["箕作麟祥","阮甫の孫。法学者としてフランス法の翻訳や民法づくりに関わった"],["ペリー","アメリカ東インド艦隊司令長官。阮甫が国書を翻訳した"],["プチャーチン","ロシアの使節。長崎で交渉した"],["宇田川榕菴","同じ津山藩の洋学者。化学の用語をつくった"]],"deep":["津山藩は宇田川玄随・玄真・榕菴、箕作阮甫など多くの洋学者を出したことで知られます。近くの «津山洋学資料館» でその歩みを学べます。","旧宅は江戸時代の津山の町家とされ、修理・整備されて公開されています。国の史跡指定は1975年です。","阮甫が翻訳・編集した本は100点を超えるといわれ、医学・地理・歴史・兵学など分野がとても広いのが特徴です。","蕃書調所は、のちに洋書調所・開成所と名前を変え、明治になって東京大学の前身の一つとなりました。","阮甫の子孫・門人には多くの学者がいて、«箕作一族» は近代日本の学問に大きく関わりました。","阮甫は幕府の天文方で «蕃書和解御用» という外国の本を訳す役にもつき、幕府の翻訳の中心人物の一人になりました。"],"look":["表通りに面した町家の外観と格子","店の間から奥へ続く部屋の並び","中庭と土蔵","近くの津山洋学資料館（あわせて見学するとわかりやすい）"],"q":["箕作阮甫が首席教授になった、幕府の洋学の学校の名前は？","«蕃書調所» です。のちに東京大学のもとの一つになりました。"],"myth":"旧宅が阮甫の生まれた家かどうかについては、少年時代をすごした家と説明されることが多い。","img":["箕作阮甫","蕃書調所","津山洋学資料館"],"wp":"箕作阮甫旧宅","rel":{"ev":[],"grave":[]},"ph":[["c:9/92/%E7%AE%95%E4%BD%9C%E9%98%AE%E7%94%AB%E6%97%A7%E5%AE%85.jpg",3840,2160,"箕作阮甫旧宅"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:f/f8/%E7%AE%95%E4%BD%9C%E9%98%AE%E7%94%AB%E6%97%A7%E5%AE%85%E6%AF%8D%E5%B1%8B%EF%BC%88%E8%A7%A3%E4%BD%93%E5%89%8D%EF%BC%89.jpg",1891,1260],["c:4/4a/%E7%AE%95%E4%BD%9C%E9%98%AE%E7%94%AB%E6%97%A7%E5%AE%85%E9%9B%A2%E3%82%8C%EF%BC%88%E8%A7%A3%E4%BD%93%E5%89%8D%EF%BC%89.jpg",1735,1164],["c:e/e3/%E7%AE%95%E4%BD%9C%E9%98%AE%E7%94%AB%E6%97%A7%E5%AE%85%E5%A4%96%E8%A6%B3%EF%BC%88%E8%A7%A3%E4%BD%93%E5%89%8D%EF%BC%89.jpg",1672,1114],["c:5/58/Mitsukuri_Genpo.jpg",572,841,"箕作阮甫"],["c:e/ed/Bansyoshirabesyo.jpg",480,640,"蕃書調所"],["c:1/18/TSUYAMA_ARCHIVES_OF_WESTERN_LEARNING02n4140.jpg",4140,2760,"津山洋学資料館"]]},{"id":"33_asao","n":"倉敷浅尾騒動の地（第二奇兵隊の襲撃）","yomi":"くらしきあさおそうどうのち","cat":"幕末","rank":"B","y":1866,"era":["edo"],"sh":"","ad":"倉敷市本町（倉敷代官所跡・現在の倉敷アイビースクエア）","st":"JR倉敷駅から歩いて約15分","la":34.5942,"lo":133.7738,"hook":"美観地区の赤レンガの場所で、幕末のある朝、長州の脱走兵が幕府の代官所に火を放った。","lead":"1866年（慶応2年）、長州藩の «第二奇兵隊» をぬけ出した兵たちが、倉敷の幕府代官所と、近くの浅尾藩の陣屋を襲いました。これを «倉敷浅尾騒動» といいます。代官所の跡は、いま倉敷アイビースクエアになっています。","story":["江戸時代の倉敷は、幕府が直接治める «天領» でした。町のまん中には、幕府の役人・代官が仕事をする «倉敷代官所» がありました。今の倉敷アイビースクエアは、その跡地に明治になって建てられた紡績工場を生かした施設です。","1866年の春、長州藩は幕府との戦いに備えて、身分をこえた兵の部隊をいくつもつくっていました。その一つが «第二奇兵隊» です。ところが、この隊から一部の兵がぬけ出し、瀬戸内海をわたって備中へやってきます。率いていたのは立石孫一郎という人物でした。","4月のある日、一団は倉敷代官所を襲って火を放ちました。代官は留守だったといわれます。さらに一団は、近くの浅尾藩（今の総社市）の陣屋も襲いました。浅尾藩は幕府の京都警備で知られた蒔田氏の小さな藩です。«なぜ倉敷と浅尾がねらわれたのか?» 幕府の力の象徴である代官所と、幕府に近い藩をたたき、倒幕の動きを広げようとしたと考えられています。","しかし、この行動は長州藩の正式な命令ではありませんでした。幕府と戦う準備を進めていた長州藩にとっても、勝手な行動は困るものでした。一団はその後、各地で追われて散りぢりになり、立石は長州にもどったあと命を落としました。この騒動では、襲った側にも襲われた側にも犠牲者が出ました。","今、アイビースクエアのつたのからまる赤レンガを見ていると、ここで火の手が上がったことは想像しにくいかもしれません。しかしこの小さな事件は、幕府の支配がゆらぎ、世の中が大きく動き始めていたことを示しています。"],"tl":[["江戸時代","倉敷が幕府の天領となり、代官所が置かれる"],["1866年4月","第二奇兵隊をぬけた一団が倉敷代官所を襲撃"],["1866年4月","続いて浅尾藩の陣屋を襲撃"],["1866年","一団は各地で追われ、散りぢりになる"],["1866年6月","第二次長州征討（四境戦争）が始まる"],["1889年","代官所跡に倉敷紡績の工場がつくられる"],["1974年","工場を生かした倉敷アイビースクエアが開業"]],"who":[["立石孫一郎","第二奇兵隊をぬけ出した一団を率いた人物"],["蒔田氏","浅尾藩の藩主家。陣屋を襲われた"],["第二奇兵隊","長州藩の諸隊の一つ。騒動を起こしたのはそこを脱走した兵"],["倉敷の町人たち","騒動に巻きこまれ、町の人々も不安な日々をすごした"]],"deep":["騒動の名は、襲われた二か所 «倉敷» と «浅尾» から。浅尾藩の陣屋跡は総社市にあり、こちらにも案内板があります。","立石孫一郎は倉敷と縁のある人物だったといわれ、そのことが倉敷をねらった理由の一つと見る説もあります。出自や経歴には不明な点があります。","長州藩はこの行動を正式なものと認めず、一団の処置を行いました。藩が幕府との戦いを前に、勝手な行動をきびしく取りしまったことがわかります。","この騒動のあと、備中の天領や小藩では警備が強められ、農兵の組織などが進みました。","倉敷代官所の跡地は明治に倉敷紡績の工場となり、そのレンガ建築が倉敷アイビースクエアとして使われています。","騒動の経過については地元の記録や長州側の記録で細部が異なり、犠牲者の数などには諸説があります。"],"look":["倉敷アイビースクエア（代官所跡）と案内の碑","赤レンガの建物とつた","美観地区の倉敷川沿いの町並み","総社市の浅尾陣屋跡（足をのばすなら）"],"q":["倉敷代官所の跡地は、今どんな施設になっている？","倉敷アイビースクエアです。明治に建てられた紡績工場の建物を生かしています。"],"myth":"立石孫一郎の出自、襲撃の目的、犠牲者の数などには諸説がある。","img":["倉敷アイビースクエア","奇兵隊","浅尾藩"],"wp":"倉敷浅尾騒動","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/5d/Kurashiki_Ivy_Square23s.jpg",4592,3056,"倉敷アイビースクエア"],["c:3/3a/Kurashiki_Ohara_Art_Museum02nt3200.jpg",2130,3200,"近く: 大原美術館"],["c:3/32/%E8%B3%87%E6%BA%90%E6%A4%8D%E7%89%A9%E7%A7%91%E5%AD%A6%E7%A0%94%E7%A9%B6%E6%89%80.jpg",2707,1857,"近く: 岡山大学資源植物科学研究所"],["c:4/49/Kurashiki_city_auditorium_2.JPG",1280,960,"近く: 倉敷市民会館"],["c:4/47/Kurashiki_Ohashi_House01n4592.jpg",4592,3056,"近く: 大橋家住宅"],["c:a/a9/Kurashiki_Observatory.jpg",4096,3072,"近く: 倉敷天文台"]]},{"id":"33_ohara_house","n":"旧大原家住宅（倉敷の大地主）","yomi":"きゅうおおはらけじゅうたく","cat":"町","rank":"B","y":1795,"era":["edo","meiji","taisho"],"sh":"国の重要文化財","ad":"倉敷市中央1丁目","st":"JR倉敷駅から歩いて約15分（倉敷美観地区内）","la":34.5957,"lo":133.7714,"hook":"倉敷の町と大原美術館をつくった一族は、この倉敷格子の屋敷で暮らしていた。","lead":"旧大原家住宅は、倉敷の大地主・大原家の屋敷です。江戸時代の終わりごろに建てられ、倉敷川沿いの美観地区の中心にあります。国の重要文化財で、いまは «語らい座 大原本邸» として中を見学できます。","story":["倉敷川のほとり、柳の並木の向こうに、黒い瓦と白い壁、こまかな «倉敷格子» の大きな屋敷が見えます。これが大原家の本邸です。江戸時代の倉敷は、年貢米や綿の取り引きでにぎわう天領の町で、大原家はその中で力をもった商人・地主でした。","屋敷の主屋は江戸時代の終わりごろ、1795年ごろに建てられたといわれます。表はつつましく、奥へ行くほど広い。これは当時の町家の特徴で、倉や離れがいくつも連なっています。«なぜ外からは地味なの?» 江戸時代には、ぜいたくをいましめる決まりがあり、商人はお金持ちでも表を目立たせないようにしていたのです。","明治になると、大原孝四郎らが中心となって «倉敷紡績» を立ち上げます。代官所の跡地に紡績工場ができ、倉敷は近代産業の町へと変わりました。孝四郎の子・大原孫三郎は、会社を大きくするだけでなく、働く人の暮らしや町の未来にも力を注ぎました。","孫三郎は、病院や研究所をつくり、画家・児島虎次郎を応援してヨーロッパの名画を集めさせました。1930年、その作品をもとに日本で最初の本格的な西洋美術館の一つ «大原美術館» が開かれます。すべては、この屋敷で育った一族の «町を豊かにしたい» という思いから始まったといえるでしょう。","2018年、屋敷は «語らい座 大原本邸» として公開されました。部屋や蔵には、大原家の歩みや言葉が展示されています。倉敷の町並みがなぜ守られてきたのか、その答えの一つがここにあります。"],"tl":[["1795年ごろ","主屋が建てられたといわれる"],["江戸時代後期","大原家が倉敷の有力な商人・地主として力をつける"],["1888年","倉敷紡績が設立される"],["1930年","大原孫三郎が大原美術館を開く"],["1971年","旧大原家住宅が国の重要文化財に指定される"],["2018年","«語らい座 大原本邸» として公開が始まる"]],"who":[["大原孝四郎","倉敷紡績の設立に関わった大原家の当主"],["大原孫三郎","孝四郎の子。倉敷紡績を発展させ、大原美術館などをつくった"],["児島虎次郎","孫三郎が支援した画家。美術館の名画を集めた"],["大原總一郎","孫三郎の子。倉敷の町並み保存にも力を注いだ"]],"deep":["«倉敷格子» は、太い親格子の間に細い子格子を入れた倉敷独特の格子で、旧大原家住宅はその代表例です。","屋敷の向かいには、大原家の別邸 «有隣荘» があります。緑色の瓦から «緑御殿» とも呼ばれ、特別公開のときだけ中を見られます。","大原孫三郎は «倉敷中央病院» や «大原社会問題研究所»«大原農業研究所» などをつくり、社会事業家としても知られます。","大原總一郎は戦後、美観地区の町並みを守る運動を支えました。倉敷の保存運動は全国でも早いものでした。","倉敷美観地区は1979年に国の重要伝統的建造物群保存地区に選ばれています。","大原美術館には、エル・グレコ «受胎告知» など、児島虎次郎が選んだ作品が所蔵されています。"],"look":["倉敷格子と «倉敷窓» のある表構え","奥へ連なる蔵と中庭","語らい座 大原本邸の展示","向かいの有隣荘（外観）と大原美術館"],"q":["大原孫三郎が1930年に開いた美術館の名前は？","大原美術館です。画家・児島虎次郎が集めた西洋の名画をもとに開かれました。"],"myth":"主屋の建築年は «1795年ごろ» とされ、正確な年には幅がある。","img":["大原孫三郎","大原美術館","倉敷美観地区"],"wp":"旧大原家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/211203_Old_Ohara_House_Kurashiki_Okayama_pref_Japan01s3.jpg",4912,3264,"旧大原家住宅"],["c:8/8b/Magosaburo_Ohara.jpg",1000,1500,"大原孫三郎"],["c:3/3a/Kurashiki_Ohara_Art_Museum02nt3200.jpg",2130,3200,"大原美術館"],["c:c/cb/Kurasiki_morning01.JPG",4608,3072,"倉敷美観地区"]]},{"id":"33_rokko","n":"旧制第六高等学校の跡","yomi":"きゅうせいだいろくこうとうがっこうのあと","cat":"学び","rank":"B","y":1900,"era":["meiji","taisho","showa"],"sh":"","ad":"岡山市北区古京町（現在の岡山県立岡山朝日高等学校）","st":"JR岡山駅から岡電バスで約15分、または路面電車「城下」から歩いて約15分","la":34.666,"lo":133.935,"hook":"マントに高下駄、寮歌を歌う若者たち。岡山の «六高» は、明治から昭和の青春の舞台だった。","lead":"第六高等学校（六高）は、1900年に岡山にできた旧制高等学校です。全国から集まった若者が、大学に進む前の3年間をここで学びました。1950年に廃止され、跡地は岡山朝日高校になっています。","story":["明治の日本では、大学に進む人は、その前に «高等学校» で学ぶ決まりでした。第一から第八まで番号のついた «ナンバースクール» は、その中でも特別な学校。1900年、6番目の学校が岡山に置かれました。これが «六高» です。","六高生たちは、白線の入った帽子にマントをはおり、下駄を鳴らして町を歩きました。寮では夜おそくまで語り合い、ボートやスポーツにも熱中しました。«なぜそんなに自由だったの?» 旧制高校は、勉強だけでなく、仲間と議論して人間をみがく場所だと考えられていたのです。","六高からは、多くの人が巣立ちました。小説家・随筆家の内田百閒、物理学者の仁科芳雄など、さまざまな分野で活やくする人々がこの学び舎で青春をすごしています。後楽園や旭川の河原は、六高生の散歩道でした。","1945年の岡山空襲では、校舎の多くが焼けてしまいました。戦後の学制改革で旧制高校は廃止されることになり、六高は岡山大学にまとめられて1950年に幕を下ろします。跡地には県立岡山朝日高校が移ってきました。","今、朝日高校の敷地には «六高記念館» があり、六高の歴史を伝える資料が展示されています。校門の近くに立つと、マントをひるがえした若者たちの声が聞こえてきそうです。"],"tl":[["1900年","第六高等学校が岡山に設立される"],["明治〜大正","全国から学生が集まり、寮生活やスポーツが盛んになる"],["1945年","岡山空襲で校舎の多くが焼失"],["1949年","学制改革で新制の岡山大学に包括される"],["1950年","第六高等学校が廃止される"],["その後","跡地に岡山県立岡山朝日高等学校が移る"]],"who":[["内田百閒","岡山出身の文学者。六高で学んだ"],["仁科芳雄","岡山出身の物理学者。六高で学び、のちに日本の原子物理学の基礎を築いた"],["六高生たち","寮歌やボートなど独特の文化を育てた"]],"deep":["旧制高等学校は、今の大学の教養課程にあたる3年制の学校で、卒業生の多くが帝国大学に進みました。","«ナンバースクール» は第一（東京）から第八（名古屋）まであり、六高は中国地方で唯一のナンバースクールでした。","六高記念館は岡山朝日高校の敷地内にあり、公開日や見学方法は事前に確認が必要です。","六高の寮歌は今も同窓生の集まりで歌われることがあり、旧制高校文化の名残を伝えています。","岡山空襲は1945年6月29日。六高だけでなく岡山城天守なども焼け、多くの市民が犠牲になりました。","岡山朝日高校の前身は、明治に創立された岡山県尋常中学校にさかのぼります。六高の跡地に移ったのは戦後のことです。","六高の学生は、岡山の町の人々から親しみをこめて «六高さん» と呼ばれたといわれます。学生が町の文化や祭りに加わることもあり、学校と町のつながりは深いものでした。"],"look":["岡山朝日高校の校門付近と案内","六高記念館（公開日を確認）","近くの岡山城と後楽園（六高生の散歩道）","旭川の河原の景色"],"q":["旧制高校のうち、番号がついた8校を何と呼ぶ？","«ナンバースクール» です。六高はその6番目で、岡山にありました。"],"myth":"","img":["岡山県立岡山朝日高等学校","旧制高等学校","内田百閒"],"wp":"第六高等学校 (旧制)","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/T15-okayama-si-syasintyo013.jpg",640,483,"第六高等学校 (旧制)"],["c:8/83/Okayama_asahi02.JPG",1280,960],["c:2/25/Okayama_asahi01.JPG",1280,960,"岡山県立岡山朝日高等学校"],["c:5/5d/University_of_Tokyo_-_Komaba_Campus_-_Building_1.JPG",3072,2304,"旧制高等学校"],["c:2/2f/Uchida_Hyakken.jpg",1452,2460,"内田百閒"]]},{"id":"33_tsuyama_rail","n":"旧津山扇形機関車庫","yomi":"きゅうつやまおうぎがたきかんしゃこ","cat":"近代","rank":"B","y":1936,"era":["showa"],"sh":"","ad":"津山市大谷（津山まなびの鉄道館）","st":"JR津山駅から歩いて約10分","la":35.059,"lo":134.01,"hook":"まん中の転車台がくるりと回ると、扇の形に並んだ車庫へ機関車が吸いこまれていく。","lead":"津山駅の近くに、扇を広げたような形の大きな機関車の車庫が残っています。1936年（昭和11年）に建てられた «旧津山扇形機関車庫» です。今は «津山まなびの鉄道館» として、蒸気機関車やディーゼル機関車が並べられています。","story":["蒸気機関車は、前にしか進むのが得意ではありません。終点に着いたら、向きを変えなければなりません。そこで使われたのが «転車台»。線路ごと機関車をのせてくるりと回す、大きな回転台です。その転車台のまわりに、扇の骨のように線路をのばし、車庫を並べたのが扇形機関車庫です。","津山は、姫新線・因美線・津山線が集まる中国山地の鉄道の町でした。«なぜ山の中の町に大きな車庫が必要だったの?» 山を越える列車には力の強い機関車がたくさん必要で、その手入れや出発の準備をする基地が欠かせなかったのです。1936年、津山に17本の線路をもつ扇形庫が建てられました。","機関車庫では、夜明け前から多くの人が働いていました。石炭をくべて火をおこし、車輪や部品を点検し、油をさします。すすで顔をまっ黒にしながら、«今日も安全に走らせる» と機関車を送り出しました。","やがて蒸気機関車はディーゼル機関車に替わり、全国の扇形庫は次々に姿を消しました。けれど津山の車庫は大切に残され、2009年には経済産業省の «近代化産業遺産» に選ばれます。そして2016年、鉄道の歴史を学べる «津山まなびの鉄道館» に生まれ変わりました。","今、扇形庫には «D51» の蒸気機関車や、めずらしいディーゼル機関車などが並んでいます。転車台が回るようすを見られる日もあります。昭和の鉄道の町の音や匂いを、想像してみてください。"],"tl":[["1898年","津山に鉄道（のちの津山線）が通じる"],["1936年","扇形機関車庫が建てられる"],["昭和中ごろ","蒸気機関車からディーゼル機関車への切り替えが進む"],["2009年","近代化産業遺産に選ばれる"],["2016年","«津山まなびの鉄道館» として開館"]],"who":[["機関士・機関助士","機関車を運転し、石炭をくべて走らせた人々"],["整備を担った職員","車庫で機関車の点検・修理を行った人々"],["津山の人々","鉄道の町として駅や車庫とともに暮らした"]],"deep":["津山の扇形庫は17線あり、京都の梅小路（現在の京都鉄道博物館）に次いで国内で2番目に大きい現存の扇形庫といわれます。","扇形庫の建物は鉄筋コンクリート造で、戦前の鉄道施設の姿をよく残しています。","転車台は大型の蒸気機関車も一度にのせて回せる大きさで、今も動かせる状態で保存されています。","展示車両には、D51形蒸気機関車の «D51 2»（初期の «なめくじ» 形）や、国内で数台しかつくられなかったディーゼル機関車などがあります。","津山は、姫新線・因美線・津山線が集まる «鉄道の十字路»。かつては急行や貨物列車も多く走りました。","館内には、鉄道の歴史や仕組みを学べる展示のほか、昭和の津山駅のようすを再現したジオラマもあります。"],"look":["扇形に並ぶ車庫と展示車両","転車台（回転する日を確認）","D51 2などの蒸気機関車","館内のジオラマと鉄道の歴史展示"],"q":["扇形機関車庫のまん中にある、機関車の向きを変える装置を何という？","«転車台» です。線路ごと機関車をのせて回し、向きを変えます。"],"myth":"","img":["扇形庫","転車台","国鉄D51形蒸気機関車"],"wp":"津山まなびの鉄道館","rel":{"ev":[],"grave":[]},"ph":[["c:b/b7/Tsuyama_Railroad_Educational_Museum%2C_entrance.jpg",6016,4000,"津山まなびの鉄道館"],["c:9/9e/D51_2_in_Tsuyama_Railroad_Educational_Museum.jpg",6016,4000],["c:e/e4/DF50_tsuyama.JPG",3840,2160],["c:f/f6/Tsuyama_Turnplate.JPG",2048,1536],["c:d/d1/Tsuyama_Railroad_Educational_Museum_garage_20160410.jpg",4056,1048],["c:8/84/Tsuyama_Depot_19980920.jpg",754,491],["c:c/c2/Umekoji_SL_museum_002_JPN.jpg",3456,2304,"扇形庫"],["c:1/11/Turntable_car_parking.jpg",1024,768,"転車台"]]},{"id":"33_uko","n":"宇野港（宇高連絡船の港）","yomi":"うのこう","cat":"近代","rank":"B","y":1910,"era":["meiji","showa"],"sh":"","ad":"玉野市築港","st":"JR宇野線・宇野駅から歩いてすぐ","la":34.491,"lo":133.952,"hook":"瀬戸大橋ができる前、本州と四国をつなぐ «海の線路» はこの港から出ていた。","lead":"玉野市の宇野港は、1910年に開かれた港です。四国の高松との間に国の鉄道の «宇高連絡船» が結ばれ、およそ78年のあいだ、本州と四国を行き来する人と荷物を運びました。1988年に瀬戸大橋ができて連絡船は廃止されましたが、港は今も島々への玄関口です。","story":["明治の終わり、岡山から南へ線路がのび、海辺の宇野に駅と港がつくられました。1910年、宇野線の開通と同じ年に、高松との間に連絡船が就航します。«列車を降りたら、すぐ船に乗れる»。本州と四国を一つにつなぐ、まさに «海の線路» の誕生でした。","連絡船は、昼も夜も瀬戸内海を行き来しました。大正時代からは、貨車をそのまま船にのせて運ぶこともできるようになります。船の中で食べる «さぬきうどん» は名物で、ほんの短い時間に急いですすったという思い出を語る人もたくさんいます。","しかし、悲しい出来事もありました。1955年5月、霧の中で連絡船 «紫雲丸» がほかの連絡船とぶつかって沈み、修学旅行中の子どもたちをふくむ多くの人が亡くなりました。«どうすれば、安全に海をわたれるのか?» この事故は、本州と四国を橋で結ぼうという声を大きくするきっかけの一つになりました。","1988年4月、瀬戸大橋が開通すると、宇高連絡船は役目を終えました。最後の船が出た日、港には別れを惜しむ多くの人が集まったといいます。長いあいだ本州と四国をつないだ港は、静かになりました。","けれど宇野港は、今も直島や豊島など、瀬戸内の島々へ向かうフェリーの港としてにぎわっています。アートの祭り «瀬戸内国際芸術祭» のときには、世界中から人が集まります。海の玄関口としての役目は、形を変えて続いているのです。"],"tl":[["1910年","宇野線開通。宇野港が開かれ、宇高連絡船が就航"],["大正時代","貨車をのせて運ぶ «車両航送» が始まる"],["1955年","紫雲丸が衝突・沈没し、多くの人が亡くなる"],["1978年","瀬戸大橋の工事が始まる"],["1988年","瀬戸大橋開通。宇高連絡船が廃止される"],["2010年","第1回瀬戸内国際芸術祭。宇野港が会場の一つに"]],"who":[["連絡船の乗組員","本州と四国の間で船を運航した人々"],["紫雲丸事故の犠牲者","1955年の事故で亡くなった乗客・乗員。修学旅行の児童・生徒も多かった"],["宇野の町の人々","港とともに暮らし、連絡船を見送った"]],"deep":["宇高連絡船の «宇高» は、宇野と高松の頭文字です。所要時間はおよそ1時間ほどでした。","連絡船は国鉄（のちJR四国）の航路で、鉄道の切符で列車と船を乗りつぐことができました。","紫雲丸事故は1955年5月11日に起きました。紫雲丸はそれ以前にも事故を起こしており、«紫雲丸» の名は変えられた後も語りつがれています。","貨車を船に積む «車両渡船» は、四国の物流を支えました。港には貨車を船に送りこむ設備がありました。","宇高航路にはJRの連絡船のほか民間のフェリーも走っていましたが、利用が減ってやがて姿を消しました。","宇野港の近くには、連絡船時代をしのぶ記念碑や、瀬戸内国際芸術祭の作品が置かれています。"],"look":["宇野港の岸壁と島々への船","連絡船をしのぶ記念碑や案内","港に置かれた芸術祭のアート作品","JR宇野駅（終着駅）の駅舎"],"q":["«宇高連絡船» の «宇高» は、どこの地名？","宇野（岡山県玉野市）と高松（香川県）です。"],"myth":"連絡船のうどんにまつわる話は利用者の思い出として語られるもの。","img":["宇野港","紫雲丸","瀬戸大橋"],"wp":"宇高連絡船","rel":{"ev":[],"grave":[]},"ph":[["c:a/a7/Sanuki-maru_anchor_Takamatsu.jpg",960,720,"宇高連絡船"],["c:e/e4/Uko_Ferry_Udon_restaurant_02.jpg",5184,3456],["c:8/83/JNR_Ukou_Ship_Line_at_Takamatsu_Port.jpg",3000,1840],["c:b/b1/Takamatsu_Station.1980.jpg",2000,1500],["c:7/77/Uko_hover_craft_19880322_Takamatsu_Station.jpg",1448,959],["c:a/a0/RenrakusenUdon.JPG",1219,728],["c:4/4d/Rennrakusenn_JNRsikoku_sanukimaru.jpg",945,683],["c:4/40/Rennrakusenn_JNRsikoku_awamaru.jpg",945,669]]},{"id":"33_kitagishima","n":"北木島（大坂城の石を切り出した島）","yomi":"きたぎしま","cat":"島","rank":"B","y":1620,"era":["edo","meiji","showa"],"sh":"","ad":"笠岡市北木島町","st":"JR笠岡駅から歩いて約5分の笠岡港（住吉港）から、旅客船・フェリーで約1時間前後","la":34.378,"lo":133.545,"hook":"島を削ってつくられた青い湖。その岩肌は、大坂城や東京の名建築の石を生んだ «石の島» の証だ。","lead":"北木島は、笠岡諸島でいちばん大きな島です。島ぜんたいが良い花こう岩でできていて、«北木石» として昔から切り出されてきました。江戸時代の大坂城の再建に使われたといわれ、明治・大正以降は東京の建物にも使われました。","story":["笠岡の港から船に揺られて北木島に近づくと、山肌が白く削られたところが見えてきます。石を切り出した «丁場（ちょうば）» の跡です。北木島の石は、かたくて美しい花こう岩。島の人たちは、何百年もこの石とともに暮らしてきました。","言い伝えでは、江戸時代のはじめ、徳川幕府が大坂城を建て直したとき、北木島の石も運ばれたといわれます。大坂城の石垣には、瀬戸内海の島々から集められた巨大な石がたくさん使われています。«どうやって海をわたって運んだの?» 石を船にのせ、瀬戸内海の潮の流れを読みながら大坂まで運んだのです。","明治から昭和にかけて、北木石は大きな建物に使われ、石の仕事がさかんになりました。日本銀行本店や靖国神社の大鳥居などに使われたと伝えられています。島にはたくさんの石工が集まり、学校や商店もにぎわいました。","しかし、外国から安い石が入るようになると、石の仕事は少なくなりました。今も切り出しを続ける丁場はわずかです。深く掘り下げた丁場のあとに水がたまり、まるで湖のような景色も生まれました。","2019年、笠岡諸島の石の文化は日本遺産の物語の一部に選ばれました。島を歩くと、石を切り出した跡、石で造られた波止場や石段など、石とともに生きた人々の歴史が見えてきます。"],"tl":[["江戸時代初期","大坂城の再建で北木島の石も使われたと伝わる"],["明治時代","北木石の切り出しが本格化する"],["明治〜昭和","東京などの大きな建物や記念碑に北木石が使われる"],["昭和後期","外国産の石が増え、丁場が減る"],["2019年","笠岡諸島の «石の島» の物語が日本遺産に認定される"]],"who":[["石工たち","島で石を切り出し、加工した職人"],["徳川幕府","江戸時代に大坂城を再建し、各地の大名に石を運ばせた"],["島の人々","石の仕事とともに、漁業や暮らしを支えた"]],"deep":["北木石は、白っぽい地に黒い粒が散らばる花こう岩で、みがくとつやが出るのが特徴です。","大坂城の再建は1620年から始まり、多くの大名が石垣づくりを分担しました。北木島の石が使われたという話は伝承で、どの石かは特定されていません。","日本銀行本店や靖国神社の大鳥居に北木石が使われたといわれますが、使われた部分などには不明な点があります。","丁場の跡にできた «丁場湖» は、深い青色の水と切り立った岩壁の景色で、観光の名所になっています。","石の切り出しでは、岩に «矢» と呼ばれるくさびを並べて打ちこみ、石の «目»（割れやすい向き）に沿って割っていきました。のちには機械も使われるようになりました。","北木島には «北木石記念館» があり、石を切る道具や石の仕事の歴史が紹介されています。","日本遺産の認定名は «知ってる!? 悠久の時が流れる石の島 ～海を越え、日本の礎を築いた笠岡諸島～» です。"],"look":["丁場湖（石を掘った跡の湖）","稼働中・閉鎖した丁場の岩壁（見学は案内に従う）","北木石記念館","石で造られた波止場や石垣"],"q":["北木島で切り出される石の種類は？","花こう岩です。«北木石» と呼ばれ、かたくて美しいのが特徴です。"],"myth":"大坂城の石垣や日本銀行本店・靖国神社の大鳥居に使われたという話は、伝承・諸説を含む。","img":["笠岡諸島","花崗岩","大坂城"],"wp":"北木島","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Kitagishima-Ooura1.jpg",4288,3216,"北木島"],["c:7/7d/Kitagishima_Quarry_lakes_06_1.jpg",4592,3448],["c:e/e1/Kitagishima_Quarry_lakes_03_1.jpg",4592,3448],["c:7/7e/Kitagishima-Kanaburo1.jpg",4288,3216],["c:9/93/Hikari_Gekijo_Kitagishima_ac_%281%29.jpg",5889,3915],["c:b/bc/Kitagishima_Quarry_lakes_05_1.jpg",2448,3264],["c:b/b0/Kitagishima_Quarry_lakes_04_1.jpg",3264,2448],["c:f/f2/Kitagishima_Quarry_lakes_02_1.jpg",3264,2448]]},{"id":"33_shiraishi","n":"白石島（白石踊の島）","yomi":"しらいしじま","cat":"島","rank":"B","y":1185,"era":["heian","edo"],"sh":"国指定名勝","ad":"笠岡市白石島","st":"JR笠岡駅から歩いて約5分の笠岡港（住吉港）から、旅客船で約35分","la":34.397,"lo":133.524,"hook":"お盆の夜、浜にかがり火がともり、何百年も前から伝わる踊りの輪が広がる。","lead":"白石島は、笠岡諸島にある花こう岩の白い岩と砂浜の美しい島です。島ぜんたいが国の名勝に指定されています。お盆に踊られる «白石踊» は、源平合戦で亡くなった人々をとむらうために始まったと伝わり、国の重要無形民俗文化財です。","story":["白い花こう岩が海に顔を出し、白い砂浜が続く島。その景色から «白石島» と呼ばれるようになったといわれます。山の上には大きな岩がごろごろと重なり、瀬戸内の島々を一望できます。","平安時代の終わり、源氏と平氏がはげしく争いました。1183年には、この近くの海で «水島の戦い» があったと伝わります。海の上で多くの武士が命を落としました。«なぜ、ここで踊りが始まったの?» 白石踊は、この戦いで亡くなった人々の霊をなぐさめるために始まったと伝えられています。","白石踊のふしぎなところは、一つの歌に合わせて、男踊り・女踊り・娘踊り・笠踊りなど、いくつもの違う踊りが同時に踊られることです。やぐらの上で音頭取りが歌い、そのまわりに踊りの輪が重なります。一つの踊りの輪の中で、違う振りが混ざり合うようすはとても美しいものです。","白石踊は1976年に国の重要無形民俗文化財に指定されました。さらに2022年には、全国の «風流踊» の一つとして、ユネスコの無形文化遺産にも登録されています。島の小さな盆踊りが、世界に認められたのです。","島には、弘法大師が開いたと伝わる開龍寺もあります。大きな岩の下にまつられたお堂は、島の人たちの信仰の中心です。お盆の季節でなくても、海と岩と祈りの島を歩いてみると、昔の人々の心にふれられます。"],"tl":[["1183年","近くの海で源平の水島の戦いがあったと伝わる"],["中世以降","戦いで亡くなった人々をとむらう踊りが始まったと伝わる"],["江戸時代","白石島が海の交通の島としてにぎわう"],["1950年","白石島が国の名勝に指定される"],["1976年","白石踊が国の重要無形民俗文化財に指定される"],["2022年","«風流踊» の一つとしてユネスコ無形文化遺産に登録"]],"who":[["音頭取り","やぐらの上で白石踊の歌を歌う人"],["源平の武士たち","水島の戦いで亡くなり、踊りでとむらわれたと伝わる"],["弘法大師（空海）","開龍寺を開いたと伝わる"],["島の踊り手たち","子どもからお年寄りまで、踊りを受けついできた"]],"deep":["白石踊の起源を源平合戦の供養とするのは伝承で、実際の成り立ちは中世以降の盆踊りの流れの中で考えられています。","踊りの種類は十数種類あるといわれ、同じ歌に合わせて違う踊りが同時に踊られるのが最大の特徴です。","2022年のユネスコ無形文化遺産 «風流踊» には、全国41件の民俗芸能がまとめて登録され、白石踊もその一つです。","島全体が国の名勝に指定されており、花こう岩の奇岩や砂浜の景観が評価されています。","開龍寺には、岩のくぼみを生かしたお堂があり、島の八十八か所巡りの中心になっています。","夏の白石島は海水浴場としてもにぎわい、国際交流ヴィラなどの宿泊施設もあります。"],"look":["白い砂浜と花こう岩の奇岩","山頂近くの展望地からの笠岡諸島のながめ","開龍寺の岩屋のお堂","お盆の白石踊（毎年8月）"],"q":["白石踊の起源として伝えられている戦いは？","源平の «水島の戦い» です。亡くなった人々の霊をなぐさめるために始まったと伝わります。"],"myth":"白石踊の起源、白石島の名の由来、開龍寺の開基は伝承による。","img":["白石踊","笠岡諸島","風流踊"],"wp":"白石島","rel":{"ev":[],"grave":[]},"ph":[["c:c/cd/Shiraishijima_2019.jpg",4206,2808,"白石島"],["c:6/6f/Tsukanomaruyama01.JPG",1280,960,"笠岡諸島"],["c:c/ce/Aronia_Blossoms_Screen_2.jpg",17593,7745,"風流踊"]]},{"id":"33_anni","n":"安仁神社（備前一宮の論社・藤原純友の乱）","yomi":"あにじんじゃ","cat":"寺社","rank":"B","y":940,"era":["heian"],"sh":"","ad":"岡山市東区西大寺一宮","st":"JR赤穂線・大多羅駅や西大寺駅から車で約15分。車が便利","la":34.64,"lo":134.06,"hook":"かつて備前の国でいちばん格の高い神社だったのに、ある反乱をきっかけにその座を失ったといわれる。","lead":"安仁神社は、岡山市の東、西大寺の近くにある古い神社です。平安時代の «延喜式» で «名神大社» に数えられる、とても格の高い神社でした。備前国の «一宮» だったとする説があり、藤原純友の乱との関わりが語られています。","story":["山のふもとの静かな境内に、安仁神社の社殿が建っています。«安仁» という名前は、古い時代のこの土地の名前からきているともいわれます。祭神は、神武天皇の兄たちの神々とされ、この神社がとても古い由来をもつことを物語っています。","平安時代の中ごろ、国の決まりをまとめた «延喜式» という書物がつくられました。その中で安仁神社は、特に格の高い «名神大社» とされています。備前国でこの位を得たのは、安仁神社だけでした。«それなら、安仁神社が備前でいちばん大事な神社だったのでは?»","ところが今、備前国の一宮といえば、岡山市北区の吉備津彦神社がよく知られています。なぜでしょう。ここで語られるのが «藤原純友の乱» です。10世紀の前半、伊予（愛媛県）の役人だった藤原純友が、瀬戸内海の海賊をひきいて朝廷にそむきました。","言い伝えでは、このとき安仁神社が純友の側についた、あるいは純友の拠点になったため、朝廷の怒りを買い、一宮の地位を吉備津彦神社にゆずることになったといわれます。ただ、これははっきりした史料で確かめられた話ではなく、諸説があります。«一宮はどちらだったのか»。この問いは、今も歴史好きの間で語り合われています。","今の安仁神社は、訪れる人も少なく、深い森に包まれています。しかしその静けさの奥に、かつて瀬戸内の大きな争いにかかわったかもしれない古い神社の歴史が眠っているのです。"],"tl":[["古代","安仁神社がまつられたと伝わる"],["927年","«延喜式» が完成。安仁神社は名神大社とされる"],["939年","藤原純友の乱が本格化する"],["941年","純友が討たれ、乱がおさまる"],["その後","一宮の地位が吉備津彦神社に移ったといわれる（諸説）"],["現在","備前国一宮の論社の一つとされる"]],"who":[["藤原純友","平安時代、瀬戸内海で朝廷にそむいた人物"],["吉備津彦神社","現在、備前国一宮として知られる神社"],["小野好古","朝廷から派遣され、純友の乱をしずめた武官"]],"deep":["«論社» とは、昔の記録に出てくる神社がどれにあたるのか、複数の候補があって議論されている神社のことです。","延喜式の «神名帳» で、備前国の名神大社は安仁神社ただ一社でした。このことが、安仁神社を一宮とする説の根拠の一つになっています。","純友の乱と安仁神社のつながりを示す同時代の史料ははっきりせず、一宮の地位が移った話は後世の伝えによるものが多いとされます。","祭神の五瀬命・稲氷命・御毛沼命は、神武天皇の兄とされる神々です。神武天皇の東征の物語と結びつけて語られることもあります。","藤原純友の乱は、同じころ関東で起きた平将門の乱とあわせて «承平・天慶の乱» と呼ばれます。","神社の周りの地形は、昔は海が近かったと考えられ、瀬戸内の海上交通とのつながりを想像させます。"],"look":["森に包まれた社殿と参道","境内の由緒書き（一宮をめぐる説の説明）","周辺の田園と山の景色","近くの西大寺観音院（あわせて訪ねると西大寺地区の歴史がわかる）"],"q":["藤原純友の乱と、同じころ関東で起きた平将門の乱をあわせて何と呼ぶ？","«承平・天慶の乱» です。"],"myth":"純友の乱で一宮の地位を失ったという話は伝承で、史料での確認はできず諸説ある。","img":["藤原純友の乱","吉備津彦神社","延喜式神名帳"],"wp":"安仁神社","rel":{"ev":[],"grave":[]},"ph":[["c:e/e0/Ani_jinja_05.JPG",2048,1362,"安仁神社"],["c:a/a5/Takedono_no_Rakugan_%E9%AB%98%E6%AE%BF%E8%90%BD%E9%9B%81_%28BM_2008%2C3037.19902_1%29.jpg",1142,1600,"藤原純友の乱"],["c:f/f2/Kibitsuhiko-jinja_tourou_and_haiden.JPG",3648,2736,"吉備津彦神社"],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"]]},{"id":"33_kohoji","n":"弘法寺（千手山の古刹）","yomi":"こうぼうじ","cat":"寺社","rank":"B","y":750,"era":["nara","heian","edo"],"sh":"","ad":"瀬戸内市牛窓町千手","st":"JR赤穂線・邑久駅から車で約15分。車が便利","la":34.641,"lo":134.133,"hook":"山の上の古いお寺で、年に一度、菩薩の面をつけた人々が «この世» と «あの世» をつなぐ橋をわたる。","lead":"弘法寺は、瀬戸内市の千手山にある古いお寺です。奈良時代に報恩大師が開いたと伝わり、のちに弘法大師（空海）が修行したことから «弘法寺» と名づけられたといわれます。菩薩の面をつけて練り歩く «踟供養（ねりくよう）» という珍しい行事で知られます。","story":["牛窓の海から少し北へ入った山の中に、千手山弘法寺があります。境内からは、木々の間に瀬戸内海が見えかくれします。この寺は、備前に多くの寺を開いたと伝わる報恩大師が、奈良時代に建てたのが始まりといわれます。","寺の名前の由来にはこんな話が伝わります。平安時代のはじめ、弘法大師（空海）がこの山で修行したというのです。«それで弘法寺という名前なの?» そう伝えられていますが、全国には空海にまつわる言い伝えをもつ寺がたくさんあり、確かなことはわかっていません。","かつての弘法寺は、山の上にいくつもの坊（僧の住まい）が建ち並ぶ大きな寺だったといわれます。戦国時代の戦乱や、長い年月の中で多くの建物を失いましたが、そのたびに人々の手で立て直されてきました。昭和には火事で本堂などが焼けるという災難にもあいました。","弘法寺でいちばん有名なのが、5月に行われる «踟供養» です。金色の菩薩の面をつけた人々が、仏さまの世界から迎えに来るようすを表して、境内をゆっくりと練り歩きます。«亡くなった人を極楽へ導く» という願いがこめられた行事で、岡山県の重要無形民俗文化財に指定されています。","古い寺の石段をのぼると、海風と山の空気がまざり合います。はるかな昔から、人々が祈りをささげてきた山の寺です。"],"tl":[["奈良時代","報恩大師が開いたと伝わる"],["平安時代初期","弘法大師が修行したと伝わる"],["中世","山上に多くの坊が建つ大寺となったといわれる"],["戦国時代","戦乱で建物を失ったと伝わる"],["昭和時代","火災で本堂などを失う"],["現在","5月の踟供養が続けられている"]],"who":[["報恩大師","奈良時代の僧。備前に多くの寺を開いたと伝わる"],["弘法大師（空海）","この山で修行したと伝わる"],["寺を支えた地域の人々","焼けた建物を立て直し、行事を受けついできた"]],"deep":["報恩大師が開いたとされる備前の寺は «備前四十八ヶ寺» と呼ばれ、弘法寺もその一つに数えられます。ただし、どの寺が含まれるかには諸説があります。","«踟供養» は «練供養» とも書き、来迎会（らいごうえ）の一種です。奈良の當麻寺の練供養などが知られますが、弘法寺のものは中国・四国地方では珍しいとされます。","弘法寺には塔頭の遍明院などがあり、仏像や古文書などの文化財が伝えられています。","弘法寺のある千手山は、牛窓の町と海を見下ろす位置にあり、中世には海上交通とのつながりもあったと考えられます。","近くの牛窓は、江戸時代に朝鮮通信使が立ち寄った港町で、お寺めぐりとあわせて歴史散策ができます。","報恩大師は備前の出身とされる奈良時代の僧で、孝謙天皇の病気を祈りで治したという伝説があります。その実像については、はっきりしない部分が多い人物です。"],"look":["山上の境内への石段","境内から見える瀬戸内海","踟供養（毎年5月・日程を確認）","塔頭の遍明院"],"q":["弘法寺で5月に行われる、菩薩の面をつけて練り歩く行事の名前は？","«踟供養（ねりくよう）» です。極楽から菩薩が迎えに来るようすを表します。"],"myth":"報恩大師の開基、弘法大師の修行、寺名の由来はいずれも伝承。","img":["報恩大師","練供養","牛窓町"],"wp":"弘法寺 (瀬戸内市)","rel":{"ev":[],"grave":[]},"ph":[["c:f/f5/Senzusan_Koboji_01.JPG",4127,2609,"弘法寺 (瀬戸内市)"],["c:5/57/Senzusan_Koboji_06.JPG",4288,2848],["c:d/d6/Koboji_Tojuin_02.JPG",4288,2848],["c:7/78/Koboji_Sannosha_03.JPG",4288,2848],["c:0/07/Koboji_Henmyoin_01.JPG",4288,2848],["c:f/f7/Setouchi_Ushimado_Port01n4272.jpg",4272,2848,"牛窓町"]]},{"id":"33_yokeiji","n":"餘慶寺（邑久の天台寺院）","yomi":"よけいじ","cat":"寺社","rank":"B","y":749,"era":["nara","heian","muromachi"],"sh":"国の重要文化財（本堂）","ad":"瀬戸内市邑久町北島","st":"JR赤穂線・邑久駅から車で約10分","la":34.656,"lo":134.087,"hook":"吉井川の河口近くの小山に、室町時代の本堂と三重塔が静かに建つ天台の古寺。","lead":"餘慶寺は、瀬戸内市邑久町にある天台宗のお寺です。奈良時代に報恩大師が開いたと伝わります。室町時代の本堂は国の重要文化財で、平安時代の仏像も伝わっています。冬には «会陽（えよう）» という行事も行われます。","story":["吉井川が瀬戸内海にそそぐ近く、邑久の平野の中に小高い山があります。その山の中腹に建つのが餘慶寺です。«餘慶» とは、よい行いを積み重ねると、その幸せが子や孫にまでおよぶ、という意味のことばです。","言い伝えでは、奈良時代の749年、報恩大師がこの地に寺を開いたといわれます。のちに天台宗の寺として栄え、山の上にはいくつもの坊が建ち並びました。«なぜこの場所に?» 吉井川の水運と海の道が交わるこのあたりは、古くから人と物が行き来する豊かな土地だったのです。","境内の本堂は室町時代に建てられたもので、国の重要文化財に指定されています。どっしりとした屋根と太い柱は、何百年もの風雪にたえてきました。境内には三重塔も建ち、山の緑の中に美しい姿を見せています。","寺には、平安時代につくられた仏像も伝わっています。長い年月の中で、戦乱や火事から仏像を守ってきたのは、代々の僧や村人たちでした。仏像を拝むと、その人々の思いが伝わってくるようです。","境内を歩くと、本堂や塔のほかにも、鐘楼や小さなお堂が点在しています。山の斜面に沿って建物が並ぶようすは、昔の «山の寺» の姿を今に伝えています。石段の途中でふり返ると、吉井川の流れと邑久の田畑が広がり、この寺が長い間、この平野を見守ってきたことが感じられます。","餘慶寺では、冬に «会陽» が行われます。まわしをしめた男たちが、福を呼ぶ «宝木（しんぎ）» をうばい合う、いわゆる «はだか祭り» です。近くの西大寺の会陽が有名ですが、餘慶寺の会陽も地域の人々に親しまれてきました。"],"tl":[["749年","報恩大師が開いたと伝わる"],["平安時代","仏像がつくられ、天台宗の寺として栄える"],["室町時代","現在の本堂が建てられる"],["江戸時代","三重塔などが整えられる"],["現在","本堂が国の重要文化財。冬に会陽が行われる"]],"who":[["報恩大師","奈良時代の僧。餘慶寺を開いたと伝わる"],["代々の住職","寺と仏像を守りついできた"],["邑久の人々","会陽などの行事を支えてきた"]],"deep":["«積善の家には必ず餘慶あり» は中国の古典『易経』のことばで、寺の名前もこれに由来すると考えられます。","本堂は室町時代後期の建物とされ、国の重要文化財に指定されています。建築年代の細かな点には諸説があります。","寺に伝わる平安時代の薬師如来坐像なども文化財に指定されています。","境内の三重塔は本堂より新しい時代の建物とされ、本堂とともに山の中腹の景観をつくっています。","会陽は岡山県の各地で行われ、西大寺会陽は日本三大奇祭の一つともいわれます。餘慶寺の会陽はそれより規模は小さいものの、長く続いてきた行事です。","餘慶寺も «備前四十八ヶ寺» の一つに数えられることがあります。","餘慶寺のある山は «上寺山（じょうじさん）» と呼ばれ、かつては山の上にも多くの坊があったといわれます。今も境内にはいくつかの院が並び、山全体が一つのお寺のような雰囲気です。"],"look":["室町時代の本堂","山の緑に映える三重塔","境内から見下ろす邑久の平野","冬の会陽（日程を確認）"],"q":["«餘慶» ということばには、どんな意味がある？","よい行いを積み重ねると、その幸せが子や孫にまでおよぶ、という意味です。"],"koji":[{"w":"積善の家には必ず餘慶あり","m":"よい行いを重ねた家には、子孫にまで幸せがおよぶ、という意味（『易経』）"}],"myth":"報恩大師の開基は伝承。本堂・三重塔の建築年代には諸説がある。","img":["報恩大師","会陽","瀬戸内市"],"wp":"餘慶寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/Yokeiji_01.JPG",1600,1064,"餘慶寺"],["c:e/e8/Yokeiji_04.JPG",1600,1064],["c:e/ec/Yokeiji_02.JPG",1600,1064],["c:2/2c/Yokeiji_03.JPG",1063,1600],["c:3/33/Todaiji_Syunie_Nara_JPN_001.JPG",3456,2182,"会陽"],["c:f/f7/Setouchi_Ushimado_Port01n4272.jpg",4272,2848,"瀬戸内市"]]},{"id":"33_chofukuji","n":"長福寺（美作最古の三重塔）","yomi":"ちょうふくじ","cat":"寺社","rank":"B","y":1285,"era":["kamakura"],"sh":"国の重要文化財（三重塔）","ad":"美作市真神","st":"JR姫新線・林野駅から車で約15分。車が便利","la":34.998,"lo":134.199,"hook":"鎌倉時代、元の大軍が攻めてきたころに建てられた三重塔が、今も山里に立っている。","lead":"長福寺は、美作市の山里にある真言宗のお寺です。境内の三重塔は鎌倉時代の1285年ごろに建てられたとされ、岡山県で最も古い塔として国の重要文化財に指定されています。もとは山の上にあった寺から移された塔です。","story":["湯郷温泉にほど近い真神の山里。田んぼの向こうの木々の中に、朱色がかった三重塔がすっと立っています。これが長福寺の三重塔です。«こんな静かな村に、なぜこれほど古い塔があるの?»","長福寺は、もともと近くの山の上にあった大きな寺だったといわれます。山の上に多くの坊が建ち並び、美作の真言宗の中心の一つとしてさかえました。三重塔が建てられたのは鎌倉時代の1285年ごろ。ちょうど、元（モンゴル）の大軍が二度にわたって日本に攻めてきた «元寇» のころです。","長い年月のうちに、山の上の寺はさびれていきました。建物は失われ、三重塔だけがぽつんと残されたといいます。昭和になって、塔は山のふもとの今の場所へ移されました。大きな塔を一度ばらばらにして運び、また組み立てる大工事でした。","塔を見上げると、1階から3階まで屋根の大きさが少しずつ小さくなり、全体が引きしまった姿をしています。軒を支える組物には鎌倉時代らしい力強さがあり、昔の大工たちの腕のよさを感じさせます。","«三重塔» は、お釈迦さまの遺骨（仏舎利）をまつる塔がもとになった建物です。中国や朝鮮半島を通って日本に伝わり、各地のお寺に建てられました。鎌倉時代の塔が今も残っているのは全国でも多くなく、しかも山里の小さなお寺に伝わっているのは貴重なことです。","何百年もの間、雨や風、地震にたえてきた塔。地域の人々が守りついできたからこそ、今も私たちはその姿を見ることができるのです。"],"tl":[["奈良〜平安時代","山の上に寺が開かれたと伝わる"],["1285年ごろ","三重塔が建てられる（鎌倉時代）"],["中世以降","山上の寺がしだいにさびれる"],["昭和時代","三重塔が山のふもとの現在地へ移される"],["現在","三重塔が国の重要文化財として守られている"]],"who":[["塔を建てた鎌倉時代の大工たち","三重塔を建てた職人たち"],["長福寺の歴代住職","寺と塔を守ってきた"],["真神の人々","塔の移築や保存を支えた地域の人々"]],"deep":["三重塔の建立年は、塔に残る墨書などから1285年（弘安8年）とされ、岡山県内に残る塔の中でいちばん古いといわれます。","1285年は、元寇の文永の役（1274年）と弘安の役（1281年）の間から少しあとの時期にあたります。","塔の移築は昭和の時代に行われました。移築のときの調査で、建立年代を知る手がかりが確かめられたともいわれます。","塔は日本の伝統的な «和様» を基本とした落ち着いたつくりで、鎌倉時代の建築の特徴を今に伝えています。","山の上にあった旧寺域には、今も寺の跡とされる平らな土地や石垣などが残るといわれます。","三重塔は、中心に «心柱（しんばしら）» という太い柱が通り、地震のときに塔全体のゆれをおさえる働きをしていると考えられています。長く倒れずに残った理由の一つとされます。"],"look":["鎌倉時代の三重塔","軒を支える組物の細工","塔と山里の田園風景","近くの湯郷温泉（あわせて訪ねやすい）"],"q":["長福寺の三重塔が建てられたのは、何時代？","鎌倉時代です。1285年ごろとされ、岡山県でいちばん古い塔といわれます。"],"myth":"寺の開基、山上の寺の規模、移築の経緯の細部には伝承や諸説がある。","img":["三重塔","元寇","美作市"],"wp":"長福寺 (美作市)","rel":{"ev":[],"grave":[]},"ph":[["c:6/63/Makisan_Chofukuji_Pagoda.jpg",1282,1966,"長福寺 (美作市)"],["c:c/c5/Hokiji03ds1536.jpg",2900,4350,"三重塔"],["c:1/19/M%C5%8Dko_Sh%C5%ABrai_Ekotoba.jpg",2520,843,"元寇"],["c:a/a9/%E6%B9%AF%E9%83%B7%E6%B8%A9%E6%B3%89_-_panoramio.jpg",1600,900,"美作市"]]},{"id":"33_hokaiin","n":"法界院（岡山の古刹）","yomi":"ほうかいいん","cat":"寺社","rank":"B","y":750,"era":["nara","edo"],"sh":"","ad":"岡山市北区法界院","st":"JR津山線・法界院駅から歩いて約10分","la":34.687,"lo":133.927,"hook":"駅の名前にもなった古いお寺。岡山城下の北の山すそで、1200年以上祈りが続いてきた。","lead":"法界院は、岡山市の北にある真言宗のお寺です。奈良時代に報恩大師が開いたと伝わり、江戸時代には岡山藩主・池田家の祈願所として大切にされました。JR津山線の «法界院駅» や町の名前にもなっています。","story":["岡山駅から津山線に乗ると、すぐに «法界院» という駅があります。駅の名前になるほど、このお寺はこの地域にとって大切な存在でした。岡山大学のキャンパスの北、山すその静かな場所に、法界院の境内が広がっています。","寺の始まりは奈良時代といわれます。備前に多くの寺を開いたと伝わる報恩大師が、この地に寺を建てたとされます。«1200年以上も前から、ここで祈りが続いているの?» そう考えると、境内の空気がいっそう深く感じられます。","長い歴史の中で、法界院はたびたび戦乱や火事にあいました。戦国時代には、備前の覇権をめぐる争いの中で建物が失われたこともあったといわれます。そのたびに再建され、祈りの場は守られてきました。","江戸時代になると、岡山藩主・池田家がこの寺を大切にしました。藩の安泰や人々の無事を祈る «祈願所» として、城下の北の守りの寺の役目も果たしたと考えられています。寺には、藩主から寄せられた品や古い仏像が伝えられています。","境内には本堂のほか、大師堂や鐘楼などが並びます。山すそを背にした建物の配置は、古い山の寺の姿をしのばせます。戦後、まわりには住宅や大学が広がりましたが、門をくぐると急に静かになり、時間がゆっくり流れているように感じられます。","今の法界院は、四季の花が咲く境内を散歩する人や、お参りに訪れる人でにぎわいます。都会のすぐそばにありながら、古い寺の落ち着いた空気を感じられる場所です。"],"tl":[["奈良時代","報恩大師が開いたと伝わる"],["平安時代","真言宗の寺として整えられたといわれる"],["戦国時代","戦乱で建物を失ったと伝わる"],["江戸時代","岡山藩主・池田家の祈願所となる"],["1898年","中国鉄道（のちの津山線）が開通。のちに法界院駅が置かれる"],["現在","地域の古刹として親しまれる"]],"who":[["報恩大師","法界院を開いたと伝わる奈良時代の僧"],["池田家（岡山藩主）","江戸時代に法界院を祈願所として保護した"],["歴代の住職","戦乱や火災のたびに寺を立て直した"]],"deep":["法界院も、報恩大師が開いたとされる «備前四十八ヶ寺» の一つに数えられます。","寺には平安時代の仏像などが伝わり、文化財に指定されているものもあります。拝観できるかどうかは事前に確認が必要です。","寺名の «法界» は仏教のことばで、真理の世界やすべての存在を意味します。","法界院駅はJR津山線の駅で、寺の名前がそのまま駅名や町名になっていることからも、地域でのこの寺の存在の大きさがわかります。","近くの岡山大学の敷地には、旧陸軍の施設だった時代の建物や跡も残り、法界院周辺を歩くと古代から近代までの歴史が重なっています。","江戸時代の岡山藩主・池田光政は、寺院の整理を進めたことで知られますが、法界院は池田家の祈願所として江戸時代を通じて続きました。藩の宗教政策の中で、どの寺が重んじられたかを考える手がかりになります。"],"look":["山門と本堂","境内の四季の花","寺に伝わる仏像（公開日を確認）","法界院駅からの参道"],"q":["法界院を江戸時代に祈願所として大切にした、岡山藩の藩主の家は？","池田家です。"],"myth":"報恩大師の開基や戦国時代の焼失の経緯は伝承による。","img":["報恩大師","法界院駅","岡山藩"],"wp":"法界院","rel":{"ev":[],"grave":[]},"ph":[["c:6/67/Hokaiin_04.JPG",3806,2494,"法界院"],["c:9/91/Hokaiin_05.JPG",3872,2592],["c:8/8f/Hokaiin_02.JPG",3872,2592],["c:c/ca/Hokaiin_01.JPG",3823,2521],["c:0/04/JRW-H%C5%8DkaiinStation.jpg",1600,993,"法界院駅"],["c:9/90/Okayama_Castle.IMG_5917.jpg",3504,2336,"岡山藩"]]},{"id":"33_bitchu_hyoran","n":"備中兵乱の地（三村氏滅亡の戦い）","yomi":"びっちゅうひょうらんのち","cat":"古戦場","rank":"B","y":1575,"era":["azuchi"],"sh":"","ad":"高梁市内山下（備中松山城跡一帯）","st":"JR伯備線・備中高梁駅から車（乗合タクシーなど）で約10分、ふいご峠から歩いて約20分","la":34.809,"lo":133.622,"hook":"«毛利か、織田か» 父のかたきと手を組めなかった武将は、一族の運命をかけて毛利にそむいた。","lead":"«備中兵乱» は、1574年から1575年にかけて、備中の戦国大名・三村元親が毛利氏と戦い、敗れた戦いです。本拠の備中松山城をはじめ、備中の多くの城が攻め落とされ、三村氏は滅びました。","story":["戦国時代、備中（岡山県西部）で力をもっていたのが三村氏でした。三村家親は毛利氏と手を組み、備中の大部分をおさえ、さらに美作や備前へも勢力をのばします。ところが1566年、家親は美作の陣中で、宇喜多直家の送った刺客に鉄砲で撃たれて命を落としました。","父のあとをついだ三村元親は、宇喜多直家を深くうらみました。1567年には直家と戦いますが、敗れてしまいます（明善寺合戦）。ところがその後、毛利氏は宇喜多直家と手を組むことにしました。«父のかたきと味方になれというのか!» 元親は、とうてい受け入れられなかったといわれます。","元親は毛利氏とたもとを分かち、東で勢いを増す織田信長と結ぼうとしました。これに対し、毛利氏は小早川隆景らを大将に大軍を備中へ送りこみます。1574年の終わりから、三村方の城が次々に攻められていきました。","三村氏の城は一つまた一つと落ち、1575年、ついに本拠の備中松山城も落城します。元親は城を逃れたのち、自ら命を絶ったと伝わります。同じころ、元親の妹とされる鶴姫は、嫁ぎ先の常山城（玉野市・岡山市）で侍女たちとともに戦ったという話も伝わっています。","備中松山城の山を歩くと、戦国時代の曲輪や堀切の跡が、江戸時代の石垣の周りにも残っています。今そびえる天守は江戸時代のものですが、その足もとには、三村氏の最後の戦いの記憶が眠っているのです。"],"tl":[["1566年","三村家親が宇喜多直家の刺客に撃たれ死去"],["1567年","明善寺合戦で三村元親が宇喜多直家に敗れる"],["1574年","毛利氏が宇喜多氏と結び、三村元親が毛利から離れる"],["1574〜1575年","毛利軍が備中の三村方の城を次々に攻める（備中兵乱）"],["1575年","備中松山城が落城し、三村元親が自害。常山城も落ちる"],["1683年ごろ","水谷勝宗が備中松山城の天守などを修築（現存天守）"]],"who":[["三村元親","備中の戦国大名。毛利にそむき、敗れて自害した"],["三村家親","元親の父。宇喜多直家の刺客に討たれた"],["宇喜多直家","備前の戦国大名。三村氏の宿敵"],["小早川隆景","毛利元就の三男。備中兵乱で毛利軍を率いた"],["鶴姫","元親の妹とされる女性。常山城で戦ったと伝わる"]],"deep":["三村家親の暗殺は、鉄砲による暗殺としては日本でも早い例の一つといわれています。","«備中兵乱» という名前は、江戸時代にまとめられた軍記物『備中兵乱記』などに由来します。軍記物には脚色も含まれるため、細部は注意が必要です。","元親が自害した場所は、松山城下の寺だったと伝わり、高梁市内には元親の墓とされるものもあります。","鶴姫の «常山城の女軍» の話は有名ですが、軍記物にもとづく伝承で、どこまで事実かははっきりしません。","備中兵乱のあと、備中は毛利氏の支配下に入り、やがて羽柴秀吉の中国攻め（1582年の備中高松城水攻め）の舞台になります。","備中松山城は、現存天守をもつ12城のうち、最も高い所にある山城として知られています。"],"look":["備中松山城の天守と石垣（江戸時代）","大松山・小松山に残る戦国の曲輪や堀切","ふいご峠から城への登り道","高梁の城下町と頼久寺"],"q":["三村元親が毛利氏から離れた大きな理由は、毛利氏が誰と手を組んだから？","宇喜多直家です。父・三村家親のかたきだったため、元親は受け入れられなかったといわれます。"],"myth":"元親の最期の場所、鶴姫の奮戦などは軍記物にもとづく伝承を含む。","img":["三村元親","備中松山城","常山城"],"wp":"備中兵乱","rel":{"ev":[],"grave":[]},"ph":[["c:9/9e/Bitchu_Matsuyama_Castle_1.JPG",3008,2000,"備中兵乱"],["c:5/52/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E2.jpg",4032,3024,"備中松山城"],["c:2/25/Mt._Tsuneyama.JPG",2048,1362,"常山城"]]},{"id":"33_hinase","n":"日生諸島（備前の海の島々）","yomi":"ひなせしょとう","cat":"島","rank":"B","y":1698,"era":["edo","showa"],"sh":"","ad":"備前市日生町","st":"JR赤穂線・日生駅から歩いてすぐの日生港から、定期船で各島へ","la":34.716,"lo":134.278,"hook":"江戸時代の石の防波堤がいまも波を受け止める。漁師の海に浮かぶ、十あまりの島々。","lead":"日生諸島は、岡山県の東のはし、備前市日生町の沖に浮かぶ島々です。鹿久居島・頭島・大多府島などがあり、古くから漁業の海として栄えました。大多府島には、江戸時代に岡山藩が築いた «元禄防波堤» が残っています。","story":["日生の港に立つと、目の前の海に大小の島々が重なって見えます。これが日生諸島。岡山県と兵庫県の境に近い播磨灘の海です。島と島の間は波がおだやかで、魚がよく育つため、日生は昔から漁師の町として知られてきました。","江戸時代、日生の沖は瀬戸内海を東西に行き来する船の通り道でもありました。風や潮が悪いとき、船は安全な港に入って待たなければなりません。そこで岡山藩が目をつけたのが、日生諸島の東にある大多府島でした。«船が安心して休める港をつくろう»。1698年、藩の命令で島の港に大きな石の防波堤が築かれます。","この防波堤は «元禄防波堤» と呼ばれ、300年以上たった今も波を受け止めています。«なぜそんなに長くもつの?» 大きな石を組み合わせ、波の力をうまく受け流すように積み上げた、当時の技術の高さのおかげです。防波堤は国の登録有形文化財になっています。","大多府島は、北前船や参勤交代の船なども立ち寄る «風待ち港» としてにぎわったといわれます。島には船乗りたちのための宿や店もありました。いまは静かな島ですが、港の石積みや細い路地に、当時のにぎわいの名残を感じることができます。","日生の海は、今もカキの養殖でよく知られています。カキを入れたお好み焼き «カキオコ» は、日生の名物として全国に知られるようになりました。2015年には本土と鹿久居島を結ぶ «備前♡日生大橋» が開通し、頭島大橋とあわせて島々と本土が陸続きになりました。"],"tl":[["古代〜中世","日生の海で漁業が営まれる"],["1698年","岡山藩が大多府島に元禄防波堤を築く"],["江戸時代","大多府島が風待ち港としてにぎわう"],["昭和時代","日生でカキの養殖がさかんになる"],["2015年","本土と鹿久居島を結ぶ備前♡日生大橋が開通"]],"who":[["池田綱政","当時の岡山藩主。元禄防波堤の築造を命じたとされる"],["日生の漁師たち","この海で漁を続け、日生を漁師の町にした"],["船乗りたち","大多府島の港で風待ちをした"]],"deep":["元禄防波堤は石積みの防波堤で、江戸時代の港湾施設が今も使われている貴重な例です。","大多府島の港づくりには、岡山藩の郡代として土木事業を進めた津田永忠が関わったといわれます。永忠は閑谷学校や後楽園の造営にも関わった人物です。","日生のカキ養殖は昭和に本格的に始まり、今では岡山県のカキの主な産地の一つです。","«日生» の地名の由来には、«日が生まれる（のぼる）東の地» という説などがありますが、はっきりしません。","鹿久居島は日生諸島でいちばん大きな島で、古い遺跡も見つかっています。","日生諸島の海は国立公園（瀬戸内海国立公園）の一部です。"],"look":["大多府島の元禄防波堤","日生港と島々を結ぶ定期船","備前♡日生大橋・頭島大橋と島々の景色","名物のカキオコ（冬のカキの季節）"],"q":["大多府島に江戸時代に築かれ、今も使われている石の防波堤の名前は？","«元禄防波堤» です。1698年に岡山藩が築きました。"],"myth":"防波堤の築造に関わった人物や地名の由来には諸説がある。","img":["大多府島","頭島 (岡山県)","鹿久居島"],"wp":"日生諸島","rel":{"ev":[],"grave":[]},"ph":[["c:f/f4/Hinase_01.jpg",1244,758,"日生諸島"],["c:a/a6/%E9%B9%BF%E4%B9%85%E5%B1%85%E5%B3%B6.jpg",11264,6000],["c:7/78/%E9%B4%BB%E5%B3%B6.jpg",3954,3231],["c:8/87/%E9%95%B7%E5%B3%B6.jpg",7586,3364],["c:0/07/Harbor_View_Park_Hinase_Bizen_Okayama_Pref_Japan03bs.jpg",4912,3264],["c:a/a2/%E6%9B%BD%E5%B3%B6.jpg",3444,1569],["c:4/47/%E5%A4%A7%E5%A4%9A%E5%BA%9C%E5%B3%B6.jpg",2629,1707],["c:b/b4/%E9%A0%AD%E5%B3%B6.jpg",2209,1662]]},{"id":"33_takahashi_school","n":"高梁市郷土資料館（明治の旧高梁尋常高等小学校）","yomi":"たかはししきょうどしりょうかん","cat":"学び","rank":"B","y":1904,"era":["meiji"],"sh":"","ad":"高梁市向町","st":"JR伯備線・備中高梁駅から歩いて約15分","la":34.793,"lo":133.619,"hook":"城下町の坂の上に建つ明治の洋風校舎。その中には、町の人々が使ってきた道具がぎっしり並ぶ。","lead":"高梁市郷土資料館は、明治時代に建てられた旧高梁尋常高等小学校の本館を使った資料館です。木造2階建ての洋風の建物で、昔のくらしの道具や、城下町・高梁の歴史にかかわる資料が展示されています。","story":["高梁は、備中松山城のふもとに広がる城下町です。武家屋敷や古い寺が並ぶ町の一角に、白い壁と大きな窓をもつ洋風の建物が建っています。これが、1904年（明治37年）に建てられた高梁尋常高等小学校の本館でした。","明治になると、全国で «学校» がつくられ、子どもたちは読み書きや算数を学ぶようになりました。«江戸時代の寺子屋と何がちがうの?» 国が決めた教科を、同じ年の子どもたちがいっしょに学ぶ。これが新しい学校のかたちでした。高梁の人々は、町の未来を担う子どもたちのために、立派な校舎を建てたのです。","建物は、左右に長くのびた木造2階建てで、白い壁と整然と並んだ窓が印象的です。明治の職人たちが、西洋の建物をまねながら、日本の木造の技術で建てた «擬洋風建築» の流れをくむ姿です。","学校として長く使われたあと、建物は郷土資料館になりました。いま中には、農具や生活の道具、備中松山藩の資料、祭りの道具などが並べられています。昔の教室の雰囲気を感じながら、高梁のくらしの歴史をたどることができます。","高梁は、幕末に藩政改革をなしとげた山田方谷のふるさとでもあります。«学ぶことで人と町を豊かにする»。明治の校舎を歩くと、そんな高梁の人々の思いが今も息づいているように感じられます。"],"tl":[["江戸時代","高梁（松山）が備中松山藩の城下町として栄える"],["1872年","学制が発布され、全国で学校づくりが始まる"],["1904年","高梁尋常高等小学校の本館が建てられる"],["昭和時代","校舎が使われなくなり、保存が進められる"],["現在","高梁市郷土資料館として公開されている"]],"who":[["明治の大工・職人たち","洋風の木造校舎を建てた人々"],["高梁の子どもたち","この校舎で学んだ"],["山田方谷","備中松山藩の藩政改革を行った学者。高梁の教育の象徴的な人物"]],"deep":["«尋常高等小学校» は、義務教育の尋常小学校と、その上の高等小学校をあわせた学校のことです。","建物は木造2階建てで、明治後期の学校建築のようすをよく残しています。","資料館には農具や民具、備中松山藩にかかわる資料などが展示されています。展示内容は変わることがあります。","高梁は «備中の小京都» とも呼ばれ、武家屋敷通りや頼久寺など、城下町の見どころが歩いて回れる範囲に集まっています。","高梁の町では、明治のころからキリスト教の布教も行われ、明治に建てられた «高梁基督教会堂» も残っています。明治の高梁が新しい文化を受け入れた町だったことがわかります。","高梁の城下町は、幕末の藩政改革で知られる山田方谷が学頭（校長にあたる役）をつとめた藩校 «有終館» があった町でもあります。明治の学校づくりも、こうした学問を大切にする土地柄の上に進められました。"],"look":["明治の洋風校舎の外観（玄関まわりと窓の並び）","昔の教室の雰囲気が残る室内","展示されている民具や藩の資料","近くの武家屋敷通りや頼久寺"],"q":["この建物は、もともと何に使われていた？","小学校です。1904年に建てられた高梁尋常高等小学校の本館でした。"],"myth":"","img":["高梁市","備中松山城","山田方谷"],"wp":"高梁市郷土資料館","rel":{"ev":[],"grave":[]},"ph":[["c:8/8c/Takahashi_City_Local_Museum_ac.jpg",5439,3616,"高梁市郷土資料館"],["c:1/1b/Bitchu_Matsuyama_Castle_2.JPG",3008,2000,"高梁市"],["c:5/52/%E5%82%99%E4%B8%AD%E6%9D%BE%E5%B1%B1%E5%9F%8E2.jpg",4032,3024,"備中松山城"],["c:8/84/Yamada_Hokoku_portrait.jpg",1528,2000,"山田方谷"]]},{"id":"33_seto_ohashi","n":"瀬戸大橋（本州と四国を結ぶ）","yomi":"せとおおはし","cat":"昭和","rank":"B","y":1988,"era":["showa"],"sh":"","ad":"倉敷市下津井（鷲羽山展望台）","st":"JR瀬戸大橋線・児島駅から下電バスで鷲羽山方面へ約20分","la":34.439,"lo":133.814,"hook":"«いつか、四国と本州を橋でつなぎたい» 明治の人の夢が、昭和の終わりに実現した。","lead":"瀬戸大橋は、岡山県倉敷市の児島と香川県坂出市を結ぶ橋です。いくつもの島を渡る6つの橋からなり、上を自動車、下を鉄道が走る «二階建て» の橋として1988年に開通しました。鷲羽山からは、その全景を見わたせます。","story":["明治の終わり、香川県の政治家・大久保諶之丞が «四国と本州を橋でつなごう» と語ったといわれます。当時の人々は、それを夢物語と思ったでしょう。瀬戸内海には潮の流れが速い海峡が多く、大きな船も行き来します。そこに長い橋をかけるのは、とてつもなく難しいことでした。","戦後、その夢を後押しする悲しい出来事がありました。1955年、宇高連絡船の «紫雲丸» が霧の中で沈み、修学旅行の子どもたちをふくむ多くの人が亡くなったのです。«海が荒れても、安全に行き来できる道がほしい»。四国の人々の願いは、ますます強くなりました。","1978年、ついに瀬戸大橋の工事が始まりました。海の底に巨大な土台を沈め、その上に高い塔を建て、ケーブルをはり、橋げたをつっていきます。潮の流れの速い海での工事は危険ととなり合わせで、約10年の年月をかけて進められました。","1988年4月10日、瀬戸大橋が開通しました。岡山から四国へ、列車に乗ったまま海を渡れる。人々は新しい時代の始まりを喜びました。いっぽうで、長く本州と四国を結んできた宇高連絡船は、この年に役目を終えています。","鷲羽山の展望台に立つと、島から島へと続く橋が、瀬戸内海の青い海の上にのびています。夜になるとライトアップされる日もあります。人々の長い夢と努力がつくりあげた風景です。"],"tl":[["1889年ごろ","大久保諶之丞が瀬戸内海に橋をかける構想を語ったと伝わる"],["1955年","紫雲丸事故。橋を求める声が強まる"],["1970年","本州四国連絡橋公団が設立される"],["1978年","瀬戸大橋の工事が始まる"],["1988年4月10日","瀬戸大橋が開通。宇高連絡船が廃止される"],["現在","瀬戸大橋線（JR）と瀬戸中央自動車道が通る"]],"who":[["大久保諶之丞","明治の香川県の政治家。本州と四国を橋で結ぶ構想を語った"],["橋の建設に関わった技術者・作業員","約10年かけて難しい工事をなしとげた"],["紫雲丸事故の犠牲者","1955年の事故で亡くなった人々。橋の必要性を強く訴える出来事となった"]],"deep":["瀬戸大橋は、下津井瀬戸大橋・櫃石島橋・岩黒島橋・与島橋・北備讃瀬戸大橋・南備讃瀬戸大橋の6つの橋と、高架橋などからなります。","海峡部の長さは約9.4km。道路と鉄道を一緒に通す «道路鉄道併用橋» としては、世界最大級の規模です。","つり橋・斜張橋・トラス橋という異なる形式の橋が組み合わされ、«橋の博物館» とも呼ばれます。","鉄道部分には、将来の新幹線を通すための準備もされているといわれます。","橋の下を通る船のため、橋げたは海面から高い位置にあり、大型船も通ることができます。","岡山側の下津井には、かつて本州と四国を結ぶ渡し船の港があり、その海の上に瀬戸大橋がかけられたことになります。"],"look":["鷲羽山展望台からの瀬戸大橋の全景","下津井の港から見上げる橋","瀬戸大橋線の列車から見る海と島々","ライトアップ（実施日を確認）"],"q":["瀬戸大橋の上の段と下の段を通るのは、それぞれ何？","上を自動車（瀬戸中央自動車道）、下を鉄道（JR瀬戸大橋線）が通ります。"],"myth":"大久保諶之丞の構想の年や発言の内容は伝えられた話。","img":["鷲羽山","紫雲丸","本州四国連絡橋"],"wp":"瀬戸大橋","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/JP-Kagawa-Great-Seto-Bridge-Minami_Bisan-Seto-Bridge.jpg",3332,2222,"瀬戸大橋"],["c:2/2e/Obatake%2C_Kurashiki%2C_Okayama_Prefecture_711-0924%2C_Japan_-_panoramio_%285%29.jpg",3264,2448],["c:d/d0/BisanSetoBridge_20150722_131540.jpg",3568,2000],["c:f/fc/Seto-Ohashi_Bridge.jpg",2756,1628],["c:9/94/Great_Seto_Bridge-Rikujyo01.jpg",2400,1800],["c:c/cf/Shimotsui-Seto_Bridge_who_saw_from_Okayama_Prefecture.JPG",2048,1536],["c:3/3c/Seto_Bri1original.jpg",1600,1200],["c:a/a1/SetonaiKaiTagged.jpg",1280,960]]},{"id":"33_oyaseki","n":"大多羅寄宮跡（池田光政の神社整理）","yomi":"おおたらよせみやあと","cat":"寺社","rank":"B","y":1666,"era":["edo"],"sh":"","ad":"岡山市東区大多羅町","st":"JR赤穂線・大多羅駅から歩いて約10分","la":34.67,"lo":134.005,"hook":"村々の小さな神様を一か所に集めよ。名君と呼ばれた藩主の、大胆な改革の跡。","lead":"大多羅寄宮（おおたらよせみや）は、江戸時代の岡山藩主・池田光政が行った «神社整理» でつくられた神社の跡です。村々にあった小さなほこらの神様を集め、ここにまとめてまつりました。今は石の鳥居や石段などが残っています。","story":["江戸時代のはじめ、岡山藩を治めた池田光政は «名君» として知られています。学問を重んじ、閑谷学校をつくり、災害に備える政治を行いました。その光政が、1666年ごろから進めた改革の一つが、寺や神社の整理でした。","当時の村々には、小さなほこらや、正体のよくわからない神様がたくさんまつられていました。«おまじないやお祭りにお金がかかって、村人の暮らしが苦しくなっているのでは?» 儒学を深く学んでいた光政は、そう考えたといわれます。そこで、由来のはっきりしない小さな神社をまとめ、決められた場所に集めてまつらせました。","こうしてつくられた神社が «寄宮（よせみや）» です。大多羅の寄宮は、その中でも大きなものの一つでした。広い境内に社殿が建ち、石の鳥居や石段が整えられました。村々から神様を «引っ越し» させた場所だったのです。","しかし、村人にとって長く親しんできたほこらを失うことは、つらいことでもありました。光政が亡くなったあと、この政策はゆるめられ、多くの神様はまたもとの村にもどされていったといわれます。大多羅の寄宮も、その後は布施神社の境内として受けつがれました。","今、大多羅の森には、堂々とした石の鳥居や石垣が残り、当時の寄宮の大きさを感じさせます。«人々の暮らしを良くしたい» という藩主の思いと、«なじみの神様を大切にしたい» という村人の思い。二つの思いがぶつかった場所です。"],"tl":[["1632年","池田光政が岡山藩主となる"],["1666年","光政が寺院・神社の整理を本格的に進める"],["1660年代後半","大多羅に寄宮が整えられる"],["1672年","光政が隠居する"],["1682年","光政が亡くなる。その後、政策がゆるめられる"],["現在","石の鳥居や石垣などの遺構が残る"]],"who":[["池田光政","岡山藩主。神社整理を進め、大多羅寄宮をつくらせた"],["津田永忠","光政に仕えた家臣。藩の多くの土木・建築事業を担った"],["村々の人々","ほこらの神様を寄宮に移すことになった人々"]],"deep":["光政の神社整理では、一万を超える小さなほこらが整理され、各地の寄宮などにまとめられたといわれます。正確な数については史料により違いがあります。","寺院の整理も同時に行われ、特に日蓮宗の «不受不施派» はきびしく取りしまられました。","光政は儒学（特に陽明学・朱子学）を重んじ、仏教の葬式ではなく儒式の葬礼を広めようともしました。","大多羅寄宮の石の鳥居は、江戸時代前期の大きな石鳥居として知られ、寄宮の規模を今に伝えています。","寄宮の工事には、閑谷学校や後楽園でも活やくした津田永忠が関わったといわれます。","光政の没後、寄宮に集められた神々の多くはもとの村にもどされましたが、大多羅の寄宮の跡は、今は布施神社の境内として残っています。"],"look":["大きな石の鳥居","参道の石段と石垣","布施神社の社殿","周囲の森と地形（寄宮の広さを想像する）"],"q":["池田光政が、村々の小さな神様を集めてまつらせた神社を何という？","«寄宮（よせみや）» です。大多羅寄宮はその代表的なものです。"],"myth":"整理された神社の数や、寄宮の構造・範囲については諸説がある。","img":["池田光政","閑谷学校","津田永忠","岡山藩"],"wp":"大多羅寄宮","rel":{"ev":[],"grave":[]},"ph":[["c:8/8b/Odara_Yosemiya_Site_01.JPG",4608,3456,"大多羅寄宮"],["c:3/36/%E6%B1%A0%E7%94%B0%E5%85%89%E6%94%BF2.jpg",1386,2109,"池田光政"],["c:d/d0/Shizutani_school_the_hall_and_shosai.JPG",2240,1488,"閑谷学校"],["c:9/90/Tsuda_Nagatada_003.JPG",2000,3008,"津田永忠"],["c:9/90/Okayama_Castle.IMG_5917.jpg",3504,2336,"岡山藩"]]},{"id":"33_fukiya_school","n":"旧吹屋小学校（明治の木造校舎）","yomi":"きゅうふきやしょうがっこう","cat":"学び","rank":"B","y":1909,"era":["meiji","heisei"],"sh":"県指定重要文化財","ad":"高梁市成羽町吹屋","st":"JR伯備線・備中高梁駅から備北バスで吹屋方面へ約1時間、車の方が便利","la":34.856,"lo":133.48,"hook":"ベンガラ色の町の奥で、明治の木造校舎は2012年まで子どもたちの声を聞いていた。","lead":"旧吹屋小学校は、ベンガラの町として知られる高梁市吹屋にある木造の校舎です。明治時代に建てられ、2012年まで現役の小学校として使われていました。現役の木造校舎としては日本でも最も古いものの一つといわれ、いまは修理を終えて見学できます。","story":["吹屋は、標高500mほどの山の上にある町です。江戸時代から明治にかけて、銅山と、赤い顔料 «ベンガラ» づくりで大いに栄えました。町の家々は、ベンガラ色の赤い壁と石州瓦の赤い屋根で統一され、今も独特の景色をつくっています。","その町の奥に、白い壁と木の柱が美しい、大きな校舎が建っています。旧吹屋小学校です。東西の校舎は明治33年（1900年）ごろ、中央の本館は明治42年（1909年）に建てられたといわれます。«山の上の町に、なぜこんなに立派な学校が?» ベンガラと銅山でうるおった町の人々が、子どもたちの教育のために力を合わせたのです。","校舎は長い廊下でつながり、教室には大きな窓がならんでいます。冬は雪も降る山の町。子どもたちは木の床をぞうきんがけし、ストーブを囲んで勉強しました。何世代もの子どもたちが、この校舎で学び、遊び、卒業していきました。","けれど、銅山の閉山やベンガラ産業の衰えとともに町の人口は減り、子どもも少なくなりました。2012年、学校はついに閉校します。最後まで木造校舎で授業が続けられた、全国でもまれな学校でした。","閉校後、校舎は県の重要文化財に指定され、大がかりな修理が行われました。2022年からは一般に公開され、明治の校舎の中を歩くことができます。廊下のきしむ音に耳をすますと、100年以上の子どもたちの声が聞こえてくるようです。"],"tl":[["江戸時代","吹屋が銅山とベンガラ生産で栄え始める"],["1900年ごろ","東西の校舎が建てられる"],["1909年","中央の本館が建てられる"],["1977年","吹屋の町並みが国の重要伝統的建造物群保存地区に選ばれる"],["2012年","吹屋小学校が閉校"],["2022年","修理を終え、一般公開が始まる"]],"who":[["吹屋の町の人々","ベンガラと銅山で栄え、学校を支えた"],["明治の大工たち","大きな木造校舎を建てた職人"],["吹屋小学校の子どもたち","100年以上にわたってこの校舎で学んだ"]],"deep":["ベンガラは酸化鉄を主な成分とする赤い顔料で、吹屋のベンガラは品質が高く、九谷焼や伊万里焼などの焼き物の絵付けや、建物の塗料に使われました。","吹屋のベンガラは、銅山から出る硫化鉄鉱を原料に «ローハ（緑礬）» をつくり、それを焼いてつくる独特の方法でした。","吹屋の町並みは1977年に国の重要伝統的建造物群保存地区に選ばれ、2020年には «ジャパンレッド» の物語として日本遺産にも認定されました。","旧吹屋小学校は、本館と東西の校舎がつながった左右対称に近い配置で、明治の学校建築の特徴をよく残しています。","閉校時は、現役で使われていた木造校舎としては日本最古級といわれ、全国から注目を集めました。","近くには、ベンガラ製造のようすを伝える «ベンガラ館» や、ベンガラで財をなした «広兼邸» などがあります。"],"look":["本館と東西の校舎の外観","長い木の廊下と教室","ベンガラ色の吹屋の町並み","ベンガラ館と広兼邸"],"q":["吹屋の町で作られていた赤い顔料の名前は？","«ベンガラ» です。焼き物の絵付けや建物の塗料に使われました。"],"myth":"校舎の建築年（東西校舎）には資料により差がある。","img":["吹屋","弁柄","広兼邸"],"wp":"高梁市立吹屋小学校","rel":{"ev":[],"grave":[]},"ph":[["c:a/ab/Fukiya_elementary_school02s3200.jpg",3450,2300,"高梁市立吹屋小学校"],["c:d/d7/Fukiya_elementary_school04s3200.jpg",3600,2400],["c:9/92/Fukiya_20180501_152151.jpg",4266,2400],["c:e/ec/Fukiya_elementary_school01s3200.jpg",3200,2142],["c:6/6e/Fukya_Elenentary_School.png",1200,600],["c:8/87/Fukiya01s3200.jpg",3600,2400,"吹屋"],["c:f/fa/Bengala_Akanesawa_red_rock_IMG_5840.jpg",4608,3456,"弁柄"],["c:1/14/Hirokane_house14bss.jpg",3420,2280,"広兼邸"]]}];
